"use client";

import { useState } from "react";
import { Button, Tooltip } from "antd";
import { BookOpen, Library } from "lucide-react";

import { PromptSelectDialog } from "@/components/prompts/prompt-select-dialog";
import { UserPromptPresetDialog } from "@/components/prompts/user-prompt-preset-dialog";
import { canvasThemes } from "@/lib/canvas-theme";
import { useThemeStore } from "@/stores/use-theme-store";

export function CanvasPromptLibrary({ onSelect }: { onSelect: (prompt: string) => void }) {
    const [open, setOpen] = useState(false);
    const [presetOpen, setPresetOpen] = useState(false);
    const theme = canvasThemes[useThemeStore((state) => state.theme)];

    return (
        <div className="flex shrink-0 items-center gap-1">
            <Tooltip title="我的预设">
                <Button
                    type="text"
                    className="!h-8 !w-8 !min-w-8 shrink-0 !rounded-full !bg-transparent !p-0"
                    style={{ color: theme.node.text }}
                    icon={<Library className="size-3.5" />}
                    onClick={() => setPresetOpen(true)}
                    aria-label="我的预设"
                    data-testid="canvas-user-prompt-presets"
                />
            </Tooltip>
            <Tooltip title="提示词库">
                <Button
                    type="text"
                    className="!h-8 !w-8 !min-w-8 shrink-0 !rounded-full !bg-transparent !p-0"
                    style={{ color: theme.node.text }}
                    icon={<BookOpen className="size-3.5" />}
                    onClick={() => setOpen(true)}
                    aria-label="提示词库"
                />
            </Tooltip>
            <PromptSelectDialog open={open} onOpenChange={setOpen} onSelect={onSelect} />
            <UserPromptPresetDialog open={presetOpen} onOpenChange={setPresetOpen} onSelect={onSelect} />
        </div>
    );
}
