"use client";

import type { CSSProperties } from "react";
import { BookOpen, Keyboard, LogOut, Settings2, UserRound } from "lucide-react";

import { AnimatedThemeToggler } from "@/components/ui/animated-theme-toggler";
import { useLocation } from "wouter";
import { useAuth } from "@/contexts/AuthContext";
import { DOCS_URL } from "@/constant/env";
import { canvasThemes } from "@/lib/canvas-theme";
import { useConfigStore } from "@/stores/use-config-store";
import { useThemeStore } from "@/stores/use-theme-store";

type UserStatusActionsProps = {
    showConfig?: boolean;
    variant?: "default" | "canvas";
    onOpenShortcuts?: () => void;
};

export function UserStatusActions({ showConfig = true, variant = "default", onOpenShortcuts }: UserStatusActionsProps) {
    const [, navigate] = useLocation();
    const { user, logout } = useAuth();
    const theme = useThemeStore((state) => state.theme);
    const setTheme = useThemeStore((state) => state.setTheme);
    const openConfigDialog = useConfigStore((state) => state.openConfigDialog);
    const canvasTheme = canvasThemes[theme];
    const naturalIconClass = variant === "canvas" ? "canvas-topbar-icon inline-flex size-8 shrink-0 items-center justify-center rounded-lg transition [&_svg]:size-4" : "studio-tool-icon [&_svg]:size-4";
    const iconStyle: CSSProperties | undefined = variant === "canvas" ? { color: canvasTheme.node.text } : undefined;

    return (
        <div className="inline-flex shrink-0 items-center gap-1">
            <a href={DOCS_URL} target="_blank" rel="noopener noreferrer" className={naturalIconClass} style={iconStyle} aria-label="文档" title="文档">
                <BookOpen className="size-4" />
            </a>
            {showConfig ? (
                <button type="button" className={naturalIconClass} style={iconStyle} onClick={() => openConfigDialog(false)} aria-label="制作偏好" title="制作偏好">
                    <Settings2 className="size-4" />
                </button>
            ) : null}
            <AnimatedThemeToggler theme={theme} onThemeChange={setTheme} className={naturalIconClass} style={iconStyle} aria-label={theme === "dark" ? "切换到浅色主题" : "切换到深色主题"} title={theme === "dark" ? "切换到浅色主题" : "切换到深色主题"} />
            {user ? (
                <span className={variant === "canvas" ? "hidden max-w-28 items-center gap-1 truncate px-1 text-xs sm:inline-flex" : "studio-user-pill hidden max-w-36 gap-1 truncate text-xs sm:inline-flex"} style={variant === "canvas" ? { color: canvasTheme.node.muted } : undefined} title={user.display_name || user.username}>
                    <UserRound className="size-3.5 shrink-0" />
                    <span className="truncate">{user.display_name || user.username}</span>
                </span>
            ) : null}
            {user ? (
                <button type="button" className={naturalIconClass} style={iconStyle} onClick={() => void logout().then(() => navigate("/login", { replace: true }))} aria-label="退出登录" title="退出登录" data-testid="user-logout">
                    <LogOut className="size-4" />
                </button>
            ) : null}
            {onOpenShortcuts ? (
                <button type="button" className={naturalIconClass} style={iconStyle} onClick={onOpenShortcuts} aria-label="快捷键" title="快捷键">
                    <Keyboard className="size-4" />
                </button>
            ) : null}
        </div>
    );
}
