"use client";

import { forwardRef, useEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, MouseEvent, PointerEvent, TextareaHTMLAttributes } from "react";
import { createPortal } from "react-dom";
import { FileText, Image as ImageIcon, Music2, Video } from "lucide-react";

import { canvasThemes } from "@/lib/canvas-theme";
import { useThemeStore } from "@/stores/use-theme-store";
import type { CanvasResourceReference } from "../utils/canvas-resource-references";
import { buildCanvasMentionMenuGroups, canvasMentionToken, filterCanvasMentionReferences, matchCanvasMentionTrigger, splitCanvasMentionText } from "../utils/canvas-mention-tokens";

type MentionState = {
    start: number;
    query: string;
};

type Props = Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, "onChange" | "value"> & {
    value: string;
    references: CanvasResourceReference[];
    onChange: (value: string) => void;
    onSubmit?: () => void;
    onMentionQueryChange?: (query: string) => void;
    containerClassName?: string;
    highlightLabels?: boolean;
};

export const CanvasResourceMentionTextarea = forwardRef<HTMLTextAreaElement, Props>(function CanvasResourceMentionTextarea({ value, references, onChange, onSubmit, onMentionQueryChange, onKeyDown, className, containerClassName, style, highlightLabels = true, ...props }, forwardedRef) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const textareaRef = useRef<HTMLTextAreaElement | null>(null);
    const overlayRef = useRef<HTMLDivElement | null>(null);
    const [mention, setMention] = useState<MentionState | null>(null);
    const [activeIndex, setActiveIndex] = useState(0);
    const [hasSelection, setHasSelection] = useState(false);
    const [focused, setFocused] = useState(false);
    const candidates = useMemo(() => {
        if (!mention) return [];
        return filterCanvasMentionReferences(references, mention.query);
    }, [mention, references]);
    const activeReferences = useMemo(() => references.filter((item) => item.active), [references]);
    const highlightParts = useMemo(() => (highlightLabels ? splitCanvasMentionText(value, references) : []), [highlightLabels, references, value]);

    useEffect(() => {
        if (!mention) return;
        onMentionQueryChange?.(mention.query);
    }, [mention, onMentionQueryChange]);

    const updateValue = (next: string, selectionStart?: number) => {
        onChange(next);
        if (typeof selectionStart !== "number") return;
        requestAnimationFrame(() => {
            textareaRef.current?.focus();
            textareaRef.current?.setSelectionRange(selectionStart, selectionStart);
        });
    };

    const closeMention = () => {
        setMention(null);
        setActiveIndex(0);
    };

    const syncMention = (nextValue: string, cursor: number) => {
        const prefix = nextValue.slice(0, cursor);
        const match = matchCanvasMentionTrigger(prefix);
        if (!match) {
            closeMention();
            return;
        }
        setMention({ start: cursor - match.query.length - 1, query: match.query });
        setActiveIndex(0);
    };

    const insertReference = (reference: CanvasResourceReference) => {
        if (!mention) return;
        const textarea = textareaRef.current;
        const end = textarea?.selectionStart ?? value.length;
        const insertText = `${canvasMentionToken(reference.targetId, reference.mentionSource)} `;
        const next = `${value.slice(0, mention.start)}${insertText}${value.slice(end)}`;
        closeMention();
        updateValue(next, mention.start + insertText.length);
    };

    const syncOverlayScroll = () => {
        if (!overlayRef.current || !textareaRef.current) return;
        overlayRef.current.scrollTop = textareaRef.current.scrollTop;
        overlayRef.current.scrollLeft = textareaRef.current.scrollLeft;
    };

    const updateSelectionState = () => {
        const textarea = textareaRef.current;
        setHasSelection(Boolean(textarea && textarea.selectionStart !== textarea.selectionEnd));
    };

    const showOverlay = Boolean(value && highlightLabels && !hasSelection && !focused);
    const mergedStyle = {
        ...(style || {}),
        color: style?.color || theme.node.text,
        caretColor: theme.node.activeStroke,
    } as CSSProperties;
    const menu = mention && textareaRef.current ? <MentionMenu textarea={textareaRef.current} references={candidates} allReferences={activeReferences} activeIndex={Math.min(activeIndex, Math.max(candidates.length - 1, 0))} theme={theme} onSelect={insertReference} /> : null;

    return (
        <div className={`relative h-full w-full ${containerClassName || ""}`}>
            {showOverlay ? (
                <div ref={overlayRef} className={`${className || ""} pointer-events-none absolute inset-0 overflow-hidden whitespace-pre-wrap break-words`} style={{ ...style, color: theme.node.text }}>
                    <MentionHighlightText value={value || props.placeholder?.toString() || ""} parts={highlightParts} placeholder={!value} theme={theme} />
                </div>
            ) : null}
            <textarea
                {...props}
                ref={(node) => {
                    textareaRef.current = node;
                    if (typeof forwardedRef === "function") forwardedRef(node);
                    else if (forwardedRef) forwardedRef.current = node;
                }}
                value={value}
                className={className}
                style={mergedStyle}
                onChange={(event) => {
                    const next = event.target.value;
                    onChange(next);
                    syncMention(next, event.target.selectionStart);
                    requestAnimationFrame(() => {
                        syncOverlayScroll();
                        updateSelectionState();
                    });
                }}
                onSelect={(event) => {
                    updateSelectionState();
                    props.onSelect?.(event);
                }}
                onKeyUp={(event) => {
                    updateSelectionState();
                    props.onKeyUp?.(event);
                }}
                onPointerUp={(event) => {
                    updateSelectionState();
                    props.onPointerUp?.(event);
                }}
                onKeyDown={(event) => {
                    if (mention) {
                        if (event.key === "ArrowDown" && candidates.length) {
                            event.preventDefault();
                            setActiveIndex((index) => (index + 1) % candidates.length);
                            return;
                        }
                        if (event.key === "ArrowUp" && candidates.length) {
                            event.preventDefault();
                            setActiveIndex((index) => (index - 1 + candidates.length) % candidates.length);
                            return;
                        }
                        if (event.key === "Enter" && candidates.length) {
                            event.preventDefault();
                            insertReference(candidates[Math.min(activeIndex, candidates.length - 1)]);
                            return;
                        }
                        if (event.key === "Escape") {
                            event.preventDefault();
                            closeMention();
                            return;
                        }
                    }
                    if (event.key === "Enter" && onSubmit && !event.ctrlKey && !event.metaKey && !event.shiftKey) {
                        event.preventDefault();
                        onSubmit();
                        return;
                    }
                    onKeyDown?.(event);
                }}
                onScroll={(event) => {
                    syncOverlayScroll();
                    props.onScroll?.(event);
                }}
                onBlur={(event) => {
                    setFocused(false);
                    setHasSelection(false);
                    window.setTimeout(closeMention, 120);
                    props.onBlur?.(event);
                }}
                onFocus={(event) => {
                    setFocused(true);
                    props.onFocus?.(event);
                }}
            />
            {menu}
        </div>
    );
});

function MentionHighlightText({ value, parts, placeholder, theme }: { value: string; parts: ReturnType<typeof splitCanvasMentionText>; placeholder: boolean; theme: (typeof canvasThemes)[keyof typeof canvasThemes] }) {
    if (placeholder) return <span className="opacity-45">{value}</span>;
    if (!parts.length) return <>{value}</>;
    return (
        <>
            {parts.map((part, index) =>
                part.type === "reference" ? (
                    <span
                        key={`${part.mentionKey}-${index}`}
                        className={`rounded-md px-1 py-0.5 font-medium ring-1 ${part.missing ? "bg-[#ef4444]/14 text-[#ef4444] ring-[#ef4444]/25" : ""}`}
                        style={part.missing ? undefined : { background: theme.toolbar.itemHover, color: theme.node.activeStroke, boxShadow: `0 0 0 1px ${theme.node.activeStroke}24` }}
                    >
                        {part.label}
                    </span>
                ) : (
                    <span key={`${part.value}-${index}`}>{part.value}</span>
                ),
            )}
        </>
    );
}

function MentionMenu({ textarea, references, allReferences, activeIndex, theme, onSelect }: { textarea: HTMLTextAreaElement; references: CanvasResourceReference[]; allReferences: CanvasResourceReference[]; activeIndex: number; theme: (typeof canvasThemes)[keyof typeof canvasThemes]; onSelect: (reference: CanvasResourceReference) => void }) {
    const selectedRef = useRef(false);
    const rect = textarea.getBoundingClientRect();
    const boundary = textarea.closest(".ant-modal-content")?.getBoundingClientRect() || { left: 8, top: 8, right: window.innerWidth - 8, bottom: window.innerHeight - 8 };
    const menuWidth = 256;
    const maxMenuHeight = 224;
    const gap = 6;
    const left = clamp(rect.left, boundary.left + 8, boundary.right - menuWidth - 8);
    const showAbove = rect.bottom + gap + maxMenuHeight > boundary.bottom && rect.top - gap - maxMenuHeight >= boundary.top;
    const top = clamp(showAbove ? rect.top - gap - maxMenuHeight : rect.bottom + gap, boundary.top + 8, boundary.bottom - maxMenuHeight - 8);

    const stopCanvasInteraction = (event: PointerEvent | MouseEvent) => {
        event.stopPropagation();
    };
    const selectReference = (reference: CanvasResourceReference) => {
        if (selectedRef.current) return;
        selectedRef.current = true;
        onSelect(reference);
    };
    const groups = buildCanvasMentionMenuGroups(allReferences, references);

    return createPortal(
        <div
            data-canvas-resource-mention-menu="true"
            className="fixed z-[120] max-h-56 w-64 overflow-y-auto rounded-xl border p-1 shadow-2xl backdrop-blur-md"
            style={{ left, top, background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }}
            onPointerDown={stopCanvasInteraction}
            onMouseDown={stopCanvasInteraction}
            onClick={(event) => event.stopPropagation()}
        >
            {groups.map((group) => {
                return (
                    <div key={group.source}>
                        <div className="px-2 py-1 text-[11px] font-medium opacity-55">{group.title}</div>
                        {group.empty ? <div className="px-2 pb-2 text-[11px] leading-4 opacity-45">{group.emptyText}</div> : null}
                        {group.unmatched ? <div className="px-2 pb-2 text-[11px] leading-4 opacity-45">无匹配素材</div> : null}
                        {group.items.map(({ reference, index }) => {
                            return (
                                <button
                                    key={reference.id}
                                    type="button"
                                    className="flex w-full min-w-0 items-center gap-2 rounded-lg px-2 py-1.5 text-left text-xs transition"
                                    style={{ background: index === activeIndex ? theme.toolbar.activeBg : "transparent", color: index === activeIndex ? theme.toolbar.activeText : theme.node.text }}
                                    onPointerDown={(event) => {
                                        event.preventDefault();
                                        event.stopPropagation();
                                        selectReference(reference);
                                    }}
                                    onClick={(event) => {
                                        event.preventDefault();
                                        event.stopPropagation();
                                        selectReference(reference);
                                    }}
                                >
                                    <ReferencePreview reference={reference} />
                                    <span className="min-w-0 flex-1">
                                        <span className="block truncate font-medium">{reference.label || reference.title}</span>
                                        <span className="block truncate opacity-65">{referenceSubtitle(reference)}</span>
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                );
            })}
        </div>,
        document.body,
    );
}

function ReferencePreview({ reference }: { reference: CanvasResourceReference }) {
    if (reference.kind === "image" && reference.previewUrl) return <img src={reference.previewUrl} alt="" className="size-9 rounded-md object-cover" />;
    if (reference.kind === "video" && reference.previewUrl) return <video src={reference.previewUrl} className="size-9 rounded-md bg-black object-cover" muted preload="metadata" />;
    const Icon = reference.kind === "audio" ? Music2 : reference.kind === "video" ? Video : reference.kind === "image" ? ImageIcon : FileText;
    return (
        <span className="grid size-9 shrink-0 place-items-center rounded-md bg-black/10">
            <Icon className="size-4" />
        </span>
    );
}

function clamp(value: number, min: number, max: number) {
    if (max < min) return min;
    return Math.min(Math.max(value, min), max);
}

function referenceSubtitle(reference: CanvasResourceReference) {
    return reference.source === "asset-library" ? `素材库 · ${kindLabel(reference.kind)}` : `${reference.sourceLabel} · 已连接素材`;
}

function kindLabel(kind: CanvasResourceReference["kind"]) {
    if (kind === "image") return "图片";
    if (kind === "video") return "视频";
    if (kind === "audio") return "音频";
    return "文本";
}
