function isImageGenerationReady(config: Pick<AiConfig, "model" | "imageModels">) {
    return Boolean(config.model.trim() && config.imageModels.includes(config.model));
}

function currentImageModel(config: Pick<AiConfig, "imageModel" | "imageModels">) {
    return config.imageModels.includes(config.imageModel) ? config.imageModel : config.imageModels[0] || "";
}

function isGenerationModeReady(config: AiConfig, mode: CanvasNodeGenerationMode) {
    if (mode === "image") return isImageGenerationReady(config);
    if (mode === "video") return Boolean(config.model.trim() && config.videoModels.includes(config.model));
    if (mode === "audio") return Boolean(config.model.trim() && config.audioModels.includes(config.model));
    return Boolean(config.model.trim() && config.models.includes(config.model));
}

type CanvasSyncStatus = NonNullable<CanvasProject["syncStatus"]> | "local";

const canvasSyncStatusLabel: Record<CanvasSyncStatus, string> = {
    local: "本地",
    synced: "已同步",
    pending: "待同步",
    conflict: "冲突",
};

function resolveCanvasSyncStatus(project: CanvasProject | null | undefined): CanvasSyncStatus {
    return project?.syncStatus || (project?.serverProjectId ? "pending" : "local");
}

function formatCanvasSyncLabel(status: CanvasSyncStatus, snapshotVersion?: number) {
    return snapshotVersion ? `${canvasSyncStatusLabel[status]} v${snapshotVersion}` : canvasSyncStatusLabel[status];
}

function createCanvasNode(type: CanvasNodeType, position: Position, metadata?: CanvasNodeMetadata): CanvasNodeData {
    const spec = getNodeSpec(type);
    const id = `${type}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;

    return {
        id,
        type,
        title: spec.title,
        position: {
            x: position.x - spec.width / 2,
            y: position.y - spec.height / 2,
        },
        width: spec.width,
        height: spec.height,
        metadata: { ...spec.metadata, ...metadata },
    };
}

