    const startGenerationRequest = useCallback((targetNodeId: string, originNodeId: string, runningId = originNodeId, controller = new AbortController()) => {
        const previous = generationRequestsRef.current.get(targetNodeId);
        if (previous?.controller !== controller) previous?.controller.abort();
        const requestId = nanoid();
        generationRequestsRef.current.set(targetNodeId, { requestId, targetNodeId, originNodeId, runningNodeId: runningId, controller });
        return { controller, requestId };
    }, []);

    const finishGenerationRequest = useCallback((targetNodeId: string, requestId: string) => {
        const request = generationRequestsRef.current.get(targetNodeId);
        if (request?.requestId === requestId) generationRequestsRef.current.delete(targetNodeId);
    }, []);

    const updateNodeJobProgress = useCallback((nodeId: string, job: JobRecord | JobSubmission) => {
        const jobId = job.job_id || job.id || "";
        const progress = "progress" in job && typeof job.progress === "number" ? job.progress : 0;
        setNodes((prev) =>
            prev.map((node) =>
                node.id === nodeId
                    ? {
                          ...node,
                          metadata: {
                              ...node.metadata,
                              jobId: jobId || node.metadata?.jobId,
                              jobProgress: progress,
                              status: NODE_STATUS_LOADING,
                              errorDetails: undefined,
                          },
                      }
                    : node,
            ),
        );
    }, []);

