    useEffect(() => {
        const preventUIBrowserZoom = (event: WheelEvent) => {
            if (!event.ctrlKey && !event.metaKey) return;
            const target = event.target instanceof Element ? event.target : null;
            if (target?.closest("[data-canvas-ui],[data-canvas-no-zoom],input,textarea,select,button,[contenteditable='true'],.ant-modal,.ant-popover,.ant-dropdown,.ant-select-dropdown,.ant-picker-dropdown")) event.preventDefault();
        };
        document.addEventListener("wheel", preventUIBrowserZoom, { capture: true, passive: false });
        return () => document.removeEventListener("wheel", preventUIBrowserZoom, true);
    }, []);

    useEffect(() => {
        const isTypingTarget = (target: EventTarget | null) => {
            const element = target instanceof Element ? target : null;
            return target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement || Boolean(element?.closest("[contenteditable='true']"));
        };
        const isPopupEditing = (target: Element | null) => {
            if (target?.closest("[role='dialog'],.ant-modal,.ant-popover,.ant-dropdown,.ant-select-dropdown,.ant-picker-dropdown")) return true;
            return Array.from(document.querySelectorAll<HTMLElement>(".ant-modal-wrap")).some((element) => element.offsetParent !== null);
        };
        const handleKeyDown = (event: KeyboardEvent) => {
            const target = event.target instanceof Element ? event.target : null;
            if (event.code === "Space" && !isTypingTarget(event.target)) {
                setIsSpacePressed(true);
                return;
            }
            if (isTypingTarget(event.target)) return;
            if (isPopupEditing(target)) return;

            if (event.code === "Backquote" && !event.ctrlKey && !event.metaKey && !event.altKey) {
                const hoveredId = hoveredNodeIdRef.current;
                if (hoveredId) {
                    event.preventDefault();
                    focusNodeInViewport(hoveredId);
                }
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.undo)) {
                event.preventDefault();
                undoCanvas();
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.redo)) {
                event.preventDefault();
                redoCanvas();
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.selectAll)) {
                event.preventDefault();
                setSelectedNodeIds(new Set(nodesRef.current.map((node) => node.id)));
                setSelectedConnectionId(null);
                setContextMenu(null);
                setSelectionBox(null);
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.copy)) {
                event.preventDefault();
                copySelectedNodes();
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.paste)) {
                event.preventDefault();
                if (!pasteCopiedNodes()) void pasteSystemClipboard();
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.runSelection)) {
                event.preventDefault();
                void runSelectedGeneration();
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.openSettings)) {
                event.preventDefault();
                openConfigDialog(false);
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.resetZoom)) {
                event.preventDefault();
                setViewport({ x: size.width / 2, y: size.height / 2, k: 1 });
                return;
            }

            if (eventMatchesShortcut(event, shortcuts.delete)) {
                event.preventDefault();
                if (selectedGroupIdRef.current) {
                    const groupId = selectedGroupIdRef.current;
                    setGroups((prev) => prev.filter((group) => group.id !== groupId));
                    setSelectedGroupId(null);
                    setContextMenu((current) => (current?.type === "group" && current.groupId === groupId ? null : current));
                } else if (selectedNodeIdsRef.current.size) {
                    deleteNodes(new Set(selectedNodeIdsRef.current));
                } else if (selectedConnectionId) {
                    deleteConnection(selectedConnectionId);
                }
                return;
            }

            if (event.key === "Escape") {
                setSelectedNodeIds(new Set());
                setSelectedGroupId(null);
                setSelectedConnectionId(null);
                setContextMenu(null);
                setSelectionBox(null);
                setConnecting(null);
                setHoveredNodeId(null);
                setToolbarNodeId(null);
                setDialogNodeId(null);
                setEditingNodeId(null);
                setInfoNodeId(null);
                setCropNodeId(null);
                setMaskEditNodeId(null);
                setPendingConnectionCreate(null);
            }
        };

        const handleKeyUp = (event: KeyboardEvent) => {
            if (event.code === "Space") setIsSpacePressed(false);
        };

        const releaseSpace = () => setIsSpacePressed(false);

        window.addEventListener("keydown", handleKeyDown);
        window.addEventListener("keyup", handleKeyUp);
        window.addEventListener("blur", releaseSpace);
        return () => {
            window.removeEventListener("keydown", handleKeyDown);
            window.removeEventListener("keyup", handleKeyUp);
            window.removeEventListener("blur", releaseSpace);
        };
    }, [copySelectedNodes, deleteConnection, deleteNodes, focusNodeInViewport, openConfigDialog, pasteCopiedNodes, pasteSystemClipboard, redoCanvas, selectedConnectionId, setConnecting, shortcuts, size.height, size.width, undoCanvas]);

