    const connectSelectedNodesToNewConfig = useCallback(() => {
        const currentNodes = nodesRef.current;
        const selectedIds = Array.from(selectedNodeIdsRef.current).filter((nodeId) => currentNodes.some((node) => node.id === nodeId && !isHiddenBatchChild(node, currentNodes)));
        if (selectedIds.length < 2) return;
        const bounds = buildSelectedNodeBounds(currentNodes, new Set(selectedIds));
        if (!bounds) return;

        const configSpec = NODE_DEFAULT_SIZE[CanvasNodeType.Config];
        const configNode = createCanvasNode(
            CanvasNodeType.Config,
            {
                x: bounds.x + bounds.width + 120 + configSpec.width / 2,
                y: bounds.y + bounds.height / 2,
            },
            {
                model: currentImageModel(effectiveConfig),
                size: "auto",
                count: getGenerationCount(effectiveConfig.canvasImageCount || effectiveConfig.count),
            },
        );
        const candidateNodes = [...currentNodes, configNode];
        const existingPairs = new Set(connectionsRef.current.map((connection) => `${connection.fromNodeId}->${connection.toNodeId}`));
        const newConnections = selectedIds.flatMap((nodeId) => {
            const connection = normalizeConnection(nodeId, configNode.id, candidateNodes, "source");
            if (!connection) return [];
            const key = `${connection.fromNodeId}->${connection.toNodeId}`;
            if (existingPairs.has(key)) return [];
            existingPairs.add(key);
            return [{ id: nanoid(), ...connection }];
        });

        if (!newConnections.length) {
            message.warning("选中的节点无法连接到新的配置节点");
            return;
        }

        setNodes((prev) => [...prev, configNode]);
        setConnections((prev) => [...prev, ...newConnections]);
        setSelectedNodeIds(new Set([configNode.id]));
        setSelectedGroupId(null);
        setSelectedConnectionId(null);
        setToolbarNodeId(null);
        setContextMenu(null);
        setPendingConnectionCreate(null);
        setConnecting(null);
        setDialogNodeId(configNode.id);
    }, [effectiveConfig, message, setConnecting]);

