import axios from "axios";

import { API_BASE_URL } from "@/constant/env";
import { dataUrlToFile, ensureImageDataUrlMimeType, getDataUrlByteSize, imageDataUrlMimeType, readImageMeta, resizeImageDataUrl } from "@/lib/image-utils";
import { downloadServerAsset, serverAssetStorageKey } from "@/services/api/assets";
import { getMediaBlob, uploadMediaFile, type UploadedFile } from "@/services/file-storage";
import { imageToDataUrl } from "@/services/image-storage";
import { fetchJob, isTerminalJob, jobErrorMessage, jobRecordId, waitForJob, type JobRecord, type JobSubmission, type WaitForJobOptions } from "@/services/api/jobs";
import { getStoredAuthToken, requestApi } from "@/services/api/request";
import { boolConfig, buildSeedancePromptText, isSeedanceVideoConfig, normalizeSeedanceDuration, normalizeSeedanceRatio, normalizeSeedanceResolution, seedanceVideoReferenceError, SEEDANCE_REFERENCE_LIMITS } from "@/lib/seedance-video";
import { modelOptionName, type AiConfig } from "@/stores/use-config-store";
import type { ReferenceImage } from "@/types/image";
import type { ReferenceAudio, ReferenceVideo } from "@/types/media";

type SeedanceTask = {
    id: string;
    status?: "queued" | "running" | "succeeded" | "failed" | "cancelled" | "expired";
    error?: { code?: string; message?: string } | null;
    content?: { video_url?: string; last_frame_url?: string } | null;
};
type ApiEnvelope<T> = T | { code?: number; data?: T | null; msg?: string };
type RequestOptions = WaitForJobOptions;

// TokenHub documents Base64 image references as usable below 2MB; leave room for JSON overhead.
const SEEDANCE_IMAGE_DATA_URL_MAX_BYTES = 1800 * 1024;
// Image-to-video does not need full source resolution in the request body; this keeps payloads stable.
const SEEDANCE_IMAGE_DATA_URL_MAX_EDGE = 1280;
const SEEDANCE_IMAGE_COMPRESSION_STEPS = [
    { edge: 1280, quality: 0.78 },
    { edge: 1024, quality: 0.72 },
    { edge: 896, quality: 0.66 },
    { edge: 768, quality: 0.6 },
    { edge: 640, quality: 0.56 },
    { edge: 512, quality: 0.52 },
];

export type VideoGenerationResult = { blob?: Blob; url?: string; mimeType?: string };
export type VideoGenerationTask = { id: string; provider: "openai" | "seedance"; model: string };
export type VideoGenerationTaskState = { status: "pending" } | { status: "completed"; result: VideoGenerationResult } | { status: "failed"; error: string };

export async function requestVideoGeneration(config: AiConfig, prompt: string, references: ReferenceImage[] = [], videoReferences: ReferenceVideo[] = [], audioReferences: ReferenceAudio[] = [], options?: RequestOptions): Promise<VideoGenerationResult> {
    const task = await createVideoGenerationTask(config, prompt, references, videoReferences, audioReferences, options);
    if (task.provider === "openai") {
        const job = await waitForJob(task.id, options);
        if (job.status !== "succeeded") throw new Error(jobErrorMessage(job, "视频生成失败"));
        return videoResultFromCompletedJob(job, options);
    }
    const delayMs = task.provider === "seedance" ? 5000 : 2500;
    for (let attempt = 0; attempt < 120; attempt += 1) {
        if (options?.signal?.aborted) throw new DOMException("Aborted", "AbortError");
        const state = await pollVideoGenerationTask(config, task, options);
        if (state.status === "completed") return state.result;
        if (state.status === "failed") throw new Error(state.error);
        if (attempt === 119) throw new Error(`${task.provider === "seedance" ? "Seedance " : ""}视频生成超时，请稍后重试`);
        await delay(delayMs, options?.signal);
    }
    throw new Error("视频生成超时，请稍后重试");
}

export async function createVideoGenerationTask(config: AiConfig, prompt: string, references: ReferenceImage[] = [], videoReferences: ReferenceVideo[] = [], audioReferences: ReferenceAudio[] = [], options?: RequestOptions): Promise<VideoGenerationTask> {
    const selectedModel = (config.model || config.videoModel).trim();
    const model = modelOptionName(selectedModel);
    assertVideoConfig(model);
    if (isSeedanceVideoConfig({ ...config, model })) {
        return createSeedanceTask({ ...config, model }, selectedModel, prompt, references, videoReferences, audioReferences, options);
    }
    if (hasAssetReference(references) || hasMediaAssetReference(videoReferences) || hasMediaAssetReference(audioReferences)) {
        throw new Error("asset:// 素材引用仅支持 Seedance / 火山视频模型，请切换模型或移除拟真人/活体授权素材");
    }
    if (videoReferences.length || audioReferences.length) {
        throw new Error("当前视频接口不支持参考视频或参考音频，请切换到 Seedance 2.0 / 火山 Agent Plan 模型，或移除参考素材");
    }
    return createOpenAIVideoTask({ ...config, model }, selectedModel, prompt, references, options);
}

export async function pollVideoGenerationTask(config: AiConfig, task: VideoGenerationTask, options?: RequestOptions): Promise<VideoGenerationTaskState> {
    const model = modelOptionName(task.model || config.model || config.videoModel);
    assertVideoConfig(model);
    return task.provider === "seedance" ? pollSeedanceTask({ ...config, model }, task, options) : pollOpenAIVideoTask(task, options);
}

export async function storeGeneratedVideo(result: VideoGenerationResult): Promise<UploadedFile> {
    if (result.blob) return uploadMediaFile(result.blob, "video");
    if (result.url) return { url: result.url, storageKey: "", bytes: 0, mimeType: result.mimeType || "video/mp4" };
    throw new Error("视频接口没有返回可播放的视频");
}

async function createOpenAIVideoTask(config: AiConfig, model: string, prompt: string, references: ReferenceImage[], options?: RequestOptions): Promise<VideoGenerationTask> {
    const body = new FormData();
    body.append("model", model);
    body.append("prompt", prompt);
    body.append("seconds", normalizeVideoSeconds(config.videoSeconds));
    if (normalizeVideoSize(config.size)) body.append("size", normalizeVideoSize(config.size)!);
    body.append("resolution_name", normalizeVideoResolution(config.vquality));
    body.append("preset", "normal");
    const files = await Promise.all(references.slice(0, 7).map(async (image) => dataUrlToFile({ ...image, dataUrl: await imageToDataUrl(image) })));
    files.forEach((file) => body.append("input_reference[]", file));
    try {
        const created = await requestApi<JobSubmission>("/api/ai/videos", { method: "POST", body, signal: options?.signal });
        options?.onJobAccepted?.(created);
        const jobId = jobRecordId(created);
        if (!jobId) throw new Error("视频接口没有返回任务 ID");
        return { id: jobId, provider: "openai", model };
    } catch (error) {
        throw new Error(readAxiosError(error, "视频任务创建失败"));
    }
}

async function pollOpenAIVideoTask(task: VideoGenerationTask, options?: RequestOptions): Promise<VideoGenerationTaskState> {
    try {
        const job = await fetchJob(task.id, { signal: options?.signal });
        options?.onProgress?.(job);
        if (job.status === "succeeded") return { status: "completed", result: await videoResultFromCompletedJob(job, options) };
        if (isTerminalJob(job)) return { status: "failed", error: jobErrorMessage(job, "视频生成失败") };
        return { status: "pending" };
    } catch (error) {
        throw new Error(readAxiosError(error, "视频任务查询失败"));
    }
}

async function createSeedanceTask(config: AiConfig, model: string, prompt: string, references: ReferenceImage[], videoReferences: ReferenceVideo[], audioReferences: ReferenceAudio[], options?: RequestOptions): Promise<VideoGenerationTask> {
    if (audioReferences.length && !references.length && !videoReferences.length) {
        throw new Error("Seedance 参考音频不能单独使用，请同时添加参考图或参考视频");
    }
    assertSeedanceVideoReferences(videoReferences);
    assertSeedanceAudioReferences(audioReferences);
    const content = await buildSeedanceContent(config, prompt, references, videoReferences, audioReferences);
    if (!content.length) throw new Error("请输入视频提示词，或连接参考图片/视频/音频");
    const payload = {
        model,
        content,
        ratio: normalizeSeedanceRatio(config.size),
        resolution: normalizeSeedanceResolution(config.vquality, modelOptionName(model)),
        duration: normalizeSeedanceDuration(config.videoSeconds),
        generate_audio: boolConfig(config.videoGenerateAudio, true),
        watermark: boolConfig(config.videoWatermark, false),
    };

    try {
        const created = unwrapSeedanceTask(await requestApi<ApiEnvelope<SeedanceTask>>("/api/ai/contents/generations/tasks", { method: "POST", body: JSON.stringify(payload), signal: options?.signal }));
        if (!created.id) throw new Error("Seedance 接口没有返回任务 ID");
        return { id: created.id, provider: "seedance", model };
    } catch (error) {
        throw new Error(readAxiosError(error, "Seedance 任务创建失败"));
    }
}

async function pollSeedanceTask(config: AiConfig, task: VideoGenerationTask, options?: RequestOptions): Promise<VideoGenerationTaskState> {
    try {
        const state = unwrapSeedanceTask(await requestApi<ApiEnvelope<SeedanceTask>>(`/api/ai/contents/generations/tasks/${encodeURIComponent(task.id)}?model=${encodeURIComponent(task.model)}`, { signal: options?.signal }));
        if (state.status === "succeeded") {
            const url = state.content?.video_url;
            if (!url) return { status: "failed", error: "Seedance 任务成功但没有返回视频 URL" };
            return { status: "completed", result: await videoResultFromSeedanceTaskContent(task, url, options) };
        }
        if (state.status === "failed" || state.status === "cancelled" || state.status === "expired") return { status: "failed", error: state.error?.message || `Seedance 视频生成${state.status === "expired" ? "超时" : "失败"}` };
        return { status: "pending" };
    } catch (error) {
        throw new Error(readAxiosError(error, "Seedance 任务查询失败"));
    }
}

function assertSeedanceVideoReferences(videoReferences: ReferenceVideo[]) {
    const error = seedanceVideoReferenceError(videoReferences);
    if (error) throw new Error(error);
    let total = 0;
    for (const video of videoReferences) {
        if (!video.durationMs) continue;
        if (video.durationMs < 2000 || video.durationMs > 15000) throw new Error("Seedance 参考视频单个时长需要在 2-15 秒之间");
        total += video.durationMs;
    }
    if (total > 15000) throw new Error("Seedance 参考视频总时长不能超过 15 秒");
}

function assertSeedanceAudioReferences(audioReferences: ReferenceAudio[]) {
    let total = 0;
    for (const audio of audioReferences) {
        if (!audio.durationMs) continue;
        if (audio.durationMs < 2000 || audio.durationMs > 15000) throw new Error("Seedance 参考音频单个时长需要在 2-15 秒之间");
        total += audio.durationMs;
    }
    if (total > 15000) throw new Error("Seedance 参考音频总时长不能超过 15 秒");
}

export async function videoResultFromCompletedJob(job: JobRecord, options?: RequestOptions): Promise<VideoGenerationResult> {
    if (job.status !== "succeeded") throw new Error(jobErrorMessage(job, "视频生成失败"));
    const output = firstVideoOutput(job.result);
    if (!output) throw new Error("视频任务没有返回可播放结果");
    const scope = job.scope || "personal";
    const contentType = stringValue(output.content_type) || stringValue(output.mimeType) || "video/mp4";
    const assetId = stringValue(output.asset_id) || stringValue(output.id);
    if (assetId) {
        const blob = await downloadServerAsset(serverAssetStorageKey({ id: assetId, type: "video", scope }), scope);
        if (blob) {
            await assertVideoBlob(blob);
            return { blob, mimeType: blob.type || contentType };
        }
    }
    const assetUrl = stringValue(output.asset_url);
    if (assetUrl) return videoResultFromAuthenticatedUrl(assetUrl, contentType, options);
    const remoteUrl = stringValue(output.remote_url) || stringValue(output.url);
    if (remoteUrl) return videoResultFromUrl(remoteUrl, options);
    throw new Error("视频任务没有返回可播放结果");
}

export async function waitForVideoJob(jobId: string, options?: RequestOptions) {
    const job = await waitForJob(jobId, options);
    return videoResultFromCompletedJob(job, options);
}

function firstVideoOutput(result: unknown) {
    if (!isRecord(result)) return null;
    const outputs = Array.isArray(result.outputs) ? result.outputs.filter(isRecord) : [];
    if (outputs.length) return outputs[0];
    const assets = Array.isArray(result.assets) ? result.assets.filter(isRecord) : [];
    if (assets.length) return { ...assets[0], asset_id: assets[0].id, asset_url: assets[0].url };
    return result;
}

async function buildSeedanceContent(config: AiConfig, prompt: string, references: ReferenceImage[], videoReferences: ReferenceVideo[], audioReferences: ReferenceAudio[]) {
    const content: Array<Record<string, unknown>> = [];
    const text = buildSeedancePromptText(prompt, references, videoReferences, audioReferences);
    if (text) content.push({ type: "text", text });
    const imageReferences = references.slice(0, SEEDANCE_REFERENCE_LIMITS.images);
    const imageBudgetBytes = seedanceImageReferenceBudget(imageReferences.length);
    for (const image of imageReferences) {
        content.push({ type: "image_url", image_url: { url: await resolveSeedanceImageUrl(image, imageBudgetBytes) }, role: "reference_image" });
    }
    for (const video of videoReferences.slice(0, SEEDANCE_REFERENCE_LIMITS.videos)) {
        content.push({ type: "video_url", video_url: { url: await resolveSeedanceVideoUrl(video) }, role: "reference_video" });
    }
    for (const audio of audioReferences.slice(0, SEEDANCE_REFERENCE_LIMITS.audios)) {
        content.push({ type: "audio_url", audio_url: { url: await resolveSeedanceAudioUrl(audio) }, role: "reference_audio" });
    }
    return content;
}

function seedanceImageReferenceBudget(count: number) {
    return Math.max(220 * 1024, Math.floor(SEEDANCE_IMAGE_DATA_URL_MAX_BYTES / Math.max(1, count)));
}

async function resolveSeedanceImageUrl(image: ReferenceImage, targetBytes: number) {
    const directUrl = image.url || image.dataUrl;
    if (isPublicMediaUrl(directUrl) || directUrl.startsWith("asset://")) return directUrl;
    const dataUrl = await imageToDataUrl(image);
    if (!dataUrl) throw new Error("参考图读取失败，请换一张图片或重新上传");
    return compressSeedanceImageDataUrl(dataUrl, targetBytes);
}

function hasAssetReference(references: ReferenceImage[]) {
    return references.some((reference) => (reference.url || reference.dataUrl || reference.storageKey || "").startsWith("asset://"));
}

function hasMediaAssetReference(references: Array<{ url?: string; storageKey?: string }>) {
    return references.some((reference) => (reference.url || reference.storageKey || "").startsWith("asset://"));
}

async function compressSeedanceImageDataUrl(dataUrl: string, targetBytes: number) {
    const normalized = ensureImageDataUrlMimeType(dataUrl);
    if (!normalized.startsWith("data:image/")) return normalized;
    const sourceBytes = getDataUrlByteSize(normalized);
    if (sourceBytes > 0 && sourceBytes <= targetBytes) return normalized;

    const meta = await readImageMeta(normalized);
    const sourceWidth = Math.max(1, meta.width || SEEDANCE_IMAGE_DATA_URL_MAX_EDGE);
    const sourceHeight = Math.max(1, meta.height || SEEDANCE_IMAGE_DATA_URL_MAX_EDGE);
    let bestDataUrl = normalized;
    let bestBytes = sourceBytes || Number.MAX_SAFE_INTEGER;

    for (const step of SEEDANCE_IMAGE_COMPRESSION_STEPS) {
        const scale = Math.min(1, step.edge / Math.max(sourceWidth, sourceHeight));
        const width = Math.max(1, Math.round(sourceWidth * scale));
        const height = Math.max(1, Math.round(sourceHeight * scale));
        const candidate = await resizeImageDataUrl(normalized, width, height, {
            mimeType: "image/jpeg",
            quality: step.quality,
        });
        const candidateBytes = getDataUrlByteSize(candidate);
        if (candidateBytes > 0 && candidateBytes < bestBytes) {
            bestDataUrl = candidate;
            bestBytes = candidateBytes;
        }
        if (candidateBytes > 0 && candidateBytes <= targetBytes) return candidate;
    }

    if (bestBytes <= targetBytes) return bestDataUrl;
    const mb = (targetBytes / 1024 / 1024).toFixed(1);
    const type = imageDataUrlMimeType(bestDataUrl);
    throw new Error(`Seedance 参考图压缩后仍超过 ${mb}MB（${type}），请先压缩图片或改用公网 URL/asset:// 素材`);
}

async function resolveSeedanceVideoUrl(video: ReferenceVideo) {
    if (isPublicMediaUrl(video.url) || video.url.startsWith("asset://")) return video.url;
    let blob: Blob | null = null;
    if (video.storageKey) blob = await getMediaBlob(video.storageKey);
    if (!blob && video.url?.startsWith("blob:")) blob = await (await fetch(video.url)).blob();
    if (!blob) throw new Error("参考视频必须是公网 URL、素材 ID，或本地已保存的视频");
    return blobToDataUrl(blob);
}

async function resolveSeedanceAudioUrl(audio: ReferenceAudio) {
    if (isPublicMediaUrl(audio.url) || audio.url.startsWith("asset://")) return audio.url;
    let blob: Blob | null = null;
    if (audio.storageKey) blob = await getMediaBlob(audio.storageKey);
    if (!blob && audio.url?.startsWith("blob:")) blob = await (await fetch(audio.url)).blob();
    if (!blob) throw new Error("参考音频必须是公网 URL、素材 ID，或本地已保存的音频");
    return blobToDataUrl(blob);
}

async function videoResultFromUrl(url: string, options?: RequestOptions): Promise<VideoGenerationResult> {
    try {
        const response = await axios.get<Blob>(url, { responseType: "blob", signal: options?.signal });
        await assertVideoBlob(response.data);
        return { blob: response.data };
    } catch (error) {
        if (axios.isCancel(error) || options?.signal?.aborted) throw error;
        return { url, mimeType: "video/mp4" };
    }
}

async function videoResultFromSeedanceTaskContent(task: VideoGenerationTask, fallbackUrl: string, options?: RequestOptions): Promise<VideoGenerationResult> {
    try {
        return await videoResultFromAuthenticatedUrl(`/api/ai/contents/generations/tasks/${encodeURIComponent(task.id)}/content?model=${encodeURIComponent(task.model)}`, "video/mp4", options);
    } catch (error) {
        if (axios.isCancel(error) || options?.signal?.aborted) throw error;
        return videoResultFromUrl(fallbackUrl, options);
    }
}

async function videoResultFromAuthenticatedUrl(url: string, mimeType: string, options?: RequestOptions): Promise<VideoGenerationResult> {
    const content = await axios.get<Blob>(url.startsWith("/") ? `${API_BASE_URL}${url}` : url, { headers: apiHeaders(), withCredentials: true, responseType: "blob", signal: options?.signal });
    await assertVideoBlob(content.data);
    return { blob: content.data, mimeType: content.data.type || mimeType };
}

function assertVideoConfig(model: string) {
    if (!model) throw new Error("请先配置视频模型");
}

function normalizeVideoSeconds(value: string) {
    const seconds = Math.floor(Number(value) || 6);
    return String(Math.max(1, Math.min(20, seconds)));
}

function normalizeVideoSize(value: string) {
    if (value === "auto") return null;
    const size = value || "1280x720";
    if (/^\d+x\d+$/.test(size)) return size;
    return ["9:16", "2:3", "3:4"].includes(size) ? "720x1280" : "1280x720";
}

function normalizeVideoResolution(value: string) {
    if (value === "low") return "480p";
    if (value === "auto" || value === "high" || value === "medium") return "720p";
    const resolution = value.replace(/p$/i, "") || "720";
    return `${resolution}p`;
}

function unwrapSeedanceTask(payload: ApiEnvelope<SeedanceTask>) {
    return unwrapEnvelope(payload, "Seedance 接口没有返回任务");
}

function unwrapEnvelope<T>(payload: ApiEnvelope<T>, emptyMessage: string): T {
    if (!payload) throw new Error(emptyMessage);
    if (typeof payload === "object" && "code" in payload && typeof payload.code === "number") {
        if (payload.code !== 0) throw new Error(payload.msg || "请求失败");
        if (!payload.data) throw new Error(emptyMessage);
        return payload.data;
    }
    return payload as T;
}

function readAxiosError(error: unknown, fallback: string) {
    if (axios.isCancel(error)) return "请求已取消";
    if (axios.isAxiosError<{ error?: { message?: string }; msg?: string; code?: number }>(error)) {
        const responseData = error.response?.data;
        return responseData?.msg || responseData?.error?.message || statusMessage(error.response?.status, fallback);
    }
    if (error instanceof DOMException && error.name === "AbortError") return "请求已取消";
    return error instanceof Error ? error.message : fallback;
}

function statusMessage(status: number | undefined, fallback: string) {
    if (status === 400) return "请联系管理员配置视频模型服务";
    if (status === 401 || status === 403) return "模型服务暂不可用，请联系管理员检查权限或模型服务";
    if (status === 429) return "请求被限流或额度不足，请稍后重试";
    return status ? `${fallback}（${status}）` : fallback;
}

function apiHeaders() {
    const token = getStoredAuthToken();
    return token ? { Authorization: `Bearer ${token}` } : {};
}

async function assertVideoBlob(blob: Blob) {
    if (!blob.type.includes("json")) return;
    let payload: { code?: number; msg?: string; error?: { message?: string } };
    try {
        payload = JSON.parse(await blob.text()) as { code?: number; msg?: string; error?: { message?: string } };
    } catch {
        return;
    }
    if (typeof payload.code === "number" && payload.code !== 0) throw new Error(payload.msg || "视频下载失败");
    if (payload.error?.message) throw new Error(payload.error.message);
}

function isPublicMediaUrl(value: string) {
    return /^https?:\/\//i.test(value || "");
}

function isRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function stringValue(value: unknown) {
    return typeof value === "string" ? value.trim() : "";
}

function delay(ms: number, signal?: AbortSignal) {
    return new Promise<void>((resolve, reject) => {
        if (signal?.aborted) {
            reject(new DOMException("Aborted", "AbortError"));
            return;
        }
        const timer = setTimeout(resolve, ms);
        signal?.addEventListener(
            "abort",
            () => {
                clearTimeout(timer);
                reject(new DOMException("Aborted", "AbortError"));
            },
            { once: true },
        );
    });
}

function blobToDataUrl(blob: Blob) {
    return new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(new Error("读取本地素材失败"));
        reader.readAsDataURL(blob);
    });
}
