import type { ViewportTransform } from "../types";

export const MIDDLE_PAN_DOUBLE_CLICK_MS = 260;

export type MiddlePanMode = "idle" | "hold-pan" | "locked-pan";

export type MiddlePanState = {
    mode: MiddlePanMode;
    startX: number;
    startY: number;
    lastX: number;
    lastY: number;
    initialViewport: ViewportTransform;
    lastMiddleDownAt: number;
    hasMoved: boolean;
};

export function createMiddlePanState(): MiddlePanState {
    return {
        mode: "idle",
        startX: 0,
        startY: 0,
        lastX: 0,
        lastY: 0,
        initialViewport: { x: 0, y: 0, k: 1 },
        lastMiddleDownAt: 0,
        hasMoved: false,
    };
}

export function startMiddlePanHold(state: MiddlePanState, clientX: number, clientY: number, viewport: ViewportTransform) {
    state.mode = "hold-pan";
    state.startX = clientX;
    state.startY = clientY;
    state.lastX = clientX;
    state.lastY = clientY;
    state.initialViewport = viewport;
    state.hasMoved = false;
}

export function enterMiddlePanLock(state: MiddlePanState, clientX: number, clientY: number, viewport: ViewportTransform) {
    state.mode = "locked-pan";
    state.startX = clientX;
    state.startY = clientY;
    state.lastX = clientX;
    state.lastY = clientY;
    state.initialViewport = viewport;
    state.hasMoved = false;
}

export function stopMiddlePan(state: MiddlePanState) {
    state.mode = "idle";
    state.hasMoved = false;
}

export function shouldEnterLockedPan(state: MiddlePanState, now = Date.now()) {
    const locked = now - state.lastMiddleDownAt <= MIDDLE_PAN_DOUBLE_CLICK_MS;
    state.lastMiddleDownAt = now;
    return locked;
}

export function nextHoldPanViewport(state: MiddlePanState, clientX: number, clientY: number, scale: number) {
    const dx = clientX - state.startX;
    const dy = clientY - state.startY;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) state.hasMoved = true;
    state.lastX = clientX;
    state.lastY = clientY;
    return { x: state.initialViewport.x + dx, y: state.initialViewport.y + dy, k: scale };
}

export function nextLockedPanViewport(state: MiddlePanState, clientX: number, clientY: number, viewport: ViewportTransform) {
    const dx = clientX - state.lastX;
    const dy = clientY - state.lastY;
    state.lastX = clientX;
    state.lastY = clientY;
    if (Math.abs(dx) > 0 || Math.abs(dy) > 0) state.hasMoved = true;
    return { x: viewport.x + dx, y: viewport.y + dy, k: viewport.k };
}

export function setGlobalPanCursor(active: boolean) {
    if (typeof document === "undefined") return;
    document.body.style.cursor = active ? "grabbing" : "default";
}
