"use client";

import type { UserRole } from "@/stores/use-user-store";

export const LEGACY_CANVAS_STORE_KEY = "infinite-canvas:canvas_store";
export const LEGACY_ASSET_STORE_KEY = "infinite-canvas:asset_store";
export const USER_PREFERENCE_STORE_KEY = "infinite-canvas:user_preferences";
const ANONYMOUS_SCOPE = "anonymous";
const migratedLegacyKeyPrefix = "infinite-canvas:legacy_migrated:";

let currentUserScope = ANONYMOUS_SCOPE;

export function currentUserStorageScope() {
    return currentUserScope;
}

export function setCurrentUserStorageScope(userId?: string) {
    currentUserScope = sanitizeStorageScope(userId || ANONYMOUS_SCOPE);
}

export function scopedCanvasStoreKey(userId = currentUserScope) {
    return `${LEGACY_CANVAS_STORE_KEY}:${sanitizeStorageScope(userId)}`;
}

export function scopedAssetStoreKey(userId = currentUserScope) {
    return `${LEGACY_ASSET_STORE_KEY}:${sanitizeStorageScope(userId)}`;
}

export function scopedUserPreferenceStoreKey(userId = currentUserScope) {
    return `${USER_PREFERENCE_STORE_KEY}:${sanitizeStorageScope(userId)}`;
}

export type UserScopedStoreKind = "canvas" | "asset";

export function shouldMigrateLegacyLocalData(user: { id: string; role: UserRole } | null | undefined, kind: UserScopedStoreKind) {
    if (!user || user.role !== "super_admin") return false;
    return typeof window !== "undefined" && window.localStorage.getItem(migratedLegacyKey(user.id, kind)) !== "1";
}

export function markLegacyLocalDataMigrated(userId: string, kind: UserScopedStoreKind) {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(migratedLegacyKey(userId, kind), "1");
}

function migratedLegacyKey(userId: string, kind: UserScopedStoreKind) {
    return `${migratedLegacyKeyPrefix}${kind}:${sanitizeStorageScope(userId)}`;
}

function sanitizeStorageScope(value: string) {
    return value.replace(/[^a-zA-Z0-9_-]+/g, "_") || ANONYMOUS_SCOPE;
}
