import { imageReferenceLabel } from "@/lib/image-reference-prompt";
import { seedanceReferenceLabel } from "@/lib/seedance-video";
import { serverAssetContentUrl, serverAssetIdFromStorageKey, serverAssetStorageKey, type ServerAsset } from "@/services/api/assets";
import type { Asset } from "@/stores/use-asset-store";
import type { WorkspaceScope } from "@/stores/use-workspace-scope-store";
import type { ReferenceImage } from "@/types/image";
import type { ReferenceAudio, ReferenceVideo } from "@/types/media";
import { CanvasNodeType, type CanvasConnection, type CanvasNodeData } from "../types";

export type CanvasResourceKind = "image" | "video" | "audio" | "text";
export type CanvasResourceSource = "canvas-node" | "asset-library";

export type CanvasResourceReference = {
    id: string;
    mentionKey: string;
    mentionSource: "node" | "asset";
    targetId: string;
    source: CanvasResourceSource;
    nodeId?: string;
    assetId?: string;
    kind: CanvasResourceKind;
    label: string;
    sourceLabel: string;
    title: string;
    previewUrl?: string;
    text?: string;
    searchText?: string;
    active: boolean;
    image?: ReferenceImage;
    video?: ReferenceVideo;
    audio?: ReferenceAudio;
};

export function buildCanvasResourceReferences(nodes: CanvasNodeData[], connections: CanvasConnection[], contextNodeId?: string | null, assets: Asset[] = [], serverAssets: ServerAsset[] = [], scope: WorkspaceScope = "personal") {
    const contextReferences = contextNodeId ? buildNodeMentionReferencesById(contextNodeId, nodes, connections, assets, serverAssets, scope) : [];
    const activeByKey = new Map(contextReferences.map((reference) => [reference.mentionKey, reference]));
    const globalReferences = [...labelResourceNodes(nodes.filter(isResourceNode), false), ...labelAllAssetReferences(assets, serverAssets, false, scope)];
    return globalReferences.map((reference) => activeByKey.get(reference.mentionKey) || reference);
}

export function buildNodeMentionReferences(node: CanvasNodeData, nodes: CanvasNodeData[], connections: CanvasConnection[], assets: Asset[] = [], serverAssets: ServerAsset[] = [], scope: WorkspaceScope = "personal") {
    return buildNodeMentionReferencesById(node.id, nodes, connections, assets, serverAssets, scope);
}

export function buildNodeMentionReferencesById(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[], assets: Asset[] = [], serverAssets: ServerAsset[] = [], scope: WorkspaceScope = "personal") {
    return [...labelResourceNodes(getMentionResourceNodes(nodeId, nodes, connections), true), ...labelAllAssetReferences(assets, serverAssets, true, scope)];
}

export function getMentionResourceNodes(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[]) {
    return getConnectedComponentResourceNodes(nodeId, nodes, connections);
}

export function getGenerationResourceNodes(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[]) {
    const configInputs = getConnectedConfigResourceNodes(nodeId, nodes, connections);
    if (configInputs.length) return configInputs;
    const ownInputs = getContextResourceNodes(nodeId, nodes, connections);
    if (ownInputs.length) return ownInputs;
    const self = nodes.find((node) => node.id === nodeId);
    if (self && isDirectUploadResourceNode(self)) return [self];
    return [];
}

export function getConnectedComponentResourceNodes(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[]) {
    const nodeById = new Map(nodes.map((node) => [node.id, node]));
    if (!nodeById.has(nodeId)) return [];
    const related = new Map<string, Set<string>>();
    const addEdge = (a: string, b: string) => {
        if (!related.has(a)) related.set(a, new Set());
        if (!related.has(b)) related.set(b, new Set());
        related.get(a)!.add(b);
        related.get(b)!.add(a);
    };
    connections.forEach((connection) => addEdge(connection.fromNodeId, connection.toNodeId));

    const result: CanvasNodeData[] = [];
    const visited = new Set<string>();
    const queue = [nodeId];
    while (queue.length) {
        const id = queue.shift()!;
        if (visited.has(id)) continue;
        visited.add(id);
        const node = nodeById.get(id);
        if (node && id !== nodeId && isResourceNode(node)) result.push(node);
        related.get(id)?.forEach((nextId) => {
            if (!visited.has(nextId)) queue.push(nextId);
        });
    }
    return result;
}

function getContextResourceNodes(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[]) {
    return connections
        .filter((connection) => connection.toNodeId === nodeId)
        .map((connection) => nodes.find((node) => node.id === connection.fromNodeId))
        .filter((node): node is CanvasNodeData => Boolean(node && isResourceNode(node)));
}

function getConnectedConfigResourceNodes(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[]) {
    const configConnection = connections.find((connection) => connection.fromNodeId === nodeId && nodes.find((node) => node.id === connection.toNodeId)?.type === CanvasNodeType.Config);
    if (!configConnection) return [];
    return getContextResourceNodes(configConnection.toNodeId, nodes, connections).filter((node) => node.id !== nodeId);
}

function labelResourceNodes(nodes: CanvasNodeData[], active: boolean) {
    const counts: Record<CanvasResourceKind, number> = { image: 0, video: 0, audio: 0, text: 0 };
    return nodes.flatMap((node): CanvasResourceReference[] => {
        const kind = resourceKind(node);
        if (!kind) return [];
        const index = counts[kind]++;
        const sourceLabel = labelForKind(kind, index);
        const title = node.title?.trim() || sourceLabel;
        const image = readReferenceImage(node);
        const video = readReferenceVideo(node);
        const audio = readReferenceAudio(node);
        return [
            {
                id: node.id,
                mentionKey: `node:${node.id}`,
                mentionSource: "node",
                targetId: node.id,
                source: "canvas-node",
                nodeId: node.id,
                kind,
                label: title,
                sourceLabel,
                title,
                previewUrl: node.metadata?.content,
                text: node.type === CanvasNodeType.Text ? node.metadata?.content || node.metadata?.prompt : undefined,
                searchText: [sourceLabel, node.title, node.metadata?.prompt, node.metadata?.content].filter(Boolean).join(" "),
                active,
                image: image || undefined,
                video: video || undefined,
                audio: audio || undefined,
            },
        ];
    });
}

function labelAssetReferences(assets: Asset[], active: boolean) {
    const counts: Record<Exclude<CanvasResourceKind, "audio">, number> = { image: 0, video: 0, text: 0 };
    return assets.flatMap((asset): CanvasResourceReference[] => {
        if (asset.kind !== "image" && asset.kind !== "video" && asset.kind !== "text") return [];
        const kind = asset.kind;
        const index = counts[kind]++;
        const sourceLabel = `素材${index + 1}`;
        const title = asset.title?.trim() || sourceLabel;
        const text = asset.kind === "text" ? asset.data.content : undefined;
        const image =
            asset.kind === "image"
                ? {
                      id: asset.id,
                      name: `${asset.title || asset.id}.png`,
                      type: asset.data.mimeType || "image/png",
                      dataUrl: asset.data.dataUrl,
                      storageKey: asset.data.storageKey,
                  }
                : undefined;
        const video =
            asset.kind === "video"
                ? {
                      id: asset.id,
                      name: `${asset.title || asset.id}.mp4`,
                      type: asset.data.mimeType || "video/mp4",
                      url: asset.data.url,
                      storageKey: asset.data.storageKey,
                      bytes: asset.data.bytes,
                      width: asset.data.width,
                      height: asset.data.height,
                  }
                : undefined;
        return [
            {
                id: `asset:${asset.id}`,
                mentionKey: `asset:${asset.id}`,
                mentionSource: "asset",
                targetId: asset.id,
                source: "asset-library",
                assetId: asset.id,
                kind,
                label: title,
                sourceLabel,
                title,
                previewUrl: asset.coverUrl || (asset.kind === "image" ? asset.data.dataUrl : asset.kind === "video" ? asset.data.url : undefined),
                text,
                searchText: [sourceLabel, asset.title, asset.source, asset.note, ...(asset.tags || []), kindLabel(kind), text].filter(Boolean).join(" "),
                active,
                image,
                video,
            },
        ];
    });
}

function labelAllAssetReferences(assets: Asset[], serverAssets: ServerAsset[], active: boolean, scope: WorkspaceScope) {
    const localServerAssetIds = new Set(assets.map(localServerAssetId).filter(Boolean));
    return [
        ...labelAssetReferences(assets, active),
        ...labelServerAssetReferences(serverAssets.filter((asset) => !localServerAssetIds.has(asset.id)), active, scope),
    ];
}

function labelServerAssetReferences(assets: ServerAsset[], active: boolean, fallbackScope: WorkspaceScope) {
    return assets.flatMap((asset): CanvasResourceReference[] => {
        if (asset.type !== "image" && asset.type !== "video" && asset.type !== "audio") return [];
        const scope = asset.scope || fallbackScope;
        const kind = asset.type;
        const title = asset.name?.trim() || "未命名资产";
        const storageKey = serverAssetStorageKey(asset, scope);
        const contentUrl = serverAssetContentUrl(asset, scope);
        const image = kind === "image" ? { id: asset.id, name: title, type: asset.content_type || "image/png", dataUrl: contentUrl, storageKey } : undefined;
        const video = kind === "video" ? { id: asset.id, name: title, type: asset.content_type || "video/mp4", url: contentUrl, storageKey, bytes: asset.size } : undefined;
        const audio = kind === "audio" ? { id: asset.id, name: title, type: asset.content_type || "audio/mpeg", url: contentUrl, storageKey } : undefined;
        return [
            {
                id: `server-asset:${asset.id}`,
                mentionKey: `asset:${asset.id}`,
                mentionSource: "asset",
                targetId: asset.id,
                source: "asset-library",
                assetId: asset.id,
                kind,
                label: title,
                sourceLabel: "资产库",
                title,
                searchText: [title, asset.category, asset.source_type, asset.source_project_id, asset.note, ...(asset.tags || []), kindLabel(kind)].filter(Boolean).join(" "),
                active,
                image,
                video,
                audio,
            },
        ];
    });
}

function localServerAssetId(asset: Asset) {
    const metadataId = typeof asset.metadata?.serverAssetId === "string" ? asset.metadata.serverAssetId : "";
    if (metadataId) return metadataId;
    if (asset.kind === "image") return serverAssetIdFromStorageKey(asset.data.storageKey);
    if (asset.kind === "video") return serverAssetIdFromStorageKey(asset.data.storageKey);
    return "";
}

function labelForKind(kind: CanvasResourceKind, index: number) {
    if (kind === "image") return imageReferenceLabel(index);
    if (kind === "video") return seedanceReferenceLabel("video", index);
    if (kind === "audio") return seedanceReferenceLabel("audio", index);
    return `文本${index + 1}`;
}

function kindLabel(kind: CanvasResourceKind) {
    if (kind === "image") return "图片";
    if (kind === "video") return "视频";
    if (kind === "audio") return "音频";
    return "文本";
}

function isResourceNode(node: CanvasNodeData) {
    return Boolean(resourceKind(node));
}

function isDirectUploadResourceNode(node: CanvasNodeData) {
    if (node.type !== CanvasNodeType.Image && node.type !== CanvasNodeType.Video && node.type !== CanvasNodeType.Audio) return false;
    return Boolean(node.metadata?.content);
}

function resourceKind(node: CanvasNodeData): CanvasResourceKind | null {
    if (node.type === CanvasNodeType.Image && node.metadata?.content) return "image";
    if (node.type === CanvasNodeType.Video && node.metadata?.content) return "video";
    if (node.type === CanvasNodeType.Audio && node.metadata?.content) return "audio";
    if (node.type === CanvasNodeType.Text && (node.metadata?.content || node.metadata?.prompt)) return "text";
    return null;
}

function readReferenceImage(node: CanvasNodeData): ReferenceImage | null {
    if (node.type !== CanvasNodeType.Image || !node.metadata?.content) return null;
    return {
        id: node.id,
        name: `${node.title || node.id}.png`,
        type: node.metadata.mimeType || "image/png",
        dataUrl: node.metadata.content,
        storageKey: node.metadata.storageKey,
    };
}

function readReferenceVideo(node: CanvasNodeData): ReferenceVideo | null {
    if (node.type !== CanvasNodeType.Video || !node.metadata?.content) return null;
    return {
        id: node.id,
        name: `${node.title || node.id}.mp4`,
        type: node.metadata.mimeType || "video/mp4",
        url: node.metadata.content,
        storageKey: node.metadata.storageKey,
        bytes: node.metadata.bytes,
        width: node.metadata.naturalWidth,
        height: node.metadata.naturalHeight,
        durationMs: node.metadata.durationMs,
    };
}

function readReferenceAudio(node: CanvasNodeData): ReferenceAudio | null {
    if (node.type !== CanvasNodeType.Audio || !node.metadata?.content) return null;
    return {
        id: node.id,
        name: `${node.title || node.id}.mp3`,
        type: node.metadata.mimeType || "audio/mpeg",
        url: node.metadata.content,
        storageKey: node.metadata.storageKey,
        durationMs: node.metadata.durationMs,
    };
}
