"use client";

import { useMemo, useState } from "react";
import { Button, Empty, Input, Popover, Tag } from "antd";
import { Check, ChevronDown, Clock3, Plus, Search } from "lucide-react";

import type { WorkspaceScope } from "@/stores/use-workspace-scope-store";
import type { CanvasProject } from "../stores/use-canvas-store";

export function CanvasProjectSwitcher({
    title,
    currentProjectId,
    projects,
    scope,
    onSwitch,
    onCreate,
    onStartTitleEditing,
}: {
    title: string;
    currentProjectId: string;
    projects: CanvasProject[];
    scope: WorkspaceScope;
    onSwitch: (projectId: string) => void;
    onCreate: () => void;
    onStartTitleEditing: () => void;
}) {
    const [open, setOpen] = useState(false);
    const [keyword, setKeyword] = useState("");
    const recentProjects = useMemo(() => {
        const normalized = keyword.trim().toLowerCase();
        return [...projects]
            .filter((project) => !normalized || project.title.toLowerCase().includes(normalized))
            .sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt));
    }, [keyword, projects]);

    const content = (
        <div className="w-[340px] max-w-[calc(100vw-32px)] p-1" data-testid="canvas-project-switcher">
            <div className="mb-2 flex items-center justify-between gap-2">
                <div>
                    <div className="text-sm font-semibold">切换画布</div>
                    <div className="mt-0.5 text-xs opacity-55">{scope === "team" ? "团队空间" : "个人空间"} · 最近使用</div>
                </div>
                <Button
                    size="small"
                    type="primary"
                    icon={<Plus className="size-3.5" />}
                    data-testid="canvas-project-switcher-create"
                    onClick={() => {
                        setOpen(false);
                        onCreate();
                    }}
                >
                    新建
                </Button>
            </div>
            <Input value={keyword} prefix={<Search className="size-4 opacity-45" />} placeholder="搜索当前工作空间画布" allowClear onChange={(event) => setKeyword(event.target.value)} />
            <div className="thin-scrollbar mt-2 max-h-[320px] space-y-1 overflow-y-auto pr-1">
                {recentProjects.map((project) => {
                    const current = project.id === currentProjectId;
                    return (
                        <button
                            key={project.id}
                            type="button"
                            className="flex w-full items-center gap-2 rounded-lg border border-transparent px-2.5 py-2 text-left transition hover:border-white/10 hover:bg-white/[0.06]"
                            data-testid="canvas-project-switcher-item"
                            data-current={current ? "true" : "false"}
                            onClick={() => {
                                if (!current) onSwitch(project.id);
                                setOpen(false);
                            }}
                        >
                            <Clock3 className="size-4 shrink-0 opacity-45" />
                            <span className="min-w-0 flex-1 truncate text-sm font-medium">{project.title}</span>
                            {current ? <Check className="size-4 shrink-0 text-emerald-400" /> : project.syncStatus === "pending" || project.syncStatus === "conflict" ? <Tag className="m-0 shrink-0">待同步</Tag> : null}
                        </button>
                    );
                })}
                {!recentProjects.length ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="没有匹配的画布" className="py-5" /> : null}
            </div>
            <div className="mt-2 border-t border-white/10 pt-2 text-xs opacity-50">双击当前名称可重命名；切换前会先保存当前快照。</div>
        </div>
    );

    return (
        <Popover trigger="click" placement="bottomLeft" open={open} onOpenChange={setOpen} content={content}>
            <button
                type="button"
                className="flex max-w-[300px] items-center gap-1.5 truncate border-b border-dashed border-transparent text-left text-lg font-black tracking-normal transition hover:border-current"
                title="单击切换画布，双击修改名称"
                data-testid="canvas-project-switcher-trigger"
                onDoubleClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    setOpen(false);
                    onStartTitleEditing();
                }}
            >
                <span className="min-w-0 truncate">{title}</span>
                <ChevronDown className="size-4 shrink-0 opacity-55" />
            </button>
        </Popover>
    );
}
