"use client";

import { useEffect, useState } from "react";
import { Button, Input, Modal, Slider } from "antd";
import { Check, X } from "lucide-react";

import { readImageMeta } from "@/lib/image-utils";
import type { OutpaintMargins } from "../utils/canvas-image-data";

export type CanvasImageOutpaintPayload = {
    margins: OutpaintMargins;
    prompt: string;
};

const DEFAULT_OUTPAINT_MARGIN = 0.22; // Percentage of the source edge added on each side by default.
const MAX_OUTPAINT_MARGIN = 0.75;

export function CanvasNodeOutpaintDialog({ dataUrl, open, onClose, onConfirm }: { dataUrl: string; open: boolean; onClose: () => void; onConfirm: (payload: CanvasImageOutpaintPayload) => void }) {
    const [margins, setMargins] = useState<OutpaintMargins>({ top: DEFAULT_OUTPAINT_MARGIN, right: DEFAULT_OUTPAINT_MARGIN, bottom: DEFAULT_OUTPAINT_MARGIN, left: DEFAULT_OUTPAINT_MARGIN });
    const [prompt, setPrompt] = useState("延展画面边缘，保持主体、光线、材质和画风一致");
    const [image, setImage] = useState<{ width: number; height: number } | null>(null);

    useEffect(() => {
        if (!open) return;
        setMargins({ top: DEFAULT_OUTPAINT_MARGIN, right: DEFAULT_OUTPAINT_MARGIN, bottom: DEFAULT_OUTPAINT_MARGIN, left: DEFAULT_OUTPAINT_MARGIN });
        setPrompt("延展画面边缘，保持主体、光线、材质和画风一致");
        void readImageMeta(dataUrl).then(setImage);
    }, [dataUrl, open]);

    const updateMargin = (key: keyof OutpaintMargins, value: number) => setMargins((current) => ({ ...current, [key]: value }));
    const targetSize = image
        ? {
              width: Math.round(image.width * (1 + margins.left + margins.right)),
              height: Math.round(image.height * (1 + margins.top + margins.bottom)),
          }
        : null;

    return (
        <Modal className="canvas-themed-modal" title="扩图" open={open && Boolean(dataUrl)} onCancel={onClose} footer={null} width={900} centered destroyOnHidden>
            <div className="grid gap-5 md:grid-cols-[minmax(260px,1fr)_320px]" data-testid="canvas-image-outpaint-dialog">
                <div className="grid min-h-[360px] place-items-center rounded-xl border border-[#b84dff4d] bg-neutral-950 p-5">
                    <div
                        className="relative w-full max-w-[560px] overflow-hidden rounded-lg border border-white/15 bg-[linear-gradient(45deg,rgba(255,255,255,.08)_25%,transparent_25%,transparent_75%,rgba(255,255,255,.08)_75%),linear-gradient(45deg,rgba(255,255,255,.08)_25%,transparent_25%,transparent_75%,rgba(255,255,255,.08)_75%)] bg-[length:22px_22px] bg-[position:0_0,11px_11px]"
                        style={{ aspectRatio: image ? `${image.width * (1 + margins.left + margins.right)} / ${image.height * (1 + margins.top + margins.bottom)}` : "16 / 10" }}
                    >
                        <img
                            src={dataUrl}
                            alt=""
                            draggable={false}
                            className="absolute object-fill"
                            style={{
                                left: `${(margins.left / (1 + margins.left + margins.right)) * 100}%`,
                                top: `${(margins.top / (1 + margins.top + margins.bottom)) * 100}%`,
                                width: `${(1 / (1 + margins.left + margins.right)) * 100}%`,
                                height: `${(1 / (1 + margins.top + margins.bottom)) * 100}%`,
                            }}
                        />
                        <div className="pointer-events-none absolute inset-0 border-2 border-dashed border-[#ff4f8c]" />
                    </div>
                </div>

                <div className="space-y-4">
                    <div className="rounded-lg border border-[#b84dff4d] bg-white/[0.045] p-3 text-sm">
                        <div className="font-semibold">目标尺寸</div>
                        <div className="mt-1 opacity-70">{targetSize ? `${targetSize.width} x ${targetSize.height}` : "读取中"}</div>
                    </div>
                    <MarginSlider label="上" value={margins.top} onChange={(value) => updateMargin("top", value)} />
                    <MarginSlider label="右" value={margins.right} onChange={(value) => updateMargin("right", value)} />
                    <MarginSlider label="下" value={margins.bottom} onChange={(value) => updateMargin("bottom", value)} />
                    <MarginSlider label="左" value={margins.left} onChange={(value) => updateMargin("left", value)} />
                    <Input.TextArea data-testid="canvas-image-outpaint-prompt" rows={4} value={prompt} maxLength={240} onChange={(event) => setPrompt(event.target.value)} />
                    <div className="flex justify-end gap-2">
                        <Button icon={<X className="size-4" />} onClick={onClose}>
                            取消
                        </Button>
                        <Button type="primary" icon={<Check className="size-4" />} data-testid="canvas-image-outpaint-confirm" onClick={() => onConfirm({ margins, prompt: prompt.trim() })}>
                            生成扩图
                        </Button>
                    </div>
                </div>
            </div>
        </Modal>
    );
}

function MarginSlider({ label, value, onChange }: { label: string; value: number; onChange: (value: number) => void }) {
    return (
        <div className="grid grid-cols-[24px_1fr_48px] items-center gap-3">
            <span className="font-medium">{label}</span>
            <Slider min={0} max={MAX_OUTPAINT_MARGIN} step={0.01} value={value} onChange={onChange} />
            <span className="text-right text-xs tabular-nums opacity-70">{Math.round(value * 100)}%</span>
        </div>
    );
}
