"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type KeyboardEvent as ReactKeyboardEvent, type PointerEvent as ReactPointerEvent } from "react";
import { Button, Input, Modal, Slider, Tooltip } from "antd";
import { ArrowUpRight, Brush, Check, Circle, MousePointer2, Redo2, RotateCcw, Square, Trash2, Type, Undo2, X } from "lucide-react";

import { readImageMeta } from "@/lib/image-utils";

type AnnotationTool = "select" | "rect" | "ellipse" | "arrow" | "brush" | "text";

type AnnotationPoint = {
    x: number;
    y: number;
};

type AnnotationBounds = {
    x: number;
    y: number;
    width: number;
    height: number;
};

type AnnotationBase = {
    id: string;
    color: string;
    strokeWidth: number;
};

type ShapeAnnotation = AnnotationBase & {
    type: "rect" | "ellipse" | "arrow";
    start: AnnotationPoint;
    end: AnnotationPoint;
};

type BrushAnnotation = AnnotationBase & {
    type: "brush";
    points: AnnotationPoint[];
};

type TextAnnotation = AnnotationBase & {
    type: "text";
    x: number;
    y: number;
    text: string;
    fontSize: number;
};

type ImageAnnotation = ShapeAnnotation | BrushAnnotation | TextAnnotation;

export type CanvasImageAnnotationPayload = {
    dataUrl: string;
};

type CanvasNodeAnnotationDialogProps = {
    dataUrl: string;
    open: boolean;
    onClose: () => void;
    onConfirm: (payload: CanvasImageAnnotationPayload) => void | Promise<void>;
};

type ImageMeta = {
    width: number;
    height: number;
    mimeType: string;
};

type DragState = {
    id: string;
    tool: Exclude<AnnotationTool, "select" | "text">;
    start: AnnotationPoint;
    color: string;
    strokeWidth: number;
    points: AnnotationPoint[];
};

type MoveAnnotationState = {
    id: string;
    start: AnnotationPoint;
    originalMarks: ImageAnnotation[];
    moved: boolean;
};

type ResizeAnnotationHandle = "top-left" | "top-right" | "bottom-left" | "bottom-right";

type ResizeAnnotationState = {
    id: string;
    handle: ResizeAnnotationHandle;
    originalBounds: AnnotationBounds;
    originalMarks: ImageAnnotation[];
    moved: boolean;
};

const MIN_ANNOTATION_RESIZE_SIZE = 8; // Prevent collapsed marks when resizing from a corner.
const ANNOTATION_RESIZE_HANDLE_SIZE = 18; // Image-space control size for selected annotation handles.
const ANNOTATION_DRAG_EPSILON = 0.5; // Ignore sub-pixel pointer noise while committing undo history.
const ANNOTATION_HISTORY_LIMIT = 50; // Bound undo/redo memory while retaining a useful editing history.
const MIN_ANNOTATION_FONT_SIZE = 8;
const MAX_ANNOTATION_FONT_SIZE = 160;
const annotationColors = ["#ff4f8c", "#b84dff", "#ffb33d", "#35c8ff", "#6be35f", "#ff5367", "#f8f2ff", "#120d20"];
const resizeHandles: ResizeAnnotationHandle[] = ["top-left", "top-right", "bottom-left", "bottom-right"];

const toolOptions: Array<{ id: AnnotationTool; label: string; icon: React.ReactNode }> = [
    { id: "select", label: "选择", icon: <MousePointer2 className="size-4" /> },
    { id: "rect", label: "矩形", icon: <Square className="size-4" /> },
    { id: "ellipse", label: "圆形", icon: <Circle className="size-4" /> },
    { id: "arrow", label: "箭头", icon: <ArrowUpRight className="size-4" /> },
    { id: "brush", label: "画笔", icon: <Brush className="size-4" /> },
    { id: "text", label: "文字", icon: <Type className="size-4" /> },
];

export function CanvasNodeAnnotationDialog({ dataUrl, open, onClose, onConfirm }: CanvasNodeAnnotationDialogProps) {
    const [image, setImage] = useState<ImageMeta | null>(null);
    const [tool, setTool] = useState<AnnotationTool>("rect");
    const [color, setColor] = useState(annotationColors[0]);
    const [strokeWidth, setStrokeWidth] = useState(8);
    const [textDraft, setTextDraft] = useState("标注");
    const [marks, setMarks] = useState<ImageAnnotation[]>([]);
    const [draftMark, setDraftMark] = useState<ImageAnnotation | null>(null);
    const [selectedId, setSelectedId] = useState<string | null>(null);
    const [undoStack, setUndoStack] = useState<ImageAnnotation[][]>([]);
    const [redoStack, setRedoStack] = useState<ImageAnnotation[][]>([]);
    const [editingTextId, setEditingTextId] = useState<string | null>(null);
    const [applying, setApplying] = useState(false);
    const stageRef = useRef<SVGSVGElement | null>(null);
    const inlineTextRef = useRef<HTMLTextAreaElement | null>(null);
    const dragRef = useRef<DragState | null>(null);
    const moveRef = useRef<MoveAnnotationState | null>(null);
    const resizeRef = useRef<ResizeAnnotationState | null>(null);
    const marksRef = useRef<ImageAnnotation[]>(marks);
    const textEditOriginalRef = useRef<ImageAnnotation[] | null>(null);
    const cancelingTextEditRef = useRef(false);
    const fontSizeOriginalRef = useRef<ImageAnnotation[] | null>(null);
    marksRef.current = marks;
    const selectedText = useMemo(() => marks.find((mark): mark is TextAnnotation => mark.type === "text" && mark.id === selectedId), [marks, selectedId]);
    const editingText = useMemo(() => marks.find((mark): mark is TextAnnotation => mark.type === "text" && mark.id === editingTextId), [editingTextId, marks]);

    useEffect(() => {
        if (!open) return;
        let active = true;
        setImage(null);
        setTool("rect");
        setMarks([]);
        setDraftMark(null);
        setSelectedId(null);
        setUndoStack([]);
        setRedoStack([]);
        setEditingTextId(null);
        setTextDraft("标注");
        textEditOriginalRef.current = null;
        cancelingTextEditRef.current = false;
        fontSizeOriginalRef.current = null;
        void readImageMeta(dataUrl).then((meta) => {
            if (active) setImage(meta);
        });
        return () => {
            active = false;
            dragRef.current = null;
            moveRef.current = null;
            resizeRef.current = null;
        };
    }, [dataUrl, open]);

    useEffect(() => {
        if (selectedText && !editingTextId) setTextDraft(selectedText.text);
    }, [editingTextId, selectedText?.id]);

    useEffect(() => {
        if (!editingTextId) return;
        const frame = requestAnimationFrame(() => {
            inlineTextRef.current?.focus();
            inlineTextRef.current?.select();
        });
        return () => cancelAnimationFrame(frame);
    }, [editingTextId]);

    const commitMarks = useCallback(
        (nextMarks: ImageAnnotation[]) => {
            const snapshot = cloneAnnotations(marks);
            const next = cloneAnnotations(nextMarks);
            setUndoStack((stack) => [...stack, snapshot].slice(-ANNOTATION_HISTORY_LIMIT));
            setRedoStack([]);
            marksRef.current = next;
            setMarks(next);
        },
        [marks],
    );

    const undo = useCallback(() => {
        setUndoStack((stack) => {
            const previous = stack.at(-1);
            if (!previous) return stack;
            const next = cloneAnnotations(previous);
            setRedoStack((items) => [cloneAnnotations(marksRef.current), ...items].slice(0, ANNOTATION_HISTORY_LIMIT));
            marksRef.current = next;
            setMarks(next);
            setSelectedId(null);
            setEditingTextId(null);
            textEditOriginalRef.current = null;
            return stack.slice(0, -1);
        });
    }, []);

    const redo = useCallback(() => {
        setRedoStack((stack) => {
            const next = stack[0];
            if (!next) return stack;
            const restored = cloneAnnotations(next);
            setUndoStack((items) => [...items, cloneAnnotations(marksRef.current)].slice(-ANNOTATION_HISTORY_LIMIT));
            marksRef.current = restored;
            setMarks(restored);
            setSelectedId(null);
            setEditingTextId(null);
            textEditOriginalRef.current = null;
            return stack.slice(1);
        });
    }, []);

    useEffect(() => {
        if (!open) return;
        const handleShortcut = (event: KeyboardEvent) => {
            if ((!event.ctrlKey && !event.metaKey) || event.altKey || editingTextId) return;
            const key = event.key.toLowerCase();
            if (key === "z" && event.shiftKey) {
                event.preventDefault();
                redo();
                return;
            }
            if (key === "z") {
                event.preventDefault();
                undo();
                return;
            }
            if (key === "y" && !event.shiftKey) {
                event.preventDefault();
                redo();
            }
        };
        document.addEventListener("keydown", handleShortcut, true);
        return () => document.removeEventListener("keydown", handleShortcut, true);
    }, [editingTextId, open, redo, undo]);

    const beginTextEdit = useCallback((mark: TextAnnotation) => {
        textEditOriginalRef.current = cloneAnnotations(marksRef.current);
        cancelingTextEditRef.current = false;
        setSelectedId(mark.id);
        setEditingTextId(mark.id);
        setTextDraft(mark.text);
    }, []);

    const commitTextEdit = useCallback(() => {
        const id = editingTextId;
        if (!id) return;
        const original = textEditOriginalRef.current;
        const next = marksRef.current.map((mark) => (mark.id === id && mark.type === "text" ? { ...mark, text: mark.text.trim() || "标注" } : mark));
        if (original && !annotationsEqual(original, next)) {
            setUndoStack((stack) => [...stack, cloneAnnotations(original)].slice(-ANNOTATION_HISTORY_LIMIT));
            setRedoStack([]);
        }
        marksRef.current = next;
        setMarks(next);
        setTextDraft(next.find((mark): mark is TextAnnotation => mark.id === id && mark.type === "text")?.text || "标注");
        setEditingTextId(null);
        textEditOriginalRef.current = null;
    }, [editingTextId]);

    const cancelTextEdit = useCallback(() => {
        const original = textEditOriginalRef.current;
        cancelingTextEditRef.current = true;
        if (original) {
            const restored = cloneAnnotations(original);
            marksRef.current = restored;
            setMarks(restored);
            const originalText = restored.find((mark): mark is TextAnnotation => mark.id === editingTextId && mark.type === "text");
            if (originalText) setTextDraft(originalText.text);
        }
        setEditingTextId(null);
        textEditOriginalRef.current = null;
    }, [editingTextId]);

    const handleTextEditorKeyDown = (event: ReactKeyboardEvent<HTMLTextAreaElement>) => {
        if (event.key === "Escape") {
            event.preventDefault();
            event.stopPropagation();
            event.nativeEvent.stopImmediatePropagation();
            cancelTextEdit();
            event.currentTarget.blur();
            return;
        }
        if (event.key === "Enter" && !event.shiftKey) {
            event.preventDefault();
            event.stopPropagation();
            commitTextEdit();
            event.currentTarget.blur();
        }
    };

    const handleStagePointerDown = (event: ReactPointerEvent<SVGSVGElement>) => {
        if (!image || event.button !== 0) return;
        const point = readStagePoint(event, image);
        setSelectedId(null);
        if (tool === "select") return;

        if (tool === "text") {
            const text = textDraft.trim() || "标注";
            const mark: TextAnnotation = {
                id: createAnnotationId(),
                type: "text",
                x: point.x,
                y: point.y,
                text,
                color,
                strokeWidth,
                fontSize: clamp(Math.max(24, strokeWidth * 4 + 12), MIN_ANNOTATION_FONT_SIZE, MAX_ANNOTATION_FONT_SIZE),
            };
            commitMarks([...marks, mark]);
            setSelectedId(mark.id);
            setTool("select");
            return;
        }

        event.currentTarget.setPointerCapture(event.pointerId);
        const drag: DragState = {
            id: createAnnotationId(),
            tool,
            start: point,
            color,
            strokeWidth,
            points: [point],
        };
        dragRef.current = drag;
        setDraftMark(buildDragMark(drag, point));
    };

    const handleStagePointerMove = (event: ReactPointerEvent<SVGSVGElement>) => {
        if (!image || !dragRef.current) return;
        const point = readStagePoint(event, image);
        if (dragRef.current.tool === "brush") {
            const last = dragRef.current.points.at(-1);
            if (!last || distance(last, point) >= 2) dragRef.current.points.push(point);
        }
        setDraftMark(buildDragMark(dragRef.current, point));
    };

    const finishDrawing = (event: ReactPointerEvent<SVGSVGElement>) => {
        if (!image || !dragRef.current) return;
        const point = readStagePoint(event, image);
        const nextMark = buildDragMark(dragRef.current, point);
        dragRef.current = null;
        setDraftMark(null);
        if (!isMeaningfulAnnotation(nextMark)) return;
        commitMarks([...marks, nextMark]);
        setSelectedId(nextMark.id);
    };

    const startMoveMark = (mark: ImageAnnotation, event: ReactPointerEvent<SVGGElement>) => {
        if (!image || tool !== "select") return;
        const svg = stageRef.current;
        if (!svg) return;
        event.preventDefault();
        event.stopPropagation();
        setSelectedId(mark.id);
        const start = readStageClientPoint(event.clientX, event.clientY, svg, image);
        moveRef.current = { id: mark.id, start, originalMarks: marks, moved: false };

        let lastPointer = { x: event.clientX, y: event.clientY };
        const move = (event: PointerEvent) => {
            const current = moveRef.current;
            if (!current) return;
            lastPointer = { x: event.clientX, y: event.clientY };
            const point = readStageClientPoint(event.clientX, event.clientY, svg, image);
            const original = current.originalMarks.find((item) => item.id === current.id);
            if (!original) return;
            const delta = boundedAnnotationDelta(original, point.x - current.start.x, point.y - current.start.y, image);
            current.moved = current.moved || Math.abs(delta.x) > 0.5 || Math.abs(delta.y) > 0.5;
            const nextMarks = current.originalMarks.map((item) => (item.id === current.id ? translateAnnotation(item, delta.x, delta.y) : item));
            marksRef.current = nextMarks;
            setMarks(nextMarks);
        };
        const trackMove = (event: PointerEvent) => move(event);
        const up = () => {
            const current = moveRef.current;
            document.removeEventListener("pointermove", trackMove);
            document.removeEventListener("pointerup", up);
            document.removeEventListener("pointercancel", up);
            moveRef.current = null;
            if (!current?.moved) return;
            const point = readStageClientPoint(lastPointer.x, lastPointer.y, svg, image);
            const original = current.originalMarks.find((item) => item.id === current.id);
            if (!original) return;
            const delta = boundedAnnotationDelta(original, point.x - current.start.x, point.y - current.start.y, image);
            const nextMarks = current.originalMarks.map((item) => (item.id === current.id ? translateAnnotation(item, delta.x, delta.y) : item));
            setUndoStack((stack) => [...stack, cloneAnnotations(current.originalMarks)].slice(-ANNOTATION_HISTORY_LIMIT));
            setRedoStack([]);
            marksRef.current = nextMarks;
            setMarks(nextMarks);
        };
        document.addEventListener("pointermove", trackMove);
        document.addEventListener("pointerup", up);
        document.addEventListener("pointercancel", up);
    };

    const startResizeMark = (mark: ImageAnnotation, handle: ResizeAnnotationHandle, event: ReactPointerEvent<SVGRectElement>) => {
        if (!image || tool !== "select") return;
        const svg = stageRef.current;
        const bounds = annotationBounds(mark);
        if (!svg || !bounds) return;
        event.preventDefault();
        event.stopPropagation();
        setSelectedId(mark.id);
        resizeRef.current = { id: mark.id, handle, originalBounds: bounds, originalMarks: marks, moved: false };

        let lastPointer = { x: event.clientX, y: event.clientY };
        const move = (event: PointerEvent) => {
            const current = resizeRef.current;
            if (!current) return;
            lastPointer = { x: event.clientX, y: event.clientY };
            const point = readStageClientPoint(event.clientX, event.clientY, svg, image);
            const original = current.originalMarks.find((item) => item.id === current.id);
            if (!original) return;
            const nextBounds = resizeBoundsFromHandle(current.originalBounds, current.handle, point, image);
            current.moved = current.moved || annotationBoundsChanged(current.originalBounds, nextBounds);
            const nextMarks = current.originalMarks.map((item) => (item.id === current.id ? resizeAnnotationToBounds(original, current.originalBounds, nextBounds) : item));
            marksRef.current = nextMarks;
            setMarks(nextMarks);
        };
        const trackMove = (event: PointerEvent) => move(event);
        const up = () => {
            const current = resizeRef.current;
            document.removeEventListener("pointermove", trackMove);
            document.removeEventListener("pointerup", up);
            document.removeEventListener("pointercancel", up);
            resizeRef.current = null;
            if (!current?.moved) {
                if (current) {
                    marksRef.current = current.originalMarks;
                    setMarks(current.originalMarks);
                }
                return;
            }
            const point = readStageClientPoint(lastPointer.x, lastPointer.y, svg, image);
            const original = current.originalMarks.find((item) => item.id === current.id);
            if (!original) return;
            const nextBounds = resizeBoundsFromHandle(current.originalBounds, current.handle, point, image);
            const nextMarks = current.originalMarks.map((item) => (item.id === current.id ? resizeAnnotationToBounds(original, current.originalBounds, nextBounds) : item));
            setUndoStack((stack) => [...stack, cloneAnnotations(current.originalMarks)].slice(-ANNOTATION_HISTORY_LIMIT));
            setRedoStack([]);
            marksRef.current = nextMarks;
            setMarks(nextMarks);
        };
        document.addEventListener("pointermove", trackMove);
        document.addEventListener("pointerup", up);
        document.addEventListener("pointercancel", up);
    };

    const deleteSelected = () => {
        if (!selectedId) return;
        commitMarks(marks.filter((mark) => mark.id !== selectedId));
        setSelectedId(null);
        setEditingTextId(null);
        textEditOriginalRef.current = null;
    };

    const clearMarks = () => {
        if (!marks.length) return;
        commitMarks([]);
        setSelectedId(null);
        setEditingTextId(null);
        textEditOriginalRef.current = null;
    };

    const handleTextChange = (value: string) => {
        setTextDraft(value);
        if (!selectedText) return;
        setMarks((items) => {
            const next = items.map((mark) => (mark.id === selectedText.id && mark.type === "text" ? { ...mark, text: value } : mark));
            marksRef.current = next;
            return next;
        });
    };

    const updateSelectedFontSize = (value: number) => {
        if (!selectedText) return;
        if (!fontSizeOriginalRef.current) fontSizeOriginalRef.current = cloneAnnotations(marksRef.current);
        const fontSize = clamp(Math.round(value), MIN_ANNOTATION_FONT_SIZE, MAX_ANNOTATION_FONT_SIZE);
        setMarks((items) => {
            const next = items.map((mark) => (mark.id === selectedText.id && mark.type === "text" ? { ...mark, fontSize } : mark));
            marksRef.current = next;
            return next;
        });
    };

    const commitSelectedFontSize = () => {
        const original = fontSizeOriginalRef.current;
        fontSizeOriginalRef.current = null;
        if (!original || annotationsEqual(original, marksRef.current)) return;
        setUndoStack((stack) => [...stack, cloneAnnotations(original)].slice(-ANNOTATION_HISTORY_LIMIT));
        setRedoStack([]);
    };

    const submit = async () => {
        setApplying(true);
        try {
            const nextDataUrl = await renderAnnotatedImage(dataUrl, marks);
            await onConfirm({ dataUrl: nextDataUrl });
        } finally {
            setApplying(false);
        }
    };

    const visibleMarks = draftMark ? [...marks, draftMark] : marks;
    const orderedVisibleMarks = selectedId ? [...visibleMarks.filter((mark) => mark.id !== selectedId), ...visibleMarks.filter((mark) => mark.id === selectedId)] : visibleMarks;
    const editingTextBounds = editingText ? annotationBounds(editingText) : null;

    return (
        <Modal
            className="canvas-themed-modal"
            title="图片标注"
            open={open && Boolean(dataUrl)}
            onCancel={onClose}
            width={1180}
            centered
            destroyOnHidden
            footer={
                <div className="flex items-center justify-between gap-3">
                    <div className="text-xs text-[#b6adc6]">{image ? `${image.width} x ${image.height}` : "读取图片中"}</div>
                    <div className="flex items-center gap-2">
                        <Button icon={<X className="size-4" />} onClick={onClose}>
                            取消
                        </Button>
                        <Button type="primary" icon={<Check className="size-4" />} loading={applying} disabled={!marks.length} onClick={() => void submit()}>
                            应用标注
                        </Button>
                    </div>
                </div>
            }
        >
            <div className="grid gap-4 lg:grid-cols-[56px_minmax(0,1fr)_260px]" data-canvas-no-zoom data-testid="canvas-image-annotation-dialog">
                <div className="flex gap-2 rounded-lg border border-[#b84dff4d] bg-white/[0.045] p-2 shadow-[inset_0_1px_0_rgba(255,255,255,.06)] lg:flex-col">
                    {toolOptions.map((item) => (
                        <Tooltip key={item.id} title={item.label} placement="right">
                            <Button
                                type={tool === item.id ? "primary" : "text"}
                                shape="circle"
                                aria-label={item.label}
                                icon={item.icon}
                                data-testid={`canvas-image-annotation-tool-${item.id}`}
                                onClick={() => {
                                    if (editingTextId) commitTextEdit();
                                    setTool(item.id);
                                }}
                            />
                        </Tooltip>
                    ))}
                </div>

                <div className="flex min-h-[420px] items-center justify-center overflow-hidden rounded-lg bg-neutral-950 p-3">
                    <div className="relative inline-block max-h-[72vh] max-w-full select-none">
                        <img src={dataUrl} alt="" className="block max-h-[72vh] max-w-full rounded-md" draggable={false} />
                        {image ? (
                            <svg
                                ref={stageRef}
                                className={`absolute inset-0 h-full w-full ${tool === "select" ? "cursor-default" : tool === "text" ? "cursor-text" : "cursor-crosshair"}`}
                                viewBox={`0 0 ${image.width} ${image.height}`}
                                onPointerDown={handleStagePointerDown}
                                onPointerMove={handleStagePointerMove}
                                onPointerUp={finishDrawing}
                                onPointerCancel={finishDrawing}
                                data-testid="canvas-image-annotation-stage"
                            >
                                {orderedVisibleMarks.map((mark) => (
                                    <AnnotationSvgMark
                                        key={mark.id}
                                        mark={mark}
                                        selected={mark.id === selectedId}
                                        editing={mark.id === editingTextId}
                                        selectable={tool === "select"}
                                        onSelect={() => setSelectedId(mark.id)}
                                        onTextEditStart={beginTextEdit}
                                        onMoveStart={startMoveMark}
                                        onResizeStart={startResizeMark}
                                    />
                                ))}
                                {editingText && editingTextBounds ? (
                                    <foreignObject
                                        x={editingText.x}
                                        y={editingText.y}
                                        width={Math.max(1, Math.min(image.width - editingText.x, Math.max(120, editingTextBounds.width + 32)))}
                                        height={Math.max(1, Math.min(image.height - editingText.y, Math.max(64, editingTextBounds.height + 24)))}
                                        style={{ overflow: "visible", pointerEvents: "all" }}
                                    >
                                        <textarea
                                            ref={inlineTextRef}
                                            value={textDraft}
                                            data-testid="canvas-image-annotation-inline-text"
                                            className="size-full resize-none rounded border-2 border-white bg-black/75 px-2 py-1 font-bold text-white outline outline-2 outline-black"
                                            style={{ color: editingText.color, fontSize: `${editingText.fontSize}px`, lineHeight: 1.18 }}
                                            onPointerDown={(event) => event.stopPropagation()}
                                            onChange={(event) => handleTextChange(event.target.value)}
                                            onKeyDown={handleTextEditorKeyDown}
                                            onBlur={() => {
                                                if (cancelingTextEditRef.current) {
                                                    cancelingTextEditRef.current = false;
                                                    return;
                                                }
                                                commitTextEdit();
                                            }}
                                        />
                                    </foreignObject>
                                ) : null}
                            </svg>
                        ) : null}
                    </div>
                </div>

                <div className="space-y-4 rounded-lg border border-[#b84dff4d] bg-white/[0.045] p-4 shadow-[inset_0_1px_0_rgba(255,255,255,.06)]">
                    <div>
                        <div className="mb-2 text-sm font-semibold">颜色</div>
                        <div className="grid grid-cols-4 gap-2">
                            {annotationColors.map((item) => (
                                <button
                                    key={item}
                                    type="button"
                                    className={`size-8 rounded-full border-2 transition ${color === item ? "border-[#ff4f8c] shadow-[0_0_16px_rgba(255,79,140,.45)]" : "border-transparent"}`}
                                    style={{ background: item }}
                                    onClick={() => setColor(item)}
                                    aria-label={`选择颜色 ${item}`}
                                />
                            ))}
                        </div>
                    </div>

                    <div>
                        <div className="mb-2 flex items-center justify-between gap-3 text-sm font-semibold">
                            <span>线宽</span>
                            <span className="text-xs text-[#b6adc6]">{strokeWidth}px</span>
                        </div>
                        <Slider min={2} max={36} value={strokeWidth} onChange={setStrokeWidth} />
                    </div>

                    {(tool === "text" || selectedText) && (
                        <div>
                            <div className="mb-2 text-sm font-semibold">文字</div>
                            <Input.TextArea
                                value={textDraft}
                                rows={3}
                                maxLength={80}
                                readOnly={Boolean(selectedText) && editingTextId !== selectedText?.id}
                                data-testid="canvas-image-annotation-text-input"
                                onChange={(event) => handleTextChange(event.target.value)}
                            />
                            {selectedText && editingTextId !== selectedText.id ? <div className="mt-1 text-xs text-[#b6adc6]">双击画布中的文字后编辑</div> : null}
                        </div>
                    )}

                    {selectedText ? (
                        <div>
                            <div className="mb-2 flex items-center justify-between gap-3 text-sm font-semibold">
                                <span>字号</span>
                                <span className="text-xs text-[#b6adc6]">{Math.round(selectedText.fontSize)}px</span>
                            </div>
                            <div data-testid="canvas-image-annotation-font-size" data-font-size={Math.round(selectedText.fontSize)}>
                                <Slider
                                    min={MIN_ANNOTATION_FONT_SIZE}
                                    max={MAX_ANNOTATION_FONT_SIZE}
                                    value={Math.round(selectedText.fontSize)}
                                    onChange={updateSelectedFontSize}
                                    onChangeComplete={commitSelectedFontSize}
                                />
                            </div>
                        </div>
                    ) : null}

                    <div className="grid grid-cols-2 gap-2">
                        <Button icon={<Undo2 className="size-4" />} disabled={!undoStack.length} onClick={undo}>
                            撤销
                        </Button>
                        <Button icon={<Redo2 className="size-4" />} disabled={!redoStack.length} onClick={redo}>
                            重做
                        </Button>
                        <Button icon={<Trash2 className="size-4" />} disabled={!selectedId} danger onClick={deleteSelected}>
                            删除
                        </Button>
                        <Button icon={<RotateCcw className="size-4" />} disabled={!marks.length} onClick={clearMarks}>
                            清空
                        </Button>
                    </div>
                </div>
            </div>
        </Modal>
    );
}

function AnnotationSvgMark({
    mark,
    selected,
    editing,
    selectable,
    onSelect,
    onTextEditStart,
    onMoveStart,
    onResizeStart,
}: {
    mark: ImageAnnotation;
    selected: boolean;
    editing: boolean;
    selectable: boolean;
    onSelect: () => void;
    onTextEditStart: (mark: TextAnnotation) => void;
    onMoveStart: (mark: ImageAnnotation, event: ReactPointerEvent<SVGGElement>) => void;
    onResizeStart: (mark: ImageAnnotation, handle: ResizeAnnotationHandle, event: ReactPointerEvent<SVGRectElement>) => void;
}) {
    const bounds = annotationBounds(mark);
    const handleSize = bounds ? Math.min(Math.max(ANNOTATION_RESIZE_HANDLE_SIZE, Math.max(bounds.width, bounds.height) * 0.035), 36) : ANNOTATION_RESIZE_HANDLE_SIZE;
    return (
        <g
            data-testid={`canvas-image-annotation-mark-${mark.type}`}
            style={{ pointerEvents: selectable ? "auto" : "none" }}
            onPointerDown={(event) => {
                const target = event.target instanceof Element ? event.target : null;
                if (target?.closest("[data-annotation-resize-handle]")) return;
                event.stopPropagation();
                onSelect();
                onMoveStart(mark, event);
            }}
            onDoubleClick={(event) => {
                if (!selectable || mark.type !== "text") return;
                event.preventDefault();
                event.stopPropagation();
                onTextEditStart(mark);
            }}
        >
            <g opacity={editing ? 0.2 : 1}>{renderSvgMark(mark)}</g>
            {selected && bounds ? (
                <>
                    <rect x={bounds.x - 6} y={bounds.y - 6} width={bounds.width + 12} height={bounds.height + 12} fill="none" stroke="#09070d" strokeWidth={5} vectorEffect="non-scaling-stroke" pointerEvents="none" />
                    <rect x={bounds.x - 6} y={bounds.y - 6} width={bounds.width + 12} height={bounds.height + 12} fill="none" stroke="#ffffff" strokeDasharray="8 6" strokeWidth={2} vectorEffect="non-scaling-stroke" pointerEvents="none" />
                    {selectable
                        ? resizeHandles.map((handle) => {
                              const center = resizeHandleCenter(bounds, handle);
                              return (
                                  <g key={handle} data-annotation-resize-handle="true">
                                      <rect
                                          data-testid={`canvas-image-annotation-resize-${handle}`}
                                          data-annotation-resize-handle="true"
                                          x={center.x - handleSize / 2}
                                          y={center.y - handleSize / 2}
                                          width={handleSize}
                                          height={handleSize}
                                          rx={Math.max(2, handleSize * 0.18)}
                                          fill="#09070d"
                                          stroke="#ffffff"
                                          strokeWidth={2}
                                          vectorEffect="non-scaling-stroke"
                                          style={{ cursor: resizeHandleCursor(handle), pointerEvents: "all", filter: "drop-shadow(0 2px 3px rgba(0,0,0,.75))" }}
                                          onPointerDown={(event) => onResizeStart(mark, handle, event)}
                                      />
                                      <rect
                                          x={center.x - handleSize / 2 + 4}
                                          y={center.y - handleSize / 2 + 4}
                                          width={Math.max(2, handleSize - 8)}
                                          height={Math.max(2, handleSize - 8)}
                                          rx={Math.max(1, handleSize * 0.12)}
                                          fill="#ffffff"
                                          stroke="#09070d"
                                          strokeWidth={1.5}
                                          vectorEffect="non-scaling-stroke"
                                          pointerEvents="none"
                                      />
                                  </g>
                              );
                          })
                        : null}
                </>
            ) : null}
        </g>
    );
}

function renderSvgMark(mark: ImageAnnotation) {
    if (mark.type === "rect") {
        const box = normalizeBox(mark.start, mark.end);
        return <rect x={box.x} y={box.y} width={box.width} height={box.height} fill="transparent" stroke={mark.color} strokeWidth={mark.strokeWidth} />;
    }
    if (mark.type === "ellipse") {
        const box = normalizeBox(mark.start, mark.end);
        return <ellipse cx={box.x + box.width / 2} cy={box.y + box.height / 2} rx={box.width / 2} ry={box.height / 2} fill="transparent" stroke={mark.color} strokeWidth={mark.strokeWidth} />;
    }
    if (mark.type === "arrow") {
        return (
            <>
                <line x1={mark.start.x} y1={mark.start.y} x2={mark.end.x} y2={mark.end.y} stroke={mark.color} strokeWidth={mark.strokeWidth} strokeLinecap="round" />
                <polygon points={arrowHeadPoints(mark.start, mark.end, Math.max(16, mark.strokeWidth * 4))} fill={mark.color} />
            </>
        );
    }
    if (mark.type === "brush") {
        return <polyline points={mark.points.map((point) => `${point.x},${point.y}`).join(" ")} fill="none" stroke={mark.color} strokeWidth={mark.strokeWidth} strokeLinecap="round" strokeLinejoin="round" />;
    }
    if (mark.type === "text") {
        return (
            <text x={mark.x} y={mark.y} fill={mark.color} stroke="rgba(0,0,0,.72)" strokeWidth={Math.max(3, mark.fontSize * 0.1)} paintOrder="stroke" fontSize={mark.fontSize} fontWeight={700} dominantBaseline="hanging">
                {mark.text.split("\n").map((line, index) => (
                    <tspan key={`${mark.id}-${index}`} x={mark.x} dy={index ? mark.fontSize * 1.18 : 0}>
                        {line || " "}
                    </tspan>
                ))}
            </text>
        );
    }
    return null;
}

async function renderAnnotatedImage(dataUrl: string, marks: ImageAnnotation[]) {
    const image = await loadImage(dataUrl);
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, image.naturalWidth || image.width);
    canvas.height = Math.max(1, image.naturalHeight || image.height);
    const context = canvas.getContext("2d");
    if (!context) return dataUrl;
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    marks.forEach((mark) => drawCanvasMark(context, mark));
    return canvas.toDataURL("image/png");
}

function drawCanvasMark(context: CanvasRenderingContext2D, mark: ImageAnnotation) {
    context.save();
    context.lineCap = "round";
    context.lineJoin = "round";
    context.strokeStyle = mark.color;
    context.fillStyle = mark.color;
    context.lineWidth = mark.strokeWidth;

    if (mark.type === "rect") {
        const box = normalizeBox(mark.start, mark.end);
        context.strokeRect(box.x, box.y, box.width, box.height);
    } else if (mark.type === "ellipse") {
        const box = normalizeBox(mark.start, mark.end);
        context.beginPath();
        context.ellipse(box.x + box.width / 2, box.y + box.height / 2, Math.max(1, box.width / 2), Math.max(1, box.height / 2), 0, 0, Math.PI * 2);
        context.stroke();
    } else if (mark.type === "arrow") {
        context.beginPath();
        context.moveTo(mark.start.x, mark.start.y);
        context.lineTo(mark.end.x, mark.end.y);
        context.stroke();
        const points = arrowHeadPath(mark.start, mark.end, Math.max(16, mark.strokeWidth * 4));
        context.beginPath();
        context.moveTo(points[0].x, points[0].y);
        context.lineTo(points[1].x, points[1].y);
        context.lineTo(points[2].x, points[2].y);
        context.closePath();
        context.fill();
    } else if (mark.type === "brush") {
        context.beginPath();
        mark.points.forEach((point, index) => {
            if (index) context.lineTo(point.x, point.y);
            else context.moveTo(point.x, point.y);
        });
        context.stroke();
    } else if (mark.type === "text") {
        context.font = `700 ${mark.fontSize}px sans-serif`;
        context.textBaseline = "top";
        context.lineWidth = Math.max(3, mark.fontSize * 0.1);
        mark.text.split("\n").forEach((line, index) => {
            const y = mark.y + index * mark.fontSize * 1.18;
            context.strokeStyle = "rgba(0,0,0,.72)";
            context.strokeText(line || " ", mark.x, y);
            context.fillStyle = mark.color;
            context.fillText(line || " ", mark.x, y);
        });
    }

    context.restore();
}

function readStagePoint(event: ReactPointerEvent<SVGSVGElement>, image: ImageMeta): AnnotationPoint {
    const rect = event.currentTarget.getBoundingClientRect();
    return readPointFromRect(event.clientX, event.clientY, rect, image);
}

function readStageClientPoint(clientX: number, clientY: number, stage: SVGSVGElement, image: ImageMeta): AnnotationPoint {
    return readPointFromRect(clientX, clientY, stage.getBoundingClientRect(), image);
}

function readPointFromRect(clientX: number, clientY: number, rect: DOMRect, image: ImageMeta): AnnotationPoint {
    return {
        x: clamp(((clientX - rect.left) / Math.max(1, rect.width)) * image.width, 0, image.width),
        y: clamp(((clientY - rect.top) / Math.max(1, rect.height)) * image.height, 0, image.height),
    };
}

function translateAnnotation(mark: ImageAnnotation, dx: number, dy: number): ImageAnnotation {
    if (mark.type === "rect" || mark.type === "ellipse" || mark.type === "arrow") return { ...mark, start: translatePoint(mark.start, dx, dy), end: translatePoint(mark.end, dx, dy) };
    if (mark.type === "brush") return { ...mark, points: mark.points.map((point) => translatePoint(point, dx, dy)) };
    if (mark.type === "text") return { ...mark, x: mark.x + dx, y: mark.y + dy };
    return mark;
}

function boundedAnnotationDelta(mark: ImageAnnotation, dx: number, dy: number, image: ImageMeta) {
    const bounds = annotationBounds(mark);
    if (!bounds) return { x: dx, y: dy };
    return {
        x: clamp(dx, -bounds.x, image.width - (bounds.x + bounds.width)),
        y: clamp(dy, -bounds.y, image.height - (bounds.y + bounds.height)),
    };
}

function resizeBoundsFromHandle(bounds: AnnotationBounds, handle: ResizeAnnotationHandle, point: AnnotationPoint, image: ImageMeta): AnnotationBounds {
    const right = bounds.x + bounds.width;
    const bottom = bounds.y + bounds.height;
    const fromLeft = handle.includes("left");
    const fromTop = handle.includes("top");
    const x = fromLeft ? clamp(point.x, 0, right - MIN_ANNOTATION_RESIZE_SIZE) : bounds.x;
    const y = fromTop ? clamp(point.y, 0, bottom - MIN_ANNOTATION_RESIZE_SIZE) : bounds.y;
    const nextRight = fromLeft ? right : clamp(point.x, bounds.x + MIN_ANNOTATION_RESIZE_SIZE, image.width);
    const nextBottom = fromTop ? bottom : clamp(point.y, bounds.y + MIN_ANNOTATION_RESIZE_SIZE, image.height);
    return {
        x,
        y,
        width: Math.max(MIN_ANNOTATION_RESIZE_SIZE, nextRight - x),
        height: Math.max(MIN_ANNOTATION_RESIZE_SIZE, nextBottom - y),
    };
}

function resizeAnnotationToBounds(mark: ImageAnnotation, originalBounds: AnnotationBounds, bounds: AnnotationBounds): ImageAnnotation {
    if (mark.type === "rect" || mark.type === "ellipse") {
        return { ...mark, start: { x: bounds.x, y: bounds.y }, end: { x: bounds.x + bounds.width, y: bounds.y + bounds.height } };
    }
    if (mark.type === "arrow") {
        return {
            ...mark,
            start: mapPointBetweenBounds(mark.start, originalBounds, bounds),
            end: mapPointBetweenBounds(mark.end, originalBounds, bounds),
        };
    }
    if (mark.type === "brush") {
        return { ...mark, points: mark.points.map((point) => mapPointBetweenBounds(point, originalBounds, bounds)) };
    }
    if (mark.type === "text") {
        const widthScale = bounds.width / Math.max(1, originalBounds.width);
        const heightScale = bounds.height / Math.max(1, originalBounds.height);
        const scale = Math.max(0.25, Math.min(widthScale, heightScale));
        return { ...mark, x: bounds.x, y: bounds.y, fontSize: clamp(mark.fontSize * scale, MIN_ANNOTATION_FONT_SIZE, MAX_ANNOTATION_FONT_SIZE) };
    }
    return mark;
}

function mapPointBetweenBounds(point: AnnotationPoint, originalBounds: AnnotationBounds, bounds: AnnotationBounds) {
    const ratioX = (point.x - originalBounds.x) / Math.max(1, originalBounds.width);
    const ratioY = (point.y - originalBounds.y) / Math.max(1, originalBounds.height);
    return {
        x: bounds.x + ratioX * bounds.width,
        y: bounds.y + ratioY * bounds.height,
    };
}

function annotationBoundsChanged(a: AnnotationBounds, b: AnnotationBounds) {
    return Math.abs(a.x - b.x) > ANNOTATION_DRAG_EPSILON || Math.abs(a.y - b.y) > ANNOTATION_DRAG_EPSILON || Math.abs(a.width - b.width) > ANNOTATION_DRAG_EPSILON || Math.abs(a.height - b.height) > ANNOTATION_DRAG_EPSILON;
}

function resizeHandleCenter(bounds: AnnotationBounds, handle: ResizeAnnotationHandle): AnnotationPoint {
    return {
        x: handle.includes("left") ? bounds.x : bounds.x + bounds.width,
        y: handle.includes("top") ? bounds.y : bounds.y + bounds.height,
    };
}

function resizeHandleCursor(handle: ResizeAnnotationHandle) {
    return handle === "top-left" || handle === "bottom-right" ? "nwse-resize" : "nesw-resize";
}

function translatePoint(point: AnnotationPoint, dx: number, dy: number) {
    return { x: point.x + dx, y: point.y + dy };
}

function buildDragMark(drag: DragState, point: AnnotationPoint): ImageAnnotation {
    if (drag.tool === "brush") {
        return {
            id: drag.id,
            type: "brush",
            points: [...drag.points, point],
            color: drag.color,
            strokeWidth: drag.strokeWidth,
        };
    }
    return {
        id: drag.id,
        type: drag.tool,
        start: drag.start,
        end: point,
        color: drag.color,
        strokeWidth: drag.strokeWidth,
    };
}

function isMeaningfulAnnotation(mark: ImageAnnotation) {
    if (mark.type === "text") return Boolean(mark.text.trim());
    if (mark.type === "brush") return mark.points.length > 2 && pathLength(mark.points) > 6;
    return distance(mark.start, mark.end) > 8;
}

function annotationBounds(mark: ImageAnnotation) {
    if (mark.type === "rect" || mark.type === "ellipse" || mark.type === "arrow") return normalizeBox(mark.start, mark.end);
    if (mark.type === "brush") {
        if (!mark.points.length) return null;
        const xs = mark.points.map((point) => point.x);
        const ys = mark.points.map((point) => point.y);
        const x = Math.min(...xs);
        const y = Math.min(...ys);
        return { x, y, width: Math.max(1, Math.max(...xs) - x), height: Math.max(1, Math.max(...ys) - y) };
    }
    if (mark.type === "text") {
        const lines = mark.text.split("\n");
        const width = Math.max(...lines.map((line) => line.length), 1) * mark.fontSize * 0.62;
        return { x: mark.x, y: mark.y, width, height: lines.length * mark.fontSize * 1.18 };
    }
    return null;
}

function normalizeBox(start: AnnotationPoint, end: AnnotationPoint) {
    const x = Math.min(start.x, end.x);
    const y = Math.min(start.y, end.y);
    return {
        x,
        y,
        width: Math.max(1, Math.abs(end.x - start.x)),
        height: Math.max(1, Math.abs(end.y - start.y)),
    };
}

function arrowHeadPoints(start: AnnotationPoint, end: AnnotationPoint, size: number) {
    return arrowHeadPath(start, end, size)
        .map((point) => `${point.x},${point.y}`)
        .join(" ");
}

function arrowHeadPath(start: AnnotationPoint, end: AnnotationPoint, size: number) {
    const angle = Math.atan2(end.y - start.y, end.x - start.x);
    const spread = Math.PI / 7;
    return [
        end,
        {
            x: end.x - Math.cos(angle - spread) * size,
            y: end.y - Math.sin(angle - spread) * size,
        },
        {
            x: end.x - Math.cos(angle + spread) * size,
            y: end.y - Math.sin(angle + spread) * size,
        },
    ];
}

function pathLength(points: AnnotationPoint[]) {
    return points.reduce((total, point, index) => total + (index ? distance(points[index - 1], point) : 0), 0);
}

function distance(a: AnnotationPoint, b: AnnotationPoint) {
    return Math.hypot(a.x - b.x, a.y - b.y);
}

function cloneAnnotations(marks: ImageAnnotation[]): ImageAnnotation[] {
    return marks.map((mark) => {
        if (mark.type === "rect" || mark.type === "ellipse" || mark.type === "arrow") return { ...mark, start: { ...mark.start }, end: { ...mark.end } };
        if (mark.type === "brush") return { ...mark, points: mark.points.map((point) => ({ ...point })) };
        return { ...mark };
    });
}

function annotationsEqual(left: ImageAnnotation[], right: ImageAnnotation[]) {
    return JSON.stringify(left) === JSON.stringify(right);
}

function clamp(value: number, min: number, max: number) {
    return Math.min(max, Math.max(min, value));
}

function createAnnotationId() {
    return `annotation-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function loadImage(src: string) {
    return new Promise<HTMLImageElement>((resolve, reject) => {
        const image = new Image();
        image.onload = () => resolve(image);
        image.onerror = () => reject(new Error("图片读取失败"));
        image.src = src;
    });
}
