"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, KeyboardEvent, MouseEvent, PointerEvent } from "react";
import { Button, Image } from "antd";
import { FileText, Image as ImageIcon, Music2, Video, X } from "lucide-react";

import { canvasThemes } from "@/lib/canvas-theme";
import { useThemeStore } from "@/stores/use-theme-store";
import { CANVAS_MENTION_PATTERN, buildCanvasMentionMenuGroups, canvasMentionKey, canvasMentionToken, canvasMentionTokenFromKey, filterCanvasMentionReferences, matchCanvasMentionTrigger, type CanvasMentionSource } from "../utils/canvas-mention-tokens";
import type { CanvasResourceReference } from "../utils/canvas-resource-references";

type CanvasConfigComposerProps = {
    value: string;
    references: CanvasResourceReference[];
    onChange: (value: string) => void;
    onClose: () => void;
    onMentionQueryChange?: (query: string) => void;
    editorHeight?: number;
};

type Token =
    | { type: "text"; value: string }
    | { type: "reference"; source: CanvasMentionSource; targetId: string; mentionKey: string; missing?: boolean };

type MentionState = {
    query: string;
};

export const CONFIG_REFERENCE_PATTERN = CANVAS_MENTION_PATTERN;

export function CanvasConfigComposer({ value, references, onChange, onClose, onMentionQueryChange, editorHeight = 112 }: CanvasConfigComposerProps) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const editorRef = useRef<HTMLDivElement>(null);
    const composingRef = useRef(false);
    const lastRenderedValueRef = useRef("");
    const [mention, setMention] = useState<MentionState | null>(null);
    const [activeIndex, setActiveIndex] = useState(0);
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const tokens = useMemo(() => parseComposerTokens(value), [value]);
    const referenceByKey = useMemo(() => new Map(references.map((reference) => [reference.mentionKey, reference])), [references]);
    const candidates = useMemo(() => {
        if (!mention) return [];
        return filterCanvasMentionReferences(references, mention.query || "");
    }, [mention, references]);
    const activeReferences = useMemo(() => references.filter((reference) => reference.active), [references]);

    useEffect(() => {
        if (!mention) return;
        onMentionQueryChange?.(mention.query);
    }, [mention, onMentionQueryChange]);

    useEffect(() => {
        const editor = editorRef.current;
        if (!editor) return;
        if (document.activeElement === editor || composingRef.current) return;
        if (lastRenderedValueRef.current === value && editor.childNodes.length) return;
        const caretOffset = getCaretTextOffset(editor);
        editor.textContent = "";
        tokens.forEach((token) => {
            if (token.type === "text") {
                editor.append(document.createTextNode(token.value));
                return;
            }
            const reference = referenceByKey.get(token.mentionKey);
            editor.append(reference ? createReferenceChip(reference, theme, setImagePreview) : createMissingReferenceChip(token.mentionKey, theme));
        });
        lastRenderedValueRef.current = value;
        if (caretOffset !== null) restoreCaretByTextOffset(editor, caretOffset);
    }, [referenceByKey, theme, tokens]);

    const syncFromEditor = () => {
        const editor = editorRef.current;
        if (!editor) return;
        const next = serializeEditor(editor);
        lastRenderedValueRef.current = next;
        onChange(next);
        syncMention();
    };

    const syncMention = () => {
        const text = textBeforeCaret();
        const match = matchCanvasMentionTrigger(text);
        if (!match) {
            closeMention();
            return;
        }
        setMention({ query: match.query });
        setActiveIndex(0);
    };

    const closeMention = () => {
        setMention(null);
        setActiveIndex(0);
    };

    const insertReference = (reference: CanvasResourceReference) => {
        const editor = editorRef.current;
        if (!editor) return;
        const insertionOffset = removeActiveMention();
        if (insertionOffset !== null) restoreCaretByTextOffset(editor, insertionOffset);
        const chip = createReferenceChip(reference, theme, setImagePreview);
        const space = document.createTextNode(" ");
        const selection = window.getSelection();
        const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
        if (range) {
            range.insertNode(space);
            range.insertNode(chip);
            range.setStartAfter(space);
            range.collapse(true);
            selection?.removeAllRanges();
            selection?.addRange(range);
        } else {
            editor.append(chip, space);
            placeCaretAtEnd(editor);
        }
        closeMention();
        const next = serializeEditor(editor);
        lastRenderedValueRef.current = next;
        onChange(next);
    };

    const stopCanvasInteraction = (event: PointerEvent | MouseEvent) => event.stopPropagation();

    return (
        <div
            data-canvas-no-zoom
            data-testid="canvas-config-composer"
            className="rounded-2xl border p-3 shadow-2xl backdrop-blur"
            style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }}
            onMouseDown={stopCanvasInteraction}
            onPointerDown={stopCanvasInteraction}
            onWheel={(event) => event.stopPropagation()}
        >
            <div className="mb-2 flex items-center justify-between gap-2">
                <div className="flex min-w-0 items-baseline gap-2">
                    <div className="shrink-0 text-xs font-semibold">组装提示词</div>
                    <div className="truncate text-[11px] opacity-55">@ 引用连接素材或资产库</div>
                </div>
                <Button size="small" type="text" className="!h-7 !w-7 !min-w-7 !p-0" icon={<X className="size-3.5" />} onClick={onClose} />
            </div>
            <div className="relative rounded-xl border" style={{ background: theme.node.fill, borderColor: theme.node.stroke }}>
                {!value.trim() ? <div className="pointer-events-none absolute left-3 top-2 text-sm leading-7" style={{ color: theme.node.placeholder }}>输入提示词，按 @ 引用连接素材或素材库</div> : null}
                <div
                    ref={editorRef}
                    data-testid="canvas-config-composer-editor"
                    contentEditable
                    suppressContentEditableWarning
                    className="thin-scrollbar w-full overflow-y-auto whitespace-pre-wrap break-words px-3 py-2 text-sm leading-7 outline-none"
                    style={{ color: theme.node.text, height: editorHeight }}
                    onInput={() => {
                        if (!composingRef.current) syncFromEditor();
                    }}
                    onCompositionStart={() => {
                        composingRef.current = true;
                    }}
                    onCompositionEnd={() => {
                        composingRef.current = false;
                        syncFromEditor();
                    }}
                    onKeyDown={(event: KeyboardEvent<HTMLDivElement>) => {
                        event.stopPropagation();
                        if (mention) {
                            if (event.key === "ArrowDown" && candidates.length) {
                                event.preventDefault();
                                setActiveIndex((index) => (index + 1) % candidates.length);
                                return;
                            }
                            if (event.key === "ArrowUp" && candidates.length) {
                                event.preventDefault();
                                setActiveIndex((index) => (index - 1 + candidates.length) % candidates.length);
                                return;
                            }
                            if (event.key === "Enter" && candidates.length) {
                                event.preventDefault();
                                insertReference(candidates[Math.min(activeIndex, candidates.length - 1)]);
                                return;
                            }
                            if (event.key === "Escape") {
                                event.preventDefault();
                                closeMention();
                                return;
                            }
                        }
                        if ((event.key === "Backspace" || event.key === "Delete") && deleteAdjacentReference(event.key)) {
                            event.preventDefault();
                            requestAnimationFrame(syncFromEditor);
                            return;
                        }
                        requestAnimationFrame(syncMention);
                    }}
                    onBlur={() => window.setTimeout(closeMention, 120)}
                />
                {mention ? <MentionMenu references={candidates} allReferences={activeReferences} activeIndex={Math.min(activeIndex, Math.max(candidates.length - 1, 0))} theme={theme} onSelect={insertReference} /> : null}
            </div>
            {imagePreview ? <Image src={imagePreview} alt="引用图片预览" style={{ display: "none" }} preview={{ visible: true, src: imagePreview, onVisibleChange: (visible) => !visible && setImagePreview(null) }} /> : null}
        </div>
    );

}

function MentionMenu({ references, allReferences, activeIndex, theme, onSelect }: { references: CanvasResourceReference[]; allReferences: CanvasResourceReference[]; activeIndex: number; theme: (typeof canvasThemes)[keyof typeof canvasThemes]; onSelect: (reference: CanvasResourceReference) => void }) {
    const selectedRef = useRef(false);
    const activeItemRef = useRef<HTMLButtonElement | null>(null);

    useEffect(() => {
        activeItemRef.current?.scrollIntoView({ block: "nearest" });
    }, [activeIndex, references]);

    const selectInput = (reference: CanvasResourceReference) => {
        if (selectedRef.current) return;
        selectedRef.current = true;
        onSelect(reference);
    };
    const groups = buildCanvasMentionMenuGroups(allReferences, references);

    return (
        <div className="absolute left-2 top-[calc(100%+6px)] z-[90] max-h-56 w-64 overflow-y-auto rounded-xl border p-1 shadow-2xl" style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border }}>
            {groups.map((group) => {
                return (
                    <div key={group.source}>
                        <div className="px-2 py-1 text-[11px] font-medium opacity-55">{group.title}</div>
                        {group.empty ? <div className="px-2 pb-2 text-[11px] leading-4 opacity-45">{group.emptyText}</div> : null}
                        {group.unmatched ? <div className="px-2 pb-2 text-[11px] leading-4 opacity-45">无匹配素材</div> : null}
                        {group.items.map(({ reference, index }) => {
                            return (
                                <button
                                    ref={index === activeIndex ? activeItemRef : undefined}
                                    key={reference.id}
                                    type="button"
                                    className="flex w-full min-w-0 items-center gap-2 rounded-lg px-2 py-1.5 text-left text-xs transition"
                                    style={{ background: index === activeIndex ? theme.toolbar.activeBg : "transparent", color: index === activeIndex ? theme.toolbar.activeText : theme.node.text }}
                                    onMouseDown={(event) => {
                                        event.preventDefault();
                                        event.stopPropagation();
                                        selectInput(reference);
                                    }}
                                >
                                    <ResourcePreview reference={reference} />
                                    <span className="min-w-0 flex-1">
                                        <span className="block truncate font-medium">{reference.label || reference.title}</span>
                                        <span className="block truncate opacity-65">{referenceSubtitle(reference)}</span>
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                );
            })}
        </div>
    );
}

function ResourcePreview({ reference }: { reference: CanvasResourceReference }) {
    if (reference.kind === "image" && reference.previewUrl) return <img src={reference.previewUrl} alt="" className="size-9 rounded-md object-cover" />;
    if (reference.kind === "video" && reference.previewUrl) return <video src={reference.previewUrl} className="size-9 rounded-md bg-black object-cover" muted preload="metadata" />;
    const Icon = reference.kind === "audio" ? Music2 : reference.kind === "video" ? Video : reference.kind === "image" ? ImageIcon : FileText;
    return (
        <span className="grid size-9 shrink-0 place-items-center rounded-md bg-black/10">
            <Icon className="size-4" />
        </span>
    );
}

function createReferenceChip(reference: CanvasResourceReference, theme: (typeof canvasThemes)[keyof typeof canvasThemes], onImagePreview: (url: string) => void) {
    const wrapper = document.createElement("span");
    wrapper.contentEditable = "false";
    wrapper.dataset.referenceKey = reference.mentionKey;
    wrapper.dataset.referenceSource = reference.mentionSource;
    wrapper.dataset.referenceTargetId = reference.targetId;
    const label = reference.label || reference.title;
    wrapper.className = "mx-px inline-flex h-7 max-w-40 items-center justify-center overflow-hidden rounded-md border px-1 text-xs leading-none align-middle";
    Object.assign(wrapper.style, chipStyle(theme));
    if (reference.kind === "image" && reference.previewUrl) {
        const image = document.createElement("img");
        image.src = reference.previewUrl;
        image.alt = label;
        image.className = "size-6 rounded object-cover";
        wrapper.className = "mx-px inline-flex size-6 items-center justify-center overflow-hidden rounded align-middle";
        wrapper.title = `${label}：${referenceSubtitle(reference)}`;
        wrapper.appendChild(image);
        wrapper.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            onImagePreview(reference.previewUrl || "");
        });
    } else {
        wrapper.title = reference.text || referenceSubtitle(reference);
        const text = document.createElement("span");
        text.className = "block truncate";
        text.textContent = label;
        wrapper.appendChild(text);
    }
    return wrapper;
}

function createMissingReferenceChip(mentionKey: string, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    const wrapper = document.createElement("span");
    wrapper.contentEditable = "false";
    wrapper.dataset.referenceKey = mentionKey;
    wrapper.className = "mx-px inline-flex h-7 max-w-40 items-center justify-center overflow-hidden rounded-md border px-1 text-xs leading-none align-middle";
    Object.assign(wrapper.style, { background: "rgba(239, 68, 68, 0.12)", borderColor: "rgba(239, 68, 68, 0.35)", color: theme.node.text });
    wrapper.title = `引用不存在：${mentionKey}`;
    const text = document.createElement("span");
    text.className = "block truncate text-red-400";
    text.textContent = "引用已失效";
    wrapper.appendChild(text);
    return wrapper;
}

function serializeEditor(editor: HTMLElement) {
    return serializeNodes(editor.childNodes).replace(/\uFEFF/g, "");
}

function serializeNodes(nodes: NodeListOf<ChildNode>) {
    let result = "";
    nodes.forEach((node) => {
        if (node.nodeType === Node.TEXT_NODE) result += node.textContent || "";
        if (!(node instanceof HTMLElement)) return;
        const key = node.dataset.referenceKey;
        if (key) {
            const source = node.dataset.referenceSource as CanvasMentionSource | undefined;
            const targetId = node.dataset.referenceTargetId;
            result += source && targetId ? canvasMentionToken(targetId, source) : canvasMentionTokenFromKey(key);
        } else if (node.tagName === "BR") result += "\n";
        else result += serializeNodes(node.childNodes);
    });
    return result;
}

function removeActiveMention() {
    const selection = window.getSelection();
    if (!selection?.rangeCount) return null;
    const range = selection.getRangeAt(0);
    const editor = closestEditor(range.startContainer);
    if (!editor) return null;
    const text = textBeforeCaret();
    const match = matchCanvasMentionTrigger(text);
    if (!match) return null;
    const offset = Math.max(0, (getCaretTextOffset(editor) ?? 0) - match.query.length - 1);
    range.setStart(range.startContainer, Math.max(0, range.startOffset - match.query.length - 1));
    range.deleteContents();
    return offset;
}

function deleteAdjacentReference(key: string) {
    const selection = window.getSelection();
    if (!selection?.rangeCount || !selection.isCollapsed) return false;
    const range = selection.getRangeAt(0);
    const target = adjacentReferenceNode(range, key);
    if (!target) return false;
    const nextCaretNode = document.createTextNode("");
    target.replaceWith(nextCaretNode);
    range.setStart(nextCaretNode, 0);
    range.collapse(true);
    selection.removeAllRanges();
    selection.addRange(range);
    return true;
}

function adjacentReferenceNode(range: Range, key: string) {
    const container = range.startContainer;
    const offset = range.startOffset;
    const previous = key === "Backspace";
    if (container.nodeType === Node.TEXT_NODE) {
        const text = container.textContent || "";
        if ((previous && offset > 0) || (!previous && offset < text.length)) return null;
        return findReferenceSibling(container, previous);
    }
    const children = Array.from(container.childNodes);
    return findReferenceSibling(children[previous ? offset - 1 : offset] || container, previous, true);
}

function findReferenceSibling(node: Node, previous: boolean, includeSelf = false): HTMLElement | null {
    let current: Node | null = includeSelf ? node : previous ? node.previousSibling : node.nextSibling;
    while (current && current.nodeType === Node.TEXT_NODE && !(current.textContent || "").trim()) current = previous ? current.previousSibling : current.nextSibling;
    return current instanceof HTMLElement && current.dataset.referenceKey ? current : null;
}

function textBeforeCaret() {
    const selection = window.getSelection();
    if (!selection?.rangeCount) return "";
    const range = selection.getRangeAt(0).cloneRange();
    const editor = closestEditor(range.startContainer);
    if (!editor) return "";
    range.setStart(editor, 0);
    return range.toString();
}

function closestEditor(node: Node): HTMLElement | null {
    const element = node instanceof Element ? node : node.parentElement;
    const editor = element?.closest("[contenteditable='true']");
    return editor instanceof HTMLElement ? editor : null;
}

function placeCaretAtEnd(element: HTMLElement) {
    const range = document.createRange();
    range.selectNodeContents(element);
    range.collapse(false);
    const selection = window.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);
}

function getCaretTextOffset(editor: HTMLElement) {
    const selection = window.getSelection();
    if (!selection?.rangeCount) return null;
    const range = selection.getRangeAt(0).cloneRange();
    if (!editor.contains(range.startContainer)) return null;
    range.setStart(editor, 0);
    return range.toString().length;
}

function restoreCaretByTextOffset(editor: HTMLElement, offset: number) {
    const range = document.createRange();
    const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT);
    let remaining = Math.max(0, offset);
    let node = walker.nextNode();
    while (node) {
        const textLength = node.textContent?.length || 0;
        if (remaining <= textLength) {
            range.setStart(node, remaining);
            range.collapse(true);
            const selection = window.getSelection();
            selection?.removeAllRanges();
            selection?.addRange(range);
            return;
        }
        remaining -= textLength;
        node = walker.nextNode();
    }
    placeCaretAtEnd(editor);
}

function parseComposerTokens(value: string): Token[] {
    const tokens: Token[] = [];
    let lastIndex = 0;
    for (const match of value.matchAll(CONFIG_REFERENCE_PATTERN)) {
        if (match.index === undefined) continue;
        if (match.index > lastIndex) tokens.push({ type: "text", value: value.slice(lastIndex, match.index) });
        const source = match[1] as CanvasMentionSource;
        const targetId = match[2];
        tokens.push({ type: "reference", source, targetId, mentionKey: canvasMentionKey(source, targetId) });
        lastIndex = match.index + match[0].length;
    }
    if (lastIndex < value.length) tokens.push({ type: "text", value: value.slice(lastIndex) });
    return tokens;
}

function chipStyle(theme: (typeof canvasThemes)[keyof typeof canvasThemes]): CSSProperties {
    return { background: theme.toolbar.panel, borderColor: theme.node.stroke, color: theme.node.text };
}

function referenceSubtitle(reference: CanvasResourceReference) {
    return reference.source === "asset-library" ? `素材库 · ${kindLabel(reference.kind)}` : `${reference.sourceLabel} · 已连接素材`;
}

function kindLabel(kind: CanvasResourceReference["kind"]) {
    if (kind === "image") return "图片";
    if (kind === "video") return "视频";
    if (kind === "audio") return "音频";
    return "文本";
}
