"use client";

import localforage from "localforage";
import { nanoid } from "nanoid";
import { downloadServerAsset, serverAssetStorageKey, uploadServerAsset } from "@/services/api/assets";
import { useWorkspaceScopeStore, type WorkspaceScope } from "@/stores/use-workspace-scope-store";

export type UploadedFile = { url: string; storageKey: string; bytes: number; mimeType: string; width?: number; height?: number; durationMs?: number };

const store = localforage.createInstance({ name: "infinite-canvas", storeName: "media_files" });
const objectUrls = new Map<string, string>();

export async function uploadMediaFile(input: string | Blob, prefix = "file", options?: { scope?: WorkspaceScope; name?: string }): Promise<UploadedFile> {
    const blob = typeof input === "string" ? await (await fetch(input)).blob() : input;
    const type = mediaAssetType(blob.type, prefix);
    const scope = options?.scope || useWorkspaceScopeStore.getState().scope;
    const serverAsset = type ? await uploadServerAsset(blob, { type, scope, name: options?.name }).catch(() => null) : null;
    const storageKey = serverAsset ? serverAssetStorageKey(serverAsset, scope) : `${prefix}:${nanoid()}`;
    await store.setItem(storageKey, blob);
    revokeCachedObjectUrl(storageKey);
    const url = URL.createObjectURL(blob);
    objectUrls.set(storageKey, url);
    const meta = blob.type.startsWith("video/") ? await readVideoMeta(url) : blob.type.startsWith("audio/") ? await readAudioMeta(url) : {};
    return { url, storageKey, bytes: blob.size, mimeType: blob.type || "application/octet-stream", ...meta };
}

export async function resolveMediaUrl(storageKey?: string, fallback = "") {
    if (!storageKey) return fallback;
    const cached = objectUrls.get(storageKey);
    if (cached) return cached;
    let blob = await store.getItem<Blob>(storageKey);
    if (!blob && storageKey.startsWith("server:")) {
        blob = await downloadServerAsset(storageKey);
        if (blob) await store.setItem(storageKey, blob);
    }
    if (!blob) return fallback;
    const url = URL.createObjectURL(blob);
    objectUrls.set(storageKey, url);
    return url;
}

export async function getMediaBlob(storageKey: string) {
    const blob = await store.getItem<Blob>(storageKey);
    if (blob) return blob;
    if (!storageKey.startsWith("server:")) return null;
    const downloaded = await downloadServerAsset(storageKey);
    if (downloaded) await store.setItem(storageKey, downloaded);
    return downloaded;
}

export async function refreshMediaBlob(storageKey: string) {
    if (!storageKey.startsWith("server:")) return null;
    const downloaded = await downloadServerAsset(storageKey);
    if (!downloaded) return null;
    await store.setItem(storageKey, downloaded);
    revokeCachedObjectUrl(storageKey);
    return downloaded;
}

export async function setMediaBlob(storageKey: string, blob: Blob) {
    await store.setItem(storageKey, blob);
    revokeCachedObjectUrl(storageKey);
    const url = URL.createObjectURL(blob);
    objectUrls.set(storageKey, url);
    return url;
}

export async function clearLocalMediaCache() {
    for (const url of objectUrls.values()) {
        try {
            URL.revokeObjectURL(url);
        } catch {
            // Best-effort cleanup; stale object URLs should not block logout.
        }
    }
    objectUrls.clear();
    await store.clear();
}

export async function deleteStoredMedia(keys: Iterable<string>) {
    await Promise.all(
        Array.from(new Set(keys)).map(async (key) => {
            const url = objectUrls.get(key);
            if (url) URL.revokeObjectURL(url);
            objectUrls.delete(key);
            await store.removeItem(key);
        }),
    );
}

export async function cleanupUnusedMedia(usedData: unknown) {
    const usedKeys = collectMediaStorageKeys(usedData);
    const unused: string[] = [];
    await store.iterate((_value, key) => {
        if (!usedKeys.has(key)) unused.push(key);
    });
    await Promise.all(unused.map((key) => store.removeItem(key)));
}

export function collectMediaStorageKeys(value: unknown, keys = new Set<string>()) {
    if (!value || typeof value !== "object") return keys;
    if ("storageKey" in value && typeof value.storageKey === "string" && value.storageKey.includes(":")) keys.add(value.storageKey);
    Object.values(value).forEach((item) => (Array.isArray(item) ? item.forEach((child) => collectMediaStorageKeys(child, keys)) : collectMediaStorageKeys(item, keys)));
    return keys;
}

function mediaAssetType(mimeType: string, prefix: string): "video" | "audio" | undefined {
    if (mimeType.startsWith("video/") || prefix.startsWith("video")) return "video";
    if (mimeType.startsWith("audio/") || prefix.startsWith("audio")) return "audio";
    return undefined;
}

function revokeCachedObjectUrl(storageKey: string) {
    const previousUrl = objectUrls.get(storageKey);
    if (previousUrl) URL.revokeObjectURL(previousUrl);
    objectUrls.delete(storageKey);
}

function readVideoMeta(url: string) {
    return new Promise<{ width: number; height: number; durationMs?: number }>((resolve) => {
        const video = document.createElement("video");
        const done = () => resolve({ width: video.videoWidth || 1280, height: video.videoHeight || 720, durationMs: Number.isFinite(video.duration) ? Math.round(video.duration * 1000) : undefined });
        video.onloadedmetadata = done;
        video.onerror = done;
        video.src = url;
    });
}

function readAudioMeta(url: string) {
    return new Promise<{ durationMs?: number }>((resolve) => {
        const audio = document.createElement("audio");
        const done = () => resolve({ durationMs: Number.isFinite(audio.duration) ? Math.round(audio.duration * 1000) : undefined });
        audio.onloadedmetadata = done;
        audio.onerror = done;
        audio.src = url;
    });
}
