"use client";

import { useEffect, useMemo, useState, type CSSProperties, type ReactNode } from "react";
import { App, Modal, Segmented, Tooltip } from "antd";
import { Camera, Clapperboard, Download, Ellipsis, FolderPlus, Image as ImageIcon, Info, MessageSquare, Minus, Music2, Pencil, Plus, RefreshCw, Settings2, Trash2, Upload, Video } from "lucide-react";

import { canvasThemes } from "@/lib/canvas-theme";
import { formatBytes, getDataUrlByteSize } from "@/lib/image-utils";
import { useCopyText } from "@/hooks/use-copy-text";
import { useThemeStore } from "@/stores/use-theme-store";
import { CanvasNodeType, type CanvasNodeData, type ViewportTransform } from "../types";
import { ImageToolSettingsModal, type ImageToolbarSettingsTool } from "./canvas-image-toolbar-settings-modal";
import { IMAGE_QUICK_TOOLS_STORAGE_KEY, buildImageToolbarTools, defaultImageQuickToolIds, readImageQuickToolsConfig, type ImageQuickToolId } from "./canvas-image-toolbar-tools";

type CanvasNodeHoverToolbarProps = {
    node: CanvasNodeData | null;
    viewport: ViewportTransform;
    onKeep: (nodeId: string) => void;
    onLeave: () => void;
    onInfo: (node: CanvasNodeData) => void;
    onEditText: (node: CanvasNodeData) => void;
    onDecreaseFont: (node: CanvasNodeData) => void;
    onIncreaseFont: (node: CanvasNodeData) => void;
    onToggleDialog: (node: CanvasNodeData) => void;
    onGenerateImage: (node: CanvasNodeData) => void;
    onOpenDirector: (node: CanvasNodeData) => void;
    onUpload: (node: CanvasNodeData) => void;
    onDownload: (node: CanvasNodeData) => void;
    onSaveAsset: (node: CanvasNodeData) => void;
    onAnnotate: (node: CanvasNodeData) => void;
    onMaskEdit: (node: CanvasNodeData) => void;
    onCrop: (node: CanvasNodeData) => void;
    onFocus: (node: CanvasNodeData) => void;
    onOutpaint: (node: CanvasNodeData) => void;
    onStoryboard: (node: CanvasNodeData) => void;
    onPanorama: (node: CanvasNodeData) => void;
    onSplit: (node: CanvasNodeData) => void;
    onFlipHorizontal: (node: CanvasNodeData) => void;
    onFlipVertical: (node: CanvasNodeData) => void;
    onUpscale: (node: CanvasNodeData) => void;
    onCompress: (node: CanvasNodeData) => void;
    onSuperResolve: (node: CanvasNodeData) => void;
    onAngle: (node: CanvasNodeData) => void;
    onViewImage: (node: CanvasNodeData) => void;
    onCaptureVideoFrame: (node: CanvasNodeData) => void;
    onReversePrompt: (node: CanvasNodeData) => void;
    onRetry: (node: CanvasNodeData) => void;
    onToggleFreeResize: (node: CanvasNodeData) => void;
    onDelete: (node: CanvasNodeData) => void;
};

type ToolbarTool = {
    id: string;
    title: string;
    label: string;
    icon: ReactNode;
    onClick: () => void;
    active?: boolean;
    danger?: boolean;
};

export function CanvasNodeHoverToolbar({
    node,
    viewport,
    onKeep,
    onLeave,
    onInfo,
    onEditText,
    onDecreaseFont,
    onIncreaseFont,
    onToggleDialog,
    onGenerateImage,
    onOpenDirector,
    onUpload,
    onDownload,
    onSaveAsset,
    onAnnotate,
    onMaskEdit,
    onCrop,
    onFocus,
    onOutpaint,
    onStoryboard,
    onPanorama,
    onSplit,
    onFlipHorizontal,
    onFlipVertical,
    onUpscale,
    onCompress,
    onSuperResolve,
    onAngle,
    onViewImage,
    onCaptureVideoFrame,
    onReversePrompt,
    onRetry,
    onToggleFreeResize,
    onDelete,
}: CanvasNodeHoverToolbarProps) {
    const [quickImageToolIds, setQuickImageToolIds] = useState<ImageQuickToolId[]>(defaultImageQuickToolIds);
    const [showImageToolLabels, setShowImageToolLabels] = useState(true);
    const [draftImageToolIds, setDraftImageToolIds] = useState<ImageQuickToolId[]>(defaultImageQuickToolIds);
    const [draftShowImageToolLabels, setDraftShowImageToolLabels] = useState(true);
    const [imageToolSettingsOpen, setImageToolSettingsOpen] = useState(false);
    const { message } = App.useApp();
    const copyText = useCopyText();
    const colorTheme = useThemeStore((state) => state.theme);
    const theme = canvasThemes[colorTheme];

    useEffect(() => {
        try {
            const stored = window.localStorage.getItem(IMAGE_QUICK_TOOLS_STORAGE_KEY);
            if (!stored) return;
            const parsed = JSON.parse(stored) as unknown;
            const config = readImageQuickToolsConfig(parsed);
            setQuickImageToolIds(config.ids);
            setShowImageToolLabels(config.showLabels);
        } catch {
            window.localStorage.removeItem(IMAGE_QUICK_TOOLS_STORAGE_KEY);
        }
    }, []);

    useEffect(() => {
        setImageToolSettingsOpen(false);
    }, [node?.id]);

    if (!node) return null;
    const activeNode = node;

    const left = viewport.x + (node.position.x + node.width / 2) * viewport.k;
    const top = viewport.y + node.position.y * viewport.k - 14;
    const isImage = node.type === CanvasNodeType.Image;
    const isVideo = node.type === CanvasNodeType.Video;
    const isAudio = node.type === CanvasNodeType.Audio;
    const hasImage = isImage && Boolean(node.metadata?.content);
    const hasVideo = isVideo && Boolean(node.metadata?.content);
    const hasAudio = isAudio && Boolean(node.metadata?.content);
    const isText = node.type === CanvasNodeType.Text;
    const isConfig = node.type === CanvasNodeType.Config;
    const isDirector = node.type === CanvasNodeType.Director;
    const canOpenDialog = isText || hasImage || isVideo;
    const canRetry = node.metadata?.status === "error";
    const quickImageToolIdSet = new Set(quickImageToolIds);
    const copyImagePrompt = (target: CanvasNodeData) => {
        const prompt = target.metadata?.prompt?.trim();
        if (!prompt) {
            message.warning("暂无可复制的提示词");
            return;
        }
        copyText(prompt, "提示词已复制");
    };
    const imageTools = buildImageToolbarTools(node, { onUpload, onToggleFreeResize, onAnnotate, onMaskEdit, onCrop, onFocus, onOutpaint, onStoryboard, onPanorama, onSplit, onFlipHorizontal, onFlipVertical, onUpscale, onCompress, onSuperResolve, onAngle, onViewImage, onCopyPrompt: copyImagePrompt, onReversePrompt });

    function openImageToolSettings() {
        onKeep(activeNode.id);
        setDraftImageToolIds(quickImageToolIds);
        setDraftShowImageToolLabels(showImageToolLabels);
        setImageToolSettingsOpen(true);
    }

    const baseToolbarTools: ToolbarTool[] = [
        { id: "info", title: "查看节点信息", label: "信息", icon: <Info className="size-4" />, onClick: () => onInfo(node) },
        { id: "delete", title: "移除节点", label: "删除", icon: <Trash2 className="size-4" />, onClick: () => onDelete(node), danger: true },
    ];
    const nodeToolbarTools: ToolbarTool[] = [
        ...(isDirector ? [{ id: "openDirector", title: "打开 3D 导演台", label: "打开导演台", icon: <Clapperboard className="size-4" />, onClick: () => onOpenDirector(node) }] : []),
        ...(canRetry ? [{ id: "retry", title: "重新生成", label: "重试", icon: <RefreshCw className="size-4" />, onClick: () => onRetry(node) }] : []),
        ...(hasImage || hasVideo || isText ? [{ id: "saveAsset", title: "加入资产库", label: "存资产", icon: <FolderPlus className="size-4" />, onClick: () => onSaveAsset(node) }] : []),
        ...(hasImage || hasVideo || hasAudio ? [{ id: "download", title: hasAudio ? "下载音频" : hasVideo ? "下载视频" : "下载图片", label: "下载", icon: <Download className="size-4" />, onClick: () => onDownload(node) }] : []),
        ...(canOpenDialog ? [{ id: "edit", title: "编辑", label: "编辑", icon: <MessageSquare className="size-4" />, onClick: () => onToggleDialog(node) }] : []),
        ...(isText ? [{ id: "editText", title: "编辑文本", label: "编辑文字", icon: <Pencil className="size-4" />, onClick: () => onEditText(node) }] : []),
        ...(isText ? [{ id: "generateImage", title: "用文本生图", label: "生图", icon: <ImageIcon className="size-4" />, onClick: () => onGenerateImage(node) }] : []),
        ...(isConfig ? [{ id: "config", title: "生成配置", label: "生成配置", icon: <Settings2 className="size-4" />, onClick: () => onToggleDialog(node) }] : []),
        ...(isText ? [{ id: "decreaseFont", title: "减小字号", label: "缩小", icon: <Minus className="size-4" />, onClick: () => onDecreaseFont(node) }] : []),
        ...(isText ? [{ id: "increaseFont", title: "增大字号", label: "放大", icon: <Plus className="size-4" />, onClick: () => onIncreaseFont(node) }] : []),
        ...(isImage && !hasImage ? [{ id: "uploadImage", title: "上传图片", label: "上传图片", icon: <Upload className="size-4" />, onClick: () => onUpload(node) }] : []),
        ...(isVideo ? [{ id: "uploadVideo", title: hasVideo ? "替换视频" : "上传视频", label: hasVideo ? "替换视频" : "上传视频", icon: <Video className="size-4" />, onClick: () => onUpload(node) }] : []),
        ...(hasVideo ? [{ id: "captureFrame", title: "截取当前视频帧", label: "截图", icon: <Camera className="size-4" />, onClick: () => onCaptureVideoFrame(node) }] : []),
        ...(isAudio ? [{ id: "uploadAudio", title: hasAudio ? "替换音频" : "上传音频", label: hasAudio ? "替换音频" : "上传音频", icon: <Music2 className="size-4" />, onClick: () => onUpload(node) }] : []),
        ...(hasImage ? imageTools.map((tool) => ({ id: tool.id, title: tool.title, label: tool.label, icon: tool.icon, active: tool.active, onClick: tool.onClick })) : []),
    ];
    const toolbarTools = hasImage ? [...baseToolbarTools, ...nodeToolbarTools].filter((tool) => quickImageToolIdSet.has(tool.id as ImageQuickToolId)) : [...baseToolbarTools, ...nodeToolbarTools];
    const selectableImageToolbarTools = [...baseToolbarTools, ...nodeToolbarTools].filter((tool) => tool.id !== "retry") as ImageToolbarSettingsTool[];
    const toolbarStyle = {
        left: hasImage ? `clamp(236px, ${left}px, calc(100% - 236px))` : left,
        top,
        ...(hasImage ? { width: 440, maxWidth: "calc(100% - 32px)", maxHeight: Math.max(160, Math.min(360, top - 18)) } : {}),
        background: colorTheme === "dark" ? "linear-gradient(135deg, rgba(157,77,255,.13), rgba(255,79,140,.055)), rgba(9,10,18,.90)" : "rgba(255,255,255,.88)",
        borderColor: theme.toolbar.border,
        boxShadow: colorTheme === "dark" ? "0 18px 42px rgba(0,0,0,.32), inset 0 1px 0 rgba(255,255,255,.08)" : "0 14px 34px rgba(46,20,88,.14)",
        color: theme.node.text,
        "--canvas-node-tool-hover": theme.toolbar.itemHover,
        "--canvas-node-tool-active": theme.toolbar.activeBg,
        "--canvas-node-tool-danger": "#ff5367",
    } as CSSProperties;

    const closeImageToolSettings = () => {
        setImageToolSettingsOpen(false);
        onLeave();
    };

    const setDraftImageToolVisible = (id: ImageQuickToolId, visible: boolean) => {
        setDraftImageToolIds((current) => {
            const selected = new Set(current);
            if (visible) selected.add(id);
            else selected.delete(id);
            return selectableImageToolbarTools.filter((tool) => selected.has(tool.id)).map((tool) => tool.id);
        });
    };

    const saveImageToolSettings = () => {
        const config = { ids: draftImageToolIds, showLabels: draftShowImageToolLabels };
        setQuickImageToolIds(config.ids);
        setShowImageToolLabels(config.showLabels);
        window.localStorage.setItem(IMAGE_QUICK_TOOLS_STORAGE_KEY, JSON.stringify(config));
        closeImageToolSettings();
    };

    return (
        <>
            <div
                className={hasImage
                    ? "canvas-node-hover-toolbar canvas-node-hover-toolbar--card absolute z-[70] flex -translate-x-1/2 -translate-y-full flex-col overflow-visible rounded-2xl border p-3 text-[15px] backdrop-blur-xl"
                    : "canvas-node-hover-toolbar absolute z-[70] flex h-12 -translate-x-1/2 -translate-y-full items-center overflow-visible rounded-xl border text-[15px] backdrop-blur-xl"}
                style={toolbarStyle}
                data-canvas-ui
                data-canvas-no-zoom
                onMouseEnter={() => onKeep(node.id)}
                onMouseLeave={() => {
                    if (!imageToolSettingsOpen) onLeave();
                }}
                onMouseDown={(event) => event.stopPropagation()}
                onPointerDown={(event) => event.stopPropagation()}
            >
                {hasImage ? (
                    <>
                        <div className="mb-2 flex items-center justify-between gap-3 px-1">
                            <div>
                                <div className="text-sm font-semibold">图片操作</div>
                                <div className="mt-0.5 text-[11px] opacity-55">选择工具后在当前图片上继续处理</div>
                            </div>
                            <span className="rounded-full border px-2 py-0.5 text-[10px] opacity-60" style={{ borderColor: theme.toolbar.border }}>{toolbarTools.length} 项</span>
                        </div>
                        <div className={`thin-scrollbar grid min-h-0 flex-1 gap-1 overflow-x-hidden overflow-y-auto pr-1 ${showImageToolLabels ? "grid-cols-4" : "grid-cols-6"}`}>
                            {toolbarTools.map((tool) => (
                                <ToolbarAction key={tool.id} {...tool} showLabel={showImageToolLabels} variant="card" />
                            ))}
                            <ToolbarAction id="more" title="配置快捷工具" label="更多" icon={<Ellipsis className="size-4" />} active={imageToolSettingsOpen} onClick={openImageToolSettings} showLabel={showImageToolLabels} variant="card" />
                        </div>
                    </>
                ) : (
                    toolbarTools.map((tool) => <ToolbarAction key={tool.id} {...tool} showLabel />)
                )}
            </div>
            {hasImage ? (
                <ImageToolSettingsModal
                    open={imageToolSettingsOpen}
                    tools={selectableImageToolbarTools}
                    selectedIds={draftImageToolIds}
                    showLabels={draftShowImageToolLabels}
                    onToggle={setDraftImageToolVisible}
                    onShowLabelsChange={setDraftShowImageToolLabels}
                    onCancel={closeImageToolSettings}
                    onSave={saveImageToolSettings}
                />
            ) : null}
        </>
    );
}

export function CanvasNodeInfoModal({ node, open, onClose }: { node: CanvasNodeData | null; open: boolean; onClose: () => void }) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const [view, setView] = useState<"info" | "json">("info");
    const modalNode = node;
    const imageBytes = modalNode?.type === CanvasNodeType.Image && modalNode.metadata?.content ? getDataUrlByteSize(modalNode.metadata.content) : 0;
    const batchCount = node?.type === CanvasNodeType.Image ? node.metadata?.batchChildIds?.length || 0 : 0;
    const json = useMemo(() => {
        if (!node) return "";
        return JSON.stringify(
            node,
            (key, value) => {
                if (key === "title") return undefined;
                if (key === "content" && typeof value === "string" && value.startsWith("data:image/")) {
                    return "[base64 image]";
                }
                return value;
            },
            2,
        );
    }, [node]);

    useEffect(() => {
        if (open) setView("info");
    }, [node?.id, open]);

    const title = (
        <div className="flex items-center justify-between gap-4 pr-12">
            <span>节点信息</span>
            <Segmented
                size="small"
                value={view}
                onChange={(value) => setView(value as "info" | "json")}
                options={[
                    { label: "信息", value: "info" },
                    { label: "JSON", value: "json" },
                ]}
            />
        </div>
    );

    return (
        <Modal className="canvas-themed-modal canvas-node-info-modal" title={title} open={open && Boolean(node)} centered footer={null} onCancel={onClose}>
            {modalNode ? (
                <div className="h-[56vh] min-h-[360px] text-sm">
                    {view === "info" ? (
                        <div className="thin-scrollbar h-full space-y-3 overflow-auto pr-1">
                            <InfoRow label="ID" value={modalNode.id} />
                            <InfoRow label="类型" value={modalNode.type === CanvasNodeType.Text ? "文本" : modalNode.type === CanvasNodeType.Image ? "图片" : modalNode.type === CanvasNodeType.Video ? "视频" : modalNode.type === CanvasNodeType.Audio ? "音频" : modalNode.type === CanvasNodeType.Director ? "3D 导演台" : "生成配置"} />
                            <InfoRow label="尺寸" value={`${Math.round(modalNode.width)} x ${Math.round(modalNode.height)}`} />
                            <InfoRow label="位置" value={`${Math.round(modalNode.position.x)}, ${Math.round(modalNode.position.y)}`} />
                            <InfoRow label="状态" value={modalNode.metadata?.status || "idle"} />
                            {batchCount > 1 ? <InfoRow label="图片组" value={`${batchCount} 张`} /> : null}
                            {modalNode.metadata?.prompt ? <InfoRow label="提示词" value={modalNode.metadata.prompt} /> : null}
                            {imageBytes ? <InfoRow label="图片大小" value={formatBytes(imageBytes)} /> : null}
                            {modalNode.metadata?.errorDetails ? (
                                <div className="rounded-lg border p-3 text-red-400" style={{ borderColor: theme.node.stroke }}>
                                    {modalNode.metadata.errorDetails}
                                </div>
                            ) : null}
                        </div>
                    ) : (
                        <pre className="thin-scrollbar h-full overflow-auto rounded-lg border p-3 text-xs leading-5" style={{ background: theme.node.fill, borderColor: theme.node.stroke, color: theme.node.text }}>
                            {json}
                        </pre>
                    )}
                </div>
            ) : null}
        </Modal>
    );
}

function ToolbarAction({ id, title, label, icon, onClick, showLabel, variant = "bar", active = false, danger = false }: ToolbarTool & { showLabel: boolean; variant?: "bar" | "card" }) {
    const hasText = showLabel && Boolean(label);
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const card = variant === "card";
    return (
        <Tooltip title={title} placement="top" mouseEnterDelay={0.2} color="rgba(9,10,18,.94)" styles={{ root: { color: theme.node.text, boxShadow: "0 10px 28px rgba(0,0,0,.28)", fontSize: 13, fontWeight: 600 } }}>
            <button type="button" className={`canvas-node-tool-action group relative flex items-center whitespace-nowrap ${card ? "h-[58px] min-w-0 justify-center p-0.5" : "h-12 px-1.5"} ${danger ? "is-danger" : ""}`} data-testid={`canvas-node-tool-${id}`} onClick={onClick} aria-label={title}>
                <span className={`flex items-center ${card ? `h-full w-full min-w-0 flex-col justify-center rounded-xl ${hasText ? "gap-1 px-1" : "gap-0"}` : `h-9 rounded-lg ${hasText ? "gap-2 px-2.5" : "justify-center px-2"}`} transition ${active ? "is-active" : ""}`} style={{ color: danger ? "#ff5367" : theme.node.text }}>
                    {icon}
                    {hasText ? <span className={card ? "max-w-full truncate text-[11px] leading-4" : undefined}>{label}</span> : null}
                </span>
            </button>
        </Tooltip>
    );
}

function InfoRow({ label, value }: { label: string; value: ReactNode }) {
    return (
        <div className="grid grid-cols-[72px_minmax(0,1fr)] gap-3">
            <span className="opacity-50">{label}</span>
            <span className="min-w-0 whitespace-pre-wrap break-words">{value}</span>
        </div>
    );
}
