"use client";

import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";

import { fetchUserPreferences, updateUserPreferences, type CanvasShortcutAction, type UserCanvasPreferences, type UserGenerationPreferences, type UserPreferences, type UserPreferencesPayload, type UserPromptPreset, type UserPromptPresetPriority } from "@/services/api/user-preferences";
import { scopedUserPreferenceStoreKey, setCurrentUserStorageScope } from "@/services/user-scoped-storage";
import { defaultConfig, useConfigStore, type AiConfig } from "@/stores/use-config-store";
import type { LocalUser } from "@/stores/use-user-store";

export type { CanvasShortcutAction, UserCanvasPreferences, UserGenerationPreferences, UserPreferences, UserPromptPreset, UserPromptPresetPriority };

// Keeps persisted drag order bounded while leaving ample room for user-managed presets.
const MAX_PROMPT_PRESET_SORT_ORDER = 1_000_000;
const PROMPT_PRESET_PRIORITY_ORDER: Record<UserPromptPresetPriority, number> = { pinned: 0, high: 1, normal: 2, low: 3 };

export const shortcutActionLabels: Record<CanvasShortcutAction, string> = {
    undo: "撤销",
    redo: "重做",
    delete: "删除选中",
    copy: "复制",
    paste: "粘贴",
    selectAll: "全选",
    runSelection: "运行选中",
    openSettings: "打开设置",
    resetZoom: "缩放复位",
};

export const shortcutActionOrder: CanvasShortcutAction[] = ["undo", "redo", "delete", "copy", "paste", "selectAll", "runSelection", "openSettings", "resetZoom"];

export const defaultUserPreferences: UserPreferences = {
    generation: {
        imageModel: "",
        videoModel: "",
        textModel: "",
        audioModel: "",
        quality: "auto",
        size: "1:1",
        count: "1",
        canvasImageCount: "3",
        videoSeconds: "6",
        vquality: "720",
        videoGenerateAudio: "true",
        videoWatermark: "false",
        audioVoice: "alloy",
        audioFormat: "mp3",
        audioSpeed: "1",
        audioInstructions: "",
        systemPrompt: "",
    },
    shortcuts: {
        undo: ["Ctrl+Z", "Meta+Z"],
        redo: ["Ctrl+Shift+Z", "Meta+Shift+Z", "Ctrl+Y"],
        delete: ["Delete", "Backspace"],
        copy: ["Ctrl+C", "Meta+C"],
        paste: ["Ctrl+V", "Meta+V"],
        selectAll: ["Ctrl+A", "Meta+A"],
        runSelection: ["Ctrl+Enter", "Meta+Enter"],
        openSettings: ["Ctrl+,"],
        resetZoom: ["Ctrl+0", "Meta+0"],
    },
    canvas: {
        middleButtonLockHint: true,
        backgroundMode: "lines",
        wheelZoomRequiresCtrl: true,
        promptPresets: [],
    },
};

type UserPreferencesStore = {
    hydrated: boolean;
    loading: boolean;
    saving: boolean;
    error: string;
    preferences: UserPreferences;
    switchUserScope: (user: LocalUser | null) => Promise<void>;
    hydrateRemote: () => Promise<void>;
    updateGeneration: <K extends keyof UserGenerationPreferences>(key: K, value: UserGenerationPreferences[K]) => void;
    updateCanvas: <K extends keyof UserCanvasPreferences>(key: K, value: UserCanvasPreferences[K]) => void;
    updateShortcut: (action: CanvasShortcutAction, shortcuts: string[]) => void;
    savePreferences: (patch?: UserPreferencesPayload) => Promise<UserPreferences>;
    resetDefaults: () => Promise<UserPreferences>;
};

export const useUserPreferencesStore = create<UserPreferencesStore>()(
    persist(
        (set, get) => ({
            hydrated: false,
            loading: false,
            saving: false,
            error: "",
            preferences: defaultUserPreferences,
            switchUserScope: async (user) => {
                const nextKey = scopedUserPreferenceStoreKey(user?.id);
                if (useUserPreferencesStore.persist.getOptions().name === nextKey && get().hydrated) {
                    if (user) void get().hydrateRemote();
                    return;
                }
                setCurrentUserStorageScope(user?.id);
                useUserPreferencesStore.persist.setOptions({ name: nextKey });
                set({ hydrated: false, loading: Boolean(user), error: "", preferences: defaultUserPreferences });
                await useUserPreferencesStore.persist.rehydrate();
                if (!user) {
                    set({ hydrated: true, loading: false, preferences: defaultUserPreferences });
                    applyGenerationToConfig(defaultUserPreferences.generation);
                    return;
                }
                await get().hydrateRemote();
            },
            hydrateRemote: async () => {
                set({ loading: true, error: "" });
                try {
                    const remote = normalizeUserPreferences(await fetchUserPreferences());
                    set({ preferences: remote, hydrated: true, loading: false });
                    applyGenerationToConfig(remote.generation);
                    return;
                } catch (error) {
                    set({ hydrated: true, loading: false, error: error instanceof Error ? error.message : "偏好加载失败" });
                }
            },
            updateGeneration: (key, value) =>
                set((state) => {
                    const preferences = normalizeUserPreferences({ ...state.preferences, generation: { ...state.preferences.generation, [key]: value } });
                    applyGenerationToConfig(preferences.generation);
                    return { preferences };
                }),
            updateCanvas: (key, value) =>
                set((state) => ({
                    preferences: normalizeUserPreferences({ ...state.preferences, canvas: { ...state.preferences.canvas, [key]: value } }),
                })),
            updateShortcut: (action, shortcuts) =>
                set((state) => ({
                    preferences: normalizeUserPreferences({ ...state.preferences, shortcuts: { ...state.preferences.shortcuts, [action]: normalizeShortcutList(shortcuts) } }),
                })),
            savePreferences: async (patch) => {
                const current = normalizeUserPreferences(get().preferences);
                const payload = patch || current;
                set({ saving: true, error: "" });
                try {
                    const saved = normalizeUserPreferences(await updateUserPreferences(payload));
                    set({ preferences: saved, saving: false });
                    applyGenerationToConfig(saved.generation);
                    return saved;
                } catch (error) {
                    set({ saving: false, error: error instanceof Error ? error.message : "偏好保存失败" });
                    throw error;
                }
            },
            resetDefaults: async () => {
                const next = normalizeUserPreferences(defaultUserPreferences);
                set({ preferences: next });
                applyGenerationToConfig(next.generation);
                return get().savePreferences(next);
            },
        }),
        {
            name: scopedUserPreferenceStoreKey(),
            storage: createJSONStorage(() => window.localStorage),
            partialize: (state) => ({ preferences: state.preferences }),
            merge: (persisted, current) => {
                const persistedState = (persisted || {}) as Partial<UserPreferencesStore>;
                return {
                    ...current,
                    preferences: normalizeUserPreferences(persistedState.preferences),
                };
            },
            onRehydrateStorage: () => () => {
                const preferences = normalizeUserPreferences(useUserPreferencesStore.getState().preferences);
                useUserPreferencesStore.setState({ hydrated: true, preferences });
                applyGenerationToConfig(preferences.generation);
            },
        },
    ),
);

export function normalizeUserPreferences(value?: Partial<UserPreferences> | null): UserPreferences {
    return {
        generation: normalizeGenerationPreferences(value?.generation),
        shortcuts: normalizeShortcuts(value?.shortcuts),
        canvas: normalizeCanvasPreferences(value?.canvas),
        updated_at: value?.updated_at,
    };
}

export function normalizeShortcutCombo(event: KeyboardEvent) {
    const key = normalizeKeyName(event.key);
    if (!key) return "";
    const modifiers = [];
    if (event.ctrlKey) modifiers.push("Ctrl");
    if (event.metaKey) modifiers.push("Meta");
    if (event.altKey) modifiers.push("Alt");
    if (event.shiftKey) modifiers.push("Shift");
    if (["Control", "Meta", "Alt", "Shift"].includes(key)) return "";
    return [...modifiers, key].join("+");
}

export function eventMatchesShortcut(event: KeyboardEvent, shortcuts: string[]) {
    const combo = normalizeShortcutCombo(event);
    return Boolean(combo && normalizeShortcutList(shortcuts).includes(combo));
}

export function shortcutDisplay(combo: string) {
    return combo.replaceAll("Ctrl", "Ctrl").replaceAll("Meta", "Cmd").replaceAll("Shift", "Shift").replaceAll("Alt", "Alt").replaceAll("+", " + ");
}

export function findShortcutConflicts(shortcuts: Record<CanvasShortcutAction, string[]>) {
    const seen = new Map<string, CanvasShortcutAction>();
    const conflicts = new Map<string, CanvasShortcutAction[]>();
    shortcutActionOrder.forEach((action) => {
        normalizeShortcutList(shortcuts[action]).forEach((combo) => {
            const existing = seen.get(combo);
            if (existing && existing !== action) {
                conflicts.set(combo, Array.from(new Set([...(conflicts.get(combo) || [existing]), action])));
                return;
            }
            seen.set(combo, action);
        });
    });
    return conflicts;
}

function normalizeGenerationPreferences(value?: Partial<UserGenerationPreferences> | null): UserGenerationPreferences {
    const base = defaultUserPreferences.generation;
    return {
        ...base,
        ...(value || {}),
        count: normalizeIntegerString(value?.count, base.count, 1, 15),
        canvasImageCount: normalizeIntegerString(value?.canvasImageCount, base.canvasImageCount, 1, 15),
        videoSeconds: normalizePlainString(value?.videoSeconds, base.videoSeconds),
        audioSpeed: normalizeNumberString(value?.audioSpeed, base.audioSpeed, 0.25, 4),
    };
}

function normalizeCanvasPreferences(value?: Partial<UserCanvasPreferences> | null): UserCanvasPreferences {
    return {
        ...defaultUserPreferences.canvas,
        ...(value || {}),
        backgroundMode: value?.backgroundMode === "dots" || value?.backgroundMode === "blank" ? value.backgroundMode : value?.backgroundMode === "lines" ? "lines" : defaultUserPreferences.canvas.backgroundMode,
        middleButtonLockHint: value?.middleButtonLockHint !== false,
        wheelZoomRequiresCtrl: value?.wheelZoomRequiresCtrl !== false,
        promptPresets: normalizePromptPresets(value?.promptPresets),
    };
}

function normalizePromptPresets(value?: UserPromptPreset[] | null): UserPromptPreset[] {
    if (!Array.isArray(value)) return [];
    const seen = new Set<string>();
    return value
        .map((item, index) => ({
            id: normalizePlainString(item?.id, `preset-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`),
            title: String(item?.title || "").trim().slice(0, 80),
            prompt: String(item?.prompt || "").trim().slice(0, 4000),
            tags: Array.isArray(item?.tags) ? item.tags.map((tag) => String(tag || "").trim().slice(0, 24)).filter(Boolean).slice(0, 12) : [],
            priority: normalizePromptPresetPriority(item?.priority),
            sort_order: normalizePromptPresetSortOrder(item?.sort_order, index),
            createdAt: String(item?.createdAt || new Date().toISOString()),
            updatedAt: String(item?.updatedAt || item?.createdAt || new Date().toISOString()),
        }))
        .filter((item) => {
            if (!item.id || !item.title || !item.prompt || seen.has(item.id)) return false;
            seen.add(item.id);
            return true;
        })
        .sort((left, right) => PROMPT_PRESET_PRIORITY_ORDER[left.priority] - PROMPT_PRESET_PRIORITY_ORDER[right.priority] || left.sort_order - right.sort_order || left.createdAt.localeCompare(right.createdAt))
        .slice(0, 100);
}

function normalizePromptPresetPriority(value?: UserPromptPresetPriority): UserPromptPresetPriority {
    return value === "pinned" || value === "high" || value === "low" ? value : "normal";
}

function normalizePromptPresetSortOrder(value: number | undefined, fallback: number) {
    const parsed = Math.floor(Number(value));
    return Math.max(0, Math.min(MAX_PROMPT_PRESET_SORT_ORDER, Number.isFinite(parsed) ? parsed : fallback));
}

function normalizeShortcuts(value?: Partial<Record<CanvasShortcutAction, string[]>> | null): Record<CanvasShortcutAction, string[]> {
    return shortcutActionOrder.reduce(
        (result, action) => ({
            ...result,
            [action]: normalizeShortcutList(value?.[action] || defaultUserPreferences.shortcuts[action]),
        }),
        {} as Record<CanvasShortcutAction, string[]>,
    );
}

export function normalizeShortcutList(shortcuts: string[]) {
    const seen = new Set<string>();
    return (shortcuts || [])
        .map((shortcut) => normalizeShortcutString(shortcut))
        .filter((shortcut) => {
            if (!shortcut || seen.has(shortcut)) return false;
            seen.add(shortcut);
            return true;
        });
}

function normalizeShortcutString(value: string) {
    const parts = String(value || "")
        .split("+")
        .map((part) => normalizeKeyName(part.trim()))
        .filter(Boolean);
    if (!parts.length) return "";
    const key = parts.pop()!;
    const modifiers = ["Ctrl", "Meta", "Alt", "Shift"].filter((modifier) => parts.includes(modifier));
    return [...modifiers, key].join("+");
}

function normalizeKeyName(value: string) {
    const key = value.trim();
    if (!key) return "";
    const lower = key.toLowerCase();
    if (lower === "control" || lower === "ctrl") return "Ctrl";
    if (lower === "cmd" || lower === "command" || lower === "meta") return "Meta";
    if (lower === "option" || lower === "alt") return "Alt";
    if (lower === "shift") return "Shift";
    if (lower === "esc") return "Escape";
    if (lower === " ") return "Space";
    if (key.length === 1) return key.toUpperCase();
    return key[0]?.toUpperCase() + key.slice(1);
}

function applyGenerationToConfig(generation: UserGenerationPreferences) {
    const state = useConfigStore.getState();
    const current = state.config;
    const patch: Partial<AiConfig> = {
        imageModel: generation.imageModel && current.imageModels.includes(generation.imageModel) ? generation.imageModel : current.imageModel,
        videoModel: generation.videoModel && current.videoModels.includes(generation.videoModel) ? generation.videoModel : current.videoModel,
        textModel: generation.textModel && current.textModels.includes(generation.textModel) ? generation.textModel : current.textModel,
        audioModel: generation.audioModel && current.audioModels.includes(generation.audioModel) ? generation.audioModel : current.audioModel,
        quality: generation.quality || defaultConfig.quality,
        size: generation.size || defaultConfig.size,
        count: generation.count || defaultConfig.count,
        canvasImageCount: generation.canvasImageCount || defaultConfig.canvasImageCount,
        videoSeconds: generation.videoSeconds || defaultConfig.videoSeconds,
        vquality: generation.vquality || defaultConfig.vquality,
        videoGenerateAudio: generation.videoGenerateAudio || defaultConfig.videoGenerateAudio,
        videoWatermark: generation.videoWatermark || defaultConfig.videoWatermark,
        audioVoice: generation.audioVoice || defaultConfig.audioVoice,
        audioFormat: generation.audioFormat || defaultConfig.audioFormat,
        audioSpeed: generation.audioSpeed || defaultConfig.audioSpeed,
        audioInstructions: generation.audioInstructions || "",
        systemPrompt: generation.systemPrompt || "",
    };
    useConfigStore.setState({ config: { ...current, ...patch } });
}

function normalizeIntegerString(value: string | undefined, fallback: string, min: number, max: number) {
    const parsed = Math.floor(Math.abs(Number(value)));
    return String(Math.max(min, Math.min(max, Number.isFinite(parsed) && parsed > 0 ? parsed : Number(fallback))));
}

function normalizeNumberString(value: string | undefined, fallback: string, min: number, max: number) {
    const parsed = Number(value);
    return String(Math.max(min, Math.min(max, Number.isFinite(parsed) ? Number(parsed.toFixed(2)) : Number(fallback))));
}

function normalizePlainString(value: string | undefined, fallback: string) {
    return typeof value === "string" && value.trim() ? value : fallback;
}
