"use client";

import { useEffect, useMemo, useState } from "react";
import type { DragEvent as ReactDragEvent } from "react";
import { App, Button, Empty, Input, Modal, Select, Tag } from "antd";
import { Check, GripVertical, Pencil, Plus, Save, Search, Trash2 } from "lucide-react";

import { useUserPreferencesStore, type UserPromptPreset, type UserPromptPresetPriority } from "@/stores/use-user-preferences-store";

type DraftPreset = {
    id: string | null;
    title: string;
    prompt: string;
    tags: string;
    priority: UserPromptPresetPriority;
};

const emptyDraft: DraftPreset = { id: null, title: "", prompt: "", tags: "", priority: "normal" };
const priorityOptions: Array<{ value: UserPromptPresetPriority; label: string }> = [
    { value: "pinned", label: "置顶" },
    { value: "high", label: "高" },
    { value: "normal", label: "普通" },
    { value: "low", label: "低" },
];
const priorityLabels: Record<UserPromptPresetPriority, string> = { pinned: "置顶", high: "高", normal: "普通", low: "低" };
const priorityColors: Record<UserPromptPresetPriority, string> = { pinned: "magenta", high: "orange", normal: "blue", low: "default" };

export function UserPromptPresetDialog({ open, onOpenChange, onSelect }: { open: boolean; onOpenChange: (open: boolean) => void; onSelect: (prompt: string) => void }) {
    const { message } = App.useApp();
    const presets = useUserPreferencesStore((state) => state.preferences.canvas.promptPresets);
    const savePreferences = useUserPreferencesStore((state) => state.savePreferences);
    const saving = useUserPreferencesStore((state) => state.saving);
    const [keyword, setKeyword] = useState("");
    const [draft, setDraft] = useState<DraftPreset>(emptyDraft);
    const [draggedId, setDraggedId] = useState<string | null>(null);
    const filtered = useMemo(() => filterPresets(presets, keyword), [keyword, presets]);

    useEffect(() => {
        if (!open) return;
        setKeyword("");
        setDraft(emptyDraft);
        setDraggedId(null);
    }, [open]);

    const saveDraft = async () => {
        const title = draft.title.trim();
        const prompt = draft.prompt.trim();
        if (!title || !prompt) {
            message.warning("请填写标题和提示词");
            return;
        }
        const now = new Date().toISOString();
        const existing = presets.find((item) => item.id === draft.id);
        const nextItem: UserPromptPreset = {
            id: draft.id || `preset-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            title,
            prompt,
            tags: draft.tags
                .split(/[,\s，、]+/)
                .map((tag) => tag.trim())
                .filter(Boolean)
                .slice(0, 12),
            priority: draft.priority,
            sort_order: existing?.priority === draft.priority ? existing.sort_order : nextSortOrder(presets, draft.priority),
            createdAt: existing?.createdAt || now,
            updatedAt: now,
        };
        const next = draft.id ? presets.map((item) => (item.id === draft.id ? nextItem : item)) : [...presets, nextItem];
        await savePreferences({ canvas: { promptPresets: next } });
        setDraft(emptyDraft);
        message.success("预设已保存");
    };

    const deletePreset = async (id: string) => {
        await savePreferences({ canvas: { promptPresets: presets.filter((item) => item.id !== id) } });
        if (draft.id === id) setDraft(emptyDraft);
        message.success("预设已删除");
    };

    const editPreset = (item: UserPromptPreset) => setDraft({ id: item.id, title: item.title, prompt: item.prompt, tags: item.tags.join(" "), priority: item.priority });

    const reorderPreset = async (targetId: string) => {
        if (!draggedId || draggedId === targetId || keyword.trim()) return;
        const dragged = presets.find((item) => item.id === draggedId);
        const target = presets.find((item) => item.id === targetId);
        if (!dragged || !target || dragged.priority !== target.priority) return;
        const samePriority = presets.filter((item) => item.priority === dragged.priority);
        const fromIndex = samePriority.findIndex((item) => item.id === dragged.id);
        const toIndex = samePriority.findIndex((item) => item.id === target.id);
        if (fromIndex < 0 || toIndex < 0) return;
        samePriority.splice(toIndex, 0, samePriority.splice(fromIndex, 1)[0]);
        const orderById = new Map(samePriority.map((item, index) => [item.id, index]));
        const next = presets.map((item) => (item.priority === dragged.priority ? { ...item, sort_order: orderById.get(item.id) ?? item.sort_order } : item));
        setDraggedId(null);
        await savePreferences({ canvas: { promptPresets: next } });
        message.success("同级预设顺序已更新");
    };

    const allowPresetDrop = (event: ReactDragEvent, target: UserPromptPreset) => {
        const dragged = presets.find((item) => item.id === draggedId);
        if (!dragged || dragged.priority !== target.priority || keyword.trim()) return;
        event.preventDefault();
        event.dataTransfer.dropEffect = "move";
    };

    const selectPreset = (item: UserPromptPreset) => {
        onSelect(item.prompt);
        onOpenChange(false);
    };

    return (
        <Modal title="我的预设" open={open} onCancel={() => onOpenChange(false)} footer={null} width={980} centered>
            <div className="grid gap-5 md:grid-cols-[minmax(0,1fr)_340px]" data-testid="user-prompt-preset-dialog">
                <div className="min-w-0">
                    <Input size="large" prefix={<Search className="size-4 text-stone-400" />} value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="搜索标题、标签或提示词" />
                    <p className="mt-2 text-xs text-stone-500 dark:text-stone-400">按置顶 / 高 / 普通 / 低排序；同一级别可拖动调整常用顺序。</p>
                    <div className="thin-scrollbar mt-4 max-h-[560px] space-y-3 overflow-y-auto pr-2">
                        {filtered.map((item) => (
                            <div
                                key={item.id}
                                className="rounded-xl border border-stone-200 bg-white p-3 shadow-sm dark:border-white/10 dark:bg-white/[0.04]"
                                data-testid="user-prompt-preset-item"
                                data-priority={item.priority}
                                data-sort-order={item.sort_order}
                                draggable={!saving && !keyword.trim()}
                                onDragStart={(event) => {
                                    setDraggedId(item.id);
                                    event.dataTransfer.effectAllowed = "move";
                                    event.dataTransfer.setData("text/plain", item.id);
                                }}
                                onDragOver={(event) => allowPresetDrop(event, item)}
                                onDrop={(event) => {
                                    event.preventDefault();
                                    void reorderPreset(item.id);
                                }}
                                onDragEnd={() => setDraggedId(null)}
                            >
                                <div className="flex items-start justify-between gap-3">
                                    <div className="flex min-w-0 gap-2">
                                        <GripVertical className="mt-0.5 size-4 shrink-0 cursor-grab text-stone-400" aria-label="拖动排序" />
                                        <div className="min-w-0">
                                        <div className="flex items-center gap-2">
                                            <div className="truncate font-semibold">{item.title}</div>
                                            <Tag color={priorityColors[item.priority]} className="m-0 shrink-0">{priorityLabels[item.priority]}</Tag>
                                        </div>
                                        <p className="mt-1 line-clamp-3 text-xs leading-5 text-stone-500 dark:text-stone-400">{item.prompt}</p>
                                        </div>
                                    </div>
                                    <div className="flex shrink-0 items-center gap-1">
                                        <Button size="small" type="primary" icon={<Check className="size-3.5" />} onClick={() => selectPreset(item)}>
                                            使用
                                        </Button>
                                        <Button size="small" icon={<Pencil className="size-3.5" />} onClick={() => editPreset(item)} aria-label="编辑预设" />
                                        <Button size="small" danger icon={<Trash2 className="size-3.5" />} onClick={() => void deletePreset(item.id)} aria-label="删除预设" />
                                    </div>
                                </div>
                                {item.tags.length ? (
                                    <div className="mt-2 flex flex-wrap gap-1">
                                        {item.tags.map((tag) => (
                                            <Tag key={tag}>{tag}</Tag>
                                        ))}
                                    </div>
                                ) : null}
                            </div>
                        ))}
                        {!filtered.length ? <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="还没有匹配的预设" className="py-10" /> : null}
                    </div>
                </div>

                <div className="rounded-xl border border-stone-200 bg-stone-50 p-3 dark:border-white/10 dark:bg-white/[0.04]">
                    <div className="mb-3 flex items-center justify-between gap-2">
                        <div className="font-semibold">{draft.id ? "编辑预设" : "新建预设"}</div>
                        {draft.id ? (
                            <Button size="small" icon={<Plus className="size-3.5" />} onClick={() => setDraft(emptyDraft)}>
                                新建
                            </Button>
                        ) : null}
                    </div>
                    <div className="space-y-3">
                        <Input data-testid="user-prompt-preset-title" value={draft.title} maxLength={80} onChange={(event) => setDraft((current) => ({ ...current, title: event.target.value }))} placeholder="标题" />
                        <Input data-testid="user-prompt-preset-tags" value={draft.tags} maxLength={160} onChange={(event) => setDraft((current) => ({ ...current, tags: event.target.value }))} placeholder="标签，用空格或逗号分隔" />
                        <Select data-testid="user-prompt-preset-priority" value={draft.priority} options={priorityOptions} onChange={(priority) => setDraft((current) => ({ ...current, priority }))} className="w-full" />
                        <Input.TextArea data-testid="user-prompt-preset-prompt" rows={8} value={draft.prompt} maxLength={4000} onChange={(event) => setDraft((current) => ({ ...current, prompt: event.target.value }))} placeholder="提示词正文" />
                        <Button type="primary" block icon={<Save className="size-4" />} loading={saving} data-testid="user-prompt-preset-save" onClick={() => void saveDraft()}>
                            保存预设
                        </Button>
                    </div>
                </div>
            </div>
        </Modal>
    );
}

function filterPresets(items: UserPromptPreset[], keyword: string) {
    const text = keyword.trim().toLowerCase();
    if (!text) return items;
    return items.filter((item) => [item.title, item.prompt, ...item.tags].join(" ").toLowerCase().includes(text));
}

function nextSortOrder(items: UserPromptPreset[], priority: UserPromptPresetPriority) {
    return items.reduce((maximum, item) => (item.priority === priority ? Math.max(maximum, item.sort_order) : maximum), -1) + 1;
}
