"use client";

import { useEffect, useMemo, useState } from "react";
import { App, Empty, Input, Modal, Pagination, Spin, Tag } from "antd";
import { Search } from "lucide-react";

import { cn } from "@/lib/utils";
import { listServerAssets, serverAssetContentUrl, serverAssetIdFromStorageKey, serverAssetStorageKey, type ServerAsset } from "@/services/api/assets";
import { resolveMediaUrl } from "@/services/file-storage";
import { resolveImageUrl } from "@/services/image-storage";
import { useAssetStore, type Asset } from "@/stores/use-asset-store";
import { useWorkspaceScopeStore } from "@/stores/use-workspace-scope-store";

export type InsertAssetPayload = { kind: "text"; content: string; title: string } | { kind: "image"; dataUrl: string; title: string; storageKey?: string } | { kind: "video"; url: string; title: string; storageKey?: string; width?: number; height?: number };

type Props = {
    open: boolean;
    onInsert: (payload: InsertAssetPayload) => void;
    onClose: () => void;
    acceptedKinds?: InsertAssetPayload["kind"][];
};

export function AssetPickerModal({ open, onInsert, onClose, acceptedKinds }: Props) {
    return (
        <Modal className="canvas-themed-modal" title="选择素材" open={open} onCancel={onClose} footer={null} width={860} destroyOnHidden styles={{ body: { padding: "0 24px 24px", minHeight: 480 } }}>
            <MyAssetsTab open={open} acceptedKinds={acceptedKinds} onInsert={onInsert} />
        </Modal>
    );
}

const PAGE_SIZE = 8;

const kindOptions = [
    { label: "全部", value: "all" },
    { label: "文本", value: "text" },
    { label: "图片", value: "image" },
    { label: "视频", value: "video" },
];

type PickerItem = {
    id: string;
    title: string;
    kind: InsertAssetPayload["kind"];
    cover: string;
    tags: string[];
    source: "server" | "local";
    local?: Asset;
    server?: ServerAsset;
};

function PickerCard({ title, kind, cover, source, loading, onClick }: { title: string; kind: string; cover: string; source: PickerItem["source"]; loading: boolean; onClick: () => void }) {
    return (
        <button
            type="button"
            className="studio-result-card group relative cursor-pointer text-left disabled:cursor-wait disabled:opacity-70"
            onClick={onClick}
            disabled={loading}
        >
            {cover ? (
                <img src={cover} alt={title} className="aspect-[4/3] w-full object-cover" />
            ) : (
                <div className="studio-empty flex aspect-[4/3] items-center justify-center p-3 text-center text-xs leading-5">{title}</div>
            )}
            <div className="p-2.5">
                <div className="flex items-center justify-between gap-2">
                    <span className="line-clamp-1 text-xs font-medium">{title}</span>
                    <div className="flex shrink-0 gap-1">
                        <Tag className="m-0 text-[10px]">{kind === "image" ? "图片" : kind === "video" ? "视频" : "文本"}</Tag>
                        <Tag className="m-0 text-[10px]" color={source === "server" ? "purple" : "default"}>{source === "server" ? "资产库" : "本地"}</Tag>
                    </div>
                </div>
            </div>
            <div className="studio-insert-overlay pointer-events-none absolute inset-0 flex items-center justify-center text-sm font-medium text-white">{loading ? <Spin size="small" /> : "插入"}</div>
        </button>
    );
}

function MyAssetsTab({ open, acceptedKinds, onInsert }: { open: boolean; acceptedKinds?: InsertAssetPayload["kind"][]; onInsert: (payload: InsertAssetPayload) => void }) {
    const { message } = App.useApp();
    const assets = useAssetStore((state) => state.assets);
    const scope = useWorkspaceScopeStore((state) => state.scope);
    const allowedKinds = useMemo(() => new Set<InsertAssetPayload["kind"]>(acceptedKinds?.length ? acceptedKinds : ["text", "image", "video"]), [acceptedKinds]);
    const [serverAssets, setServerAssets] = useState<ServerAsset[]>([]);
    const [serverLoading, setServerLoading] = useState(false);
    const [insertingId, setInsertingId] = useState("");
    const [keyword, setKeyword] = useState("");
    const [kindFilter, setKindFilter] = useState("all");
    const [page, setPage] = useState(1);

    useEffect(() => {
        if (!open) return;
        let disposed = false;
        setServerLoading(true);
        void listServerAssets(scope)
            .then((items) => {
                if (!disposed) setServerAssets(items);
            })
            .catch((error) => {
                if (!disposed) {
                    setServerAssets([]);
                    message.error(error instanceof Error ? error.message : "服务端资产读取失败");
                }
            })
            .finally(() => {
                if (!disposed) setServerLoading(false);
            });
        return () => {
            disposed = true;
        };
    }, [message, open, scope]);

    const filtered = useMemo(() => {
        const query = keyword.trim().toLowerCase();
        const localItems: PickerItem[] = assets
            .filter((asset) => (asset.metadata?.scope || "personal") === scope)
            .filter((asset) => allowedKinds.has(asset.kind))
            .map((asset) => ({
                id: `local:${asset.id}`,
                title: asset.title,
                kind: asset.kind,
                cover: asset.coverUrl || (asset.kind === "image" ? asset.data.dataUrl : ""),
                tags: asset.tags || [],
                source: "local",
                local: asset,
            }));
        const linkedServerIds = new Set(localItems.map((item) => (item.local ? localServerAssetId(item.local) : "")).filter(Boolean));
        const serverItems: PickerItem[] = serverAssets
            .filter((asset): asset is ServerAsset & { type: "image" | "video" } => asset.type === "image" || asset.type === "video")
            .filter((asset) => allowedKinds.has(asset.type))
            .filter((asset) => !linkedServerIds.has(asset.id))
            .map((asset) => ({
                id: `server:${asset.id}`,
                title: asset.name || "未命名资产",
                kind: asset.type,
                cover: asset.type === "image" ? serverAssetContentUrl(asset, scope) : "",
                tags: asset.tags || [],
                source: "server",
                server: asset,
            }));
        return [...serverItems, ...localItems]
            .filter((item) => kindFilter === "all" || item.kind === kindFilter)
            .filter((item) => !query || [item.title, ...item.tags].join(" ").toLowerCase().includes(query));
    }, [allowedKinds, assets, keyword, kindFilter, scope, serverAssets]);

    const visible = useMemo(() => filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE), [filtered, page]);

    useEffect(() => {
        const maxPage = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
        setPage((v) => Math.min(v, maxPage));
    }, [filtered.length]);

    const handleInsert = async (item: PickerItem) => {
        setInsertingId(item.id);
        try {
            if (item.local) {
                const asset = item.local;
                if (asset.kind === "text") onInsert({ kind: "text", content: asset.data.content, title: asset.title });
                else if (asset.kind === "video") onInsert({ kind: "video", url: asset.data.url, storageKey: asset.data.storageKey, title: asset.title, width: asset.data.width, height: asset.data.height });
                else onInsert({ kind: "image", dataUrl: asset.data.dataUrl, storageKey: asset.data.storageKey, title: asset.title });
                return;
            }
            const asset = item.server;
            if (!asset) return;
            const storageKey = serverAssetStorageKey(asset, scope);
            if (asset.type === "image") {
                const dataUrl = await resolveImageUrl(storageKey, serverAssetContentUrl(asset, scope));
                if (!dataUrl) throw new Error("资产图片读取失败");
                onInsert({ kind: "image", dataUrl, storageKey, title: asset.name || "资产图片" });
            } else if (asset.type === "video") {
                const url = await resolveMediaUrl(storageKey, serverAssetContentUrl(asset, scope));
                if (!url) throw new Error("资产视频读取失败");
                onInsert({ kind: "video", url, storageKey, title: asset.name || "资产视频" });
            }
        } catch (error) {
            message.error(error instanceof Error ? error.message : "素材读取失败");
        } finally {
            setInsertingId("");
        }
    };

    const visibleKindOptions = kindOptions.filter((option) => option.value === "all" || allowedKinds.has(option.value as InsertAssetPayload["kind"]));

    return (
        <div className="space-y-4">
            <div className="flex flex-wrap items-center gap-3">
                <Input
                    className="w-56"
                    size="small"
                    prefix={<Search className="size-3.5 studio-muted" />}
                    placeholder="搜索素材"
                    value={keyword}
                    allowClear
                    onChange={(e) => {
                        setPage(1);
                        setKeyword(e.target.value);
                    }}
                />
                <div className="flex gap-1.5">
                    {visibleKindOptions.map((opt) => (
                        <Tag.CheckableTag
                            key={opt.value}
                            checked={kindFilter === opt.value}
                            className={cn("prompt-filter-tag", kindFilter === opt.value && "is-active")}
                            onChange={() => {
                                setPage(1);
                                setKindFilter(opt.value);
                            }}
                        >
                            {opt.label}
                        </Tag.CheckableTag>
                    ))}
                </div>
            </div>

            {visible.length ? (
                <div className="grid grid-cols-4 gap-3">
                    {visible.map((item) => (
                        <PickerCard key={item.id} title={item.title} kind={item.kind} cover={item.cover} source={item.source} loading={insertingId === item.id} onClick={() => void handleInsert(item)} />
                    ))}
                </div>
            ) : serverLoading ? (
                <div className="flex min-h-64 items-center justify-center"><Spin /></div>
            ) : (
                <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="没有素材" className="py-12" />
            )}

            {filtered.length > PAGE_SIZE && (
                <div className="flex justify-center">
                    <Pagination size="small" current={page} pageSize={PAGE_SIZE} total={filtered.length} onChange={setPage} showSizeChanger={false} />
                </div>
            )}
        </div>
    );
}

function localServerAssetId(asset: Asset) {
    const metadataId = asset.metadata?.serverAssetId;
    if (typeof metadataId === "string" && metadataId) return metadataId;
    if (asset.kind === "image" || asset.kind === "video") return serverAssetIdFromStorageKey(asset.data.storageKey);
    return "";
}
