export const CANVAS_MENTION_PATTERN = /@\[(node|asset):([^\]]+)\]/g;
export const CANVAS_MENTION_TRIGGER_PATTERN = /(^|[^A-Za-z0-9_])@([^\s@]*)$/;

export type CanvasMentionSource = "node" | "asset";
export type CanvasMentionMenuGroupSource = "canvas-node" | "asset-library";

export const CANVAS_MENTION_MENU_GROUPS = [
    {
        source: "canvas-node" as const,
        title: "已连接素材",
        emptyText: "当前节点未连接任何素材节点,连线后即可引用",
    },
    {
        source: "asset-library" as const,
        title: "资产库",
        emptyText: "当前 workspace 的资产库还没有可用素材",
    },
];

export type CanvasMentionToken = {
    source: CanvasMentionSource;
    targetId: string;
    key: string;
    nodeId?: string;
    assetId?: string;
    raw: string;
    index: number;
};

export type CanvasMentionReferenceLike = {
    mentionKey?: string;
    mentionSource?: CanvasMentionSource;
    targetId?: string;
    nodeId?: string;
    assetId?: string;
    label: string;
    sourceLabel?: string;
    kind?: string;
    title?: string;
    text?: string;
    searchText?: string;
};

export type CanvasMentionMenuReferenceLike = CanvasMentionReferenceLike & {
    source: CanvasMentionMenuGroupSource;
    active?: boolean;
};

export type CanvasMentionTextPart =
    | { type: "text"; value: string }
    | { type: "reference"; mentionKey: string; label: string; missing: boolean };

export function canvasMentionKey(source: CanvasMentionSource, targetId: string) {
    return `${source}:${targetId}`;
}

export function canvasMentionToken(targetId: string, source: CanvasMentionSource = "node") {
    return `@[${source}:${targetId}]`;
}

export function canvasMentionTokenFromKey(key: string) {
    const [source, ...rest] = key.split(":");
    const targetId = rest.join(":");
    return source === "asset" ? canvasMentionToken(targetId, "asset") : canvasMentionToken(targetId, "node");
}

export function canvasMentionKeyForReference(reference: CanvasMentionReferenceLike) {
    if (reference.mentionKey) return reference.mentionKey;
    if (reference.mentionSource && reference.targetId) return canvasMentionKey(reference.mentionSource, reference.targetId);
    if (reference.nodeId) return canvasMentionKey("node", reference.nodeId);
    if (reference.assetId) return canvasMentionKey("asset", reference.assetId);
    return "";
}

export function extractCanvasMentionTokens(value: string): CanvasMentionToken[] {
    const tokens: CanvasMentionToken[] = [];
    for (const match of value.matchAll(CANVAS_MENTION_PATTERN)) {
        if (match.index === undefined) continue;
        const source = match[1] as CanvasMentionSource;
        const targetId = match[2];
        const key = canvasMentionKey(source, targetId);
        tokens.push({
            source,
            targetId,
            key,
            nodeId: source === "node" ? targetId : undefined,
            assetId: source === "asset" ? targetId : undefined,
            raw: match[0],
            index: match.index,
        });
    }
    return tokens;
}

export function hasCanvasMentionTokens(value: string) {
    return extractCanvasMentionTokens(value).length > 0;
}

export function splitCanvasMentionText(value: string, references: CanvasMentionReferenceLike[]): CanvasMentionTextPart[] {
    const referenceByKey = new Map<string, CanvasMentionReferenceLike>(
        references
            .map((reference): [string, CanvasMentionReferenceLike] => [canvasMentionKeyForReference(reference), reference])
            .filter(([key]) => Boolean(key)),
    );
    const parts: CanvasMentionTextPart[] = [];
    let lastIndex = 0;
    for (const match of value.matchAll(CANVAS_MENTION_PATTERN)) {
        if (match.index === undefined) continue;
        if (match.index > lastIndex) parts.push({ type: "text", value: value.slice(lastIndex, match.index) });
        const mentionKey = canvasMentionKey(match[1] as CanvasMentionSource, match[2]);
        const reference = referenceByKey.get(mentionKey);
        parts.push({ type: "reference", mentionKey, label: reference?.label || reference?.title || reference?.sourceLabel || "引用已失效", missing: !reference });
        lastIndex = match.index + match[0].length;
    }
    if (lastIndex < value.length) parts.push({ type: "text", value: value.slice(lastIndex) });
    return parts.length ? parts : [{ type: "text", value }];
}

export function canvasMentionSearchText(reference: CanvasMentionReferenceLike) {
    return `${reference.label} ${reference.sourceLabel || ""} ${reference.title || ""} ${reference.kind || ""} ${reference.text || ""} ${reference.searchText || ""}`.toLowerCase();
}

export function matchCanvasMentionTrigger(value: string) {
    const match = CANVAS_MENTION_TRIGGER_PATTERN.exec(value);
    if (!match) return null;
    return {
        start: value.length - match[2].length - 1,
        query: match[2] || "",
    };
}

export function filterCanvasMentionReferences<T extends CanvasMentionMenuReferenceLike>(references: T[], query: string) {
    const normalizedQuery = query.trim().toLowerCase();
    const activeReferences = references.filter((reference) => reference.active);
    const matchedReferences = normalizedQuery ? activeReferences.filter((reference) => canvasMentionSearchText(reference).includes(normalizedQuery)) : activeReferences;
    return sortCanvasMentionReferencesByGroup(matchedReferences);
}

export function buildCanvasMentionMenuGroups<T extends CanvasMentionMenuReferenceLike>(allReferences: T[], matchedReferences: T[]) {
    let selectableIndex = 0;
    return CANVAS_MENTION_MENU_GROUPS.map((group) => {
        const groupAllReferences = allReferences.filter((reference) => reference.source === group.source);
        const groupReferences = matchedReferences.filter((reference) => reference.source === group.source);
        const items = groupReferences.map((reference) => ({ reference, index: selectableIndex++ }));
        return {
            ...group,
            allReferences: groupAllReferences,
            references: groupReferences,
            items,
            empty: groupAllReferences.length === 0,
            unmatched: groupAllReferences.length > 0 && groupReferences.length === 0,
        };
    });
}

export function sortCanvasMentionReferencesByGroup<T extends CanvasMentionMenuReferenceLike>(references: T[]) {
    return [...references].sort((a, b) => canvasMentionGroupIndex(a.source) - canvasMentionGroupIndex(b.source));
}

export function canvasMentionGroupIndex(source: CanvasMentionMenuGroupSource) {
    const index = CANVAS_MENTION_MENU_GROUPS.findIndex((group) => group.source === source);
    return index === -1 ? CANVAS_MENTION_MENU_GROUPS.length : index;
}

export function missingCanvasMentionKeys(value: string, references: CanvasMentionReferenceLike[]) {
    const referenceKeys = new Set(references.map(canvasMentionKeyForReference).filter(Boolean));
    return extractCanvasMentionTokens(value)
        .map((token) => token.key)
        .filter((key, index, all) => !referenceKeys.has(key) && all.indexOf(key) === index);
}

export function missingCanvasMentionNodeIds(value: string, references: CanvasMentionReferenceLike[]) {
    return missingCanvasMentionKeys(value, references);
}

export function findLegacyMentionedReferences(value: string, references: CanvasMentionReferenceLike[]) {
    if (hasCanvasMentionTokens(value)) return [];
    return references.filter((reference) => containsLegacyMentionLabel(value, reference.sourceLabel || reference.label));
}

export function escapeRegExp(value: string) {
    return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function containsLegacyMentionLabel(value: string, label: string) {
    const escaped = escapeRegExp(label);
    if (/[\p{Script=Han}]/u.test(label)) return new RegExp(`${escaped}(?!\\d)`, "u").test(value);
    return new RegExp(`(^|[^\\p{L}\\p{N}_])${escaped}(?=$|[^\\p{L}\\p{N}_])`, "u").test(value);
}
