"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";

export type WorkspaceScope = "personal" | "team";

type WorkspaceScopeStore = {
    scope: WorkspaceScope;
    setScope: (scope: WorkspaceScope) => void;
};

export const WORKSPACE_SCOPE_STORAGE_KEY = "ai-manju:workspace_scope";

export const useWorkspaceScopeStore = create<WorkspaceScopeStore>()(
    persist(
        (set) => ({
            scope: "personal",
            setScope: (scope) => set({ scope }),
        }),
        {
            name: WORKSPACE_SCOPE_STORAGE_KEY,
        },
    ),
);

export function workspaceScopeLabel(scope: WorkspaceScope) {
    return scope === "team" ? "团队空间" : "个人空间";
}
