export type Position = {
    x: number;
    y: number;
};

export type ViewportTransform = {
    x: number;
    y: number;
    k: number;
};

export enum CanvasNodeType {
    Image = "image",
    Text = "text",
    Config = "config",
    Video = "video",
    Audio = "audio",
    Director = "director",
}

export type CanvasNodeStatus = "idle" | "success" | "loading" | "error";
export type CanvasGenerationMode = "text" | "image" | "video" | "audio";
export type CanvasImageGenerationType = "generation" | "edit";

export type CanvasNodeMetadata = {
    content?: string;
    composerContent?: string;
    prompt?: string;
    status?: CanvasNodeStatus;
    errorDetails?: string;
    jobId?: string;
    jobProgress?: number;
    fontSize?: number;
    generationMode?: CanvasGenerationMode;
    generationType?: CanvasImageGenerationType;
    model?: string;
    size?: string;
    quality?: string;
    count?: number;
    seconds?: string;
    vquality?: string;
    generateAudio?: string;
    watermark?: string;
    audioVoice?: string;
    audioFormat?: string;
    audioSpeed?: string;
    audioInstructions?: string;
    references?: string[];
    seedanceMaterialAssets?: Array<{ id: string; name?: string; status?: string }>;
    seedanceVolcanoAssets?: Array<{ id: string; volcanoAssetId: string; name?: string; status?: string; assetType?: string }>;
    naturalWidth?: number;
    naturalHeight?: number;
    freeResize?: boolean;
    isBatchRoot?: boolean;
    batchRootId?: string;
    batchChildIds?: string[];
    batchUsesReferenceImages?: boolean;
    primaryImageId?: string;
    imageBatchExpanded?: boolean;
    storageKey?: string;
    mimeType?: string;
    bytes?: number;
    compressionSourceBytes?: number;
    compressionTargetBytes?: number;
    compressionQuality?: number;
    compressionMaxDimension?: number;
    compressionFormat?: "image/jpeg" | "image/webp";
    assetId?: string;
    assetCategory?: string;
    assetTags?: string[];
    assetSourceType?: string;
    durationMs?: number;
    directorInstanceId?: string;
    directorCanvasId?: string;
    directorProjectFingerprint?: string;
    directorRevision?: number;
    directorPreviewAssetId?: string;
    directorOutputKeys?: string[];
    directorOutputNodeIds?: string[];
    directorUpdatedAt?: string;
    directorSourceNodeId?: string;
    directorOutputKey?: string;
    // Per-node prompt panel dimensions are stored in snapshots and shared by
    // the DOM and Leafer canvas engines.
    promptPanelWidth?: number;
    promptEditorHeight?: number;
};

export type CanvasNodeData = {
    id: string;
    type: CanvasNodeType;
    title: string;
    position: Position;
    width: number;
    height: number;
    metadata?: CanvasNodeMetadata;
};

export type CanvasGroupData = {
    id: string;
    title: string;
    nodeIds: string[];
    position: Position;
    width: number;
    height: number;
    color: string;
};

export type CanvasConnection = {
    id: string;
    fromNodeId: string;
    toNodeId: string;
};

export type CanvasAssistantReference = {
    id: string;
    type: CanvasNodeType;
    title: string;
    dataUrl?: string;
    storageKey?: string;
    text?: string;
};

export type CanvasAssistantImage = {
    id: string;
    dataUrl: string;
    storageKey?: string;
    prompt: string;
};

export type CanvasAssistantMessage = {
    id: string;
    role: "user" | "assistant" | "system" | "tool" | "error";
    title?: string;
    text: string;
    meta?: string;
    detail?: unknown;
    references?: CanvasAssistantReference[];
};

export type CanvasAssistantSession = {
    id: string;
    title: string;
    messages: CanvasAssistantMessage[];
    createdAt: string;
    updatedAt: string;
};

export type ConnectionHandle = {
    nodeId: string;
    handleType: "source" | "target";
};

export type SelectionBox = {
    startWorldX: number;
    startWorldY: number;
    currentWorldX: number;
    currentWorldY: number;
    additive: boolean;
    initialSelectedNodeIds: string[];
};

export type ContextMenuState =
    | {
          type: "canvas";
          x: number;
          y: number;
      }
    | {
          type: "node";
          x: number;
          y: number;
          nodeId: string;
      }
    | {
          type: "group";
          x: number;
          y: number;
          groupId: string;
      }
    | {
          type: "selection";
          x: number;
          y: number;
      }
    | {
          type: "connection";
          x: number;
          y: number;
          connectionId: string;
      };
