import type { CanvasProject } from "../../../vendor/canvas/stores/use-canvas-store";
import { requestApi } from "./request";
import type { WorkspaceScope } from "../../stores/use-workspace-scope-store";

export type ServerProject = {
    id: string;
    title: string;
    owner_id: string;
    workspace_id?: string;
    scope?: WorkspaceScope;
    data?: Partial<CanvasProject>;
    created_at: string;
    updated_at: string;
};

export type ServerCanvasSnapshot = {
    project_id: string;
    version: number;
    data: Partial<CanvasProject>;
    created_at: string;
    updated_at: string;
};

type ProjectCreateRequest = {
    title: string;
    data?: Partial<CanvasProject>;
};

type ProjectUpdateRequest = {
    title?: string;
    data?: Partial<CanvasProject>;
};

export async function listServerProjects(scope: WorkspaceScope = "personal") {
    return requestProjectApi<ServerProject[]>(projectPath("/api/projects", scope));
}

export async function createServerProject(project: CanvasProject, scope: WorkspaceScope = "personal") {
    return requestProjectApi<ServerProject>(projectPath("/api/projects", scope), {
        method: "POST",
        body: JSON.stringify(toProjectCreateRequest(project, scope)),
    });
}

export async function updateServerProject(serverProjectId: string, project: CanvasProject, scope: WorkspaceScope = "personal") {
    return requestProjectApi<ServerProject>(projectPath(`/api/projects/${encodeURIComponent(serverProjectId)}`, scope), {
        method: "PUT",
        body: JSON.stringify(toProjectUpdateRequest(project, scope)),
    });
}

export async function deleteServerProject(serverProjectId: string, scope: WorkspaceScope = "personal") {
    await requestProjectApi<void>(projectPath(`/api/projects/${encodeURIComponent(serverProjectId)}`, scope), {
        method: "DELETE",
    });
}

export async function saveServerCanvasSnapshot(serverProjectId: string, project: CanvasProject, scope: WorkspaceScope = "personal") {
    return requestProjectApi<ServerCanvasSnapshot>(projectPath(`/api/projects/${encodeURIComponent(serverProjectId)}/snapshot`, scope), {
        method: "PUT",
        body: JSON.stringify({ data: toSnapshotPayload(project, scope) }),
    });
}

export async function fetchServerCanvasSnapshot(serverProjectId: string, scope: WorkspaceScope = "personal") {
    return requestProjectApi<ServerCanvasSnapshot>(projectPath(`/api/projects/${encodeURIComponent(serverProjectId)}/snapshot`, scope));
}

export function applyServerSyncMeta(project: CanvasProject, serverProject: ServerProject, snapshot?: ServerCanvasSnapshot): CanvasProject {
    const scope = serverProject.scope || scopeFromWorkspaceId(serverProject.workspace_id) || project.scope || "personal";
    return {
        ...project,
        serverProjectId: serverProject.id,
        workspaceId: serverProject.workspace_id || project.workspaceId || workspaceIdForScope(scope),
        scope,
        snapshotVersion: snapshot?.version ?? project.snapshotVersion,
        lastSyncAt: (snapshot?.updated_at || serverProject.updated_at || new Date().toISOString()),
        syncStatus: "synced",
    };
}

export function mergeSnapshotIntoLocalProject(local: CanvasProject, snapshot: ServerCanvasSnapshot): CanvasProject {
    return {
        ...local,
        ...snapshot.data,
        id: local.id,
        serverProjectId: snapshot.project_id,
        snapshotVersion: snapshot.version,
        lastSyncAt: snapshot.updated_at,
        syncStatus: "synced",
    };
}

function toProjectCreateRequest(project: CanvasProject, scope: WorkspaceScope): ProjectCreateRequest {
    return {
        title: project.title,
        data: toSnapshotPayload(project, scope),
    };
}

function toProjectUpdateRequest(project: CanvasProject, scope: WorkspaceScope): ProjectUpdateRequest {
    return {
        title: project.title,
        data: toSnapshotPayload(project, scope),
    };
}

function toSnapshotPayload(project: CanvasProject, scope: WorkspaceScope): CanvasProject {
    const unsafeProject = project as CanvasProject & Record<string, unknown>;
    const { owner_id: _ownerId, ownerId: _camelOwnerId, ...safeProject } = unsafeProject;
    return {
        ...(safeProject as CanvasProject),
        scope,
        workspaceId: project.workspaceId || workspaceIdForScope(scope),
        syncStatus: project.syncStatus || "pending",
    };
}

async function requestProjectApi<T>(path: string, init?: RequestInit): Promise<T> {
    return requestApi<T>(path, init);
}

function projectPath(path: string, scope: WorkspaceScope) {
    return `${path}${path.includes("?") ? "&" : "?"}scope=${encodeURIComponent(scope)}`;
}

export function workspaceIdForScope(scope: WorkspaceScope, userId?: string) {
    return scope === "team" ? "team:default" : `default:${userId || "current"}`;
}

export function scopeFromWorkspaceId(workspaceId?: string): WorkspaceScope | "" {
    if (workspaceId === "team:default") return "team";
    if (workspaceId?.startsWith("default:")) return "personal";
    return "";
}
