import { useCallback } from "react";
import { useLocation, useParams as useWouterParams } from "wouter";

export function useParams<T extends Record<string, string | string[]>>() {
    return useWouterParams<Record<string, string>>() as T;
}

export function useRouter() {
    const [, navigate] = useLocation();
    return {
        push: useCallback((href: string) => navigate(href), [navigate]),
        replace: useCallback((href: string) => navigate(href, { replace: true }), [navigate]),
        back: useCallback(() => window.history.back(), []),
        refresh: useCallback(() => window.location.reload(), []),
    };
}
