"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { App, Button, Segmented, Tag } from "antd";
import { Clapperboard, Download, FileUp, Plus } from "lucide-react";

import { readZip } from "@/lib/zip";
import { PROJECT_STORAGE_MODE } from "@/constant/env";
import { setMediaBlob } from "@/services/file-storage";
import { setImageBlob } from "@/services/image-storage";
import { listServerProjects } from "@/services/api/project-canvas";
import { CanvasCreateProjectDialog } from "./components/canvas-create-project-dialog";
import { CanvasDeleteProjectsDialog } from "./components/canvas-delete-projects-dialog";
import { CanvasProjectCard } from "./components/canvas-project-card";
import type { CanvasExportFile } from "./export-types";
import { useCanvasStore } from "./stores/use-canvas-store";
import { useCanvasUiStore } from "./stores/use-canvas-ui-store";
import { exportCanvasProjects } from "./utils/canvas-export";
import { hydrateProjectFromServer, serverSyncMetaFromProject } from "./utils/server-project-sync";
import { useWorkspaceScopeStore, workspaceScopeLabel } from "@/stores/use-workspace-scope-store";

export default function CanvasPage() {
    const { message } = App.useApp();
    const router = useRouter();
    const inputRef = useRef<HTMLInputElement>(null);
    const hydrated = useCanvasStore((state) => state.hydrated);
    const projects = useCanvasStore((state) => state.projects);
    const scope = useWorkspaceScopeStore((state) => state.scope);
    const setScope = useWorkspaceScopeStore((state) => state.setScope);
    const importProject = useCanvasStore((state) => state.importProject);
    const upsertProject = useCanvasStore((state) => state.upsertProject);
    const updateProjectSyncMeta = useCanvasStore((state) => state.updateProjectSyncMeta);
    const selectedIds = useCanvasUiStore((state) => state.selectedProjectIds);
    const setDeleteIds = useCanvasUiStore((state) => state.setDeleteProjectIds);
    const [createDialogOpen, setCreateDialogOpen] = useState(false);
    const scopedProjects = projects.filter((project) => (project.scope || "personal") === scope);

    const enterProject = (id: string) => {
        router.push(`/canvas/${id}`);
    };

    useEffect(() => {
        if (!hydrated || PROJECT_STORAGE_MODE !== "server") return;
        let disposed = false;
        const syncServerProjects = async () => {
            try {
                const serverProjects = await listServerProjects(scope);
                if (disposed) return;
                const localProjects = useCanvasStore.getState().projects;
                serverProjects.forEach((serverProject) => {
                    const existing = localProjects.find((project) => (project.scope || "personal") === scope && (project.serverProjectId === serverProject.id || project.id === serverProject.data?.id));
                    const remoteProject = hydrateProjectFromServer(serverProject);
                    if (existing) {
                        if (remoteProject && existing.syncStatus !== "pending" && existing.syncStatus !== "conflict" && toTime(remoteProject.updatedAt) > toTime(existing.updatedAt)) {
                            upsertProject({ ...remoteProject, id: existing.id });
                        } else {
                            updateProjectSyncMeta(existing.id, serverSyncMetaFromProject(serverProject));
                        }
                        return;
                    }
                    if (remoteProject) upsertProject(remoteProject);
                });
            } catch (error) {
                message.warning(error instanceof Error ? `服务端项目同步失败：${error.message}` : "服务端项目同步失败");
            }
        };
        void syncServerProjects();
        return () => {
            disposed = true;
        };
    }, [hydrated, message, scope, updateProjectSyncMeta, upsertProject]);

    const createAndEnter = () => setCreateDialogOpen(true);
    const createDirectorDesk = () => {
        router.push(`/director?instanceId=director_${crypto.randomUUID()}`);
    };
    const exportSelectedProjects = async () => {
        try {
            const result = await exportCanvasProjects(scopedProjects.filter((project) => selectedIds.includes(project.id)), `分镜画布-${selectedIds.length}个项目`);
            message.success(`已生成导出文件 ${result.fileName}`);
        } catch (error) {
            message.error(error instanceof Error ? error.message : "导出失败，请稍后重试");
        }
    };
    const importCanvas = async (file?: File) => {
        if (!file) return;
        try {
            const zip = await readZip(file);
            const projectFile = zip.get("projects.json");
            if (!projectFile) throw new Error("missing projects.json");
            const data = JSON.parse(await projectFile.text()) as CanvasExportFile;
            await Promise.all(
                data.projects.flatMap((project) =>
                    project.files.map(async (item) => {
                        const blob = zip.get(item.path);
                        if (!blob) return;
                        const typedBlob = blob.type ? blob : blob.slice(0, blob.size, item.mimeType);
                        await (isImageStorageKey(item.storageKey) ? setImageBlob(item.storageKey, typedBlob) : setMediaBlob(item.storageKey, typedBlob));
                    }),
                ),
            );
            data.projects.forEach((item) => {
                const importedId = importProject({ ...item.project, scope });
                useCanvasStore.getState().updateProjectSyncMeta(importedId, { workspaceId: scope === "team" ? "team:default" : undefined });
            });
            message.success(`已导入 ${data.projects.length} 个画布`);
        } catch {
            message.error("导入失败，请选择有效的画布压缩包");
        } finally {
            if (inputRef.current) inputRef.current.value = "";
        }
    };

    return (
        <main className="studio-page" data-testid="canvas-projects-page" data-storage-mode={PROJECT_STORAGE_MODE}>
            <div className="studio-page-content flex max-w-6xl flex-col gap-8">
                <header className="studio-page-header--canvas flex flex-wrap items-end justify-between gap-4">
                    <div>
                        <p className="studio-eyebrow">CANVAS STUDIO</p>
                        <h1 className="studio-page-title mt-3">画布工坊</h1>
                        <p className="mt-3 max-w-2xl">把脚本、分镜、角色参考、生成设置和音视频节点组织成可复用的漫剧制作画布。</p>
                    </div>
                </header>

                <section className="studio-panel flex flex-wrap items-center justify-between gap-3 p-4">
                    <div className="flex flex-wrap items-center gap-2">
                        <Segmented
                            value={scope}
                            options={[
                                { label: "个人空间", value: "personal" },
                                { label: "团队空间", value: "team" },
                            ]}
                            onChange={(value) => setScope(value as typeof scope)}
                        />
                        <Tag className="m-0">{workspaceScopeLabel(scope)}</Tag>
                        <Tag className="m-0">网格视图</Tag>
                        <Tag className="m-0">共 {scopedProjects.length} 个画布</Tag>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        {selectedIds.length ? (
                            <>
                                <Button disabled={!hydrated} icon={<Download className="size-4" />} onClick={() => void exportSelectedProjects()}>
                                    导出选中
                                </Button>
                                <Button disabled={!hydrated} onClick={() => setDeleteIds(selectedIds)}>
                                    删除选中
                                </Button>
                            </>
                        ) : null}
                        {scopedProjects.length ? (
                            <Button disabled={!hydrated} onClick={() => setDeleteIds(scopedProjects.map((project) => project.id))}>
                                删除全部
                            </Button>
                        ) : null}
                        <Button disabled={!hydrated} icon={<FileUp className="size-4" />} data-testid="canvas-import-button" onClick={() => inputRef.current?.click()}>
                            导入画布包
                        </Button>
                        <Button disabled={!hydrated} icon={<Clapperboard className="size-4" />} onClick={createDirectorDesk}>
                            创建导演台
                        </Button>
                        <Button disabled={!hydrated} type="primary" icon={<Plus className="size-4" />} data-testid="canvas-create-project" onClick={createAndEnter}>
                            新建分镜画布
                        </Button>
                    </div>
                </section>

                {!hydrated ? (
                    <section className="flex min-h-[360px] items-center justify-center studio-empty text-sm">正在加载制作画布...</section>
                ) : scopedProjects.length ? (
                    <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
                        {scopedProjects.map((project) => (
                            <CanvasProjectCard key={project.id} project={project} />
                        ))}
                    </div>
                ) : (
                    <section className="flex min-h-[360px] flex-col items-center justify-center studio-empty text-center">
                        <h2 className="studio-section-title">还没有分镜画布</h2>
                        <p className="mt-3 text-sm studio-muted">新建一个画布后，就可以保存脚本节点、关键帧、生成设置、连线和画布外观。</p>
                        <Button type="primary" className="mt-6" icon={<Plus className="size-4" />} data-testid="canvas-create-project-empty" onClick={createAndEnter}>
                            新建分镜画布
                        </Button>
                        <Button className="mt-3" icon={<Clapperboard className="size-4" />} onClick={createDirectorDesk}>
                            创建导演台
                        </Button>
                    </section>
                )}
            </div>

            <input ref={inputRef} type="file" accept="application/zip,.zip" className="hidden" data-testid="canvas-import-input" onChange={(event) => void importCanvas(event.target.files?.[0])} />
            <CanvasCreateProjectDialog
                open={createDialogOpen}
                defaultScope={scope}
                onCancel={() => setCreateDialogOpen(false)}
                onCreated={(id) => {
                    setCreateDialogOpen(false);
                    enterProject(id);
                }}
            />
            <CanvasDeleteProjectsDialog />
        </main>
    );
}

function isImageStorageKey(storageKey: string) {
    return storageKey.startsWith("image:") || storageKey.startsWith("server:image:") || storageKey.startsWith("server:personal:image:") || storageKey.startsWith("server:team:image:");
}

function toTime(value?: string) {
    return value ? Date.parse(value) || 0 : 0;
}
