"use client";

import { useCallback, useEffect, useRef } from "react";
import type { PointerEvent as ReactPointerEvent, ReactNode } from "react";

import { CanvasNodeType, type CanvasNodeData } from "../types";

export const PROMPT_PANEL_DEFAULT_WIDTH = 500;
export const PROMPT_PANEL_MIN_WIDTH = 360;
export const PROMPT_PANEL_MAX_WIDTH = 960;
export const PROMPT_EDITOR_DEFAULT_HEIGHT = 96;
export const CONFIG_PROMPT_EDITOR_DEFAULT_HEIGHT = 112;
export const PROMPT_EDITOR_MIN_HEIGHT = 96;
export const PROMPT_EDITOR_MAX_HEIGHT = 600;

type ResizeDirection = "width" | "height" | "both";

export function promptPanelWidth(node: CanvasNodeData) {
    return clamp(node.metadata?.promptPanelWidth || PROMPT_PANEL_DEFAULT_WIDTH, PROMPT_PANEL_MIN_WIDTH, PROMPT_PANEL_MAX_WIDTH);
}

export function promptEditorHeight(node: CanvasNodeData) {
    const fallback = node.type === CanvasNodeType.Config ? CONFIG_PROMPT_EDITOR_DEFAULT_HEIGHT : PROMPT_EDITOR_DEFAULT_HEIGHT;
    return clamp(node.metadata?.promptEditorHeight || fallback, PROMPT_EDITOR_MIN_HEIGHT, PROMPT_EDITOR_MAX_HEIGHT);
}

export function CanvasPromptPanelFrame({ node, scale, onResize, children }: { node: CanvasNodeData; scale: number; onResize: (nodeId: string, width: number, editorHeight: number) => void; children: ReactNode }) {
    const resizeRef = useRef({ active: false, direction: "both" as ResizeDirection, startX: 0, startY: 0, startWidth: 0, startHeight: 0 });
    const latestRef = useRef({ nodeId: node.id, scale, onResize });
    latestRef.current = { nodeId: node.id, scale, onResize };

    const handleMove = useCallback((event: PointerEvent) => {
        const state = resizeRef.current;
        if (!state.active) return;
        const safeScale = Math.max(latestRef.current.scale, 0.05);
        const width = state.direction === "height" ? state.startWidth : clamp(state.startWidth + (event.clientX - state.startX) / safeScale, PROMPT_PANEL_MIN_WIDTH, PROMPT_PANEL_MAX_WIDTH);
        const height = state.direction === "width" ? state.startHeight : clamp(state.startHeight + (event.clientY - state.startY) / safeScale, PROMPT_EDITOR_MIN_HEIGHT, PROMPT_EDITOR_MAX_HEIGHT);
        latestRef.current.onResize(latestRef.current.nodeId, Math.round(width), Math.round(height));
    }, []);

    const handleUp = useCallback(() => {
        resizeRef.current.active = false;
        window.removeEventListener("pointermove", handleMove);
        window.removeEventListener("pointerup", handleUp);
        window.removeEventListener("pointercancel", handleUp);
        document.body.style.removeProperty("user-select");
    }, [handleMove]);

    useEffect(() => () => handleUp(), [handleUp]);

    const startResize = (event: ReactPointerEvent, direction: ResizeDirection) => {
        event.preventDefault();
        event.stopPropagation();
        resizeRef.current = {
            active: true,
            direction,
            startX: event.clientX,
            startY: event.clientY,
            startWidth: promptPanelWidth(node),
            startHeight: promptEditorHeight(node),
        };
        document.body.style.userSelect = "none";
        window.addEventListener("pointermove", handleMove);
        window.addEventListener("pointerup", handleUp);
        window.addEventListener("pointercancel", handleUp);
    };

    return (
        <div
            data-canvas-ui
            data-canvas-no-zoom
            data-testid="canvas-prompt-panel-frame"
            className="relative"
            style={{ width: promptPanelWidth(node) }}
            onPointerDown={(event) => event.stopPropagation()}
            onMouseDown={(event) => event.stopPropagation()}
            onWheel={(event) => event.stopPropagation()}
        >
            {children}
            <button type="button" aria-label="调整提示词面板宽度" data-testid="canvas-prompt-panel-resize-width" className="absolute -right-1.5 top-4 z-[95] h-[calc(100%-22px)] w-3 cursor-ew-resize touch-none bg-transparent" onPointerDown={(event) => startResize(event, "width")} />
            <button type="button" aria-label="调整提示词编辑区高度" data-testid="canvas-prompt-panel-resize-height" className="absolute -bottom-1.5 left-3 z-[95] h-3 w-[calc(100%-24px)] cursor-ns-resize touch-none bg-transparent" onPointerDown={(event) => startResize(event, "height")} />
            <button type="button" aria-label="调整提示词面板大小" data-testid="canvas-prompt-panel-resize-both" className="absolute -bottom-2 -right-2 z-[96] size-5 cursor-nwse-resize touch-none rounded-sm border border-white/70 bg-black/35 shadow" onPointerDown={(event) => startResize(event, "both")} />
        </div>
    );
}

function clamp(value: number, min: number, max: number) {
    return Math.min(max, Math.max(min, value));
}
