"use client";

import { useEffect, useState } from "react";
import { Button, Modal, Segmented, Slider } from "antd";
import { RotateCcw, WandSparkles } from "lucide-react";
import type { ImageAngleLensPreset, ImageAngleViewPreset } from "../utils/canvas-image-data";

export type CanvasImageAngleParams = {
    horizontalAngle: number;
    pitchAngle: number;
    cameraDistance: number;
    wideAngle: boolean;
    lensPreset: ImageAngleLensPreset;
    viewPreset: ImageAngleViewPreset;
};

const defaultParams: CanvasImageAngleParams = {
    horizontalAngle: 0,
    pitchAngle: 9,
    cameraDistance: 4.8,
    wideAngle: false,
    lensPreset: "standard",
    viewPreset: "front",
};

const viewPresets: Array<{ label: string; value: ImageAngleViewPreset; params: Pick<CanvasImageAngleParams, "horizontalAngle" | "pitchAngle" | "cameraDistance"> }> = [
    { label: "正面", value: "front", params: { horizontalAngle: 0, pitchAngle: 6, cameraDistance: 4.8 } },
    { label: "左前 3/4", value: "front-left", params: { horizontalAngle: -45, pitchAngle: 8, cameraDistance: 4.8 } },
    { label: "右前 3/4", value: "front-right", params: { horizontalAngle: 45, pitchAngle: 8, cameraDistance: 4.8 } },
    { label: "左侧", value: "side-left", params: { horizontalAngle: -90, pitchAngle: 4, cameraDistance: 5.2 } },
    { label: "右侧", value: "side-right", params: { horizontalAngle: 90, pitchAngle: 4, cameraDistance: 5.2 } },
    { label: "背面", value: "back", params: { horizontalAngle: 180, pitchAngle: 0, cameraDistance: 5.4 } },
    { label: "俯视", value: "top", params: { horizontalAngle: 0, pitchAngle: 72, cameraDistance: 6.2 } },
    { label: "仰视", value: "low", params: { horizontalAngle: 0, pitchAngle: -42, cameraDistance: 3.8 } },
];

export function CanvasNodeAngleDialog({ dataUrl, open, onClose, onConfirm }: { dataUrl: string; open: boolean; onClose: () => void; onConfirm: (params: CanvasImageAngleParams) => void }) {
    const [params, setParams] = useState(defaultParams);

    useEffect(() => {
        if (open) setParams(defaultParams);
    }, [dataUrl, open]);

    const update = <Key extends keyof CanvasImageAngleParams>(key: Key, value: CanvasImageAngleParams[Key]) => setParams((current) => ({ ...current, [key]: value }));
    const applyViewPreset = (value: ImageAngleViewPreset) => {
        const preset = viewPresets.find((item) => item.value === value);
        if (!preset) return;
        setParams((current) => ({ ...current, ...preset.params, viewPreset: value }));
    };
    const updateLens = (lensPreset: ImageAngleLensPreset) => setParams((current) => ({ ...current, lensPreset, wideAngle: lensPreset === "wide" }));

    return (
        <Modal className="canvas-themed-modal" title={null} open={open && Boolean(dataUrl)} onCancel={onClose} footer={null} width={920} centered destroyOnHidden>
            <div className="space-y-5" data-testid="canvas-image-angle-dialog">
                <div>
                    <h2 className="text-xl font-semibold">AI 多角度</h2>
                    <p className="mt-1 text-sm opacity-60">左侧仅预览方向，结果会基于原图重新生成。极端背面视角取决于当前模型能力。</p>
                </div>
                <div className="grid gap-6 md:grid-cols-[minmax(260px,1fr)_410px]">
                    <div className="flex min-h-[330px] flex-col justify-between rounded-xl border border-[#b84dff4d] bg-white/[0.045] p-4">
                        <div className="grid flex-1 place-items-center">
                            <div className="relative">
                                <img src={dataUrl} alt="" className="size-52 rounded-2xl object-cover shadow-2xl" draggable={false} style={{ transform: previewTransform(params) }} />
                                <div className="absolute -bottom-6 left-1/2 h-10 w-24 -translate-x-1/2 rounded-full border bg-black/20 backdrop-blur" />
                            </div>
                        </div>
                        <Button className="w-fit" icon={<RotateCcw className="size-4" />} onClick={() => setParams(defaultParams)}>
                            重置
                        </Button>
                    </div>
                    <div className="space-y-5 py-1">
                        <div className="space-y-2">
                            <div className="text-sm font-semibold opacity-75">常用机位</div>
                            <div className="flex flex-wrap gap-2">
                                {viewPresets.map((preset) => (
                                    <Button key={preset.value} size="small" type={params.viewPreset === preset.value ? "primary" : "default"} data-testid={`canvas-angle-preset-${preset.value}`} onClick={() => applyViewPreset(preset.value)}>
                                        {preset.label}
                                    </Button>
                                ))}
                            </div>
                        </div>
                        <AngleSlider label="左右角度" value={params.horizontalAngle} min={-180} max={180} step={1} suffix="deg" onChange={(value) => update("horizontalAngle", value)} />
                        <AngleSlider label="俯仰角度" value={params.pitchAngle} min={-90} max={90} step={1} suffix="deg" onChange={(value) => update("pitchAngle", value)} />
                        <AngleSlider label="镜头距离" value={params.cameraDistance} min={1} max={10} step={0.1} onChange={(value) => update("cameraDistance", value)} />
                        <div className="grid grid-cols-[88px_1fr_72px] items-center gap-4">
                            <span className="font-medium opacity-75">镜头</span>
                            <Segmented
                                className="w-fit"
                                value={params.lensPreset}
                                options={[
                                    { label: "广角", value: "wide" },
                                    { label: "标准", value: "standard" },
                                    { label: "长焦", value: "telephoto" },
                                ]}
                                onChange={(value) => updateLens(value as ImageAngleLensPreset)}
                            />
                        </div>
                    </div>
                </div>
                <div className="flex justify-end">
                    <Button type="primary" size="large" icon={<WandSparkles className="size-4" />} data-testid="canvas-image-angle-confirm" onClick={() => onConfirm(params)}>
                        AI 生成
                    </Button>
                </div>
            </div>
        </Modal>
    );
}

function AngleSlider({ label, value, min, max, step, suffix = "", onChange }: { label: string; value: number; min: number; max: number; step: number; suffix?: string; onChange: (value: number) => void }) {
    return (
        <div className="grid grid-cols-[88px_1fr_72px] items-center gap-4">
            <span className="font-medium opacity-75">{label}</span>
            <Slider min={min} max={max} step={step} value={value} onChange={onChange} />
            <span className="whitespace-nowrap text-right font-semibold">
                {Number.isInteger(value) ? value : value.toFixed(1)}
                {suffix}
            </span>
        </div>
    );
}

function previewTransform(params: CanvasImageAngleParams) {
    const lensScale = params.lensPreset === "wide" ? -0.08 : params.lensPreset === "telephoto" ? 0.08 : 0;
    const scale = 1.08 - params.cameraDistance * 0.035 + lensScale;
    return `perspective(620px) rotateY(${params.horizontalAngle * -0.42}deg) rotateX(${params.pitchAngle * 0.36}deg) scale(${Math.max(0.68, Math.min(1.12, scale))})`;
}
