const IMAGE_REQUEST_TIMEOUT_MS = 120_000;
const MASK_UPLOAD_MIME_TYPE = "image/png"; // Masks must keep alpha after resizing for upstream edit APIs.
const QUALITY_BASE: Record<string, number> = {
    low: 1024,
    medium: 2048,
    high: 2880,
    standard: 1024,
    hd: 2048,
};
const QUALITY_ALIASES: Record<string, string> = {
    "1k": "low",
    "2k": "medium",
    "4k": "high",
};
const DEFAULT_IMAGE_SHORT_SIDE = 1024;
const IMAGE_SIZE_STEP = 16;
const IMAGE_MIN_PIXELS = 655360;
const IMAGE_MAX_PIXELS = 8294400;
const IMAGE_MAX_EDGE = 3840;
const IMAGE_MAX_RATIO = 3;
const IMAGE_OUTPUT_FORMAT = "png";

class ClientRequestError extends Error {
    constructor(message: string) {
        super(message);
        this.name = "ClientRequestError";
    }
}

function isGptImage2Model(model: string) {
    const raw = model.trim().toLowerCase();
    const normalized = raw.replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
    const compact = raw.replace(/[^a-z0-9]+/g, "");
    return normalized === "gpt-image-2" || normalized.startsWith("gpt-image-2-") || normalized.endsWith("-gpt-image-2") || normalized.includes("-gpt-image-2-") || compact === "gptimage2" || compact.startsWith("gptimage2") || compact.endsWith("gptimage2");
}

function normalizeQuality(quality: string) {
    const value = quality.trim().toLowerCase();
    const normalized = QUALITY_ALIASES[value] || value;
    return QUALITY_BASE[normalized] ? normalized : undefined;
}

/** Map "quality + ratio" to an explicit pixel dimension like "3840x2160". */
function resolveSize(quality: string | undefined, ratio: string): string {
    const parsedRatio = parseImageRatio(ratio);
    const basePixels = quality ? QUALITY_BASE[quality] : undefined;
    const isLandscape = parsedRatio.width >= parsedRatio.height;
    const longRatio = isLandscape ? parsedRatio.width / parsedRatio.height : parsedRatio.height / parsedRatio.width;
    let longSide: number;
    let shortSide: number;

    if (basePixels) {
        const targetPixels = basePixels * basePixels;
        const longSideRaw = Math.sqrt(targetPixels * longRatio);
        longSide = Math.floor(longSideRaw / IMAGE_SIZE_STEP) * IMAGE_SIZE_STEP;
        shortSide = Math.round(longSide / longRatio / IMAGE_SIZE_STEP) * IMAGE_SIZE_STEP;
    } else {
        shortSide = DEFAULT_IMAGE_SHORT_SIDE;
        longSide = Math.round((shortSide * longRatio) / IMAGE_SIZE_STEP) * IMAGE_SIZE_STEP;
    }

    const width = isLandscape ? longSide : shortSide;
    const height = isLandscape ? shortSide : longSide;
    validateImageSize(width, height);
    return `${width}x${height}`;
}

function parseImageRatio(value: string) {
    const parts = value.split(":");
    if (parts.length !== 2) throw new Error("图像尺寸格式不支持，请使用 auto、9:16 或 1024x1024");
    const w = Number(parts[0]);
    const h = Number(parts[1]);
    if (!Number.isFinite(w) || !Number.isFinite(h) || w <= 0 || h <= 0) throw new Error("图像比例必须是正数，例如 9:16");
    if (Math.max(w, h) / Math.min(w, h) > IMAGE_MAX_RATIO) throw new Error("图像宽高比不能超过 3:1，请调整尺寸");
    return { width: w, height: h };
}

function parseImageDimensions(value: string) {
    const match = value.match(/^(\d+)x(\d+)$/i);
    if (!match) return null;
    return { width: Number(match[1]), height: Number(match[2]) };
}

function validateImageSize(width: number, height: number) {
    if (!Number.isInteger(width) || !Number.isInteger(height) || width <= 0 || height <= 0) throw new Error("图像尺寸必须是正整数，例如 1024x1024");
    if (width % IMAGE_SIZE_STEP !== 0 || height % IMAGE_SIZE_STEP !== 0) throw new Error("图像尺寸的宽高必须是 16 的倍数，请调整尺寸");
    if (Math.max(width, height) > IMAGE_MAX_EDGE) throw new Error("图像尺寸最长边不能超过 3840px，请调整尺寸");
    if (Math.max(width, height) / Math.min(width, height) > IMAGE_MAX_RATIO) throw new Error("图像宽高比不能超过 3:1，请调整尺寸");
    const pixels = width * height;
    if (pixels < IMAGE_MIN_PIXELS || pixels > IMAGE_MAX_PIXELS) throw new Error("图像总像素需在 655360 到 8294400 之间，请调整尺寸");
}

function resolveRequestSize(quality: string | undefined, size: string) {
    const value = size.trim();
    if (!value || value.toLowerCase() === "auto") return undefined;
    const dimensions = parseImageDimensions(value);
    if (dimensions) {
        validateImageSize(dimensions.width, dimensions.height);
        return `${dimensions.width}x${dimensions.height}`;
    }
    if (value.includes(":")) return resolveSize(quality, value);
    throw new Error("图像尺寸格式不支持，请使用 auto、9:16 或 1024x1024");
}

async function resolveImageDataUrl(item: Record<string, unknown>, scope: "personal" | "team" = "personal") {
    const directDataUrl = stringValue(item.dataUrl) || stringValue(item.data_url);
    if (directDataUrl) return ensureImageDataUrlMimeType(directDataUrl);
    if (typeof item.b64_json === "string" && item.b64_json) {
        const mimeType = stringValue(item.mime_type) || stringValue(item.mimeType) || "image/png";
        return ensureImageDataUrlMimeType(`data:${mimeType};base64,${item.b64_json}`);
    }
    const serverDataUrl = await resolveServerImageDataUrl(item, scope);
    if (serverDataUrl) return serverDataUrl;
    if (typeof item.url === "string" && item.url) {
        return item.url;
    }
    if (typeof item.remote_url === "string" && item.remote_url) {
        return item.remote_url;
    }
    return null;
}

async function parseImagePayload(payload: ImageProxyResponse, scope: "personal" | "team" = "personal") {
    const items = extractImageItems(payload);
    const payloadRecord: Record<string, unknown> | undefined = isRecord(payload) ? payload : undefined;
    const code = payloadRecord?.code;
    if (typeof code === "number" && code !== 0) {
        throw new Error(stringValue(payloadRecord?.msg) || "请求失败");
    }
    const images = (
        await Promise.all(
            items?.map(async (item): Promise<GeneratedApiImage | null> => {
                const dataUrl = await resolveImageDataUrl(item, scope);
                if (!dataUrl) return null;
                const assetId = stringValue(item.asset_id) || (stringValue(item.id).startsWith("asset_") ? stringValue(item.id) : "");
                return {
                    id: nanoid(),
                    dataUrl,
                    assetId: assetId || undefined,
                    storageKey: assetId ? serverAssetStorageKey({ id: assetId, type: "image", scope }) : undefined,
                    scope,
                };
            }) || [],
        )
    ).filter((value): value is GeneratedApiImage => Boolean(value));

    if (images.length === 0) {
        throw new Error("接口没有返回图片");
    }

    return images;
}

function extractImageItems(payload: ImageProxyResponse): Record<string, unknown>[] {
    if (Array.isArray(payload)) return payload;
    if (!isRecord(payload)) return [];
    if (Array.isArray(payload.images)) return payload.images;
    if (isRecord(payload.image)) return [payload.image];
    const payloadRecord = payload as Record<string, unknown>;
    if (Array.isArray(payloadRecord.outputs)) return payloadRecord.outputs.filter(isRecord);
    if (Array.isArray(payloadRecord.assets)) return payloadRecord.assets.filter(isRecord).map((asset: Record<string, unknown>) => ({ ...asset, asset_id: asset.id, asset_url: asset.url }));
    if (Array.isArray(payload.data)) return payload.data;
    if (isRecord(payload.data)) return extractImageItems(payload.data as ImageProxyResponse);
    return [];
}

async function resolveServerImageDataUrl(item: Record<string, unknown>, scope: "personal" | "team") {
    const assetId = stringValue(item.asset_id) || stringValue(item.id);
    if (assetId) {
        const blob = await downloadServerAsset(serverAssetStorageKey({ id: assetId, type: "image", scope }), scope);
        if (blob) return blobToDataUrl(blob);
    }
    const assetUrl = stringValue(item.asset_url);
    if (!assetUrl) return null;
    const token = getStoredAuthToken();
    const headers = new Headers();
    if (token) headers.set("Authorization", `Bearer ${token}`);
    const response = await fetch(assetUrl.startsWith("/") ? `${API_BASE_URL}${assetUrl}` : assetUrl, {
        credentials: "include",
        headers,
    });
    if (!response.ok) return null;
    return blobToDataUrl(await response.blob());
}

function blobToDataUrl(blob: Blob) {
    return new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(new Error("读取本地素材失败"));
        reader.readAsDataURL(blob);
    });
}

function readAxiosError(error: unknown, fallback: string) {
    if (axios.isCancel(error)) return "请求已取消";
    if (axios.isAxiosError<{ error?: { message?: string }; msg?: string; code?: number }>(error)) {
        const responseData = error.response?.data;
        return responseData?.msg || responseData?.error?.message || readStatusError(error.response?.status, fallback);
    }
    if (error instanceof DOMException && error.name === "AbortError") return "请求已取消";
    return error instanceof Error ? error.message : fallback;
}

function readStatusError(status: number | undefined, fallback: string) {
    if (status === 401 || status === 403) return "模型服务暂不可用，请联系管理员检查权限或模型服务";
    if (status === 429) return "请求被限流或额度不足，请稍后重试";
    return status ? `${fallback}：${status}` : fallback;
}

function formatPublicImageError(error: unknown, fallback: string) {
    if (axios.isCancel(error)) return "请求已取消";
    if (error instanceof DOMException && error.name === "AbortError") return "请求已取消";
    if (error instanceof ClientRequestError) return `请求未发出：${error.message}`;
    if (error instanceof ApiError) {
        const suffix = error.requestId ? `（request_id: ${error.requestId}）` : "";
        if (error.status === 401) return `登录状态已失效，请重新登录${suffix}`;
        if (error.status === 403) return `当前账号无权使用图片模型服务${suffix}`;
        if (error.status === 429) return `请求被限流或额度不足，请稍后重试${suffix}`;
        return readableApiError(error) || error.message || `图片模型服务暂不可用，请联系管理员配置模型服务${suffix}`;
    }
    return error instanceof Error ? error.message : fallback;
}

function readableApiError(error: ApiError) {
    const data = apiErrorRecord(error.data) ? error.data : null;
    const reason = data ? apiErrorString(data.reason) : "";
    const suggestion = data ? apiErrorString(data.suggestion) : "";
    const providerStatus = data ? apiErrorNumber(data.provider_status) : 0;
    const prefix = providerStatus ? `模型服务返回 ${providerStatus}，生成失败` : error.status >= 500 ? "模型服务暂不可用" : "生成失败";
    const parts = [prefix, reason, suggestion].filter(Boolean);
    const requestId = error.requestId ? `（request_id: ${error.requestId}）` : "";
    return parts.length ? `${parts.join("。")}${requestId}` : "";
}

function apiErrorRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function apiErrorString(value: unknown) {
    return typeof value === "string" ? value.trim() : "";
}

function apiErrorNumber(value: unknown) {
    return typeof value === "number" ? value : typeof value === "string" ? Number(value) || 0 : 0;
}

function withSystemPrompt(config: AiConfig, prompt: string) {
    const systemPrompt = config.systemPrompt.trim();
    return systemPrompt ? `${systemPrompt}\n\n${prompt}` : prompt;
}

function aiApiUrl(config: AiConfig, path: string) {
    return buildApiUrl(config.baseUrl, path);
}

function aiHeaders(config: AiConfig, contentType?: string) {
    return {
        Authorization: `Bearer ${config.apiKey}`,
        ...(contentType ? { "Content-Type": contentType } : {}),
    };
}

function geminiBaseUrl(config: Pick<AiConfig, "baseUrl">) {
    const normalizedBaseUrl = config.baseUrl.trim().replace(/\/+$/, "");
    const lowerBaseUrl = normalizedBaseUrl.toLowerCase();
    return lowerBaseUrl.endsWith("/v1") || lowerBaseUrl.endsWith("/v1beta") ? normalizedBaseUrl : `${normalizedBaseUrl}/v1beta`;
}

function geminiModelName(model: string) {
    return model.trim().replace(/^models\//, "");
}

function geminiApiUrl(config: Pick<AiConfig, "baseUrl" | "model">, action?: "generateContent" | "streamGenerateContent") {
    const baseUrl = geminiBaseUrl(config);
    if (!action) return `${baseUrl}/models`;
    return `${baseUrl}/models/${encodeURIComponent(geminiModelName(config.model))}:${action}`;
}

function geminiHeaders(config: Pick<AiConfig, "apiKey">) {
    return {
        "x-goog-api-key": config.apiKey,
        "Content-Type": "application/json",
    };
}

function withSystemMessage<T extends ResponseInputMessage>(config: AiConfig, messages: T[]): ResponseInputMessage[] {
    const systemPrompt = config.systemPrompt.trim();
    return systemPrompt ? [{ role: "system" as const, content: systemPrompt }, ...messages] : messages;
}

function toResponseInput(messages: ResponseInputMessage[]): ResponseInputItem[] {
    return messages.flatMap((message): ResponseInputItem[] => {
        if ("type" in message) return [message];
        if (message.role === "tool") return [{ type: "function_call_output", call_id: message.tool_call_id, output: message.content }];
        return [{ role: message.role, content: toResponseContent(message.content || "") }];
    });
}

function toResponseContent(content: ResponseMessageContent): string | ResponseInputContent[] {
    if (!Array.isArray(content)) return String(content || "");
    return content.map((item) => (item.type === "text" ? { type: "input_text" as const, text: item.text } : { type: "input_image" as const, image_url: normalizedImageUrl(item.image_url.url) }));
}

function toResponseTool(tool: ResponseFunctionTool): ResponseApiToolDefinition {
    return {
        type: "function",
        name: tool.function.name,
        description: tool.function.description,
        parameters: tool.function.parameters,
        strict: tool.function.strict,
    };
}

function parseToolResponse(payload: ResponseApiPayload): ToolResponseResult {
    const output = payload.output || [];
    const content =
        payload.output_text ||
        output
            .flatMap((item) => (item.type === "message" ? item.content || [] : []))
            .map((item) => item.text || "")
            .join("");
    const toolCalls = output
        .filter((item): item is Extract<ResponseApiOutputItem, { type?: "function_call" }> => item.type === "function_call")
        .map((item) => ({
            id: item.call_id || item.id || "",
            type: "function" as const,
            function: { name: item.name || "", arguments: item.arguments || "{}" },
        }))
        .filter((item) => item.id && item.function.name);
    return { content, toolCalls };
}

function isRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function responseErrorMessage(value: unknown) {
    if (!isRecord(value)) return "";
    const error = isRecord(value.error) ? value.error : undefined;
    const response = isRecord(value.response) ? value.response : undefined;
    const responseError = response && isRecord(response.error) ? response.error : undefined;
    return stringValue(value.msg) || stringValue(error?.message) || stringValue(responseError?.message);
}

function stringValue(value: unknown) {
    return typeof value === "string" ? value : "";
}

function validateResponsePayload(payload: ResponseApiPayload) {
    if (typeof payload.code === "number" && payload.code !== 0) throw new Error(payload.msg || "请求失败");
    if (payload.error?.message) throw new Error(payload.error.message);
}

function validateGeminiPayload(payload: GeminiPayload) {
    if (payload.error?.message) throw new Error(payload.error.message);
    if (payload.promptFeedback?.blockReason) throw new Error(`Gemini 拒绝了本次请求：${payload.promptFeedback.blockReason}`);
}

async function readFetchError(response: Response, fallback: string) {
    const text = await response.text();
    if (!text) return readStatusError(response.status, fallback);
    try {
        return responseErrorMessage(JSON.parse(text)) || readStatusError(response.status, fallback);
    } catch {
        return text.slice(0, 300) || readStatusError(response.status, fallback);
    }
}

function consumeResponseStreamBlock(block: string, state: ResponseStreamState, onDelta?: (text: string) => void) {
    const data = block
        .split(/\r?\n/)
        .filter((line) => line.startsWith("data:"))
        .map((line) => line.slice(5).replace(/^ /, ""))
        .join("\n")
        .trim();
    if (!data || data === "[DONE]") return;
    const event = JSON.parse(data) as Record<string, unknown>;
    const type = stringValue(event.type);
    const errorMessage = responseErrorMessage(event);
    if (errorMessage) state.error = errorMessage;
    if (type === "response.output_text.delta" && typeof event.delta === "string") {
        state.text += event.delta;
        onDelta?.(state.text);
    }
    if (type === "response.output_text.done" && !state.text && typeof event.text === "string") {
        state.text = event.text;
        onDelta?.(state.text);
    }
    if (type === "response.completed" && isRecord(event.response)) {
        state.payload = event.response as ResponseApiPayload;
    } else if (Array.isArray(event.output)) {
        state.payload = event as ResponseApiPayload;
    }
}

function consumeResponseStreamText(state: ResponseStreamState, text: string, onDelta?: (text: string) => void, flush = false) {
    state.buffer += text;
    for (;;) {
        const match = state.buffer.match(/\r?\n\r?\n/);
        if (!match) break;
        const matchIndex = match.index ?? 0;
        consumeResponseStreamBlock(state.buffer.slice(0, matchIndex), state, onDelta);
        state.buffer = state.buffer.slice(matchIndex + match[0].length);
    }
    if (flush && state.buffer.trim()) {
        consumeResponseStreamBlock(state.buffer, state, onDelta);
        state.buffer = "";
    }
}

async function requestStreamingResponse(config: AiConfig, body: Record<string, unknown>, onDelta?: (text: string) => void, options?: RequestOptions): Promise<ToolResponseResult> {
    const response = await fetch(aiApiUrl(config, "/responses"), {
        method: "POST",
        headers: { ...aiHeaders(config, "application/json"), Accept: "text/event-stream" },
        body: JSON.stringify({ ...body, stream: true }),
        signal: options?.signal,
    });
    if (!response.ok) throw new Error(await readFetchError(response, "请求失败"));
    if (!response.body) {
        const payload = (await response.json()) as ResponseApiPayload;
        validateResponsePayload(payload);
        return parseToolResponse(payload);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    const state: ResponseStreamState = { buffer: "", text: "" };
    for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        consumeResponseStreamText(state, decoder.decode(value, { stream: true }), onDelta);
        if (state.error) throw new Error(state.error);
    }
    consumeResponseStreamText(state, decoder.decode(), onDelta, true);
    if (state.error) throw new Error(state.error);
    if (!state.payload) return { content: state.text, toolCalls: [] };
    validateResponsePayload(state.payload);
    const result = parseToolResponse(state.payload);
    return { ...result, content: state.text || result.content };
}

function toGeminiBody(config: AiConfig, messages: ResponseInputMessage[], extra?: Record<string, unknown>) {
    const systemText = [
        config.systemPrompt.trim(),
        ...messages.flatMap((message) => (!("type" in message) && message.role === "system" ? [geminiTextContent(message.content)] : [])),
    ]
        .filter(Boolean)
        .join("\n\n");
    const contents = toGeminiContents(messages.filter((message) => ("type" in message ? true : message.role !== "system")));
    return {
        contents,
        ...(systemText ? { systemInstruction: { parts: [{ text: systemText }] } } : {}),
        ...extra,
    };
}

function toGeminiContents(messages: ResponseInputMessage[]): GeminiContent[] {
    const callNameById = new Map<string, string>();
    return messages.flatMap((message): GeminiContent[] => {
        if ("type" in message) {
            callNameById.set(message.call_id, message.name);
            return [{ role: "model", parts: [{ functionCall: { id: message.call_id, name: message.name, args: jsonObject(message.arguments) }, ...(message.thoughtSignature ? { thoughtSignature: message.thoughtSignature } : {}) }] }];
        }
        if (message.role === "tool") {
            const name = callNameById.get(message.tool_call_id) || "tool_result";
            return [{ role: "user", parts: [{ functionResponse: { id: message.tool_call_id, name, response: { result: jsonValue(message.content) } } }] }];
        }
        return [{ role: message.role === "assistant" ? "model" : "user", parts: toGeminiParts(message.content) }];
    });
}

function toGeminiParts(content: ResponseMessageContent): GeminiPart[] {
    if (!Array.isArray(content)) return [{ text: String(content || "") }];
    return content.map((item) => (item.type === "text" ? { text: item.text } : toGeminiImagePart(item.image_url.url)));
}

function toGeminiImagePart(url: string): GeminiPart {
    url = normalizedImageUrl(url);
    const match = url.match(/^data:([^;,]+);base64,(.+)$/);
    if (match) return { inlineData: { mimeType: match[1], data: match[2] } };
    return { fileData: { fileUri: url, mimeType: "image/png" } };
}

function normalizedImageUrl(url: string) {
    return url.startsWith("data:") ? ensureImageDataUrlMimeType(url) : url;
}

function geminiTextContent(content: ResponseMessageContent) {
    if (!Array.isArray(content)) return String(content || "");
    return content.map((item) => (item.type === "text" ? item.text : item.image_url.url)).join("\n");
}

function jsonObject(value: string): Record<string, unknown> {
    const parsed = jsonValue(value);
    return isRecord(parsed) ? parsed : {};
}

function jsonValue(value: string): unknown {
    try {
        return JSON.parse(value);
    } catch {
        return value;
    }
}

function toGeminiToolOptions(tools: ResponseFunctionTool[], toolChoice: ToolChoice) {
    if (!tools.length) return {};
    const functionDeclarations = tools.map((tool) => ({
        name: tool.function.name,
        description: tool.function.description,
        parameters: tool.function.parameters,
    }));
    const functionCallingConfig =
        typeof toolChoice === "object"
            ? { mode: "ANY", allowedFunctionNames: [toolChoice.name] }
            : { mode: toolChoice === "required" ? "ANY" : "AUTO" };
    return {
        tools: [{ functionDeclarations }],
        toolConfig: { functionCallingConfig },
    };
}

async function requestGeminiStreamingResponse(config: AiConfig, body: Record<string, unknown>, onDelta?: (text: string) => void, options?: RequestOptions): Promise<ToolResponseResult> {
    const response = await fetch(`${geminiApiUrl(config, "streamGenerateContent")}?alt=sse`, {
        method: "POST",
        headers: geminiHeaders(config),
        body: JSON.stringify(body),
        signal: options?.signal,
    });
    if (!response.ok) throw new Error(await readFetchError(response, "请求失败"));
    if (!response.body) {
        const payload = (await response.json()) as GeminiPayload;
        return parseGeminiToolResponse(payload);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    const state: GeminiStreamState = { buffer: "", text: "", toolCalls: [] };
    for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        consumeGeminiStreamText(state, decoder.decode(value, { stream: true }), onDelta);
        if (state.error) throw new Error(state.error);
    }
    consumeGeminiStreamText(state, decoder.decode(), onDelta, true);
    if (state.error) throw new Error(state.error);
    return { content: state.text, toolCalls: state.toolCalls };
}

function consumeGeminiStreamText(state: GeminiStreamState, text: string, onDelta?: (text: string) => void, flush = false) {
    state.buffer += text;
    for (;;) {
        const match = state.buffer.match(/\r?\n\r?\n/);
        if (!match) break;
        const matchIndex = match.index ?? 0;
        consumeGeminiStreamBlock(state.buffer.slice(0, matchIndex), state, onDelta);
        state.buffer = state.buffer.slice(matchIndex + match[0].length);
    }
    if (flush && state.buffer.trim()) {
        consumeGeminiStreamBlock(state.buffer, state, onDelta);
        state.buffer = "";
    }
}

function consumeGeminiStreamBlock(block: string, state: GeminiStreamState, onDelta?: (text: string) => void) {
    const data = block
        .split(/\r?\n/)
        .filter((line) => line.startsWith("data:"))
        .map((line) => line.slice(5).replace(/^ /, ""))
        .join("\n")
        .trim();
    if (!data || data === "[DONE]") return;
    const result = parseGeminiToolResponse(JSON.parse(data) as GeminiPayload);
    if (result.content) {
        state.text += result.content;
        onDelta?.(state.text);
    }
    state.toolCalls.push(...result.toolCalls);
}

function parseGeminiToolResponse(payload: GeminiPayload): ToolResponseResult {
    validateGeminiPayload(payload);
    const parts = payload.candidates?.flatMap((candidate) => candidate.content?.parts || []) || [];
    const content = parts.map((part) => part.text || "").join("");
    const toolCalls = parts
        .map((part) => part.functionCall)
        .filter((call): call is NonNullable<GeminiPart["functionCall"]> => Boolean(call?.name))
        .map((call) => {
            const part = parts.find((item) => item.functionCall === call);
            const thoughtSignature = part?.thoughtSignature || part?.thought_signature;
            return {
                id: call.id || nanoid(),
                type: "function" as const,
                function: { name: call.name || "", arguments: JSON.stringify(call.args || {}) },
                ...(thoughtSignature ? { thoughtSignature } : {}),
            };
        });
    return { content, toolCalls };
}

async function requestGeminiImages(config: AiConfig, prompt: string, references: ReferenceImage[], count: number, options?: RequestOptions) {
    const requests = Array.from({ length: count }, () => requestGeminiImagesOnce(config, prompt, references, options));
    return (await Promise.all(requests)).flat();
}

async function requestGeminiImagesOnce(config: AiConfig, prompt: string, references: ReferenceImage[], options?: RequestOptions) {
    const parts: GeminiPart[] = [{ text: prompt }];
    for (const image of references) {
        parts.push(toGeminiImagePart((await normalizedReferenceImage(image)).dataUrl));
    }
    const response = await axios.post<GeminiPayload>(
        geminiApiUrl(config, "generateContent"),
        {
            ...toGeminiBody(config, [{ role: "user", content: prompt }], { generationConfig: { responseModalities: ["TEXT", "IMAGE"] } }),
            contents: [{ role: "user", parts }],
        },
        { headers: geminiHeaders(config), signal: options?.signal },
    );
    return parseGeminiImagePayload(response.data);
}

function parseGeminiImagePayload(payload: GeminiPayload) {
    validateGeminiPayload(payload);
    const images =
        payload.candidates
            ?.flatMap((candidate) => candidate.content?.parts || [])
            .map((part) => {
                const inlineData = part.inlineData || (part.inline_data ? { mimeType: part.inline_data.mimeType || part.inline_data.mime_type, data: part.inline_data.data } : undefined);
                if (inlineData?.data) return `data:${inlineData.mimeType || "image/png"};base64,${inlineData.data}`;
                return part.fileData?.fileUri || null;
            })
            .filter((value): value is string => Boolean(value))
            .map((dataUrl) => ({ id: nanoid(), dataUrl })) || [];
    if (!images.length) throw new Error("Gemini 接口没有返回图片");
    return images;
}

function idempotencyHeaders(idempotencyKey?: string) {
    const value = idempotencyKey?.trim();
    return value ? { "Idempotency-Key": value } : undefined;
}

export async function requestGeneration(config: AiConfig, prompt: string, options?: RequestOptions) {
    const requestedModel = imageModelOptionForRequest(config, config.imageModel || config.model);
    const requestConfig = resolveModelRequestConfig(config, requestedModel);
    const n = Math.max(1, Math.min(15, Math.floor(Math.abs(Number(config.count)) || 1)));
    const quality = normalizeQuality(config.quality);
    const requestSize = resolveRequestSize(quality, config.size);
    try {
        const submitted = await requestApi<JobSubmission>(scopedImagePath("/api/ai/image/generations", options?.scope), {
            method: "POST",
            signal: options?.signal,
            timeoutMs: IMAGE_REQUEST_TIMEOUT_MS,
            headers: idempotencyHeaders(options?.idempotencyKey),
            body: JSON.stringify({
                model: requestedModel,
                prompt: withSystemPrompt(requestConfig, prompt),
                n,
                ...(quality ? { quality } : {}),
                ...(requestSize ? { size: requestSize } : {}),
                response_format: "b64_json",
                output_format: IMAGE_OUTPUT_FORMAT,
                ...(options?.assetContext ? { asset_context: options.assetContext } : {}),
            }),
        });
        options?.onJobAccepted?.(submitted);
        return waitForImageJob(jobRecordId(submitted), options);
    } catch (error) {
        throw new Error(formatPublicImageError(error, "请求失败"));
    }
}

export async function requestEdit(config: AiConfig, prompt: string, references: ReferenceImage[], mask?: ReferenceImage, options?: RequestOptions) {
    const requestedModel = imageModelOptionForRequest(config, config.imageModel || config.model);
    const requestConfig = resolveModelRequestConfig(config, requestedModel);
    const isGptImage2 = isGptImage2Model(requestConfig.model);
    const n = Math.max(1, Math.min(15, Math.floor(Math.abs(Number(config.count)) || 1)));
    const requestPrompt = buildImageReferencePromptText(prompt, references);
    const quality = normalizeQuality(config.quality);
    const requestSize = resolveRequestSize(quality, config.size);
    const formData = new FormData();
    formData.set("model", requestedModel);
    formData.set("prompt", withSystemPrompt(requestConfig, requestPrompt));
    if (!isGptImage2) {
        formData.set("n", String(n));
        formData.set("response_format", "b64_json");
        formData.set("output_format", IMAGE_OUTPUT_FORMAT);
    }
    if (quality) {
        formData.set("quality", quality);
    }
    if (requestSize) {
        formData.set("size", requestSize);
    }
    if (options?.assetContext) {
        formData.set("asset_context", JSON.stringify(options.assetContext));
    }

    try {
        if (references.length > MAX_REFERENCE_IMAGES) throw new ClientRequestError(`参考图最多 ${MAX_REFERENCE_IMAGES} 张`);
        const referenceImages = await prepareReferenceImages(references);
        const files = referenceImages.map((image) => dataUrlToFile(image));
        files.forEach((file) => formData.append("image", file));
        if (mask) formData.set("mask", await prepareMaskFile(mask, referenceImages[0]));
        const submitted = await requestApi<JobSubmission>(scopedImagePath("/api/ai/image/edits", options?.scope), {
            method: "POST",
            signal: options?.signal,
            timeoutMs: IMAGE_REQUEST_TIMEOUT_MS,
            headers: idempotencyHeaders(options?.idempotencyKey),
            body: formData,
        });
        options?.onJobAccepted?.(submitted);
        return waitForImageJob(jobRecordId(submitted), options);
    } catch (error) {
        throw new Error(formatPublicImageError(error, "请求失败"));
    }
}

function scopedImagePath(path: string, scope?: WorkspaceScope) {
    return scope ? `${path}?scope=${encodeURIComponent(scope)}` : path;
}

export async function waitForImageJob(jobId: string, options?: RequestOptions) {
    const job = await waitForJob(jobId, options);
    return imagesFromCompletedJob(job);
}

export async function imagesFromCompletedJob(job: JobRecord) {
    if (job.status !== "succeeded") throw new Error(jobErrorMessage(job, "图片生成失败"));
    return parseImagePayload(job.result as ImageProxyResponse, job.scope || "personal");
}

async function normalizedReferenceImage(image: ReferenceImage): Promise<ReferenceImage> {
    const dataUrl = ensureImageDataUrlMimeType(await imageToDataUrl(image), image.type);
    return { ...image, type: imageDataUrlMimeType(dataUrl, image.type), dataUrl };
}

async function prepareReferenceImages(references: ReferenceImage[]) {
    try {
        const normalized = await mapWithConcurrency(references, IMAGE_PREPROCESS_CONCURRENCY, async (image) => compressReferenceImageForUpload(await normalizedReferenceImage(image)));
        const totalBytes = normalized.reduce((sum, image) => sum + getDataUrlByteSize(image.dataUrl), 0);
        if (totalBytes > MAX_REFERENCE_TOTAL_BYTES) throw new ClientRequestError(`参考图压缩后合计不能超过 ${Math.floor(MAX_REFERENCE_TOTAL_BYTES / 1024 / 1024)}MB`);
        return normalized;
    } catch (error) {
        if (error instanceof ClientRequestError) throw error;
        throw new ClientRequestError(error instanceof Error ? error.message : "参考图预处理失败");
    }
}

async function prepareMaskFile(mask: ReferenceImage, referenceImage?: ReferenceImage) {
    try {
        const normalized = await normalizedReferenceImage(mask);
        const matched = referenceImage ? await resizeMaskToReferenceImage(normalized, referenceImage) : normalized;
        return dataUrlToFile(matched);
    } catch (error) {
        throw new ClientRequestError(error instanceof Error ? error.message : "蒙版预处理失败");
    }
}

async function resizeMaskToReferenceImage(mask: ReferenceImage, referenceImage: ReferenceImage) {
    const [maskMeta, referenceMeta] = await Promise.all([readImageMeta(mask.dataUrl), readImageMeta(referenceImage.dataUrl)]);
    if (maskMeta.width === referenceMeta.width && maskMeta.height === referenceMeta.height) {
        return { ...mask, type: imageDataUrlMimeType(mask.dataUrl, mask.type) };
    }

    return {
        ...mask,
        type: MASK_UPLOAD_MIME_TYPE,
        dataUrl: await resizeImageDataUrl(mask.dataUrl, referenceMeta.width, referenceMeta.height, {
            mimeType: MASK_UPLOAD_MIME_TYPE,
            imageSmoothingEnabled: false,
        }),
    };
}

export async function requestImageQuestion(config: AiConfig, messages: AiTextMessage[], onDelta: (text: string) => void, options?: RequestOptions) {
    const requestConfig = resolveModelRequestConfig(config, config.model || config.textModel);
    try {
        if (requestConfig.apiFormat === "gemini") {
            const answer = (await requestGeminiStreamingResponse(requestConfig, toGeminiBody(requestConfig, messages), onDelta, options)).content || "没有返回内容";
            if (answer === "没有返回内容") onDelta(answer);
            return answer;
        }
        const answer = (await requestStreamingResponse(requestConfig, {
            model: requestConfig.model,
            input: toResponseInput(withSystemMessage(requestConfig, messages)),
        }, onDelta, options)).content || "没有返回内容";
        if (answer === "没有返回内容") onDelta(answer);
        return answer;
    } catch (error) {
        throw new Error(readAxiosError(error, "请求失败"));
    }
}

export async function requestToolResponse(config: AiConfig, messages: ResponseInputMessage[], tools: ResponseFunctionTool[], toolChoice: ToolChoice = "auto", onDelta?: (text: string) => void, options?: RequestOptions): Promise<ToolResponseResult> {
    const requestConfig = resolveModelRequestConfig(config, config.model || config.textModel);
    try {
        if (requestConfig.apiFormat === "gemini") {
            return await requestGeminiStreamingResponse(requestConfig, toGeminiBody(requestConfig, messages, toGeminiToolOptions(tools, toolChoice)), onDelta, options);
        }
        return await requestStreamingResponse(requestConfig, {
            model: requestConfig.model,
            input: toResponseInput(withSystemMessage(requestConfig, messages)),
            tools: tools.map(toResponseTool),
            tool_choice: toolChoice,
            parallel_tool_calls: false,
        }, onDelta, options);
    } catch (error) {
        throw new Error(readAxiosError(error, "请求失败"));
    }
}

export async function fetchImageModels(config: Pick<AiConfig, "baseUrl" | "apiKey" | "apiFormat">) {
    try {
        if (config.apiFormat === "gemini") {
            const response = await axios.get<GeminiPayload>(geminiApiUrl({ ...defaultGeminiConfig, ...config }), { headers: geminiHeaders({ ...defaultGeminiConfig, ...config }) });
            validateGeminiPayload(response.data);
            return (response.data.models || [])
                .map((model) => model.name?.replace(/^models\//, ""))
                .filter((id): id is string => Boolean(id))
                .sort((a, b) => a.localeCompare(b));
        }
        const response = await axios.get<{ data?: Array<{ id?: string }>; error?: { message?: string } }>(buildApiUrl(config.baseUrl, "/models"), {
            headers: {
                Authorization: `Bearer ${config.apiKey}`,
            },
        });
        return (response.data.data || [])
            .map((model) => model.id)
            .filter((id): id is string => Boolean(id))
            .sort((a, b) => a.localeCompare(b));
    } catch (error) {
        throw new Error(readAxiosError(error, "读取模型失败"));
    }
}

export async function fetchChannelModels(channel: ModelChannel) {
    return fetchImageModels({ baseUrl: channel.baseUrl, apiKey: channel.apiKey, apiFormat: channel.apiFormat });
}

const defaultGeminiConfig: Pick<AiConfig, "baseUrl" | "apiKey" | "apiFormat" | "model" | "systemPrompt"> = {
    baseUrl: "https://generativelanguage.googleapis.com",
    apiKey: "",
    apiFormat: "gemini",
    model: "",
    systemPrompt: "",
};
