import { useEffect, useRef, useState, type ReactNode } from "react";

import { useAuth } from "@/contexts/AuthContext";
import { useCanvasStore } from "../vendor/canvas/stores/use-canvas-store";
import { clearLocalMediaCache } from "./services/file-storage";
import { clearLocalImageCache } from "./services/image-storage";
import { useAssetStore } from "./stores/use-asset-store";
import { useUserPreferencesStore } from "./stores/use-user-preferences-store";
import { useUserStore, type LocalUser } from "./stores/use-user-store";
import { enqueueProductionCanvasScopeSwitch } from "./production-canvas-scope-switch";

export function ProductionCanvasBridge({ children }: { children: ReactNode }) {
    const { user, loading } = useAuth();
    const syncIdRef = useRef(0);
    const currentScopeKey = loading ? null : user?.id || "anonymous";
    const [scopeState, setScopeState] = useState<{ key: string | null; error: string }>({ key: null, error: "" });

    useEffect(() => {
        const syncId = ++syncIdRef.current;
        let active = true;
        const localUser: LocalUser | null = user
            ? {
                  id: user.id,
                  username: user.username,
                  displayName: user.display_name || user.username,
                  role: user.role,
                  status: user.status === "disabled" ? "disabled" : "active",
              }
            : null;

        if (loading) {
            useUserStore.getState().setAuthState(user, true);
            return () => {
                active = false;
            };
        }

        useUserStore.getState().setAuthState(user, true);

        const scopeSwitch = enqueueProductionCanvasScopeSwitch(async () => {
            await Promise.all([
                useCanvasStore.getState().switchUserScope(localUser),
                useAssetStore.getState().switchUserScope(localUser),
                useUserPreferencesStore.getState().switchUserScope(localUser),
                ...(localUser ? [] : [clearLocalImageCache(), clearLocalMediaCache()]),
            ]);
        });

        void scopeSwitch
            .then(() => {
                if (!active || syncId !== syncIdRef.current) return;
                useUserStore.getState().setAuthState(user, false);
                setScopeState({ key: localUser?.id || "anonymous", error: "" });
            })
            .catch((error) => {
                console.warn("Production Canvas user scope switch failed", error);
                if (!active || syncId !== syncIdRef.current) return;
                useUserStore.getState().setAuthState(user, false);
                setScopeState({ key: localUser?.id || "anonymous", error: "画布初始化失败，请刷新后重试" });
            });

        return () => {
            active = false;
        };
    }, [loading, user]);

    if (!currentScopeKey || scopeState.key !== currentScopeKey) {
        return <div data-testid="production-canvas-scope-loading">加载画布…</div>;
    }
    if (scopeState.error) {
        return <div data-testid="production-canvas-scope-error">{scopeState.error}</div>;
    }
    return children;
}
