import { API_BASE_URL } from "@/constant/env";
import { getStoredAuthToken, requestApi } from "@/services/api/request";
import type { WorkspaceScope } from "@/stores/use-workspace-scope-store";

export type JobStatus = "queued" | "running" | "succeeded" | "failed" | "canceled";

export type JobRecord = {
    id?: string;
    job_id?: string;
    type?: string;
    status: JobStatus;
    scope?: "personal" | "team";
    progress?: number;
    queue_phase?: string;
    result?: unknown;
    error?: unknown;
    payload?: unknown;
    created_at?: string;
    updated_at?: string;
    started_at?: string;
    finished_at?: string;
};

export type JobSubmission = {
    id?: string;
    job_id?: string;
    status: JobStatus;
};

export type WaitForJobOptions = {
    signal?: AbortSignal;
    idempotencyKey?: string;
    onJobAccepted?: (job: JobSubmission) => void;
    onProgress?: (job: JobRecord) => void;
    disableSSE?: boolean;
    pollingIntervalMs?: number;
};

const JOB_POLL_INTERVAL_MS = 3000;
const JOB_SSE_FALLBACK_MS = 8000;

export function jobRecordId(job: Pick<JobRecord, "id" | "job_id"> | Pick<JobSubmission, "id" | "job_id">) {
    return job.job_id || job.id || "";
}

export function isTerminalJob(job: Pick<JobRecord, "status">) {
    return job.status === "succeeded" || job.status === "failed" || job.status === "canceled";
}

export function jobErrorMessage(job: JobRecord, fallback = "任务执行失败") {
    const error = job.error;
    if (typeof error === "string" && error.trim()) return error;
    if (error && typeof error === "object") {
        const record = error as Record<string, unknown>;
        const message = record.message || record.error || record.detail || record.code;
        if (typeof message === "string" && message.trim()) return message;
    }
    return fallback;
}

export type JobListQuery = { statuses?: JobStatus[]; types?: string[]; limit?: number };

export async function listJobs(scope: WorkspaceScope, query: JobListQuery = {}, options?: { signal?: AbortSignal }) {
    const params = new URLSearchParams({ scope });
    if (query.statuses?.length) params.set("status", query.statuses.join(","));
    if (query.types?.length) params.set("type", query.types.join(","));
    if (query.limit) params.set("limit", String(query.limit));
    return requestApi<JobRecord[]>(`/api/jobs?${params.toString()}`, { signal: options?.signal });
}

export async function fetchJob(jobId: string, options?: { signal?: AbortSignal }) {
    return requestApi<JobRecord>(`/api/jobs/${encodeURIComponent(jobId)}`, { signal: options?.signal });
}

export async function cancelJob(jobId: string, options?: { signal?: AbortSignal; scope?: WorkspaceScope }) {
    if (!jobId) return null;
    const scope = options?.scope ? `?scope=${encodeURIComponent(options.scope)}` : "";
    return requestApi<JobRecord>(`/api/jobs/${encodeURIComponent(jobId)}/cancel${scope}`, { method: "POST", signal: options?.signal });
}

export async function waitForJob(jobId: string, options: WaitForJobOptions = {}) {
    if (!jobId) throw new Error("任务 ID 为空");
    if (options.signal?.aborted) throw new DOMException("Aborted", "AbortError");
    if (!options.disableSSE && typeof window !== "undefined" && typeof window.EventSource === "function") {
        try {
            return await waitForJobSSE(jobId, options);
        } catch (error) {
            if (options.signal?.aborted || isAbortError(error)) throw error;
        }
    }
    return pollJob(jobId, options);
}

async function pollJob(jobId: string, options: WaitForJobOptions) {
    for (;;) {
        if (options.signal?.aborted) throw new DOMException("Aborted", "AbortError");
        const job = await fetchJob(jobId, { signal: options.signal });
        options.onProgress?.(job);
        if (isTerminalJob(job)) return job;
        await delay(options.pollingIntervalMs || JOB_POLL_INTERVAL_MS, options.signal);
    }
}

function waitForJobSSE(jobId: string, options: WaitForJobOptions) {
    return new Promise<JobRecord>((resolve, reject) => {
        const source = new EventSource(jobStreamUrl(jobId, getStoredAuthToken()), { withCredentials: true });
        let fallbackTimer: ReturnType<typeof setTimeout> | null = null;
        let settled = false;

        const cleanup = () => {
            settled = true;
            if (fallbackTimer) clearTimeout(fallbackTimer);
            options.signal?.removeEventListener("abort", abort);
            source.close();
        };
        const settle = (callback: () => void) => {
            if (settled) return;
            cleanup();
            callback();
        };
        const abort = () => settle(() => reject(new DOMException("Aborted", "AbortError")));
        const clearFallback = () => {
            if (!fallbackTimer) return;
            clearTimeout(fallbackTimer);
            fallbackTimer = null;
        };
        const scheduleFallback = () => {
            if (fallbackTimer) return;
            fallbackTimer = setTimeout(() => {
                settle(() => reject(new Error("SSE unavailable")));
            }, JOB_SSE_FALLBACK_MS);
        };
        const handleJob = (event: MessageEvent<string>) => {
            clearFallback();
            const job = parseSSEJob(event.data);
            if (!job) return;
            options.onProgress?.(job);
            if (isTerminalJob(job)) settle(() => resolve(job));
        };

        options.signal?.addEventListener("abort", abort, { once: true });
        source.onopen = clearFallback;
        source.onerror = scheduleFallback;
        source.addEventListener("job.progress", handleJob);
        source.addEventListener("job.succeeded", handleJob);
        source.addEventListener("job.failed", handleJob);
        source.addEventListener("heartbeat", clearFallback);
        scheduleFallback();
    });
}

function jobStreamUrl(jobId: string, token?: string) {
    const url = new URL(`${API_BASE_URL}/api/jobs/${encodeURIComponent(jobId)}/stream`);
    if (token) url.searchParams.set("access_token", token);
    return url.toString();
}

function parseSSEJob(data: string): JobRecord | null {
    try {
        const payload = JSON.parse(data) as { job?: JobRecord };
        return payload.job || null;
    } catch {
        return null;
    }
}

function delay(ms: number, signal?: AbortSignal) {
    return new Promise<void>((resolve, reject) => {
        if (signal?.aborted) {
            reject(new DOMException("Aborted", "AbortError"));
            return;
        }
        const timer = setTimeout(resolve, ms);
        signal?.addEventListener(
            "abort",
            () => {
                clearTimeout(timer);
                reject(new DOMException("Aborted", "AbortError"));
            },
            { once: true },
        );
    });
}

function isAbortError(error: unknown) {
    return error instanceof DOMException && error.name === "AbortError";
}
