import {
    ApiError as StudioApiError,
    clearAuthToken,
    getAuthToken,
    request,
    setAuthToken,
    type ApiEnvelope,
} from "../../../../../services/api/request";

export type { ApiEnvelope };

export class ApiError extends Error {
    readonly status: number;
    readonly requestId?: string;
    readonly data?: unknown;

    constructor(message: string, options: { status: number; requestId?: string; data?: unknown }) {
        super(message);
        this.name = "ApiError";
        this.status = options.status;
        this.requestId = options.requestId;
        this.data = options.data;
    }
}

export const AUTH_TOKEN_STORAGE_KEY = "ai-manju:auth_token";
export const AUTH_SESSION_STORAGE_KEY = "ai-manju:auth_session";
export const AUTH_UNAUTHORIZED_EVENT = "ai-manju:auth-unauthorized";
export const AUTH_ACCOUNT_STORAGE_KEY = "ai-manju:auth_account";

export type ApiParams = Record<string, string | string[] | number | number[] | undefined>;

export type RequestApiInit = RequestInit & {
    auth?: boolean;
    timeoutMs?: number;
};

export function compactApiParams(params: ApiParams) {
    return Object.fromEntries(Object.entries(params).filter(([, value]) => value !== "" && value !== undefined && (!Array.isArray(value) || value.length > 0))) as ApiParams;
}

export function serializeApiParams(params?: ApiParams) {
    const queryParams = new URLSearchParams();
    for (const [key, value] of Object.entries(params || {})) {
        if (value === undefined) continue;
        if (Array.isArray(value)) value.forEach((item) => queryParams.append(key, String(item)));
        else queryParams.set(key, String(value));
    }
    return queryParams;
}

export function getStoredAuthToken() {
    return getAuthToken() || "";
}

export function setStoredAuthToken(token: string, persistent = true) {
    if (token) setAuthToken(token, persistent);
}

export function clearStoredAuthToken() {
    clearAuthToken();
}

export function getStoredAuthSessionHint() {
    return Boolean(getStoredAuthToken());
}

export function setStoredAuthSessionHint(_value: boolean) {}

export function getStoredAuthAccount() {
    return localStorage.getItem(AUTH_ACCOUNT_STORAGE_KEY) || "";
}

export function setStoredAuthAccount(account?: string) {
    const value = (account || "").trim();
    if (value) localStorage.setItem(AUTH_ACCOUNT_STORAGE_KEY, value);
    else localStorage.removeItem(AUTH_ACCOUNT_STORAGE_KEY);
}

export async function requestApi<T>(path: string, init: RequestApiInit = {}): Promise<T> {
    const { auth: _auth, body, headers, timeoutMs, ...requestInit } = init;
    try {
        return await request<T>(path, {
            ...requestInit,
            body: normalizeRequestBody(body),
            headers: headersToRecord(headers),
            timeoutMs: timeoutMs ?? 0,
        });
    } catch (error) {
        if (error instanceof StudioApiError) {
            throw new ApiError(error.message, {
                status: error.status,
                requestId: error.requestId,
                data: error.details,
            });
        }
        throw error;
    }
}

function normalizeRequestBody(body: BodyInit | null | undefined) {
    if (body === undefined || body === null || body instanceof FormData) return body ?? undefined;
    if (typeof body !== "string") return body;
    try {
        return JSON.parse(body) as unknown;
    } catch {
        return body;
    }
}

function headersToRecord(headers?: HeadersInit) {
    return Object.fromEntries(new Headers(headers).entries());
}
