import { requestApi } from "@/services/api/request";

export type CanvasShortcutAction = "undo" | "redo" | "delete" | "copy" | "paste" | "selectAll" | "runSelection" | "openSettings" | "resetZoom";

export type UserGenerationPreferences = {
    imageModel: string;
    videoModel: string;
    textModel: string;
    audioModel: string;
    quality: string;
    size: string;
    count: string;
    canvasImageCount: string;
    videoSeconds: string;
    vquality: string;
    videoGenerateAudio: string;
    videoWatermark: string;
    audioVoice: string;
    audioFormat: string;
    audioSpeed: string;
    audioInstructions: string;
    systemPrompt: string;
};

export type UserCanvasPreferences = {
    middleButtonLockHint: boolean;
    backgroundMode: "lines" | "dots" | "blank";
    wheelZoomRequiresCtrl: boolean;
    promptPresets: UserPromptPreset[];
};

export type UserPromptPreset = {
    id: string;
    title: string;
    prompt: string;
    tags: string[];
    priority: UserPromptPresetPriority;
    sort_order: number;
    createdAt: string;
    updatedAt: string;
};

export type UserPromptPresetPriority = "pinned" | "high" | "normal" | "low";

export type UserPreferences = {
    generation: UserGenerationPreferences;
    shortcuts: Record<CanvasShortcutAction, string[]>;
    canvas: UserCanvasPreferences;
    updated_at?: string;
};

export type UserPreferencesPayload = Partial<{
    generation: Partial<UserGenerationPreferences>;
    shortcuts: Partial<Record<CanvasShortcutAction, string[]>>;
    canvas: Partial<UserCanvasPreferences>;
}>;

export async function fetchUserPreferences() {
    return requestApi<UserPreferences>("/api/user/preferences");
}

export async function updateUserPreferences(payload: UserPreferencesPayload) {
    return requestApi<UserPreferences>("/api/user/preferences", {
        method: "PUT",
        body: JSON.stringify(payload),
    });
}
