import { API_BASE_URL } from "@/constant/env";
import { getStoredAuthToken, requestApi } from "@/services/api/request";
import type { WorkspaceScope } from "@/stores/use-workspace-scope-store";

export type ServerAsset = {
    id: string;
    user_id: string;
    workspace_id?: string;
    scope?: WorkspaceScope;
    type: "image" | "video" | "audio";
    name: string;
    url: string;
    size: number;
    content_type?: string;
    folder_id: string;
    category: AssetCategory;
    tags: string[];
    note: string;
    source_type: AssetSourceType;
    source_project_id: string;
    source_batch_id: string;
    source_item_id: string;
    source_job_id: string;
    source_metadata: Record<string, unknown>;
    trashed_at?: string;
    trash_expires_at?: string;
    trashed_by?: string;
    created_at?: string;
    updated_at?: string;
};

export type AssetCategory = "character" | "environment" | "costume" | "prop" | "ui" | "reference" | "other";
export type AssetSourceType = "manual_upload" | "image_workbench" | "canvas" | "comic_batch" | "legacy" | "unknown";

export type AssetFolder = {
    id: string;
    workspace_id: string;
    scope?: WorkspaceScope;
    created_by: string;
    parent_id: string;
    name: string;
    kind: "system" | "user";
    system_key: string;
    source_ref_type: string;
    source_ref_id: string;
    sort_order: number;
    asset_count: number;
    descendant_asset_count: number;
    created_at: string;
    updated_at: string;
};

export type AssetLibraryQuery = {
    folderId?: string;
    includeDescendants?: boolean;
    type?: ServerAsset["type"] | "";
    category?: AssetCategory | "";
    sourceType?: AssetSourceType | "";
    sourceProjectId?: string;
    keyword?: string;
    createdFrom?: string;
    createdTo?: string;
    page?: number;
    pageSize?: number;
    sort?: "created_at_desc" | "created_at_asc" | "name_asc" | "name_desc";
};

export type AssetLibraryResult = {
    items: ServerAsset[];
    total: number;
    page: number;
    page_size: number;
};

export type AssetReference = {
    id: string;
    workspace_id: string;
    asset_id: string;
    reference_type: string;
    reference_id: string;
};

export type AssetTrashPreflight = {
    count: number;
    total_bytes: number;
    references: AssetReference[];
};

export type AssetTrashMutationResult = {
    items: ServerAsset[];
    count: number;
    total_bytes: number;
};

export type AssetExportStatus = "queued" | "running" | "succeeded" | "partial_failed" | "failed" | "canceled" | "expired";
export type AssetExportItem = {
    id: string;
    export_id: string;
    asset_id: string;
    position: number;
    status: "pending" | "succeeded" | "failed" | "canceled";
    archive_path: string;
    error: Record<string, unknown>;
};
export type AssetExportBatch = {
    id: string;
    user_id: string;
    workspace_id: string;
    scope?: WorkspaceScope;
    kind: "assets" | "canvas_fragment";
    status: AssetExportStatus;
    selection_mode: "selected" | "filter" | "folder";
    selection: Record<string, unknown>;
    total: number;
    succeeded: number;
    failed: number;
    canceled: number;
    file_name: string;
    size: number;
    error: Record<string, unknown>;
    expires_at?: string;
    created_at: string;
    updated_at: string;
    started_at?: string;
    finished_at?: string;
    items?: AssetExportItem[];
};

export type AssetExportFilter = {
    folder_id?: string;
    include_descendants?: boolean;
    type?: ServerAsset["type"] | "";
    category?: AssetCategory | "";
    source_type?: AssetSourceType | "";
    source_project_id?: string;
    keyword?: string;
    created_from?: string;
    created_to?: string;
    sort?: AssetLibraryQuery["sort"];
};

export function serverAssetStorageKey(asset: Pick<ServerAsset, "id" | "type" | "scope">, fallbackScope: WorkspaceScope = "personal") {
    return `server:${asset.scope || fallbackScope}:${asset.type}:${asset.id}`;
}

export function serverAssetIdFromStorageKey(storageKey?: string) {
    return parseServerAssetStorageKey(storageKey)?.id || "";
}

export function serverAssetScopeFromStorageKey(storageKey?: string): WorkspaceScope {
    return parseServerAssetStorageKey(storageKey)?.scope || "personal";
}

export async function listServerAssets(scope: WorkspaceScope = "personal") {
    return requestApi<ServerAsset[]>(assetPath("/api/assets", scope));
}

export function getServerAsset(scope: WorkspaceScope, assetId: string) {
    return requestApi<ServerAsset>(assetPath(`/api/assets/${encodeURIComponent(assetId)}`, scope));
}

export function serverAssetContentUrl(asset: Pick<ServerAsset, "id" | "scope">, fallbackScope: WorkspaceScope = "personal") {
    const scope = asset.scope || fallbackScope;
    return `${API_BASE_URL}${assetPath(`/api/assets/${encodeURIComponent(asset.id)}/content`, scope)}`;
}

export function serverAssetContentUrlFromStorageKey(storageKey?: string) {
    const parsed = parseServerAssetStorageKey(storageKey);
    if (!parsed) return "";
    return serverAssetContentUrl({ id: parsed.id, scope: parsed.scope }, parsed.scope);
}

export async function uploadServerAsset(
    file: Blob,
    options: {
        type: "image" | "video" | "audio";
        name?: string;
        scope?: WorkspaceScope;
        folderId?: string;
        category?: AssetCategory;
        sourceType?: AssetSourceType;
        sourceProjectId?: string;
        sourceProjectName?: string;
        sourceMetadata?: Record<string, unknown>;
        tags?: string[];
        note?: string;
    },
) {
    const body = new FormData();
    body.set("file", file, options.name || `${options.type}.${fileExtension(file.type, options.type)}`);
    body.set("type", options.type);
    if (options.name) body.set("name", options.name);
    if (options.folderId) body.set("folder_id", options.folderId);
    if (options.category) body.set("category", options.category);
    if (options.sourceType) body.set("source_type", options.sourceType);
    if (options.sourceProjectId) body.set("source_project_id", options.sourceProjectId);
    if (options.sourceProjectName) body.set("source_project_name", options.sourceProjectName);
    if (options.sourceMetadata) body.set("source_metadata", JSON.stringify(options.sourceMetadata));
    if (options.tags?.length) body.set("tags", JSON.stringify(options.tags));
    if (options.note) body.set("note", options.note);
    return requestApi<ServerAsset>(assetPath("/api/assets", options.scope || "personal"), {
        method: "POST",
        body,
    });
}

