function assetLibrarySearchParams(query: AssetLibraryQuery) {
    const params = new URLSearchParams();
    if (query.folderId) params.set("folder_id", query.folderId);
    if (query.includeDescendants) params.set("include_descendants", "true");
    if (query.type) params.set("type", query.type);
    if (query.category) params.set("category", query.category);
    if (query.sourceType) params.set("source_type", query.sourceType);
    if (query.sourceProjectId) params.set("source_project_id", query.sourceProjectId);
    if (query.keyword) params.set("keyword", query.keyword);
    if (query.createdFrom) params.set("created_from", query.createdFrom);
    if (query.createdTo) params.set("created_to", query.createdTo);
    if (query.page) params.set("page", String(query.page));
    if (query.pageSize) params.set("page_size", String(query.pageSize));
    if (query.sort) params.set("sort", query.sort);
    return params;
}

export function listAssetLibrary(scope: WorkspaceScope, query: AssetLibraryQuery = {}, options?: { signal?: AbortSignal }) {
    const params = assetLibrarySearchParams(query);
    return requestApi<AssetLibraryResult>(assetPath(`/api/assets/library${params.size ? `?${params.toString()}` : ""}`, scope), { signal: options?.signal });
}

