export async function downloadAssetExport(scope: WorkspaceScope, exportId: string) {
    const token = getStoredAuthToken();
    const headers = new Headers();
    if (token) headers.set("Authorization", `Bearer ${token}`);
    const response = await fetch(`${API_BASE_URL}${assetPath(`/api/asset-exports/${encodeURIComponent(exportId)}/content`, scope)}`, {
        credentials: "include",
        headers,
    });
    if (!response.ok) {
        const payload = await response.json().catch(() => null) as { error?: string } | null;
        throw new Error(payload?.error || `asset export download failed (${response.status})`);
    }
    return response.blob();
}

export async function downloadServerAsset(storageKey: string, scope: WorkspaceScope = serverAssetScopeFromStorageKey(storageKey)) {
    const id = serverAssetIdFromStorageKey(storageKey);
    if (!id) return null;
    const token = getStoredAuthToken();
    const headers = new Headers();
    if (token) headers.set("Authorization", `Bearer ${token}`);
    const response = await fetch(`${API_BASE_URL}${assetPath(`/api/assets/${encodeURIComponent(id)}/content`, scope)}`, {
        credentials: "include",
        headers,
    });
    if (!response.ok) return null;
    return response.blob();
}

export async function deleteServerAsset(storageKey: string, scope: WorkspaceScope = serverAssetScopeFromStorageKey(storageKey)) {
    const id = serverAssetIdFromStorageKey(storageKey);
    if (!id) return;
    await requestApi<void>(assetPath(`/api/assets/${encodeURIComponent(id)}`, scope), { method: "DELETE" });
}

function assetPath(path: string, scope: WorkspaceScope) {
    return `${path}${path.includes("?") ? "&" : "?"}scope=${encodeURIComponent(scope)}`;
}

function parseServerAssetStorageKey(storageKey?: string) {
    const scoped = storageKey?.match(/^server:(personal|team):(image|video|audio):([^:]+)$/);
    if (scoped) return { scope: scoped[1] as WorkspaceScope, type: scoped[2] as ServerAsset["type"], id: scoped[3] };
    const legacy = storageKey?.match(/^server:(image|video|audio):([^:]+)$/);
    if (legacy) return { scope: "personal" as const, type: legacy[1] as ServerAsset["type"], id: legacy[2] };
    return null;
}

function fileExtension(mimeType: string, type: "image" | "video" | "audio") {
    if (mimeType.includes("png")) return "png";
    if (mimeType.includes("jpeg")) return "jpg";
    if (mimeType.includes("webp")) return "webp";
    if (mimeType.includes("gif")) return "gif";
    if (mimeType.includes("mp4")) return "mp4";
    if (mimeType.includes("webm")) return "webm";
    if (mimeType.includes("wav")) return "wav";
    if (mimeType.includes("mpeg") || mimeType.includes("mp3")) return "mp3";
    if (type === "image") return "png";
    if (type === "video") return "mp4";
    return "mp3";
}
