"use client";

import type { DragEvent, RefObject } from "react";

import type { CanvasBackgroundMode } from "@/lib/canvas-theme";
import type { CanvasConnection, CanvasGroupData, CanvasNodeData, ConnectionHandle, ContextMenuState, Position, ViewportTransform } from "../types";

export type CanvasEngineKind = "dom" | "leafer";

export const CANVAS_ENGINE_STORAGE_KEY = "ai-manju.canvas.engine";

export type CanvasEngineProps = {
    containerRef: RefObject<HTMLDivElement | null>;
    nodes: CanvasNodeData[];
    connections: CanvasConnection[];
    groups: CanvasGroupData[];
    viewport: ViewportTransform;
    selectedNodeIds: Set<string>;
    selectedGroupId: string | null;
    selectedConnectionId: string | null;
    backgroundMode: CanvasBackgroundMode;
    spacePressed: boolean;
    wheelZoomRequiresCtrl?: boolean;
    middleButtonLockHint?: boolean;
    connectingParams: ConnectionHandle | null;
    connectionTargetNodeId: string | null;
    mouseWorld: Position;
    onViewportChange: (viewport: ViewportTransform) => void;
    onSelectionChange: (nodeIds: Set<string>, groupId?: string | null, connectionId?: string | null) => void;
    onNodePatch: (nodeId: string, patch: Partial<Pick<CanvasNodeData, "position" | "width" | "height">>) => void;
    onGroupPatch: (groupId: string, patch: Partial<Pick<CanvasGroupData, "position" | "width" | "height">>) => void;
    onConnectionCreate: (connection: ConnectionHandle, targetNodeId: string) => void;
    onConnectionDelete: (connectionId: string) => void;
    onCanvasDoubleClick: (position: Position) => void;
    onNodeDoubleClick: (node: CanvasNodeData) => void;
    onContextMenu: (state: ContextMenuState | null) => void;
    onConnectStart: (connection: ConnectionHandle, position: Position) => void;
    onConnectMove: (position: Position, targetNodeId: string | null) => void;
    onConnectEnd: (position: Position, targetNodeId: string | null, isNearNode: boolean) => void;
    onInteractionStart: () => void;
    onInteractionEnd: (changed: boolean) => void;
    onNodeHoverChange?: (nodeId: string | null) => void;
    onDrop?: (event: DragEvent<HTMLDivElement>) => void;
};

export function normalizeCanvasEngineKind(value: string | null | undefined): CanvasEngineKind | null {
    return value === "leafer" || value === "dom" ? value : null;
}

export function defaultCanvasEngineKind(): CanvasEngineKind {
    return normalizeCanvasEngineKind(process.env.NEXT_PUBLIC_CANVAS_ENGINE) || "dom";
}

export function resolveCanvasEngineKind(searchParams?: URLSearchParams | null): CanvasEngineKind {
    const envDefault = defaultCanvasEngineKind();
    if (typeof window === "undefined") return envDefault;

    const queryEngine = normalizeCanvasEngineKind(searchParams?.get("engine"));
    if (queryEngine) {
        window.localStorage.setItem(CANVAS_ENGINE_STORAGE_KEY, queryEngine);
        return queryEngine;
    }

    return normalizeCanvasEngineKind(window.localStorage.getItem(CANVAS_ENGINE_STORAGE_KEY)) || envDefault;
}
