import { create } from "zustand";
import type { AuthUser } from "@/services/api";

export type UserRole = "super_admin" | "member";

export type LocalUser = {
    id: string;
    username: string;
    displayName: string;
    role: UserRole;
    status?: "active" | "disabled";
    avatarUrl?: string;
};

type UserStore = {
    user: LocalUser | null;
    isHydrating: boolean;
    setAuthState: (user: AuthUser | null, isHydrating: boolean) => void;
};

export const useUserStore = create<UserStore>()((set) => ({
    user: null,
    isHydrating: true,
    setAuthState: (user, isHydrating) => set({ user: toLocalUser(user), isHydrating }),
}));

function toLocalUser(user: AuthUser | null): LocalUser | null {
    if (!user) return null;
    return {
        id: user.id,
        username: user.username,
        displayName: user.display_name || user.username,
        role: user.role,
        status: user.status === "disabled" ? "disabled" : "active",
    };
}
