"use client";

import { create } from "zustand";
import { persist, type PersistStorage, type StorageValue } from "zustand/middleware";

import { nanoid } from "nanoid";
import { localForageStorage } from "@/lib/localforage-storage";
import { LEGACY_ASSET_STORE_KEY, currentUserStorageScope, markLegacyLocalDataMigrated, scopedAssetStoreKey, setCurrentUserStorageScope, shouldMigrateLegacyLocalData } from "@/services/user-scoped-storage";
import { cleanupUnusedImages, resolveImageUrl, uploadImage } from "@/services/image-storage";
import { cleanupUnusedMedia, resolveMediaUrl } from "@/services/file-storage";
import { serverAssetContentUrlFromStorageKey } from "@/services/api/assets";
import type { LocalUser } from "@/stores/use-user-store";

export type AssetKind = "text" | "image" | "video";
export type TextAsset = AssetBase<"text"> & { data: { content: string } };
export type ImageAsset = AssetBase<"image"> & { data: { dataUrl: string; storageKey?: string; width: number; height: number; bytes: number; mimeType: string } };
export type VideoAsset = AssetBase<"video"> & { data: { url: string; storageKey?: string; width: number; height: number; bytes: number; mimeType: string } };
export type Asset = TextAsset | ImageAsset | VideoAsset;

type AssetBase<T extends AssetKind> = {
    id: string;
    kind: T;
    title: string;
    coverUrl: string;
    tags: string[];
    source?: string;
    note?: string;
    createdAt: string;
    updatedAt: string;
    metadata?: Record<string, unknown>;
};

type AssetStore = {
    hydrated: boolean;
    assets: Asset[];
    addAsset: (asset: Omit<Asset, "id" | "createdAt" | "updatedAt">) => string;
    updateAsset: (id: string, patch: Partial<Omit<Asset, "id" | "createdAt">>) => void;
    removeAsset: (id: string) => void;
    replaceAssets: (assets: Asset[]) => void;
    switchUserScope: (user: LocalUser | null) => Promise<void>;
    cleanupImages: (extra?: unknown) => void;
};

const assetStorage: PersistStorage<AssetStore> = {
    getItem: async (name) => {
        const value = await localForageStorage.getItem(name);
        if (!value) return null;
        const parsed = JSON.parse(value) as StorageValue<AssetStore>;
        parsed.state.assets = await Promise.all(
            parsed.state.assets.map(async (asset) => {
                if (asset.kind === "video") {
                    const storageKey = asset.data.storageKey || (isMediaStorageKey(asset.data.url) ? asset.data.url : "");
                    const serverUrl = serverAssetContentUrlFromStorageKey(storageKey);
                    if (serverUrl) {
                        return {
                            ...asset,
                            coverUrl: asset.coverUrl.startsWith("blob:") || isMediaStorageKey(asset.coverUrl) ? "" : asset.coverUrl,
                            data: { ...asset.data, storageKey, url: serverUrl },
                        };
                    }
                    if (storageKey) return { ...asset, coverUrl: asset.coverUrl.startsWith("blob:") ? await resolveMediaUrl(storageKey, isMediaStorageKey(asset.coverUrl) ? "" : asset.coverUrl) : asset.coverUrl, data: { ...asset.data, storageKey, url: await resolveMediaUrl(storageKey, isMediaStorageKey(asset.data.url) ? "" : asset.data.url) } };
                    return asset;
                }
                if (asset.kind !== "image") return asset;
                const storageKey = asset.data.storageKey || (isImageStorageKey(asset.data.dataUrl) ? asset.data.dataUrl : "");
                const serverUrl = serverAssetContentUrlFromStorageKey(storageKey);
                if (serverUrl)
                    return {
                        ...asset,
                        coverUrl: serverUrl,
                        data: { ...asset.data, storageKey, dataUrl: serverUrl },
                    };
                if (storageKey)
                    return {
                        ...asset,
                        coverUrl: asset.coverUrl.startsWith("blob:") || isImageStorageKey(asset.coverUrl) ? await resolveImageUrl(storageKey, isImageStorageKey(asset.coverUrl) ? "" : asset.coverUrl) : asset.coverUrl,
                        data: { ...asset.data, storageKey, dataUrl: await resolveImageUrl(storageKey, isImageStorageKey(asset.data.dataUrl) ? "" : asset.data.dataUrl) },
                    };
                if (!asset.data.dataUrl.startsWith("data:image/")) return asset;
                const image = await uploadImage(asset.data.dataUrl);
                return { ...asset, coverUrl: asset.coverUrl.startsWith("data:image/") ? image.url : asset.coverUrl, data: { ...asset.data, dataUrl: image.url, storageKey: image.storageKey, bytes: image.bytes, mimeType: image.mimeType } };
            }),
        );
        return parsed;
    },
    setItem: (name, value) => localForageStorage.setItem(name, JSON.stringify(value)),
    removeItem: (name) => localForageStorage.removeItem(name),
};

export const useAssetStore = create<AssetStore>()(
    persist(
        (set, get) => ({
            hydrated: false,
            assets: [],
            addAsset: (asset) => {
                const now = new Date().toISOString();
                const id = nanoid();
                set((state) => ({ assets: [{ ...asset, id, createdAt: now, updatedAt: now } as Asset, ...state.assets] }));
                return id;
            },
            updateAsset: (id, patch) =>
                set((state) => ({
                    assets: state.assets.map((asset) => (asset.id === id ? ({ ...asset, ...patch, updatedAt: new Date().toISOString() } as Asset) : asset)),
                })),
            removeAsset: (id) =>
                set((state) => {
                    const assets = state.assets.filter((asset) => asset.id !== id);
                    get().cleanupImages({ assets });
                    return { assets };
                }),
            replaceAssets: (assets) => set({ assets }),
            switchUserScope: async (user) => {
                const nextKey = scopedAssetStoreKey(user?.id);
                if (useAssetStore.persist.getOptions().name === nextKey && get().hydrated) return;
                setCurrentUserStorageScope(user?.id);
                useAssetStore.persist.setOptions({ name: scopedAssetStoreKey(currentUserStorageScope()) });
                set({ hydrated: false, assets: [] });
                await migrateLegacyAssetStoreForAdmin(user);
                await useAssetStore.persist.rehydrate();
            },
            cleanupImages: (extra) => {
                window.setTimeout(async () => {
                    const { useCanvasStore } = await import("@/app/(user)/canvas/stores/use-canvas-store");
                    await cleanupUnusedImages({ assets: get().assets, projects: useCanvasStore.getState().projects, extra });
                    await cleanupUnusedMedia({ assets: get().assets, projects: useCanvasStore.getState().projects, extra });
                }, 0);
            },
        }),
        {
            name: scopedAssetStoreKey(),
            storage: assetStorage,
            partialize: (state) => ({ assets: state.assets }) as StorageValue<AssetStore>["state"],
            onRehydrateStorage: () => () => {
                useAssetStore.setState({ hydrated: true });
            },
        },
    ),
);

async function migrateLegacyAssetStoreForAdmin(user: LocalUser | null) {
    if (!shouldMigrateLegacyLocalData(user, "asset")) return;
    const [legacyValue, scopedValue] = await Promise.all([localForageStorage.getItem(LEGACY_ASSET_STORE_KEY), localForageStorage.getItem(scopedAssetStoreKey(user!.id))]);
    if (legacyValue && !scopedValue) {
        await localForageStorage.setItem(scopedAssetStoreKey(user!.id), legacyValue);
    }
    markLegacyLocalDataMigrated(user!.id, "asset");
}

function isImageStorageKey(value: string) {
    return value.startsWith("image:") || value.startsWith("server:image:") || value.startsWith("server:personal:image:") || value.startsWith("server:team:image:");
}

function isMediaStorageKey(value: string) {
    return value.startsWith("video:") || value.startsWith("audio:") || value.startsWith("server:video:") || value.startsWith("server:audio:") || value.startsWith("server:personal:video:") || value.startsWith("server:team:video:") || value.startsWith("server:personal:audio:") || value.startsWith("server:team:audio:");
}
