export function createProductionCanvasScopeSwitchQueue() {
    let queue = Promise.resolve();

    return (task: () => Promise<void>) => {
        const next = queue.catch(() => undefined).then(task);
        queue = next.catch(() => undefined);
        return next;
    };
}

export const enqueueProductionCanvasScopeSwitch = createProductionCanvasScopeSwitchQueue();
