import type { ServerProject } from "@/services/api/project-canvas";
import { applyServerSyncMeta } from "@/services/api/project-canvas";
import type { CanvasProject } from "../stores/use-canvas-store";

const initialViewport = { x: 0, y: 0, k: 1 };

export function hydrateProjectFromServer(serverProject: ServerProject): CanvasProject | null {
    const data = serverProject.data;
    const id = typeof data?.id === "string" && data.id ? data.id : serverProject.id;
    const createdAt = typeof data?.createdAt === "string" && data.createdAt ? data.createdAt : serverProject.created_at;
    const updatedAt = typeof data?.updatedAt === "string" && data.updatedAt ? data.updatedAt : serverProject.updated_at;
    const scope = serverProject.scope || (serverProject.workspace_id === "team:default" ? "team" : "personal");
    if (!id || !createdAt || !updatedAt) return null;

    return applyServerSyncMeta(
        {
            id,
            title: (typeof data?.title === "string" && data.title) || serverProject.title || "未命名画布",
            createdAt,
            updatedAt,
            nodes: data?.nodes || [],
            connections: data?.connections || [],
            groups: data?.groups || [],
            chatSessions: data?.chatSessions || [],
            activeChatId: data?.activeChatId || null,
            backgroundMode: data?.backgroundMode || "lines",
            showImageInfo: data?.showImageInfo || false,
            viewport: data?.viewport || initialViewport,
            serverProjectId: serverProject.id,
            workspaceId: serverProject.workspace_id || data?.workspaceId,
            scope,
            snapshotVersion: data?.snapshotVersion,
        },
        serverProject,
    );
}

export function serverSyncMetaFromProject(serverProject: ServerProject): Pick<CanvasProject, "serverProjectId" | "workspaceId" | "scope" | "snapshotVersion" | "lastSyncAt" | "syncStatus"> {
    return {
        serverProjectId: serverProject.id,
        workspaceId: serverProject.workspace_id,
        scope: serverProject.scope || (serverProject.workspace_id === "team:default" ? "team" : "personal"),
        snapshotVersion: serverProject.data?.snapshotVersion,
        lastSyncAt: serverProject.updated_at,
        syncStatus: "synced",
    };
}
