"use client";

import { useEffect, useState } from "react";
import { App, Input, Modal, Segmented } from "antd";

import { useWorkspaceScopeStore, type WorkspaceScope } from "@/stores/use-workspace-scope-store";
import { createCanvasProjectAndSync, suggestedCanvasProjectTitle } from "../utils/canvas-project-create";

export function CanvasCreateProjectDialog({
    open,
    defaultScope,
    initialTitle,
    onCancel,
    onCreated,
}: {
    open: boolean;
    defaultScope: WorkspaceScope;
    initialTitle?: string;
    onCancel: () => void;
    onCreated: (id: string, scope: WorkspaceScope) => void;
}) {
    const { message } = App.useApp();
    const setWorkspaceScope = useWorkspaceScopeStore((state) => state.setScope);
    const [scope, setScope] = useState<WorkspaceScope>(defaultScope);
    const [title, setTitle] = useState("");
    const [submitting, setSubmitting] = useState(false);
    const [titleTouched, setTitleTouched] = useState(false);

    useEffect(() => {
        if (!open) return;
        setScope(defaultScope);
        setTitle(initialTitle?.trim() || suggestedCanvasProjectTitle(defaultScope));
        setTitleTouched(Boolean(initialTitle?.trim()));
        setSubmitting(false);
    }, [defaultScope, initialTitle, open]);

    const changeScope = (next: WorkspaceScope) => {
        setScope(next);
        if (!titleTouched) setTitle(suggestedCanvasProjectTitle(next));
    };

    const submit = async () => {
        const normalizedTitle = title.trim();
        if (!normalizedTitle) {
            message.warning("请输入画布名称");
            return;
        }
        setSubmitting(true);
        try {
            const result = await createCanvasProjectAndSync({ title: normalizedTitle, scope });
            setWorkspaceScope(scope);
            if (result.syncError) message.warning(`本地画布已创建，服务端注册失败：${result.syncError.message}`);
            else message.success("画布已创建");
            onCreated(result.id, scope);
        } catch (error) {
            message.error(error instanceof Error ? error.message : "画布创建失败");
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <Modal title="新建分镜画布" open={open} onCancel={onCancel} onOk={() => void submit()} okText="创建并进入" cancelText="取消" confirmLoading={submitting} destroyOnHidden>
            <div className="space-y-4 pt-2" data-testid="canvas-create-dialog">
                <div>
                    <div className="mb-2 text-sm font-medium">工作空间</div>
                    <Segmented
                        block
                        value={scope}
                        options={[
                            { label: "个人空间", value: "personal" },
                            { label: "团队空间", value: "team" },
                        ]}
                        onChange={(value) => changeScope(value as WorkspaceScope)}
                        data-testid="canvas-create-scope"
                    />
                </div>
                <div>
                    <div className="mb-2 text-sm font-medium">画布名称</div>
                    <Input
                        autoFocus
                        value={title}
                        maxLength={120}
                        placeholder="例如：第一集分镜"
                        data-testid="canvas-create-title"
                        onChange={(event) => {
                            setTitle(event.target.value);
                            setTitleTouched(true);
                        }}
                        onPressEnter={() => void submit()}
                    />
                </div>
                <p className="text-xs opacity-60">服务端暂时不可用时仍会保留本地画布，并标记为待同步。</p>
            </div>
        </Modal>
    );
}
