"use client";

import localforage from "localforage";

import { nanoid } from "nanoid";
import { ensureImageDataUrlMimeType, imageDataUrlMimeType, normalizeImageMimeType, readImageMeta } from "@/lib/image-utils";
import { downloadServerAsset, serverAssetStorageKey, uploadServerAsset, type AssetCategory, type AssetSourceType } from "@/services/api/assets";
import { useWorkspaceScopeStore, type WorkspaceScope } from "@/stores/use-workspace-scope-store";

export type UploadedImage = {
    url: string;
    storageKey: string;
    width: number;
    height: number;
    bytes: number;
    mimeType: string;
};

const store = localforage.createInstance({ name: "infinite-canvas", storeName: "image_files" });
const objectUrls = new Map<string, string>();

export async function uploadImage(
    input: string | Blob,
    options?: {
        scope?: WorkspaceScope;
        name?: string;
        folderId?: string;
        category?: AssetCategory;
        sourceType?: AssetSourceType;
        sourceProjectId?: string;
        sourceProjectName?: string;
        sourceMetadata?: Record<string, unknown>;
    },
): Promise<UploadedImage> {
    const normalizedInput = typeof input === "string" ? ensureImageDataUrlMimeType(input) : input;
    const blob = typeof normalizedInput === "string" ? await (await fetch(normalizedInput)).blob() : normalizedInput;
    const scope = options?.scope || useWorkspaceScopeStore.getState().scope;
    const serverAsset = await uploadServerAsset(blob, {
        type: "image",
        scope,
        name: options?.name,
        folderId: options?.folderId,
        category: options?.category,
        sourceType: options?.sourceType,
        sourceProjectId: options?.sourceProjectId,
        sourceProjectName: options?.sourceProjectName,
        sourceMetadata: options?.sourceMetadata,
    }).catch(() => null);
    const storageKey = serverAsset ? serverAssetStorageKey(serverAsset, scope) : `image:${nanoid()}`;
    await store.setItem(storageKey, blob);
    revokeCachedObjectUrl(storageKey);
    const url = URL.createObjectURL(blob);
    objectUrls.set(storageKey, url);
    const meta = await readImageMeta(url);
    const inputMimeType = typeof normalizedInput === "string" ? imageDataUrlMimeType(normalizedInput, blob.type) : undefined;
    return { url, storageKey, width: meta.width, height: meta.height, bytes: blob.size, mimeType: normalizeImageMimeType(inputMimeType, blob.type, meta.mimeType) };
}

// Reuse a Worker-registered server Asset when the browser has not changed the
// pixels. Only client-side crops/resizes should call uploadImage again.
export async function reuseGeneratedImage(
    image: { dataUrl: string; storageKey?: string },
    renderedDataUrl: string = image.dataUrl,
    options?: Parameters<typeof uploadImage>[1],
): Promise<UploadedImage> {
    if (!image.storageKey || !image.storageKey.startsWith("server:") || renderedDataUrl !== image.dataUrl) {
        return uploadImage(renderedDataUrl, options);
    }
    const blob = await (await fetch(image.dataUrl)).blob();
    const url = await setImageBlob(image.storageKey, blob);
    const meta = await readImageMeta(url);
    return {
        url,
        storageKey: image.storageKey,
        width: meta.width,
        height: meta.height,
        bytes: blob.size,
        mimeType: normalizeImageMimeType(imageDataUrlMimeType(image.dataUrl, blob.type), blob.type, meta.mimeType),
    };
}

export async function resolveImageUrl(storageKey?: string, fallback = "") {
    if (!storageKey) return fallback;
    const cached = objectUrls.get(storageKey);
    if (cached) return cached;
    let blob = await store.getItem<Blob>(storageKey);
    if (!blob && storageKey.startsWith("server:")) {
        blob = await downloadServerAsset(storageKey);
        if (blob) await store.setItem(storageKey, blob);
    }
    if (!blob) return fallback;
    const url = URL.createObjectURL(blob);
    objectUrls.set(storageKey, url);
    return url;
}

export async function getImageBlob(storageKey: string) {
    const blob = await store.getItem<Blob>(storageKey);
    if (blob) return blob;
    if (!storageKey.startsWith("server:")) return null;
    const downloaded = await downloadServerAsset(storageKey);
    if (downloaded) await store.setItem(storageKey, downloaded);
    return downloaded;
}

export async function refreshImageBlob(storageKey: string) {
    if (!storageKey.startsWith("server:")) return null;
    const downloaded = await downloadServerAsset(storageKey);
    if (!downloaded) return null;
    await store.setItem(storageKey, downloaded);
    revokeCachedObjectUrl(storageKey);
    return downloaded;
}

export async function setImageBlob(storageKey: string, blob: Blob) {
    await store.setItem(storageKey, blob);
    revokeCachedObjectUrl(storageKey);
    const url = URL.createObjectURL(blob);
    objectUrls.set(storageKey, url);
    return url;
}

export async function clearLocalImageCache() {
    for (const url of objectUrls.values()) {
        try {
            URL.revokeObjectURL(url);
        } catch {
            // Best-effort cleanup; stale object URLs should not block logout.
        }
    }
    objectUrls.clear();
    await store.clear();
}

export async function imageToDataUrl(image: { url?: string; dataUrl?: string; storageKey?: string; type?: string }) {
    const fallback = image.dataUrl || image.url || "";
    const storageKey = image.storageKey || (isImageStorageKey(fallback) ? fallback : "");
    const url = storageKey ? await resolveImageUrl(storageKey, isImageStorageKey(fallback) ? "" : fallback) : fallback;
    if (!url) return url;
    if (/^[a-z]+:[^/]/i.test(url) && !url.startsWith("data:") && !url.startsWith("blob:")) return "";
    if (url.startsWith("data:")) return ensureImageDataUrlMimeType(url, image.type);
    return blobToDataUrl(await (await fetch(url)).blob(), image.type);
}

export async function deleteStoredImages(keys: Iterable<string>) {
    await Promise.all(
        Array.from(new Set(keys)).map(async (key) => {
            const url = objectUrls.get(key);
            if (url) URL.revokeObjectURL(url);
            objectUrls.delete(key);
            await store.removeItem(key);
        }),
    );
}

export async function cleanupUnusedImages(usedData: unknown) {
    const usedKeys = collectImageStorageKeys(usedData);
    const unused: string[] = [];
    await store.iterate((_value, key) => {
        if (!usedKeys.has(key)) unused.push(key);
    });
    await deleteStoredImages(unused);
}

export function collectImageStorageKeys(value: unknown, keys = new Set<string>()) {
    if (!value || typeof value !== "object") return keys;
    if ("storageKey" in value && typeof value.storageKey === "string" && isImageStorageKey(value.storageKey)) keys.add(value.storageKey);
    Object.values(value).forEach((item) => (Array.isArray(item) ? item.forEach((child) => collectImageStorageKeys(child, keys)) : collectImageStorageKeys(item, keys)));
    return keys;
}

function isImageStorageKey(value: string) {
    return value.startsWith("image:") || value.startsWith("server:image:") || value.startsWith("server:personal:image:") || value.startsWith("server:team:image:");
}

function revokeCachedObjectUrl(storageKey: string) {
    const previousUrl = objectUrls.get(storageKey);
    if (previousUrl) URL.revokeObjectURL(previousUrl);
    objectUrls.delete(storageKey);
}

function blobToDataUrl(blob: Blob, fallbackType?: string) {
    return new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(ensureImageDataUrlMimeType(String(reader.result || ""), fallbackType || blob.type));
        reader.onerror = () => reject(new Error("读取图片失败"));
        reader.readAsDataURL(blob);
    });
}
