"use client";

import { useEffect, useMemo, useState } from "react";
import { Button, Input, Modal, Segmented } from "antd";
import { Download } from "lucide-react";

import type { StoryboardFrame, StoryboardLayout } from "../utils/canvas-image-data";

export type StoryboardExportFrame = StoryboardFrame & {
    id: string;
};

export function CanvasStoryboardExportDialog({
    open,
    frames,
    onClose,
    onExport,
}: {
    open: boolean;
    frames: StoryboardExportFrame[];
    onClose: () => void;
    onExport: (layout: StoryboardLayout, frames: StoryboardFrame[]) => void | Promise<void>;
}) {
    const [layout, setLayout] = useState<StoryboardLayout>("grid-2x2");
    const [notes, setNotes] = useState<Record<string, string>>({});
    const visibleFrames = useMemo(() => frames.slice(0, layout === "grid-3x3" ? 9 : layout === "grid-2x2" ? 4 : 6), [frames, layout]);

    useEffect(() => {
        if (!open) return;
        setLayout("grid-2x2");
        setNotes(Object.fromEntries(frames.map((frame, index) => [frame.id, frame.note || `镜头 ${index + 1}`])));
    }, [frames, open]);

    return (
        <Modal className="canvas-themed-modal" title="故事板导出" open={open} onCancel={onClose} footer={null} width={980} centered destroyOnHidden>
            <div className="space-y-4" data-testid="canvas-storyboard-export-dialog">
                <div className="flex flex-wrap items-center justify-between gap-3">
                    <Segmented
                        value={layout}
                        onChange={(value) => setLayout(value as StoryboardLayout)}
                        options={[
                            { label: "2x2", value: "grid-2x2" },
                            { label: "3x3", value: "grid-3x3" },
                            { label: "横向分镜", value: "strip-horizontal" },
                            { label: "竖向故事板", value: "strip-vertical" },
                        ]}
                    />
                    <Button
                        type="primary"
                        icon={<Download className="size-4" />}
                        data-testid="canvas-storyboard-export-confirm"
                        disabled={!visibleFrames.length}
                        onClick={() => onExport(layout, visibleFrames.map((frame, index) => ({ dataUrl: frame.dataUrl, title: frame.title || `Shot ${index + 1}`, note: notes[frame.id] || "" })))}
                    >
                        导出 PNG
                    </Button>
                </div>

                <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
                    {visibleFrames.map((frame, index) => (
                        <div key={frame.id} className="rounded-lg border border-[#b84dff4d] bg-white/[0.045] p-2" data-testid="canvas-storyboard-frame">
                            <div className="aspect-video overflow-hidden rounded-md bg-black">
                                <img src={frame.dataUrl} alt="" className="h-full w-full object-contain" draggable={false} />
                            </div>
                            <div className="mt-2 text-xs font-semibold opacity-70">{frame.title || `Shot ${index + 1}`}</div>
                            <Input.TextArea className="mt-2" rows={2} value={notes[frame.id] || ""} maxLength={120} onChange={(event) => setNotes((current) => ({ ...current, [frame.id]: event.target.value }))} />
                        </div>
                    ))}
                </div>
            </div>
        </Modal>
    );
}
