"use client";

import { CanvasNodeCropDialog, type CanvasImageCropRect } from "./canvas-node-crop-dialog";

export type CanvasImageFocusRect = CanvasImageCropRect;

export function CanvasNodeFocusDialog({ dataUrl, open, onClose, onConfirm }: { dataUrl: string; open: boolean; onClose: () => void; onConfirm: (crop: CanvasImageFocusRect) => void }) {
    return (
        <CanvasNodeCropDialog
            dataUrl={dataUrl}
            open={open}
            onClose={onClose}
            onConfirm={onConfirm}
            title="聚焦提取"
            confirmLabel="提取为新节点"
            dialogTestId="canvas-image-focus-dialog"
            boxTestId="canvas-image-focus-box"
            confirmTestId="canvas-image-focus-confirm"
        />
    );
}
