"use client";

import type { ReactNode } from "react";
import { useEffect, useMemo, useState } from "react";
import { App, Button, Input, Modal, Space, Tag } from "antd";
import { Copy, ExternalLink, Plus, Search, Trash2, UserRound } from "lucide-react";

import {
    createMaterialAsset,
    createMaterialGroup,
    createRealValidateH5,
    createVisualValidateSession,
    deleteMaterialAsset,
    deleteMaterialGroup,
    ensureMaterialAssetsActive,
    getMaterialAsset,
    getMaterialGroup,
    getVisualValidateResult,
    materialAssetFromResponse,
    materialBytedToken,
    materialH5Link,
    type SeedanceMaterialAsset,
    type SeedanceMaterialResponse,
} from "@/services/api/material";

type CanvasSeedanceMaterialDialogProps = {
    open: boolean;
    selectedAssets?: SeedanceMaterialAsset[];
    onClose: () => void;
    onSelect: (asset: SeedanceMaterialAsset) => void;
    onRemove?: (assetId: string) => void;
};

const emptyPayload = "{}";

export function CanvasSeedanceMaterialDialog({ open, selectedAssets = [], onClose, onSelect, onRemove }: CanvasSeedanceMaterialDialogProps) {
    const { message } = App.useApp();
    const [validatePayload, setValidatePayload] = useState(emptyPayload);
    const [h5Payload, setH5Payload] = useState(emptyPayload);
    const [bytedToken, setBytedToken] = useState("");
    const [groupPayload, setGroupPayload] = useState(emptyPayload);
    const [assetPayload, setAssetPayload] = useState(emptyPayload);
    const [groupId, setGroupId] = useState("");
    const [assetId, setAssetId] = useState("");
    const [loadingKey, setLoadingKey] = useState("");
    const [lastResponse, setLastResponse] = useState<SeedanceMaterialResponse | null>(null);
    const [assets, setAssets] = useState<SeedanceMaterialAsset[]>([]);
    const h5Link = useMemo(() => (lastResponse ? materialH5Link(lastResponse) : ""), [lastResponse]);

    useEffect(() => {
        if (!open || !selectedAssets.length) return;
        setAssets((prev) => mergeAssets(selectedAssets, prev));
    }, [open, selectedAssets]);

    const run = async (key: string, action: () => Promise<SeedanceMaterialResponse>, success: string, onSuccess?: (result: SeedanceMaterialResponse) => void) => {
        setLoadingKey(key);
        try {
            const result = await action();
            setLastResponse(result);
            onSuccess?.(result);
            const asset = materialAssetFromResponse(result);
            if (asset) upsertAsset(asset);
            message.success(success);
        } catch (error) {
            message.error(error instanceof Error ? error.message : "素材库请求失败");
        } finally {
            setLoadingKey("");
        }
    };

    const upsertAsset = (asset: SeedanceMaterialAsset) => {
        setAssets((prev) => [asset, ...prev.filter((item) => item.id !== asset.id)]);
    };

    const copyAssetURL = async (id: string) => {
        await navigator.clipboard.writeText(`asset://${id}`);
        message.success("已复制");
    };

    const selectAsset = async (asset: SeedanceMaterialAsset) => {
        try {
            await ensureMaterialAssetsActive([asset.id]);
            onSelect({ ...asset, status: asset.status || "Active" });
            message.success("已选入视频生成");
            onClose();
        } catch (error) {
            message.error(error instanceof Error ? error.message : "素材未激活");
        }
    };

    return (
        <Modal className="canvas-themed-modal" title="Seedance 活体授权素材" open={open} width={860} centered footer={null} onCancel={onClose} destroyOnClose={false}>
            <div className="grid gap-4 text-sm md:grid-cols-[minmax(0,1fr)_280px]">
                <div className="min-w-0 space-y-4">
                    <MaterialSection title="真人授权">
                        <PayloadBox value={validatePayload} onChange={setValidatePayload} />
                        <Space wrap>
                            <Button icon={<UserRound className="size-4" />} loading={loadingKey === "validate"} onClick={() => void run("validate", () => createVisualValidateSession(parsePayload(validatePayload)), "已创建校验会话", (result) => setBytedToken(materialBytedToken(result)))}>
                                创建校验会话
                            </Button>
                            <Button icon={<ExternalLink className="size-4" />} loading={loadingKey === "h5"} onClick={() => void run("h5", () => createRealValidateH5(parsePayload(h5Payload)), "已创建授权链接")}>
                                创建授权 H5
                            </Button>
                            {h5Link ? (
                                <Button icon={<ExternalLink className="size-4" />} onClick={() => window.open(h5Link, "_blank", "noopener,noreferrer")}>
                                    打开授权
                                </Button>
                            ) : null}
                        </Space>
                        <PayloadBox value={h5Payload} onChange={setH5Payload} compact />
                        <div className="flex gap-2">
                            <Input value={bytedToken} onChange={(event) => setBytedToken(event.target.value)} placeholder="BytedToken" />
                            <Button icon={<Search className="size-4" />} loading={loadingKey === "result"} disabled={!bytedToken.trim()} onClick={() => void run("result", () => getVisualValidateResult(bytedToken.trim()), "已查询授权结果")}>
                                查询
                            </Button>
                        </div>
                    </MaterialSection>

                    <MaterialSection title="素材组">
                        <PayloadBox value={groupPayload} onChange={setGroupPayload} />
                        <Space wrap>
                            <Button icon={<Plus className="size-4" />} loading={loadingKey === "create-group"} onClick={() => void run("create-group", () => createMaterialGroup(parsePayload(groupPayload)), "已创建素材组")}>
                                创建组
                            </Button>
                            <Input className="!w-56" value={groupId} onChange={(event) => setGroupId(event.target.value)} placeholder="Group Id" />
                            <Button icon={<Search className="size-4" />} loading={loadingKey === "get-group"} onClick={() => void run("get-group", () => getMaterialGroup(groupId.trim()), "已查询素材组")}>
                                查询组
                            </Button>
                            <Button danger icon={<Trash2 className="size-4" />} loading={loadingKey === "delete-group"} onClick={() => void run("delete-group", () => deleteMaterialGroup(groupId.trim()), "已删除素材组")}>
                                删除组
                            </Button>
                        </Space>
                    </MaterialSection>

                    <MaterialSection title="素材">
                        <PayloadBox value={assetPayload} onChange={setAssetPayload} />
                        <Space wrap>
                            <Button icon={<Plus className="size-4" />} loading={loadingKey === "create-asset"} onClick={() => void run("create-asset", () => createMaterialAsset(parsePayload(assetPayload)), "已创建素材")}>
                                创建素材
                            </Button>
                            <Input className="!w-56" value={assetId} onChange={(event) => setAssetId(event.target.value)} placeholder="Asset Id" />
                            <Button icon={<Search className="size-4" />} loading={loadingKey === "get-asset"} onClick={() => void run("get-asset", () => getMaterialAsset(assetId.trim()), "已查询素材")}>
                                查询素材
                            </Button>
                            <Button danger icon={<Trash2 className="size-4" />} loading={loadingKey === "delete-asset"} onClick={() => void run("delete-asset", () => deleteMaterialAsset(assetId.trim()), "已删除素材")}>
                                删除素材
                            </Button>
                        </Space>
                    </MaterialSection>
                </div>

                <div className="min-w-0 space-y-4">
                    <MaterialSection title="可用素材">
                        <div className="max-h-64 space-y-2 overflow-y-auto pr-1">
                            {assets.length ? (
                                assets.map((asset) => (
                                    <div key={asset.id} className="rounded-md border border-black/10 p-2">
                                        <div className="flex min-w-0 items-center justify-between gap-2">
                                            <div className="min-w-0">
                                                <div className="truncate font-medium">{asset.name || asset.id}</div>
                                                <div className="truncate text-xs opacity-60">asset://{asset.id}</div>
                                            </div>
                                            <Tag color={(asset.status || "").toLowerCase() === "active" ? "green" : "orange"}>{asset.status || "Unknown"}</Tag>
                                        </div>
                                        <div className="mt-2 flex gap-2">
                                            <Button size="small" icon={<Copy className="size-3.5" />} onClick={() => void copyAssetURL(asset.id)} />
                                            <Button size="small" type="primary" onClick={() => void selectAsset(asset)}>
                                                选入生成
                                            </Button>
                                            {onRemove ? (
                                                <Button
                                                    size="small"
                                                    danger
                                                    icon={<Trash2 className="size-3.5" />}
                                                    onClick={() => {
                                                        onRemove(asset.id);
                                                        setAssets((prev) => prev.filter((item) => item.id !== asset.id));
                                                    }}
                                                />
                                            ) : null}
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="rounded-md border border-dashed border-black/15 p-3 text-xs opacity-60">查询或创建素材后会显示在这里</div>
                            )}
                        </div>
                    </MaterialSection>
                    <MaterialSection title="最近响应">
                        <pre className="max-h-72 overflow-auto rounded-md bg-black/5 p-2 text-[11px] leading-5">{lastResponse ? JSON.stringify(lastResponse, null, 2) : "{}"}</pre>
                    </MaterialSection>
                </div>
            </div>
        </Modal>
    );
}

function mergeAssets(primary: SeedanceMaterialAsset[], secondary: SeedanceMaterialAsset[]) {
    const seen = new Set<string>();
    return [...primary, ...secondary].filter((asset) => {
        if (!asset.id || seen.has(asset.id)) return false;
        seen.add(asset.id);
        return true;
    });
}

function MaterialSection({ title, children }: { title: string; children: ReactNode }) {
    return (
        <section className="space-y-2">
            <div className="text-xs font-semibold opacity-70">{title}</div>
            {children}
        </section>
    );
}

function PayloadBox({ value, onChange, compact = false }: { value: string; onChange: (value: string) => void; compact?: boolean }) {
    return <Input.TextArea value={value} onChange={(event) => onChange(event.target.value)} autoSize={{ minRows: compact ? 2 : 3, maxRows: 6 }} spellCheck={false} />;
}

function parsePayload(value: string) {
    const trimmed = value.trim();
    if (!trimmed) return {};
    const parsed = JSON.parse(trimmed) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("JSON 必须是对象");
    return parsed as Record<string, unknown>;
}
