"use client";

import React, { useEffect, useRef, useState } from "react";

import { canvasThemes, type CanvasBackgroundMode } from "@/lib/canvas-theme";
import { useThemeStore } from "@/stores/use-theme-store";
import type { ViewportTransform } from "../types";
import { createMiddlePanState, enterMiddlePanLock, nextHoldPanViewport, nextLockedPanViewport, setGlobalPanCursor, shouldEnterLockedPan, startMiddlePanHold, stopMiddlePan } from "../utils/middle-button-pan";

type InfiniteCanvasProps = {
    containerRef: React.RefObject<HTMLDivElement | null>;
    viewport: ViewportTransform;
    backgroundMode?: CanvasBackgroundMode;
    spacePressed?: boolean;
    wheelZoomRequiresCtrl?: boolean;
    middleButtonLockHint?: boolean;
    onViewportChange: (viewport: ViewportTransform) => void;
    onCanvasMouseDown?: (event: React.PointerEvent<HTMLDivElement>) => void;
    onCanvasDoubleClick?: (event: React.MouseEvent<HTMLDivElement>) => void;
    onCanvasDeselect?: () => void;
    onContextMenu?: (event: React.MouseEvent) => void;
    onDrop?: (event: React.DragEvent<HTMLDivElement>) => void;
    children: React.ReactNode;
};

const MIN_SCALE = 0.05;
const MAX_SCALE = 5;

export function InfiniteCanvas({ containerRef, viewport, backgroundMode = "lines", spacePressed = false, wheelZoomRequiresCtrl = true, middleButtonLockHint = true, onViewportChange, onCanvasMouseDown, onCanvasDoubleClick, onCanvasDeselect, onContextMenu, onDrop, children }: InfiniteCanvasProps) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const panState = useRef(createMiddlePanState());
    const [panMode, setPanMode] = useState(panState.current.mode);
    const viewportRef = useRef(viewport);
    const scaleRef = useRef(viewport.k);
    const frameRef = useRef<number | null>(null);
    const nextViewportRef = useRef<ViewportTransform | null>(null);

    useEffect(() => {
        scaleRef.current = viewport.k;
        viewportRef.current = viewport;
    }, [viewport.k]);

    useEffect(() => {
        viewportRef.current = viewport;
    }, [viewport]);

    useEffect(
        () => () => {
            if (frameRef.current) cancelAnimationFrame(frameRef.current);
        },
        [],
    );

    const handleWheel = (event: React.WheelEvent<HTMLDivElement>) => {
        const target = event.target instanceof Element ? event.target : null;
        if (isCanvasUIWheelTarget(target)) {
            if (event.ctrlKey || event.metaKey) event.preventDefault();
            event.stopPropagation();
            return;
        }
        event.preventDefault();

        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) return;

        if (!wheelZoomRequiresCtrl || event.ctrlKey || event.metaKey) {
            const delta = -event.deltaY;
            const factor = Math.pow(1.1, delta / 100);
            const newScale = Math.min(Math.max(viewport.k * factor, MIN_SCALE), MAX_SCALE);
            const mouseX = event.clientX - rect.left;
            const mouseY = event.clientY - rect.top;
            const worldX = (mouseX - viewport.x) / viewport.k;
            const worldY = (mouseY - viewport.y) / viewport.k;

            onViewportChange({
                x: mouseX - worldX * newScale,
                y: mouseY - worldY * newScale,
                k: newScale,
            });
            return;
        }

        onViewportChange({
            x: viewport.x - event.deltaX,
            y: viewport.y - event.deltaY,
            k: viewport.k,
        });
    };

    const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
        const target = event.target instanceof Element ? event.target : null;
        if (target?.closest("[data-canvas-no-zoom]")) return;
        if (target?.closest("[data-connection-create-menu]")) return;
        const isBackgroundClick = !target?.closest("[data-node-id],[data-group-id],[data-connection-id]");

        const shouldPan = event.button === 1 || (event.button === 0 && spacePressed);
        if (shouldPan) {
            event.preventDefault();
            event.currentTarget.setPointerCapture(event.pointerId);
            if (event.button === 1 && panState.current.mode === "locked-pan") {
                stopMiddlePan(panState.current);
                setPanMode("idle");
                setGlobalPanCursor(false);
                return;
            }
            if (event.button === 1 && shouldEnterLockedPan(panState.current)) {
                enterMiddlePanLock(panState.current, event.clientX, event.clientY, viewportRef.current);
            } else {
                startMiddlePanHold(panState.current, event.clientX, event.clientY, viewportRef.current);
            }
            setPanMode(panState.current.mode);
            setGlobalPanCursor(true);
            return;
        }

        if (event.button === 0 && isBackgroundClick) {
            event.preventDefault();
            event.currentTarget.setPointerCapture(event.pointerId);
            onCanvasMouseDown?.(event);
        }
    };

    const handleDoubleClick = (event: React.MouseEvent<HTMLDivElement>) => {
        const target = event.target instanceof Element ? event.target : null;
        if (target?.closest("[data-canvas-no-zoom],.ant-modal,.ant-popover,.ant-dropdown,.ant-select-dropdown,.ant-picker-dropdown")) return;
        if (target?.closest("[data-node-id],[data-group-id],[data-connection-id],[data-connection-create-menu]")) return;
        event.preventDefault();
        onCanvasDoubleClick?.(event);
    };

    useEffect(() => {
        const handlePointerMove = (event: PointerEvent) => {
            if (panState.current.mode === "idle") return;

            nextViewportRef.current =
                panState.current.mode === "locked-pan"
                    ? nextLockedPanViewport(panState.current, event.clientX, event.clientY, viewportRef.current)
                    : nextHoldPanViewport(panState.current, event.clientX, event.clientY, scaleRef.current);
            if (frameRef.current) return;
            frameRef.current = requestAnimationFrame(() => {
                frameRef.current = null;
                if (nextViewportRef.current) {
                    viewportRef.current = nextViewportRef.current;
                    onViewportChange(nextViewportRef.current);
                }
            });
        };

        const handlePointerUp = () => {
            if (panState.current.mode !== "hold-pan") return;

            stopMiddlePan(panState.current);
            setPanMode("idle");
            setGlobalPanCursor(false);
        };

        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key !== "Escape" || panState.current.mode !== "locked-pan") return;
            stopMiddlePan(panState.current);
            setPanMode("idle");
            setGlobalPanCursor(false);
        };

        window.addEventListener("pointermove", handlePointerMove);
        window.addEventListener("pointerup", handlePointerUp);
        window.addEventListener("keydown", handleKeyDown);
        return () => {
            window.removeEventListener("pointermove", handlePointerMove);
            window.removeEventListener("pointerup", handlePointerUp);
            window.removeEventListener("keydown", handleKeyDown);
        };
    }, [onCanvasDeselect, onViewportChange]);

    useEffect(() => {
        const container = containerRef.current;
        if (!container) return;

        const preventWheelScroll = (event: WheelEvent) => {
            const target = event.target instanceof Element ? event.target : null;
            if (isCanvasUIWheelTarget(target)) {
                if (event.ctrlKey || event.metaKey) event.preventDefault();
                return;
            }
            event.preventDefault();
        };
        container.addEventListener("wheel", preventWheelScroll, { passive: false });
        return () => container.removeEventListener("wheel", preventWheelScroll);
    }, [containerRef]);

    return (
        <div
            ref={containerRef}
            data-canvas-engine="dom"
            data-testid="canvas-stage"
            className="relative h-full w-full cursor-default select-none overflow-hidden"
            style={{ background: theme.canvas.background }}
            onPointerDown={handlePointerDown}
            onDoubleClick={handleDoubleClick}
            onAuxClick={(event) => {
                if (event.button === 1) event.preventDefault();
            }}
            onWheel={handleWheel}
            onContextMenu={onContextMenu}
            onDragOver={(event) => event.preventDefault()}
            onDrop={onDrop}
        >
            {panMode === "locked-pan" && middleButtonLockHint ? (
                <div className="pointer-events-none absolute left-1/2 top-20 z-[80] -translate-x-1/2 rounded-full border px-3 py-1 text-xs shadow-lg backdrop-blur" style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }}>
                    中键锁定平移
                </div>
            ) : null}
            <CanvasGrid viewport={viewport} mode={backgroundMode} />
            <div
                className="absolute origin-top-left"
                style={{
                    transform: `translate(${viewport.x}px, ${viewport.y}px) scale(${viewport.k})`,
                }}
            >
                {children}
            </div>
        </div>
    );
}

function isCanvasUIWheelTarget(target: Element | null) {
    return Boolean(target?.closest("[data-canvas-ui],[data-canvas-no-zoom],input,textarea,select,[contenteditable='true'],.ant-modal,.ant-popover,.ant-dropdown,.ant-select-dropdown,.ant-picker-dropdown"));
}

function CanvasGrid({ viewport, mode }: { viewport: ViewportTransform; mode: CanvasBackgroundMode }) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    if (mode === "blank") return null;

    const gridSize = 48 * viewport.k;
    const x = viewport.x % gridSize;
    const y = viewport.y % gridSize;
    const dotSize = viewport.k < 0.12 ? 0.8 : 1.15;
    const backgroundImage =
        mode === "dots" ? `radial-gradient(circle, ${theme.canvas.dot} ${dotSize}px, transparent ${dotSize + 0.2}px)` : `linear-gradient(${theme.canvas.line} 1px, transparent 1px), linear-gradient(90deg, ${theme.canvas.line} 1px, transparent 1px)`;

    return (
        <div
            className="pointer-events-none absolute inset-0 opacity-40"
            style={{
                backgroundImage,
                backgroundSize: `${gridSize}px ${gridSize}px`,
                backgroundPosition: `${x}px ${y}px`,
            }}
        />
    );
}
