"use client";

import { useMemo, useState } from "react";
import { App, Button, Modal } from "antd";

import { PROJECT_STORAGE_MODE } from "@/constant/env";
import { deleteServerProject } from "@/services/api/project-canvas";
import { ApiError } from "@/services/api/request";
import { useAssetStore } from "@/stores/use-asset-store";
import { useCanvasStore } from "../stores/use-canvas-store";
import { useCanvasUiStore } from "../stores/use-canvas-ui-store";

export function CanvasDeleteProjectsDialog() {
    const { message } = App.useApp();
    const ids = useCanvasUiStore((state) => state.deleteProjectIds);
    const setDeleteIds = useCanvasUiStore((state) => state.setDeleteProjectIds);
    const removeSelectedIds = useCanvasUiStore((state) => state.removeSelectedProjectIds);
    const projects = useCanvasStore((state) => state.projects);
    const deleteProjects = useCanvasStore((state) => state.deleteProjects);
    const cleanupImages = useAssetStore((state) => state.cleanupImages);
    const [deleting, setDeleting] = useState(false);
    const projectById = useMemo(() => new Map(projects.map((project) => [project.id, project])), [projects]);
    const confirm = async () => {
        if (deleting) return;
        if (PROJECT_STORAGE_MODE !== "server") {
            deleteLocalProjects(ids);
            return;
        }

        setDeleting(true);
        const deletableIds = new Set<string>();
        const failedIds: string[] = [];
        try {
            await Promise.all(
                ids.map(async (id) => {
                    const project = projectById.get(id);
                    if (!project?.serverProjectId) {
                        deletableIds.add(id);
                        return;
                    }
                    try {
                        await deleteServerProject(project.serverProjectId, project.scope || "personal");
                        deletableIds.add(id);
                    } catch (error) {
                        if (error instanceof ApiError && error.status === 404) {
                            deletableIds.add(id);
                            return;
                        }
                        failedIds.push(id);
                    }
                }),
            );

            const deletedIds = Array.from(deletableIds);
            if (deletedIds.length) deleteLocalProjects(deletedIds);
            if (failedIds.length) {
                setDeleteIds(failedIds);
                message.error("部分画布服务端删除失败，请稍后重试");
            } else {
                setDeleteIds([]);
            }
        } finally {
            setDeleting(false);
        }
    };
    const deleteLocalProjects = (deleteIds: string[]) => {
        deleteProjects(deleteIds);
        cleanupImages();
        removeSelectedIds(deleteIds);
        if (deleteIds.length === ids.length) setDeleteIds([]);
    };

    return (
        <Modal
            className="canvas-themed-modal"
            title="删除画布？"
            open={ids.length > 0}
            centered
            onCancel={() => {
                if (!deleting) setDeleteIds([]);
            }}
            footer={
                <>
                    <Button disabled={deleting} onClick={() => setDeleteIds([])}>
                        取消
                    </Button>
                    <Button danger type="primary" loading={deleting} onClick={() => void confirm()}>
                        删除
                    </Button>
                </>
            }
        >
            <p className="text-sm text-[#b6adc6]">将删除 {ids.length} 个画布，里面的节点和连线也会一起移除。</p>
        </Modal>
    );
}
