import { App as AntdApp, ConfigProvider, theme as antdTheme } from "antd";
import { useLocation } from "wouter";

import CanvasClientPage from "../vendor/canvas/[id]/canvas-client-page";
import CanvasProjectsPage from "../vendor/canvas/page";
import { ProductionCanvasBridge } from "./production-canvas-bridge";
import { useThemeStore } from "./stores/use-theme-store";

export default function ProductionCanvasView() {
    const [location] = useLocation();
    const theme = useThemeStore((state) => state.theme);
    const pathname = location.split("?")[0];
    const isProject = pathname.startsWith("/canvas/");

    return (
        <div className="production-canvas-root" data-testid="production-canvas-root">
            <ConfigProvider theme={{ algorithm: theme === "dark" ? antdTheme.darkAlgorithm : antdTheme.defaultAlgorithm }}>
                <AntdApp>
                    <ProductionCanvasBridge>{isProject ? <CanvasClientPage /> : <CanvasProjectsPage />}</ProductionCanvasBridge>
                </AntdApp>
            </ConfigProvider>
        </div>
    );
}
