import type { ReferenceImage } from "@/types/image";

const IMAGE_MIME_TYPES = new Set(["image/png", "image/jpeg", "image/webp", "image/gif"]);
export const MAX_REFERENCE_IMAGES = 11; // Conservative headroom under the upstream 15-image limit.
export const MAX_REFERENCE_TOTAL_BYTES = 37 * 1024 * 1024; // Conservative headroom under the upstream 50 MB limit.
export const IMAGE_PREPROCESS_CONCURRENCY = 3; // Keep browser decoding/compression responsive under multi-image edits.
export const IMAGE_BATCH_CONCURRENCY = 3; // Keep image batch requests bounded while still allowing parallel work.
const DEFAULT_REFERENCE_COMPRESSION = {
    maxDimension: 1536,
    quality: 0.82,
    mimeType: "image/jpeg",
};
type ResizeImageDataUrlOptions = {
    mimeType?: string;
    quality?: number;
    imageSmoothingEnabled?: boolean;
};

export function formatBytes(bytes: number) {
    if (!Number.isFinite(bytes) || bytes <= 0) {
        return "";
    }
    const units = ["B", "KB", "MB", "GB"];
    let value = bytes;
    let unitIndex = 0;
    while (value >= 1024 && unitIndex < units.length - 1) {
        value /= 1024;
        unitIndex += 1;
    }
    return `${value >= 10 || unitIndex === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[unitIndex]}`;
}

export function formatDuration(ms: number) {
    const value = Math.max(0, Math.floor(ms / 1000));
    const minutes = Math.floor(value / 60);
    const seconds = value % 60;
    return minutes ? `${minutes}分${String(seconds).padStart(2, "0")}秒` : `${seconds}秒`;
}

export function getDataUrlByteSize(dataUrl: string) {
    const base64 = dataUrl.split(",", 2)[1];
    if (!base64) {
        return 0;
    }
    const padding = base64.endsWith("==") ? 2 : base64.endsWith("=") ? 1 : 0;
    return Math.max(0, Math.floor((base64.length * 3) / 4) - padding);
}

export function readFileAsDataUrl(file: File) {
    return new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(new Error("读取图片失败"));
        reader.readAsDataURL(file);
    });
}

export function readImageMeta(dataUrl: string) {
    return new Promise<{ width: number; height: number; mimeType: string }>((resolve) => {
        const image = new Image();
        const done = () => resolve({ width: image.naturalWidth || 1024, height: image.naturalHeight || 1024, mimeType: dataUrl.match(/^data:([^;]+)/)?.[1] || "image/png" });
        image.onload = done;
        image.onerror = done;
        setTimeout(done, 3000);
        image.src = dataUrl;
    });
}

export function dataUrlToFile(image: ReferenceImage) {
    const normalizedDataUrl = ensureImageDataUrlMimeType(image.dataUrl, image.type);
    const [header, content] = normalizedDataUrl.split(",", 2);
    const headerMimeType = header.match(/data:(.*?);base64/)?.[1] || "";
    const mimeType = normalizeImageMimeType(headerMimeType, image.type, content || "");
    const binary = atob(content || "");
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) {
        bytes[index] = binary.charCodeAt(index);
    }
    return new File([bytes], image.name || "reference.png", { type: mimeType });
}

export async function compressReferenceImageForUpload(image: ReferenceImage) {
    const sourceDataUrl = ensureImageDataUrlMimeType(image.dataUrl, image.type);
    if (!sourceDataUrl.startsWith("data:image/")) return image;

    const sourceSize = getDataUrlByteSize(sourceDataUrl);
    const loaded = await loadImage(sourceDataUrl);
    const sourceWidth = loaded.naturalWidth || loaded.width;
    const sourceHeight = loaded.naturalHeight || loaded.height;
    if (!sourceWidth || !sourceHeight) return { ...image, dataUrl: sourceDataUrl, type: imageDataUrlMimeType(sourceDataUrl, image.type) };

    const scale = Math.min(1, DEFAULT_REFERENCE_COMPRESSION.maxDimension / Math.max(sourceWidth, sourceHeight));
    const width = Math.max(1, Math.round(sourceWidth * scale));
    const height = Math.max(1, Math.round(sourceHeight * scale));
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    if (!context) return { ...image, dataUrl: sourceDataUrl, type: imageDataUrlMimeType(sourceDataUrl, image.type) };
    context.drawImage(loaded, 0, 0, width, height);

    const compressedDataUrl = canvas.toDataURL(DEFAULT_REFERENCE_COMPRESSION.mimeType, DEFAULT_REFERENCE_COMPRESSION.quality);
    if (!compressedDataUrl.startsWith("data:image/")) return { ...image, dataUrl: sourceDataUrl, type: imageDataUrlMimeType(sourceDataUrl, image.type) };
    const compressedSize = getDataUrlByteSize(compressedDataUrl);
    if (sourceSize > 0 && compressedSize >= sourceSize) return { ...image, dataUrl: sourceDataUrl, type: imageDataUrlMimeType(sourceDataUrl, image.type) };

    return {
        ...image,
        name: renameImageFile(image.name, "jpg"),
        type: DEFAULT_REFERENCE_COMPRESSION.mimeType,
        dataUrl: compressedDataUrl,
    };
}

export async function resizeImageDataUrl(dataUrl: string, width: number, height: number, options: ResizeImageDataUrlOptions = {}) {
    const sourceDataUrl = ensureImageDataUrlMimeType(dataUrl, options.mimeType);
    if (!sourceDataUrl.startsWith("data:image/")) return sourceDataUrl;

    const loaded = await loadImage(sourceDataUrl);
    const targetWidth = Math.max(1, Math.round(width));
    const targetHeight = Math.max(1, Math.round(height));
    const canvas = document.createElement("canvas");
    canvas.width = targetWidth;
    canvas.height = targetHeight;
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Image resize canvas is unavailable");
    context.imageSmoothingEnabled = options.imageSmoothingEnabled ?? true;
    context.drawImage(loaded, 0, 0, targetWidth, targetHeight);
    return canvas.toDataURL(options.mimeType || imageDataUrlMimeType(sourceDataUrl), options.quality);
}

export function normalizeImageMimeType(...candidates: Array<string | undefined>) {
    for (const candidate of candidates) {
        const value = normalizeSupportedImageMimeType(candidate);
        if (IMAGE_MIME_TYPES.has(value)) return value;
    }
    for (const candidate of candidates) {
        const detected = detectImageMimeTypeFromBase64(candidate || "");
        if (detected) return detected;
    }
    return "image/png";
}

export function ensureImageDataUrlMimeType(dataUrl: string, fallbackType?: string) {
    const match = dataUrl.match(/^data:([^;,]+)?(;base64,)([\s\S]*)$/);
    if (!match) return dataUrl;
    const headerMimeType = normalizeSupportedImageMimeType(match[1]);
    const mimeType = detectImageMimeTypeFromBase64(match[3]) || headerMimeType || normalizeSupportedImageMimeType(fallbackType) || "image/png";
    if (match[1] === mimeType) return dataUrl;
    return `data:${mimeType}${match[2]}${match[3]}`;
}

export function imageDataUrlMimeType(dataUrl: string, fallbackType?: string) {
    const match = dataUrl.match(/^data:([^;,]+)?;base64,([\s\S]*)$/);
    if (!match) return normalizeImageMimeType(fallbackType);
    return normalizeImageMimeType(match[1], fallbackType, match[2]);
}

function normalizeSupportedImageMimeType(candidate?: string) {
    const value = (candidate || "").split(";")[0].trim().toLowerCase();
    if (value === "image/jpg") return "image/jpeg";
    return IMAGE_MIME_TYPES.has(value) ? value : "";
}

function detectImageMimeTypeFromBase64(base64: string) {
    const value = base64.trim().slice(0, 24);
    if (value.startsWith("iVBORw0KGgo")) return "image/png";
    if (value.startsWith("/9j/")) return "image/jpeg";
    if (value.startsWith("R0lGOD")) return "image/gif";
    if (value.startsWith("UklGR")) return "image/webp";
    return "";
}

function loadImage(dataUrl: string) {
    return new Promise<HTMLImageElement>((resolve, reject) => {
        const image = new Image();
        const timer = setTimeout(() => reject(new Error("参考图解码超时")), 8000);
        const cleanup = () => clearTimeout(timer);
        image.onload = () => {
            cleanup();
            resolve(image);
        };
        image.onerror = () => {
            cleanup();
            reject(new Error("读取参考图失败"));
        };
        image.src = dataUrl;
    });
}

function renameImageFile(name: string | undefined, extension: string) {
    const value = (name || "reference").trim() || "reference";
    return value.replace(/\.[A-Za-z0-9]+$/, "") + "." + extension;
}
