"use client";

import { Check, Download, Pencil, Trash2, X } from "lucide-react";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { App, Button, Input } from "antd";

import { useCanvasStore, type CanvasProject } from "../stores/use-canvas-store";
import { useCanvasUiStore } from "../stores/use-canvas-ui-store";
import { exportCanvasProjects } from "../utils/canvas-export";

const syncStatusMeta: Record<NonNullable<CanvasProject["syncStatus"]> | "local", { label: string; className: string }> = {
    local: { label: "本地", className: "border border-[#b84dff66] bg-[#b84dff24] text-[#d7c9ff]" },
    synced: { label: "已同步", className: "border border-[#6be35f66] bg-[#6be35f1f] text-[#b7ffab]" },
    pending: { label: "待同步", className: "border border-[#ffb33d66] bg-[#ffb33d24] text-[#ffd36b]" },
    conflict: { label: "冲突", className: "border border-[#ff536766] bg-[#ff536724] text-[#ff8797]" },
};

const canvasCovers = [
    "/comic-lab-pack/backgrounds/bg_canvas_card_neon_city.png",
    "/comic-lab-pack/backgrounds/bg_project_cover_city_runner.png",
    "/comic-lab-pack/backgrounds/bg_project_cover_rainy_street.png",
    "/comic-lab-pack/backgrounds/bg_project_thumb_neon_girl.png",
    "/comic-lab-pack/backgrounds/bg_sidebar_hero_anime_city.png",
];

export function CanvasProjectCard({ project }: { project: CanvasProject }) {
    const router = useRouter();
    const { message } = App.useApp();
    const renameProject = useCanvasStore((state) => state.renameProject);
    const selectedIds = useCanvasUiStore((state) => state.selectedProjectIds);
    const editingId = useCanvasUiStore((state) => state.editingProjectId);
    const editingTitle = useCanvasUiStore((state) => state.editingProjectTitle);
    const startEditing = useCanvasUiStore((state) => state.startEditingProject);
    const setEditingTitle = useCanvasUiStore((state) => state.setEditingProjectTitle);
    const stopEditing = useCanvasUiStore((state) => state.stopEditingProject);
    const toggleSelected = useCanvasUiStore((state) => state.toggleSelectedProjectId);
    const setDeleteIds = useCanvasUiStore((state) => state.setDeleteProjectIds);
    const editing = editingId === project.id;
    const selected = selectedIds.includes(project.id);
    const [exportStatus, setExportStatus] = useState<"idle" | "running" | "success" | "error">("idle");
    const syncStatus = project.syncStatus || (project.serverProjectId ? "pending" : "local");
    const syncMeta = syncStatusMeta[syncStatus];
    const cover = canvasCovers[Math.abs(project.id.split("").reduce((sum, char) => sum + char.charCodeAt(0), 0)) % canvasCovers.length];
    const open = () => router.push(`/canvas/${project.id}`);
    const saveTitle = () => {
        renameProject(project.id, editingTitle);
        stopEditing();
    };
    const exportProject = async () => {
        setExportStatus("running");
        try {
            const result = await exportCanvasProjects([project], project.title || "分镜画布");
            setExportStatus("success");
            message.success(`已生成导出文件 ${result.fileName}`);
        } catch (error) {
            setExportStatus("error");
            message.error(error instanceof Error ? error.message : "导出失败，请稍后重试");
        }
    };
    const stopActionEvent = (event: React.SyntheticEvent) => event.stopPropagation();

    return (
        <article
            className={`studio-card group flex min-h-72 cursor-pointer flex-col justify-between p-0 ${selected ? "ring-2 ring-fuchsia-400/70" : ""}`}
            data-testid="canvas-project-card"
            data-project-id={project.id}
            data-server-project-id={project.serverProjectId || ""}
            data-sync-status={syncStatus}
            data-snapshot-version={project.snapshotVersion ?? ""}
            onClick={() => !editing && open()}
        >
            <div className="relative h-40 overflow-hidden">
                <img src={cover} alt="" className="size-full object-cover transition duration-300 group-hover:scale-[1.035]" />
                <label className="absolute left-3 top-3 grid size-9 place-items-center rounded-xl border border-white/18 bg-black/40 shadow-[0_0_18px_rgba(157,77,255,.24)]" onClick={stopActionEvent}>
                    <input
                        type="checkbox"
                        checked={selected}
                        onChange={(event) => toggleSelected(project.id, event.target.checked)}
                        className="size-4 accent-fuchsia-500"
                        aria-label={`选择 ${project.title}`}
                    />
                </label>
                <span className="absolute bottom-3 right-3 rounded-full border border-white/15 bg-black/45 px-3 py-1 text-xs font-semibold text-white/85">打开画布</span>
            </div>
            <div className="flex items-start gap-3 p-5">
                {editing ? (
                    <Input className="min-w-0" value={editingTitle} onClick={(event) => event.stopPropagation()} onChange={(event) => setEditingTitle(event.target.value)} onKeyDown={(event) => event.key === "Enter" && saveTitle()} autoFocus />
                ) : (
                    <button
                        type="button"
                        className="min-w-0 cursor-pointer text-left"
                        onClick={(event) => {
                            event.stopPropagation();
                            open();
                        }}
                    >
                        <h2 className="studio-card-title truncate text-[18px]">{project.title}</h2>
                        <p className="mt-3 text-sm leading-6 studio-muted">
                            {project.nodes.length} 个节点 · {project.connections.length} 条连线
                        </p>
                        <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
                            <span className={`rounded-full px-2 py-0.5 font-medium ${syncMeta.className}`}>{syncMeta.label}</span>
                            {project.snapshotVersion ? <span className="studio-muted">v{project.snapshotVersion}</span> : null}
                        </div>
                    </button>
                )}
            </div>
            <div className="flex items-end justify-between gap-3 px-5 pb-5">
                <p className="text-xs studio-muted">更新于 {new Date(project.updatedAt).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" })}</p>
                <div className="flex items-center gap-2" onClick={stopActionEvent} onMouseDown={stopActionEvent} onPointerDown={stopActionEvent}>
                    {exportStatus !== "idle" ? (
                        <span className="text-xs font-medium studio-muted" data-testid="canvas-project-export-status" data-export-status={exportStatus}>
                            {exportStatus === "running" ? "导出中" : exportStatus === "success" ? "已导出" : "导出失败"}
                        </span>
                    ) : null}
                    <div className="flex items-center gap-1">
                    {editing ? (
                        <>
                            <Button type="text" size="small" shape="circle" icon={<Check className="size-4" />} onClick={saveTitle} aria-label="保存名称" />
                            <Button type="text" size="small" shape="circle" icon={<X className="size-4" />} onClick={stopEditing} aria-label="取消重命名" />
                        </>
                    ) : (
                        <>
                            <Button type="text" size="small" shape="circle" icon={<Download className="size-4" />} data-testid="canvas-project-export" data-export-status={exportStatus} loading={exportStatus === "running"} onClick={() => void exportProject()} aria-label="导出" />
                            <Button type="text" size="small" shape="circle" icon={<Pencil className="size-4" />} onClick={() => startEditing(project.id, project.title)} aria-label="重命名" />
                            <Button type="text" size="small" shape="circle" icon={<Trash2 className="size-4" />} onClick={() => setDeleteIds([project.id])} aria-label="删除" />
                        </>
                    )}
                    </div>
                </div>
            </div>
        </article>
    );
}
