"use client";

import { useEffect, useMemo, useState } from "react";
import { Button, InputNumber, Modal, Select, Slider } from "antd";
import { Minimize2 } from "lucide-react";

import { formatBytes, getDataUrlByteSize, readImageMeta } from "@/lib/image-utils";
import type { ImageCompressionFormat, ImageCompressionParams } from "../utils/canvas-image-data";

export type CanvasImageCompressionParams = ImageCompressionParams;

const DEFAULT_QUALITY = 0.82;
const DEFAULT_MAX_DIMENSION = 2048;
const DEFAULT_TARGET_KB = 1024;

export function CanvasNodeCompressDialog({
    dataUrl,
    open,
    onClose,
    onConfirm,
}: {
    dataUrl: string;
    open: boolean;
    onClose: () => void;
    onConfirm: (params: CanvasImageCompressionParams) => void;
}) {
    const [format, setFormat] = useState<ImageCompressionFormat>("image/jpeg");
    const [quality, setQuality] = useState(DEFAULT_QUALITY);
    const [maxDimension, setMaxDimension] = useState(DEFAULT_MAX_DIMENSION);
    const [targetKB, setTargetKB] = useState<number | null>(DEFAULT_TARGET_KB);
    const [image, setImage] = useState<{ width: number; height: number; mimeType: string } | null>(null);
    const sourceBytes = useMemo(() => getDataUrlByteSize(dataUrl), [dataUrl]);

    useEffect(() => {
        if (!open) return;
        setFormat("image/jpeg");
        setQuality(DEFAULT_QUALITY);
        setMaxDimension(DEFAULT_MAX_DIMENSION);
        setTargetKB(DEFAULT_TARGET_KB);
        setImage(null);
        void readImageMeta(dataUrl).then(setImage);
    }, [dataUrl, open]);

    const sourceLongEdge = Math.max(image?.width || 0, image?.height || 0);
    const effectiveLongEdge = Math.min(sourceLongEdge || maxDimension, maxDimension);
    const scale = sourceLongEdge ? effectiveLongEdge / sourceLongEdge : 1;
    const outputSize = image
        ? { width: Math.max(1, Math.round(image.width * scale)), height: Math.max(1, Math.round(image.height * scale)) }
        : null;

    return (
        <Modal className="canvas-themed-modal" title={null} open={open && Boolean(dataUrl)} onCancel={onClose} footer={null} width={820} centered destroyOnHidden>
            <div className="space-y-5" data-testid="canvas-image-compress-dialog">
                <div>
                    <h2 className="text-xl font-semibold">压缩图片</h2>
                    <p className="mt-1 text-sm opacity-60">在浏览器本地压缩并生成新的图片子节点，不覆盖原图，也不调用模型服务。</p>
                </div>
                <div className="grid gap-6 md:grid-cols-[minmax(260px,1fr)_360px]">
                    <div className="rounded-xl border border-[#b84dff4d] bg-white/[0.045] p-4">
                        <div className="grid min-h-[280px] place-items-center rounded-lg bg-black/35">
                            <img src={dataUrl} alt="" className="max-h-[320px] max-w-full rounded-lg object-contain shadow-xl" draggable={false} />
                        </div>
                        <div className="mt-3 space-y-2 text-sm">
                            <div className="flex items-center justify-between"><span className="opacity-60">源图尺寸</span><span className="font-semibold">{image ? `${image.width} × ${image.height} px` : "读取中"}</span></div>
                            <div className="flex items-center justify-between"><span className="opacity-60">源文件体积</span><span className="font-semibold">{formatBytes(sourceBytes) || "未知"}</span></div>
                        </div>
                    </div>
                    <div className="space-y-5 py-2">
                        <label className="block space-y-2">
                            <span className="font-medium opacity-75">输出格式</span>
                            <Select
                                className="w-full"
                                value={format}
                                options={[
                                    { value: "image/jpeg", label: "JPEG · 兼容性好" },
                                    { value: "image/webp", label: "WebP · 体积更小" },
                                ]}
                                onChange={setFormat}
                            />
                        </label>
                        <label className="block space-y-2">
                            <span className="font-medium opacity-75">画质 · {Math.round(quality * 100)}%</span>
                            <Slider min={30} max={95} value={Math.round(quality * 100)} onChange={(value) => setQuality(value / 100)} />
                        </label>
                        <label className="block space-y-2">
                            <span className="font-medium opacity-75">最长边</span>
                            <Select
                                className="w-full"
                                value={maxDimension}
                                options={[4096, 2560, 2048, 1536, 1024].map((value) => ({ value, label: `${value} px` }))}
                                onChange={setMaxDimension}
                            />
                        </label>
                        <label className="block space-y-2">
                            <span className="font-medium opacity-75">目标体积（KB，可选）</span>
                            <InputNumber className="w-full" min={100} max={20480} step={100} value={targetKB} onChange={(value) => setTargetKB(value)} placeholder="留空则仅按画质压缩" />
                        </label>
                        <div className="rounded-xl border border-[#b84dff4d] bg-white/[0.045] px-4 py-3 text-sm">
                            <div className="flex items-center justify-between"><span className="opacity-60">预计像素</span><span className="font-semibold">{outputSize ? `${outputSize.width} × ${outputSize.height}` : "未知"}</span></div>
                            <div className="mt-2 flex items-center justify-between"><span className="opacity-60">目标上限</span><span className="font-semibold">{targetKB ? formatBytes(targetKB * 1024) : "不限制"}</span></div>
                        </div>
                        <Button
                            type="primary"
                            size="large"
                            className="w-full"
                            icon={<Minimize2 className="size-4" />}
                            data-testid="canvas-image-compress-confirm"
                            onClick={() => onConfirm({ format, quality, maxDimension, targetBytes: targetKB ? targetKB * 1024 : undefined })}
                        >
                            生成压缩图节点
                        </Button>
                    </div>
                </div>
            </div>
        </Modal>
    );
}