"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { PointerEvent as ReactPointerEvent, WheelEvent as ReactWheelEvent } from "react";
import { Clapperboard, FileText, Image as ImageIcon, Music2, Settings2, Video } from "lucide-react";

import { canvasThemes } from "@/lib/canvas-theme";
import { useThemeStore } from "@/stores/use-theme-store";
import type { CanvasConnection, CanvasGroupData, CanvasNodeData, ConnectionHandle, Position, SelectionBox, ViewportTransform } from "../types";
import { CanvasNodeType } from "../types";
import type { CanvasEngineProps } from "./canvas-engine";
import { createMiddlePanState, enterMiddlePanLock, nextHoldPanViewport, nextLockedPanViewport, setGlobalPanCursor, shouldEnterLockedPan, startMiddlePanHold, stopMiddlePan } from "../utils/middle-button-pan";

const MIN_SCALE = 0.05;
const MAX_SCALE = 5;
const DRAG_THRESHOLD = 4;
const CONNECTION_HANDLE_RADIUS = 7;
const CONNECTION_NODE_HIT_PADDING = 32;
const CONNECTION_HANDLE_HIT_RADIUS = 40;
const GROUP_MIN_WIDTH = 260;
const GROUP_MIN_HEIGHT = 180;

type LeaferModule = typeof import("leafer-editor");
type LeaferElement = {
    x?: number;
    y?: number;
    width?: number;
    height?: number;
    scaleX?: number;
    scaleY?: number;
    fill?: unknown;
    stroke?: unknown;
    strokeWidth?: number;
    opacity?: number;
    visible?: boolean;
    path?: string;
    text?: string;
    remove?: () => void;
    destroy?: () => void;
    add?: (child: LeaferElement | LeaferElement[]) => void;
    addMany?: (...children: LeaferElement[]) => void;
    set?: (data: Record<string, unknown>) => void;
    on?: (type: string, listener: (event: unknown) => void) => void;
};
type LeaferApp = LeaferElement & {
    tree?: LeaferElement;
    destroy?: () => void;
};

type LeaferScene = {
    app: LeaferApp;
    stage: LeaferElement;
    module: LeaferModule;
};

function asLeaferElement(value: unknown): LeaferElement {
    return value as LeaferElement;
}

function asLeaferApp(value: unknown): LeaferApp {
    return value as LeaferApp;
}

type InteractionState =
    | { type: "idle" }
    | { type: "pan"; pointerId: number; startX: number; startY: number; initialViewport: ViewportTransform; moved: boolean }
    | { type: "select"; pointerId: number; box: SelectionBox }
    | {
          type: "node-drag";
          pointerId: number;
          nodeId: string;
          startX: number;
          startY: number;
          initialNodes: { id: string; x: number; y: number }[];
          selectedAtStart: Set<string>;
          moved: boolean;
      }
    | {
          type: "group-drag";
          pointerId: number;
          groupId: string;
          startX: number;
          startY: number;
          initialPosition: Position;
          initialNodes: { id: string; x: number; y: number }[];
          moved: boolean;
      }
    | {
          type: "group-resize";
          pointerId: number;
          groupId: string;
          corner: ResizeCorner;
          startX: number;
          startY: number;
          startLeft: number;
          startTop: number;
          startWidth: number;
          startHeight: number;
          moved: boolean;
      }
    | {
          type: "connect";
          pointerId: number;
          handle: ConnectionHandle;
          moved: boolean;
      };

type ResizeCorner = "top-left" | "top-right" | "bottom-left" | "bottom-right";

export function LeaferCanvasEngine(props: CanvasEngineProps) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const [leaferError, setLeaferError] = useState<string | null>(null);
    const [selectionBox, setSelectionBox] = useState<SelectionBox | null>(null);
    const sceneRef = useRef<LeaferScene | null>(null);
    const interactionRef = useRef<InteractionState>({ type: "idle" });
    const middlePanRef = useRef(createMiddlePanState());
    const [middlePanMode, setMiddlePanMode] = useState(middlePanRef.current.mode);
    const frameRef = useRef<number | null>(null);
    const latestPropsRef = useRef(props);
    const hoveredNodeIdRef = useRef<string | null>(null);

    useLayoutEffect(() => {
        latestPropsRef.current = props;
    }, [props]);

    const screenToCanvas = useCallback(
        (clientX: number, clientY: number) => {
            const rect = props.containerRef.current?.getBoundingClientRect();
            const localX = clientX - (rect?.left || 0);
            const localY = clientY - (rect?.top || 0);
            const viewport = latestPropsRef.current.viewport;
            return {
                x: (localX - viewport.x) / viewport.k,
                y: (localY - viewport.y) / viewport.k,
            };
        },
        [props.containerRef],
    );

    const nodeById = useMemo(() => new Map(props.nodes.map((node) => [node.id, node])), [props.nodes]);

    useEffect(() => {
        const container = props.containerRef.current;
        if (!container) return;
        let disposed = false;

        void import("leafer-editor")
            .then((module) => {
                if (disposed) return;
                const app = asLeaferApp(new module.App({
                    view: container,
                    editor: {},
                    wheel: { preventDefault: true },
                    pointer: { preventDefault: true, preventDefaultMenu: true },
                } as never));
                const stage = asLeaferElement(new module.Group({ x: 0, y: 0 } as never));
                const target = app.tree || app;
                target.add?.(stage);
                sceneRef.current = { app, stage, module };
                setLeaferError(null);
                renderLeaferScene(sceneRef.current, latestPropsRef.current);
            })
            .catch((error: unknown) => {
                if (disposed) return;
                setLeaferError(error instanceof Error ? error.message : "Leafer init failed");
            });

        return () => {
            disposed = true;
            if (frameRef.current) cancelAnimationFrame(frameRef.current);
            frameRef.current = null;
            sceneRef.current?.app.destroy?.();
            sceneRef.current = null;
        };
    }, [props.containerRef]);

    useEffect(() => {
        const scene = sceneRef.current;
        if (!scene) return;
        if (frameRef.current) cancelAnimationFrame(frameRef.current);
        frameRef.current = requestAnimationFrame(() => {
            frameRef.current = null;
            if (sceneRef.current) renderLeaferScene(sceneRef.current, latestPropsRef.current);
        });
    }, [props.nodes, props.connections, props.groups, props.viewport, props.selectedNodeIds, props.selectedGroupId, props.selectedConnectionId, props.backgroundMode, props.connectingParams, props.connectionTargetNodeId, props.mouseWorld, theme]);

    const getConnectionDropTarget = useCallback(
        (world: Position, current: ConnectionHandle) => {
            const scale = Math.max(latestPropsRef.current.viewport.k, MIN_SCALE);
            const padding = CONNECTION_NODE_HIT_PADDING / scale;
            const handleRadius = CONNECTION_HANDLE_HIT_RADIUS / scale;
            let isNearNode = false;
            let bestNodeId: string | null = null;
            let bestPriority = Number.POSITIVE_INFINITY;

            [...latestPropsRef.current.nodes].reverse().forEach((node) => {
                const anchor = getConnectionTargetAnchor(node, current);
                const dx = world.x - anchor.x;
                const dy = world.y - anchor.y;
                const hitsHandle = dx * dx + dy * dy <= handleRadius * handleRadius;
                const hitsInside = world.x >= node.position.x && world.x <= node.position.x + node.width && world.y >= node.position.y && world.y <= node.position.y + node.height;
                const hitsExpanded = world.x >= node.position.x - padding && world.x <= node.position.x + node.width + padding && world.y >= node.position.y - padding && world.y <= node.position.y + node.height + padding;

                if (!hitsHandle && !hitsInside && !hitsExpanded) return;
                isNearNode = true;
                if (node.id === current.nodeId) return;

                const priority = hitsInside ? 0 : hitsHandle ? 1 : 2;
                if (priority < bestPriority) {
                    bestNodeId = node.id;
                    bestPriority = priority;
                }
            });

            return { nodeId: bestNodeId, isNearNode };
        },
        [],
    );

    const finishInteraction = useCallback(
        (changed: boolean) => {
            const state = interactionRef.current;
            interactionRef.current = { type: "idle" };
            if (state.type === "node-drag" || state.type === "group-drag" || state.type === "group-resize") {
                latestPropsRef.current.onInteractionEnd(changed);
            }
            setSelectionBox(null);
            document.body.style.cursor = "default";
        },
        [],
    );

    useEffect(() => {
        const handleGlobalMove = (event: PointerEvent) => {
            if (middlePanRef.current.mode !== "locked-pan") return;
            latestPropsRef.current.onViewportChange(nextLockedPanViewport(middlePanRef.current, event.clientX, event.clientY, latestPropsRef.current.viewport));
        };
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key !== "Escape" || middlePanRef.current.mode !== "locked-pan") return;
            stopMiddlePan(middlePanRef.current);
            setMiddlePanMode("idle");
            setGlobalPanCursor(false);
        };
        window.addEventListener("pointermove", handleGlobalMove);
        window.addEventListener("keydown", handleKeyDown);
        return () => {
            window.removeEventListener("pointermove", handleGlobalMove);
            window.removeEventListener("keydown", handleKeyDown);
        };
    }, []);

    const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (event.button !== 0 && event.button !== 1) return;
        const target = event.target instanceof Element ? event.target : null;
        if (target?.closest("[data-canvas-no-zoom]")) return;
        const resizeCorner = target?.closest<HTMLElement>("[data-leafer-group-resize-corner]")?.dataset.leaferGroupResizeCorner as ResizeCorner | undefined;
        const connectionHandle = target?.closest<HTMLElement>("[data-leafer-connect-node-id]");
        const groupTarget = target?.closest<HTMLElement>("[data-leafer-group-id]");
        const nodeTarget = target?.closest<HTMLElement>("[data-leafer-node-id]");

        event.currentTarget.setPointerCapture(event.pointerId);
        event.preventDefault();

        if (event.button === 1) {
            if (middlePanRef.current.mode === "locked-pan") {
                stopMiddlePan(middlePanRef.current);
                setMiddlePanMode("idle");
                setGlobalPanCursor(false);
                interactionRef.current = { type: "idle" };
                return;
            }
            if (shouldEnterLockedPan(middlePanRef.current)) {
                enterMiddlePanLock(middlePanRef.current, event.clientX, event.clientY, latestPropsRef.current.viewport);
                setMiddlePanMode("locked-pan");
            } else {
                startMiddlePanHold(middlePanRef.current, event.clientX, event.clientY, latestPropsRef.current.viewport);
                setMiddlePanMode("hold-pan");
            }
            setGlobalPanCursor(true);
            interactionRef.current = {
                type: "pan",
                pointerId: event.pointerId,
                startX: event.clientX,
                startY: event.clientY,
                initialViewport: latestPropsRef.current.viewport,
                moved: false,
            };
            return;
        }

        if (event.button === 0 && latestPropsRef.current.spacePressed) {
            setGlobalPanCursor(true);
            interactionRef.current = {
                type: "pan",
                pointerId: event.pointerId,
                startX: event.clientX,
                startY: event.clientY,
                initialViewport: latestPropsRef.current.viewport,
                moved: false,
            };
            return;
        }

        if (connectionHandle) {
            const nodeId = connectionHandle.dataset.leaferConnectNodeId;
            const handleType = connectionHandle.dataset.leaferConnectHandleType as "source" | "target";
            if (!nodeId || !handleType) return;
            const position = screenToCanvas(event.clientX, event.clientY);
            const handle = { nodeId, handleType };
            latestPropsRef.current.onConnectStart(handle, position);
            interactionRef.current = { type: "connect", pointerId: event.pointerId, handle, moved: false };
            return;
        }

        if (groupTarget && resizeCorner) {
            const group = latestPropsRef.current.groups.find((item) => item.id === groupTarget.dataset.leaferGroupId);
            if (!group) return;
            latestPropsRef.current.onSelectionChange(new Set(), group.id, null);
            latestPropsRef.current.onInteractionStart();
            interactionRef.current = {
                type: "group-resize",
                pointerId: event.pointerId,
                groupId: group.id,
                corner: resizeCorner,
                startX: event.clientX,
                startY: event.clientY,
                startLeft: group.position.x,
                startTop: group.position.y,
                startWidth: group.width,
                startHeight: group.height,
                moved: false,
            };
            return;
        }

        if (groupTarget) {
            const group = latestPropsRef.current.groups.find((item) => item.id === groupTarget.dataset.leaferGroupId);
            if (!group) return;
            const movingNodeIds = new Set(group.nodeIds);
            latestPropsRef.current.nodes.forEach((item) => {
                if (movingNodeIds.has(item.id)) item.metadata?.batchChildIds?.forEach((childId) => movingNodeIds.add(childId));
            });
            latestPropsRef.current.onSelectionChange(new Set(), group.id, null);
            latestPropsRef.current.onInteractionStart();
            interactionRef.current = {
                type: "group-drag",
                pointerId: event.pointerId,
                groupId: group.id,
                startX: event.clientX,
                startY: event.clientY,
                initialPosition: group.position,
                initialNodes: latestPropsRef.current.nodes.filter((item) => movingNodeIds.has(item.id)).map((item) => ({ id: item.id, x: item.position.x, y: item.position.y })),
                moved: false,
            };
            return;
        }

        if (nodeTarget) {
            const nodeId = nodeTarget.dataset.leaferNodeId;
            const node = latestPropsRef.current.nodes.find((item) => item.id === nodeId);
            if (!node) return;
            const current = latestPropsRef.current.selectedNodeIds;
            const nextSelected = new Set(current);
            if (event.shiftKey || event.metaKey || event.ctrlKey) {
                if (nextSelected.has(node.id)) nextSelected.delete(node.id);
                else nextSelected.add(node.id);
            } else if (!nextSelected.has(node.id)) {
                nextSelected.clear();
                nextSelected.add(node.id);
            }
            latestPropsRef.current.onSelectionChange(nextSelected, null, null);
            latestPropsRef.current.onInteractionStart();
            const dragIds = new Set(nextSelected);
            latestPropsRef.current.nodes.forEach((item) => {
                if (nextSelected.has(item.id)) item.metadata?.batchChildIds?.forEach((childId) => dragIds.add(childId));
            });
            interactionRef.current = {
                type: "node-drag",
                pointerId: event.pointerId,
                nodeId: node.id,
                startX: event.clientX,
                startY: event.clientY,
                initialNodes: latestPropsRef.current.nodes.filter((item) => dragIds.has(item.id)).map((item) => ({ id: item.id, x: item.position.x, y: item.position.y })),
                selectedAtStart: nextSelected,
                moved: false,
            };
            return;
        }

        const world = screenToCanvas(event.clientX, event.clientY);
        const box: SelectionBox = {
            startWorldX: world.x,
            startWorldY: world.y,
            currentWorldX: world.x,
            currentWorldY: world.y,
            additive: event.shiftKey,
            initialSelectedNodeIds: event.shiftKey ? Array.from(latestPropsRef.current.selectedNodeIds) : [],
        };
        interactionRef.current = { type: "select", pointerId: event.pointerId, box };
        setSelectionBox(box);
        latestPropsRef.current.onSelectionChange(event.shiftKey ? new Set(box.initialSelectedNodeIds) : new Set(), null, null);
    };

    const handlePointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
        const state = interactionRef.current;
        if (state.type === "idle") {
            const target = event.target instanceof Element ? event.target : null;
            const nodeId = target?.closest<HTMLElement>("[data-leafer-node-id]")?.dataset.leaferNodeId || null;
            if (nodeId !== hoveredNodeIdRef.current) {
                hoveredNodeIdRef.current = nodeId;
                latestPropsRef.current.onNodeHoverChange?.(nodeId);
            }
            return;
        }
        if (state.pointerId !== event.pointerId) return;
        const viewport = latestPropsRef.current.viewport;

        if (state.type === "pan") {
            if (middlePanRef.current.mode === "hold-pan") {
                const next = nextHoldPanViewport(middlePanRef.current, event.clientX, event.clientY, latestPropsRef.current.viewport.k);
                interactionRef.current = { ...state, moved: middlePanRef.current.hasMoved };
                latestPropsRef.current.onViewportChange(next);
                return;
            }
            const dx = event.clientX - state.startX;
            const dy = event.clientY - state.startY;
            interactionRef.current = { ...state, moved: state.moved || Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD };
            latestPropsRef.current.onViewportChange({ x: state.initialViewport.x + dx, y: state.initialViewport.y + dy, k: state.initialViewport.k });
            return;
        }

        if (state.type === "node-drag") {
            const dx = event.clientX - state.startX;
            const dy = event.clientY - state.startY;
            const moved = state.moved || Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD;
            interactionRef.current = { ...state, moved };
            if (!moved) return;
            const worldDx = dx / viewport.k;
            const worldDy = dy / viewport.k;
            state.initialNodes.forEach((item) => latestPropsRef.current.onNodePatch(item.id, { position: { x: item.x + worldDx, y: item.y + worldDy } }));
            return;
        }

        if (state.type === "group-drag") {
            const dx = event.clientX - state.startX;
            const dy = event.clientY - state.startY;
            const moved = state.moved || Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD;
            interactionRef.current = { ...state, moved };
            if (!moved) return;
            const worldDx = dx / viewport.k;
            const worldDy = dy / viewport.k;
            latestPropsRef.current.onGroupPatch(state.groupId, { position: { x: state.initialPosition.x + worldDx, y: state.initialPosition.y + worldDy } });
            state.initialNodes.forEach((item) => latestPropsRef.current.onNodePatch(item.id, { position: { x: item.x + worldDx, y: item.y + worldDy } }));
            return;
        }

        if (state.type === "group-resize") {
            const dx = event.clientX - state.startX;
            const dy = event.clientY - state.startY;
            const moved = state.moved || Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD;
            interactionRef.current = { ...state, moved };
            if (!moved) return;
            const worldDx = dx / viewport.k;
            const worldDy = dy / viewport.k;
            const startRight = state.startLeft + state.startWidth;
            const startBottom = state.startTop + state.startHeight;
            const fromLeft = state.corner.includes("left");
            const fromTop = state.corner.includes("top");
            const width = Math.max(GROUP_MIN_WIDTH, state.startWidth + (fromLeft ? -worldDx : worldDx));
            const height = Math.max(GROUP_MIN_HEIGHT, state.startHeight + (fromTop ? -worldDy : worldDy));
            latestPropsRef.current.onGroupPatch(state.groupId, {
                width,
                height,
                position: {
                    x: fromLeft ? startRight - width : state.startLeft,
                    y: fromTop ? startBottom - height : state.startTop,
                },
            });
            return;
        }

        if (state.type === "connect") {
            const world = screenToCanvas(event.clientX, event.clientY);
            const target = getConnectionDropTarget(world, state.handle);
            latestPropsRef.current.onConnectMove(world, target.nodeId);
            interactionRef.current = { ...state, moved: true };
            return;
        }

        if (state.type === "select") {
            const world = screenToCanvas(event.clientX, event.clientY);
            const nextBox = { ...state.box, currentWorldX: world.x, currentWorldY: world.y };
            interactionRef.current = { ...state, box: nextBox };
            setSelectionBox(nextBox);
            const rectX = Math.min(nextBox.startWorldX, nextBox.currentWorldX);
            const rectY = Math.min(nextBox.startWorldY, nextBox.currentWorldY);
            const rectW = Math.abs(nextBox.currentWorldX - nextBox.startWorldX);
            const rectH = Math.abs(nextBox.currentWorldY - nextBox.startWorldY);
            const nextSelected = new Set<string>(nextBox.additive ? nextBox.initialSelectedNodeIds : []);
            latestPropsRef.current.nodes.forEach((node) => {
                const intersects = rectX < node.position.x + node.width && rectX + rectW > node.position.x && rectY < node.position.y + node.height && rectY + rectH > node.position.y;
                if (intersects) nextSelected.add(node.id);
            });
            latestPropsRef.current.onSelectionChange(nextSelected, null, null);
        }
    };

    const handlePointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
        const state = interactionRef.current;
        if (state.type === "idle" || state.pointerId !== event.pointerId) return;

        if (state.type === "connect") {
            const world = screenToCanvas(event.clientX, event.clientY);
            const target = getConnectionDropTarget(world, state.handle);
            latestPropsRef.current.onConnectEnd(world, target.nodeId, target.isNearNode);
            finishInteraction(false);
            return;
        }

        if (state.type === "pan") {
            if (middlePanRef.current.mode === "locked-pan") {
                interactionRef.current = { type: "idle" };
                return;
            }
            if (middlePanRef.current.mode === "hold-pan") {
                stopMiddlePan(middlePanRef.current);
                setMiddlePanMode("idle");
                setGlobalPanCursor(false);
            }
            finishInteraction(false);
            return;
        }

        if (state.type === "node-drag") {
            finishInteraction(state.moved);
            return;
        }

        if (state.type === "select") {
            const moved = Math.abs(state.box.currentWorldX - state.box.startWorldX) > 2 || Math.abs(state.box.currentWorldY - state.box.startWorldY) > 2;
            if (!moved && !state.box.additive) latestPropsRef.current.onSelectionChange(new Set(), null, null);
            finishInteraction(false);
            return;
        }

        finishInteraction(state.type === "group-drag" || state.type === "group-resize" ? state.moved : false);
    };

    const handleDoubleClick = (event: React.MouseEvent<HTMLDivElement>) => {
        const target = event.target instanceof Element ? event.target : null;
        const connectionId = target?.closest<HTMLElement>("[data-leafer-connection-id]")?.dataset.leaferConnectionId;
        if (connectionId) {
            event.preventDefault();
            latestPropsRef.current.onConnectionDelete(connectionId);
            return;
        }
        const nodeId = target?.closest<HTMLElement>("[data-leafer-node-id]")?.dataset.leaferNodeId;
        if (nodeId) {
            const node = latestPropsRef.current.nodes.find((item) => item.id === nodeId);
            if (node) latestPropsRef.current.onNodeDoubleClick(node);
            return;
        }
        if (target?.closest("[data-leafer-group-id],[data-leafer-connect-node-id]")) return;
        event.preventDefault();
        latestPropsRef.current.onCanvasDoubleClick(screenToCanvas(event.clientX, event.clientY));
    };

    const handleWheel = (event: ReactWheelEvent<HTMLDivElement>) => {
        const target = event.target instanceof Element ? event.target : null;
        if (target?.closest("[data-canvas-ui],[data-canvas-no-zoom],input,textarea,select,[contenteditable='true'],.ant-modal,.ant-popover,.ant-dropdown,.ant-select-dropdown,.ant-picker-dropdown")) {
            if (event.ctrlKey || event.metaKey) event.preventDefault();
            event.stopPropagation();
            return;
        }
        event.preventDefault();
        const rect = props.containerRef.current?.getBoundingClientRect();
        if (!rect) return;
        const viewport = latestPropsRef.current.viewport;
        if (!latestPropsRef.current.wheelZoomRequiresCtrl || event.ctrlKey || event.metaKey) {
            const factor = Math.pow(1.1, -event.deltaY / 100);
            const nextScale = Math.min(Math.max(viewport.k * factor, MIN_SCALE), MAX_SCALE);
            const mouseX = event.clientX - rect.left;
            const mouseY = event.clientY - rect.top;
            const worldX = (mouseX - viewport.x) / viewport.k;
            const worldY = (mouseY - viewport.y) / viewport.k;
            latestPropsRef.current.onViewportChange({ x: mouseX - worldX * nextScale, y: mouseY - worldY * nextScale, k: nextScale });
            return;
        }
        latestPropsRef.current.onViewportChange({ x: viewport.x - event.deltaX, y: viewport.y - event.deltaY, k: viewport.k });
    };

    const handleContextMenu = (event: React.MouseEvent<HTMLDivElement>) => {
        event.preventDefault();
        const target = event.target instanceof Element ? event.target : null;
        const nodeId = target?.closest<HTMLElement>("[data-leafer-node-id]")?.dataset.leaferNodeId;
        const groupId = target?.closest<HTMLElement>("[data-leafer-group-id]")?.dataset.leaferGroupId;
        const connectionId = target?.closest<HTMLElement>("[data-leafer-connection-id]")?.dataset.leaferConnectionId;
        if (nodeId) {
            const selectedNodeIds = latestPropsRef.current.selectedNodeIds;
            const isSelectionContext = selectedNodeIds.size >= 2 && selectedNodeIds.has(nodeId);
            if (!isSelectionContext) latestPropsRef.current.onSelectionChange(new Set([nodeId]), null, null);
            latestPropsRef.current.onContextMenu(isSelectionContext ? { type: "selection", x: event.clientX, y: event.clientY } : { type: "node", x: event.clientX, y: event.clientY, nodeId });
            return;
        }
        if (groupId) {
            latestPropsRef.current.onSelectionChange(new Set(), groupId, null);
            latestPropsRef.current.onContextMenu({ type: "group", x: event.clientX, y: event.clientY, groupId });
            return;
        }
        if (connectionId) {
            latestPropsRef.current.onSelectionChange(new Set(), null, connectionId);
            latestPropsRef.current.onContextMenu({ type: "connection", x: event.clientX, y: event.clientY, connectionId });
            return;
        }
        if (latestPropsRef.current.selectedNodeIds.size >= 2) {
            latestPropsRef.current.onSelectionChange(latestPropsRef.current.selectedNodeIds, null, null);
            latestPropsRef.current.onContextMenu({ type: "selection", x: event.clientX, y: event.clientY });
            return;
        }
        latestPropsRef.current.onSelectionChange(new Set(), null, null);
        latestPropsRef.current.onContextMenu({ type: "canvas", x: event.clientX, y: event.clientY });
    };

    return (
        <div
            ref={props.containerRef}
            data-canvas-engine="leafer"
            className="relative h-full w-full cursor-default select-none overflow-hidden"
            style={{ background: theme.canvas.background, touchAction: "none" }}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerLeave={() => {
                if (interactionRef.current.type !== "idle" || hoveredNodeIdRef.current === null) return;
                hoveredNodeIdRef.current = null;
                latestPropsRef.current.onNodeHoverChange?.(null);
            }}
            onPointerUp={handlePointerUp}
            onPointerCancel={(event) => {
                const state = interactionRef.current;
                finishInteraction(state.type === "node-drag" || state.type === "group-drag" || state.type === "group-resize" ? state.moved : false);
                if (state.type === "connect") latestPropsRef.current.onConnectEnd(screenToCanvas(event.clientX, event.clientY), null, true);
            }}
            onDoubleClick={handleDoubleClick}
            onAuxClick={(event) => {
                if (event.button === 1) event.preventDefault();
            }}
            onWheel={handleWheel}
            onContextMenu={handleContextMenu}
            onDragOver={(event) => event.preventDefault()}
            onDrop={props.onDrop}
        >
            {middlePanMode === "locked-pan" && props.middleButtonLockHint !== false ? (
                <div className="pointer-events-none absolute left-1/2 top-20 z-[80] -translate-x-1/2 rounded-full border px-3 py-1 text-xs shadow-lg backdrop-blur" style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }}>
                    中键锁定平移
                </div>
            ) : null}
            {leaferError ? (
                <div className="pointer-events-none absolute left-1/2 top-1/2 z-20 max-w-sm -translate-x-1/2 -translate-y-1/2 rounded-lg border px-4 py-3 text-sm shadow-xl" style={{ background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }}>
                    Leafer 瀵洘鎼搁崚婵嗩潗閸栨牕銇戠拹銉窗{leaferError}
                </div>
            ) : null}
            <LeaferHitLayer nodes={props.nodes} groups={props.groups} connections={props.connections} nodeById={nodeById} viewport={props.viewport} selectedGroupId={props.selectedGroupId} selectedNodeIds={props.selectedNodeIds} />
            {selectionBox ? (
                <div
                    className="pointer-events-none absolute z-[100] border"
                    style={{
                        left: props.viewport.x + Math.min(selectionBox.startWorldX, selectionBox.currentWorldX) * props.viewport.k,
                        top: props.viewport.y + Math.min(selectionBox.startWorldY, selectionBox.currentWorldY) * props.viewport.k,
                        width: Math.abs(selectionBox.currentWorldX - selectionBox.startWorldX) * props.viewport.k,
                        height: Math.abs(selectionBox.currentWorldY - selectionBox.startWorldY) * props.viewport.k,
                        borderColor: theme.canvas.selectionStroke,
                        background: theme.canvas.selectionFill,
                    }}
                />
            ) : null}
            <LeaferNodeOverlay nodes={props.nodes} viewport={props.viewport} selectedNodeIds={props.selectedNodeIds} />
        </div>
    );
}

function renderLeaferScene(scene: LeaferScene, props: CanvasEngineProps) {
    const theme = canvasThemes[useThemeStore.getState().theme];
    const { module, stage } = scene;
    stage.x = props.viewport.x;
    stage.y = props.viewport.y;
    stage.scaleX = props.viewport.k;
    stage.scaleY = props.viewport.k;
    clearLeaferChildren(stage);
    addLeaferGrid(scene, props, theme);
    props.groups.forEach((group) => addLeaferGroup(scene, group, props, theme));
    props.connections.forEach((connection) => addLeaferConnection(scene, connection, props, theme));
    if (props.connectingParams) addLeaferActiveConnection(scene, props, theme);
    props.nodes.forEach((node) => addLeaferNode(scene, node, props, theme));
    stage.set?.({ x: props.viewport.x, y: props.viewport.y, scaleX: props.viewport.k, scaleY: props.viewport.k });
    void module;
}

function clearLeaferChildren(stage: LeaferElement) {
    const maybeChildren = (stage as LeaferElement & { children?: LeaferElement[] }).children;
    if (Array.isArray(maybeChildren)) {
        [...maybeChildren].forEach((child) => child.remove?.() || child.destroy?.());
    }
    (stage as LeaferElement & { clear?: () => void }).clear?.();
}

function addLeaferGrid(scene: LeaferScene, props: CanvasEngineProps, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    if (props.backgroundMode === "blank") return;
    const { Rect } = scene.module;
    const gridSize = 48;
    const viewLeft = -props.viewport.x / props.viewport.k - 400;
    const viewTop = -props.viewport.y / props.viewport.k - 400;
    const rect = props.containerRef.current?.getBoundingClientRect();
    const viewRight = viewLeft + (rect?.width || 1200) / props.viewport.k + 800;
    const viewBottom = viewTop + (rect?.height || 720) / props.viewport.k + 800;
    const startX = Math.floor(viewLeft / gridSize) * gridSize;
    const startY = Math.floor(viewTop / gridSize) * gridSize;
    const color = props.backgroundMode === "dots" ? theme.canvas.dot : theme.canvas.line;
    const items: LeaferElement[] = [];

    if (props.backgroundMode === "dots") {
        for (let x = startX; x < viewRight; x += gridSize) {
            for (let y = startY; y < viewBottom; y += gridSize) {
                items.push(asLeaferElement(new Rect({ x, y, width: 1.4, height: 1.4, cornerRadius: 999, fill: color, opacity: 0.52, hit: false } as never)));
            }
        }
    } else {
        for (let x = startX; x < viewRight; x += gridSize) items.push(asLeaferElement(new Rect({ x, y: viewTop, width: 1, height: viewBottom - viewTop, fill: color, opacity: 0.5, hit: false } as never)));
        for (let y = startY; y < viewBottom; y += gridSize) items.push(asLeaferElement(new Rect({ x: viewLeft, y, width: viewRight - viewLeft, height: 1, fill: color, opacity: 0.5, hit: false } as never)));
    }
    addMany(scene.stage, items);
}

function addLeaferGroup(scene: LeaferScene, group: CanvasGroupData, props: CanvasEngineProps, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    const active = props.selectedGroupId === group.id;
    const rect = asLeaferElement(new scene.module.Rect({
        x: group.position.x,
        y: group.position.y,
        width: group.width,
        height: group.height,
        cornerRadius: 28,
        fill: hexToRgba(group.color, active ? 0.24 : 0.16),
        stroke: active ? group.color : `${group.color}aa`,
        strokeWidth: 2,
        hit: false,
    } as never));
    const label = asLeaferElement(new scene.module.Text({
        x: group.position.x,
        y: group.position.y - 30,
        text: group.title || "Group",
        fontSize: 12,
        fontWeight: "700",
        fill: theme.node.text,
        hit: false,
    } as never));
    addMany(scene.stage, [rect, label]);
}

function addLeaferConnection(scene: LeaferScene, connection: CanvasConnection, props: CanvasEngineProps, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    const from = props.nodes.find((node) => node.id === connection.fromNodeId);
    const to = props.nodes.find((node) => node.id === connection.toNodeId);
    if (!from || !to) return;
    const active = props.selectedConnectionId === connection.id;
    const path = asLeaferElement(new scene.module.Path({
        path: connectionPath(from, to),
        stroke: active ? theme.node.activeStroke : theme.node.muted,
        strokeWidth: active ? 3 : 2,
        opacity: active ? 1 : 0.82,
        hit: false,
    } as never));
    addMany(scene.stage, [path]);
}

function addLeaferActiveConnection(scene: LeaferScene, props: CanvasEngineProps, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    const handle = props.connectingParams;
    if (!handle) return;
    const node = props.nodes.find((item) => item.id === handle.nodeId);
    if (!node) return;
    const target = props.connectionTargetNodeId ? props.nodes.find((item) => item.id === props.connectionTargetNodeId) : undefined;
    const startX = handle.handleType === "source" ? node.position.x + node.width : props.mouseWorld.x;
    const startY = handle.handleType === "source" ? node.position.y + node.height / 2 : props.mouseWorld.y;
    const endX = handle.handleType === "source" ? props.mouseWorld.x : node.position.x;
    const endY = handle.handleType === "source" ? props.mouseWorld.y : node.position.y + node.height / 2;
    const snappedStartX = handle.handleType === "target" && target ? target.position.x + target.width : startX;
    const snappedStartY = handle.handleType === "target" && target ? target.position.y + target.height / 2 : startY;
    const snappedEndX = handle.handleType === "source" && target ? target.position.x : endX;
    const snappedEndY = handle.handleType === "source" && target ? target.position.y + target.height / 2 : endY;
    const distance = Math.abs(snappedEndX - snappedStartX);
    const path = `M ${snappedStartX} ${snappedStartY} C ${snappedStartX + distance * 0.5} ${snappedStartY}, ${snappedEndX - distance * 0.5} ${snappedEndY}, ${snappedEndX} ${snappedEndY}`;
    addMany(scene.stage, [
        asLeaferElement(new scene.module.Path({
            path,
            stroke: theme.node.activeStroke,
            strokeWidth: 2,
            dashPattern: [5, 5],
            hit: false,
        } as never)),
    ]);
}

function addLeaferNode(scene: LeaferScene, node: CanvasNodeData, props: CanvasEngineProps, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    const active = props.selectedNodeIds.has(node.id) || props.connectionTargetNodeId === node.id;
    const hasImage = (node.type === CanvasNodeType.Image || node.type === CanvasNodeType.Director) && Boolean(node.metadata?.content);
    const hasVideo = node.type === CanvasNodeType.Video && Boolean(node.metadata?.content);
    const fill = hasImage || hasVideo ? "rgba(0,0,0,0)" : theme.node.fill;
    const stroke = active ? theme.node.activeStroke : theme.node.stroke;
    const base = asLeaferElement(new scene.module.Rect({
        x: node.position.x,
        y: node.position.y,
        width: node.width,
        height: node.height,
        cornerRadius: 24,
        fill,
        stroke,
        strokeWidth: active ? 2.5 : 1.5,
        shadow: active ? { x: 0, y: 0, blur: 24, color: `${theme.node.activeStroke}33` } : undefined,
        hit: false,
    } as never));
    const children: LeaferElement[] = [base];
    if (hasImage) {
        children.push(
            asLeaferElement(new scene.module.Image({
                x: node.position.x,
                y: node.position.y,
                width: node.width,
                height: node.height,
                url: node.metadata?.content,
                cornerRadius: 24,
                hit: false,
            } as never)),
        );
    } else {
        children.push(...nodeContentElements(scene, node, theme));
    }
    children.push(
        asLeaferElement(new scene.module.Text({
            x: node.position.x + 14,
            y: node.position.y + 10,
            text: node.title || node.type,
            fontSize: 11,
            fontWeight: "700",
            fill: theme.node.label,
            hit: false,
        } as never)),
    );
    if (active) {
        const left = asLeaferElement(new scene.module.Rect({
            x: node.position.x - CONNECTION_HANDLE_RADIUS,
            y: node.position.y + node.height / 2 - CONNECTION_HANDLE_RADIUS,
            width: CONNECTION_HANDLE_RADIUS * 2,
            height: CONNECTION_HANDLE_RADIUS * 2,
            cornerRadius: CONNECTION_HANDLE_RADIUS,
            fill: theme.node.activeStroke,
            stroke: "#ffffff",
            strokeWidth: 2,
            hit: false,
        } as never));
        children.push(left);
        if (node.type !== CanvasNodeType.Config) {
            children.push(
                asLeaferElement(new scene.module.Rect({
                    x: node.position.x + node.width - CONNECTION_HANDLE_RADIUS,
                    y: node.position.y + node.height / 2 - CONNECTION_HANDLE_RADIUS,
                    width: CONNECTION_HANDLE_RADIUS * 2,
                    height: CONNECTION_HANDLE_RADIUS * 2,
                    cornerRadius: CONNECTION_HANDLE_RADIUS,
                    fill: theme.node.activeStroke,
                    stroke: "#ffffff",
                    strokeWidth: 2,
                    hit: false,
                } as never)),
            );
        }
    }
    addMany(scene.stage, children);
}

function nodeContentElements(scene: LeaferScene, node: CanvasNodeData, theme: (typeof canvasThemes)[keyof typeof canvasThemes]) {
    const iconLabel = {
        [CanvasNodeType.Image]: "Image",
        [CanvasNodeType.Text]: "Text",
        [CanvasNodeType.Config]: "Config",
        [CanvasNodeType.Video]: "Video",
        [CanvasNodeType.Audio]: "Audio",
        [CanvasNodeType.Director]: "Director",
    }[node.type];
    const content = node.type === CanvasNodeType.Text ? node.metadata?.content || "Double click to edit text" : node.metadata?.prompt || node.metadata?.content || iconLabel;
    return [
        asLeaferElement(new scene.module.Text({
            x: node.position.x + 18,
            y: node.position.y + 48,
            width: Math.max(40, node.width - 36),
            height: Math.max(40, node.height - 66),
            text: content,
            fontSize: node.type === CanvasNodeType.Text ? node.metadata?.fontSize || 14 : 13,
            lineHeight: 21,
            fill: theme.node.text,
            textWrap: "break",
            textOverflow: "ellipsis",
            hit: false,
        } as never)),
    ];
}

function LeaferHitLayer({
    nodes,
    groups,
    connections,
    nodeById,
    viewport,
    selectedGroupId,
    selectedNodeIds,
}: {
    nodes: CanvasNodeData[];
    groups: CanvasGroupData[];
    connections: CanvasConnection[];
    nodeById: Map<string, CanvasNodeData>;
    viewport: ViewportTransform;
    selectedGroupId: string | null;
    selectedNodeIds: Set<string>;
}) {
    return (
        <div className="absolute inset-0 z-10">
            {connections.map((connection) => {
                const from = nodeById.get(connection.fromNodeId);
                const to = nodeById.get(connection.toNodeId);
                if (!from || !to) return null;
                const start = canvasToScreen({ x: from.position.x + from.width, y: from.position.y + from.height / 2 }, viewport);
                const end = canvasToScreen({ x: to.position.x, y: to.position.y + to.height / 2 }, viewport);
                const left = Math.min(start.x, end.x) - 16;
                const top = Math.min(start.y, end.y) - 16;
                return <button key={connection.id} type="button" data-leafer-connection-id={connection.id} className="absolute z-10 cursor-pointer opacity-0" style={{ left, top, width: Math.abs(end.x - start.x) + 32, height: Math.abs(end.y - start.y) + 32 }} aria-label="选择连线" />;
            })}
            {groups.map((group) => {
                const topLeft = canvasToScreen(group.position, viewport);
                const active = selectedGroupId === group.id;
                return (
                    <div
                        key={group.id}
                        data-leafer-group-id={group.id}
                        className="absolute z-20 rounded-[28px]"
                        style={{ left: topLeft.x, top: topLeft.y, width: group.width * viewport.k, height: group.height * viewport.k, pointerEvents: "none" }}
                    >
                        <button type="button" data-leafer-group-id={group.id} className="absolute -inset-3 cursor-move rounded-[32px]" style={{ pointerEvents: "auto", clipPath: "polygon(0 0, 100% 0, 100% 24px, 24px 24px, 24px calc(100% - 24px), 100% calc(100% - 24px), 100% 100%, 0 100%, 0 0)" }} aria-label="拖动分组" title="拖动分组" />
                        {(["top-left", "top-right", "bottom-left", "bottom-right"] as ResizeCorner[]).map((corner) => (
                            <button
                                key={corner}
                                type="button"
                                data-leafer-group-id={group.id}
                                data-leafer-group-resize-corner={corner}
                                className={`absolute size-6 rounded-full ${resizeHandleClass(corner)} ${active ? "opacity-100" : "opacity-0"}`}
                                style={{ pointerEvents: "auto" }}
                                aria-label="鐠嬪啯鏆ｉ崚鍡欑矋婢堆冪毈"
                            />
                        ))}
                    </div>
                );
            })}
            {nodes.map((node) => {
                const topLeft = canvasToScreen(node.position, viewport);
                const selected = selectedNodeIds.has(node.id);
                return (
                    <div key={node.id} className="absolute z-30" style={{ left: topLeft.x, top: topLeft.y, width: node.width * viewport.k, height: node.height * viewport.k }}>
                        <button type="button" data-leafer-node-id={node.id} className="absolute inset-0 cursor-grab rounded-[24px] active:cursor-grabbing" aria-label={`Select node ${node.title}`} />
                        <button type="button" data-leafer-connect-node-id={node.id} data-leafer-connect-handle-type="target" className={`absolute top-1/2 z-40 size-5 -translate-x-1/2 -translate-y-1/2 rounded-full ${selected ? "opacity-100" : "opacity-0"}`} aria-label="Connect to node" />
                        {node.type !== CanvasNodeType.Config ? <button type="button" data-leafer-connect-node-id={node.id} data-leafer-connect-handle-type="source" className={`absolute right-0 top-1/2 z-40 size-5 translate-x-1/2 -translate-y-1/2 rounded-full ${selected ? "opacity-100" : "opacity-0"}`} aria-label="Connect from node" /> : null}
                    </div>
                );
            })}
        </div>
    );
}

function LeaferNodeOverlay({ nodes, viewport, selectedNodeIds }: { nodes: CanvasNodeData[]; viewport: ViewportTransform; selectedNodeIds: Set<string> }) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    return (
        <div className="pointer-events-none absolute inset-0 z-20">
            {nodes.map((node) => {
                const position = canvasToScreen(node.position, viewport);
                const Icon = nodeIcon(node.type);
                const selected = selectedNodeIds.has(node.id);
                return (
                    <div key={node.id} className="absolute flex items-center gap-1.5 rounded-full border px-2 py-1 text-[11px] font-bold shadow-sm backdrop-blur-md" style={{ left: position.x + 12 * viewport.k, top: position.y + 10 * viewport.k, background: theme.toolbar.panel, borderColor: selected ? theme.node.activeStroke : theme.toolbar.border, color: theme.node.label }}>
                        <Icon className="size-3" />
                        <span className="max-w-[140px] truncate">{node.title}</span>
                    </div>
                );
            })}
        </div>
    );
}

function nodeIcon(type: CanvasNodeType) {
    if (type === CanvasNodeType.Image) return ImageIcon;
    if (type === CanvasNodeType.Text) return FileText;
    if (type === CanvasNodeType.Config) return Settings2;
    if (type === CanvasNodeType.Video) return Video;
    if (type === CanvasNodeType.Director) return Clapperboard;
    return Music2;
}

function addMany(parent: LeaferElement, children: LeaferElement[]) {
    if (!children.length) return;
    parent.addMany?.(...children) || parent.add?.(children);
}

function connectionPath(from: CanvasNodeData, to: CanvasNodeData) {
    const startX = from.position.x + from.width;
    const startY = from.position.y + from.height / 2;
    const endX = to.position.x;
    const endY = to.position.y + to.height / 2;
    const dx = Math.abs(endX - startX);
    const curvature = Math.max(dx * 0.5, 50);
    return `M ${startX} ${startY} C ${startX + curvature} ${startY}, ${endX - curvature} ${endY}, ${endX} ${endY}`;
}

function getConnectionTargetAnchor(node: CanvasNodeData, current: ConnectionHandle) {
    return current.handleType === "source" ? { x: node.position.x, y: node.position.y + node.height / 2 } : { x: node.position.x + node.width, y: node.position.y + node.height / 2 };
}

function canvasToScreen(position: Position, viewport: ViewportTransform) {
    return { x: viewport.x + position.x * viewport.k, y: viewport.y + position.y * viewport.k };
}

function resizeHandleClass(corner: ResizeCorner) {
    return {
        "top-left": "-left-3 -top-3 cursor-nwse-resize",
        "top-right": "-right-3 -top-3 cursor-nesw-resize",
        "bottom-left": "-bottom-3 -left-3 cursor-nesw-resize",
        "bottom-right": "-bottom-3 -right-3 cursor-nwse-resize",
    }[corner];
}

function hexToRgba(hex: string, alpha: number) {
    const normalized = hex.replace("#", "");
    const value = normalized.length === 3 ? normalized.split("").map((item) => item + item).join("") : normalized;
    const red = Number.parseInt(value.slice(0, 2), 16);
    const green = Number.parseInt(value.slice(2, 4), 16);
    const blue = Number.parseInt(value.slice(4, 6), 16);
    if ([red, green, blue].some(Number.isNaN)) return `rgba(107,114,128,${alpha})`;
    return `rgba(${red},${green},${blue},${alpha})`;
}
