import type { AiTextMessage } from "@/services/api/image";
import { ensureImageDataUrlMimeType, imageDataUrlMimeType } from "@/lib/image-utils";
import { imageReferenceLabel } from "@/lib/image-reference-prompt";
import { seedanceReferenceLabel } from "@/lib/seedance-video";
import type { ReferenceImage } from "@/types/image";
import type { ReferenceAudio, ReferenceVideo } from "@/types/media";
import { CanvasNodeType, type CanvasConnection, type CanvasNodeData } from "../types";
import { extractCanvasMentionTokens, findLegacyMentionedReferences, missingCanvasMentionKeys } from "../utils/canvas-mention-tokens";
import { getGenerationResourceNodes, type CanvasResourceReference } from "../utils/canvas-resource-references";

export type NodeGenerationContext = {
    prompt: string;
    referenceImages: ReferenceImage[];
    referenceVideos: ReferenceVideo[];
    referenceAudios: ReferenceAudio[];
    textCount: number;
    imageCount: number;
    videoCount: number;
    audioCount: number;
    missingReferenceNodeIds?: string[];
    missingReferenceKeys?: string[];
};

export type NodeGenerationInput = {
    mentionKey: string;
    mentionSource: "node" | "asset";
    targetId: string;
    nodeId: string;
    type: "text" | "image" | "video" | "audio";
    title: string;
    text?: string;
    image?: ReferenceImage;
    video?: ReferenceVideo;
    audio?: ReferenceAudio;
};

export function buildNodeGenerationContext(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[], prompt: string, mentionReferences: CanvasResourceReference[] = []): NodeGenerationContext {
    const inputs = buildNodeGenerationInputs(nodeId, nodes, connections);
    const tokenInputs = mentionReferences.length ? mentionReferencesToInputs(mentionReferences) : inputs;
    const tokenContext = buildTokenGenerationContext(tokenInputs, prompt);
    if (tokenContext) return tokenContext;

    const upstreamText = inputs
        .map((input) => input.text)
        .filter(Boolean)
        .join("\n\n");
    const referenceImages = inputs.map((input) => input.image).filter((image): image is ReferenceImage => Boolean(image));
    const referenceVideos = inputs.map((input) => input.video).filter((video): video is ReferenceVideo => Boolean(video));
    const referenceAudios = inputs.map((input) => input.audio).filter((audio): audio is ReferenceAudio => Boolean(audio));

    return {
        prompt: upstreamText ? `${prompt}\n\n${upstreamText}` : prompt,
        referenceImages,
        referenceVideos,
        referenceAudios,
        textCount: inputs.filter((input) => input.type === "text").length,
        imageCount: referenceImages.length,
        videoCount: referenceVideos.length,
        audioCount: referenceAudios.length,
    };
}

function buildTokenGenerationContext(inputs: NodeGenerationInput[], prompt: string): NodeGenerationContext | null {
    const tokens = extractCanvasMentionTokens(prompt);
    const referenceLabels = labelInputsByKey(inputs);
    if (!tokens.length) {
        const legacyInputs = findLegacyMentionedReferences(
            prompt,
            inputs.map((input) => ({ mentionKey: input.mentionKey, mentionSource: input.mentionSource, targetId: input.targetId, nodeId: input.mentionSource === "node" ? input.targetId : undefined, assetId: input.mentionSource === "asset" ? input.targetId : undefined, label: referenceLabels.get(input.mentionKey) || input.title, kind: input.type, title: input.title, text: input.text })),
        )
            .map((reference) => inputs.find((input) => input.mentionKey === reference.mentionKey))
            .filter((input): input is NodeGenerationInput => Boolean(input));
        return legacyInputs.length ? buildSelectedGenerationContext(legacyInputs, prompt, []) : null;
    }
    const missing = missingCanvasMentionKeys(
        prompt,
        inputs.map((input) => ({ mentionKey: input.mentionKey, mentionSource: input.mentionSource, targetId: input.targetId, nodeId: input.mentionSource === "node" ? input.targetId : undefined, assetId: input.mentionSource === "asset" ? input.targetId : undefined, label: referenceLabels.get(input.mentionKey) || input.title })),
    );
    const inputByKey = new Map(inputs.map((input) => [input.mentionKey, input]));
    const selectedInputs = tokens.map((token) => inputByKey.get(token.key)).filter((input): input is NodeGenerationInput => Boolean(input));
    return buildSelectedGenerationContext(selectedInputs, prompt, missing);
}

function labelInputsByKey(inputs: NodeGenerationInput[]) {
    const counts = { image: 0, video: 0, audio: 0, text: 0 };
    return new Map(inputs.map((input) => [input.mentionKey, input.mentionSource === "asset" ? input.title : generationLabel(input.type, counts[input.type]++)]));
}

function buildSelectedGenerationContext(inputs: NodeGenerationInput[], prompt: string, missingReferenceNodeIds: string[]): NodeGenerationContext {
    const inputByKey = new Map(inputs.map((input) => [input.mentionKey, input]));
    const selectedInputs: NodeGenerationInput[] = [];
    const labelByKey = new Map<string, string>();
    const textBlocks: string[] = [];
    const counts = { image: 0, video: 0, audio: 0, text: 0 };
    let hasToken = false;
    let lastIndex = 0;
    let nextPrompt = "";

    for (const match of prompt.matchAll(/@\[(node|asset):([^\]]+)\]/g)) {
        if (match.index === undefined) continue;
        hasToken = true;
        nextPrompt += prompt.slice(lastIndex, match.index);
        const key = `${match[1]}:${match[2]}`;
        const input = inputByKey.get(key);
        if (input) {
            let label = labelByKey.get(input.mentionKey);
            if (!label) {
                label = input.mentionSource === "asset" ? input.title : generationLabel(input.type, counts[input.type]++);
                labelByKey.set(input.mentionKey, label);
                if (input.type === "text") textBlocks.push(`【${label}】\n${input.text || ""}`);
                else selectedInputs.push(input);
            }
            nextPrompt += input.type === "text" ? `【${label}】` : label;
        } else {
            nextPrompt += match[0];
        }
        lastIndex = match.index + match[0].length;
    }

    if (!hasToken) {
        inputs.forEach((input) => {
            if (labelByKey.has(input.mentionKey)) return;
            const label = generationLabel(input.type, counts[input.type]++);
            labelByKey.set(input.mentionKey, label);
            if (input.type === "text") textBlocks.push(`【${label}】\n${input.text || ""}`);
            else selectedInputs.push(input);
        });
    }

    nextPrompt += prompt.slice(lastIndex);
    if (textBlocks.length) nextPrompt = `${nextPrompt.trim()}\n\n${textBlocks.join("\n\n")}`;
    const referenceImages = selectedInputs.map((input) => input.image).filter((image): image is ReferenceImage => Boolean(image));
    const referenceVideos = selectedInputs.map((input) => input.video).filter((video): video is ReferenceVideo => Boolean(video));
    const referenceAudios = selectedInputs.map((input) => input.audio).filter((audio): audio is ReferenceAudio => Boolean(audio));

    return {
        prompt: hasToken ? nextPrompt : `${prompt.trim()}\n\n${textBlocks.join("\n\n")}`.trim(),
        referenceImages,
        referenceVideos,
        referenceAudios,
        textCount: counts.text,
        imageCount: referenceImages.length,
        videoCount: referenceVideos.length,
        audioCount: referenceAudios.length,
        missingReferenceNodeIds,
        missingReferenceKeys: missingReferenceNodeIds,
    };
}

export function buildNodeGenerationInputs(nodeId: string, nodes: CanvasNodeData[], connections: CanvasConnection[]): NodeGenerationInput[] {
    return getGenerationResourceNodes(nodeId, nodes, connections).flatMap((node): NodeGenerationInput[] => {
        const image = readReferenceImage(node);
        if (image) return [nodeInput(node.id, "image", node.title, { image })];
        const video = readReferenceVideo(node);
        if (video) return [nodeInput(node.id, "video", node.title, { video })];
        const audio = readReferenceAudio(node);
        if (audio) return [nodeInput(node.id, "audio", node.title, { audio })];
        const text = readNodeTextInput(node);
        if (text) return [nodeInput(node.id, "text", node.title, { text })];
        return [];
    });
}

export function mentionReferencesToInputs(references: CanvasResourceReference[]): NodeGenerationInput[] {
    return references.flatMap((reference): NodeGenerationInput[] => {
        if (reference.kind === "image" && reference.image) return [referenceInput(reference, "image", { image: reference.image })];
        if (reference.kind === "video" && reference.video) return [referenceInput(reference, "video", { video: reference.video })];
        if (reference.kind === "audio" && reference.audio) return [referenceInput(reference, "audio", { audio: reference.audio })];
        if (reference.kind === "text" && reference.text) return [referenceInput(reference, "text", { text: reference.text })];
        return [];
    });
}

export function buildNodeResponseMessages(context: NodeGenerationContext): AiTextMessage[] {
    if (!context.referenceImages.length) {
        return [{ role: "user", content: context.prompt }];
    }

    return [
        {
            role: "user",
            content: [{ type: "text" as const, text: context.prompt }, ...context.referenceImages.map((image) => ({ type: "image_url" as const, image_url: { url: normalizedReferenceImageDataUrl(image) } }))],
        },
    ];
}

export async function hydrateNodeGenerationContext(context: NodeGenerationContext) {
    const { imageToDataUrl } = await import("@/services/image-storage");
    return {
        ...context,
        referenceImages: await Promise.all(
            context.referenceImages.map(async (image) => {
                const dataUrl = ensureImageDataUrlMimeType(await imageToDataUrl(image), image.type);
                return { ...image, type: imageDataUrlMimeType(dataUrl, image.type), dataUrl };
            }),
        ),
    };
}

function normalizedReferenceImageDataUrl(image: ReferenceImage) {
    if (!image.dataUrl.startsWith("data:")) return image.dataUrl;
    return ensureImageDataUrlMimeType(image.dataUrl, image.type);
}

function readNodeTextInput(node: CanvasNodeData) {
    if (node.type === CanvasNodeType.Text) return node.metadata?.content || node.metadata?.prompt || "";
    return node.metadata?.prompt || "";
}

function generationLabel(type: NodeGenerationInput["type"], index: number) {
    if (type === "image") return imageReferenceLabel(index);
    if (type === "video") return seedanceReferenceLabel("video", index);
    if (type === "audio") return seedanceReferenceLabel("audio", index);
    return `文本${index + 1}`;
}

function nodeInput(nodeId: string, type: NodeGenerationInput["type"], title: string, data: Pick<NodeGenerationInput, "text" | "image" | "video" | "audio">): NodeGenerationInput {
    return { mentionKey: `node:${nodeId}`, mentionSource: "node", targetId: nodeId, nodeId, type, title, ...data };
}

function referenceInput(reference: CanvasResourceReference, type: NodeGenerationInput["type"], data: Pick<NodeGenerationInput, "text" | "image" | "video" | "audio">): NodeGenerationInput {
    const targetId = reference.targetId;
    return {
        mentionKey: reference.mentionKey,
        mentionSource: reference.mentionSource,
        targetId,
        nodeId: reference.nodeId || reference.assetId || targetId,
        type,
        title: reference.title || reference.label,
        ...data,
    };
}

function readReferenceImage(node: CanvasNodeData): ReferenceImage | null {
    if (node.type !== CanvasNodeType.Image || !node.metadata?.content) return null;
    return {
        id: node.id,
        name: `${node.title || node.id}.png`,
        type: node.metadata.mimeType || "image/png",
        dataUrl: node.metadata.content,
        storageKey: node.metadata.storageKey,
    };
}

function readReferenceVideo(node: CanvasNodeData): ReferenceVideo | null {
    if (node.type !== CanvasNodeType.Video || !node.metadata?.content) return null;
    return {
        id: node.id,
        name: `${node.title || node.id}.mp4`,
        type: node.metadata.mimeType || "video/mp4",
        url: node.metadata.content,
        storageKey: node.metadata.storageKey,
        bytes: node.metadata.bytes,
        width: node.metadata.naturalWidth,
        height: node.metadata.naturalHeight,
        durationMs: node.metadata.durationMs,
    };
}

function readReferenceAudio(node: CanvasNodeData): ReferenceAudio | null {
    if (node.type !== CanvasNodeType.Audio || !node.metadata?.content) return null;
    return {
        id: node.id,
        name: `${node.title || node.id}.mp3`,
        type: node.metadata.mimeType || "audio/mpeg",
        url: node.metadata.content,
        storageKey: node.metadata.storageKey,
        durationMs: node.metadata.durationMs,
    };
}
