"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { App, Button, Empty, Input, Modal, Select, Space, Tag } from "antd";
import { Copy, RefreshCw, Search, Trash2, UserRoundCog } from "lucide-react";

import { ensureSeedanceAssetsActive, listSeedanceAssetMentions, seedanceAssetRef, type SeedanceAsset, type SeedanceAssetTag } from "@/services/api/seedance-assets";

type SelectedSeedanceVolcanoAsset = {
    id: string;
    volcanoAssetId: string;
    name?: string;
    status?: string;
    assetType?: string;
};

type CanvasSeedanceAssetDialogProps = {
    open: boolean;
    selectedAssets?: SelectedSeedanceVolcanoAsset[];
    onClose: () => void;
    onSelect: (asset: SeedanceAsset) => void;
    onRemove?: (volcanoAssetId: string) => void;
};

export function CanvasSeedanceAssetDialog({ open, selectedAssets = [], onClose, onSelect, onRemove }: CanvasSeedanceAssetDialogProps) {
    const { message } = App.useApp();
    const [assets, setAssets] = useState<SeedanceAsset[]>([]);
    const [loading, setLoading] = useState(false);
    const [search, setSearch] = useState("");
    const [tagId, setTagId] = useState("");
    const [selectingId, setSelectingId] = useState("");

    const selectedIds = useMemo(() => new Set(selectedAssets.map((asset) => asset.volcanoAssetId).filter(Boolean)), [selectedAssets]);
    const tags = useMemo(() => uniqueTags(assets.flatMap((asset) => asset.tags || [])), [assets]);
    const visibleAssets = useMemo(() => {
        if (!tagId) return assets;
        return assets.filter((asset) => (asset.tags || []).some((tag) => tag.id === tagId));
    }, [assets, tagId]);

    const load = useCallback(async () => {
        setLoading(true);
        try {
            const result = await listSeedanceAssetMentions({ search: search.trim(), limit: 100 });
            setAssets(result.items || []);
        } catch (error) {
            message.error(error instanceof Error ? error.message : "拟真人素材库读取失败");
        } finally {
            setLoading(false);
        }
    }, [message, search]);

    useEffect(() => {
        if (open) void load();
    }, [load, open]);

    const copyRef = async (asset: SeedanceAsset) => {
        await navigator.clipboard.writeText(seedanceAssetRef(asset));
        message.success("已复制 asset:// 引用");
    };

    const selectAsset = async (asset: SeedanceAsset) => {
        setSelectingId(asset.volcano_asset_id);
        try {
            await ensureSeedanceAssetsActive([asset.volcano_asset_id]);
            onSelect(asset);
            message.success("已选入拟真人素材库");
            onClose();
        } catch (error) {
            message.error(error instanceof Error ? error.message : "素材未激活");
        } finally {
            setSelectingId("");
        }
    };

    return (
        <Modal className="canvas-themed-modal" title="Seedance 拟真人素材库" open={open} width={760} centered footer={null} onCancel={onClose} destroyOnClose={false}>
            <div className="space-y-4 text-sm">
                <div className="flex flex-wrap items-center gap-2">
                    <Input className="max-w-xs" value={search} onChange={(event) => setSearch(event.target.value)} onPressEnter={() => void load()} placeholder="搜索名称 / AssetID" prefix={<Search className="size-4" />} />
                    <Select className="w-44" allowClear value={tagId || undefined} onChange={(value) => setTagId(value || "")} options={tags.map((tag) => ({ label: tag.name, value: tag.id }))} placeholder="标签" />
                    <Button icon={<Search className="size-4" />} onClick={() => void load()} loading={loading}>
                        查询
                    </Button>
                    <Button icon={<RefreshCw className="size-4" />} onClick={() => void load()} loading={loading} />
                </div>

                {selectedAssets.length ? (
                    <div className="flex flex-wrap gap-2">
                        {selectedAssets.map((asset) => (
                            <Tag key={asset.volcanoAssetId} closable={Boolean(onRemove)} onClose={(event) => {
                                event.preventDefault();
                                onRemove?.(asset.volcanoAssetId);
                            }}>
                                {asset.name || asset.volcanoAssetId}
                            </Tag>
                        ))}
                    </div>
                ) : null}

                <div className="max-h-[420px] space-y-2 overflow-y-auto pr-1">
                    {visibleAssets.length ? (
                        visibleAssets.map((asset) => {
                            const ref = seedanceAssetRef(asset);
                            const selected = selectedIds.has(asset.volcano_asset_id);
                            return (
                                <div key={asset.id} className="rounded-md border border-black/10 p-3">
                                    <div className="flex min-w-0 items-start justify-between gap-3">
                                        <div className="min-w-0">
                                            <div className="flex flex-wrap items-center gap-2">
                                                <UserRoundCog className="size-4 opacity-70" />
                                                <span className="font-medium">{asset.name || asset.volcano_asset_id}</span>
                                                <Tag color="green">{asset.status || "Active"}</Tag>
                                                <Tag>{asset.asset_type || "Image"}</Tag>
                                            </div>
                                            <div className="mt-1 break-all text-xs opacity-60">{ref}</div>
                                            {asset.description ? <div className="mt-2 text-xs opacity-70">{asset.description}</div> : null}
                                            {asset.tags?.length ? (
                                                <div className="mt-2 flex flex-wrap gap-1">
                                                    {asset.tags.map((tag) => (
                                                        <Tag key={tag.id} color={tag.color || "default"}>
                                                            {tag.name}
                                                        </Tag>
                                                    ))}
                                                </div>
                                            ) : null}
                                        </div>
                                        <Space size={4}>
                                            <Button size="small" icon={<Copy className="size-3.5" />} onClick={() => void copyRef(asset)} />
                                            {selected && onRemove ? <Button size="small" danger icon={<Trash2 className="size-3.5" />} onClick={() => onRemove(asset.volcano_asset_id)} /> : null}
                                            <Button size="small" type="primary" disabled={selected} loading={selectingId === asset.volcano_asset_id} onClick={() => void selectAsset(asset)}>
                                                {selected ? "已选" : "选入"}
                                            </Button>
                                        </Space>
                                    </div>
                                </div>
                            );
                        })
                    ) : (
                        <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={loading ? "读取中" : "暂无 Active 素材"} />
                    )}
                </div>
            </div>
        </Modal>
    );
}

function uniqueTags(tags: SeedanceAssetTag[]) {
    const seen = new Set<string>();
    return tags.filter((tag) => {
        if (!tag.id || seen.has(tag.id)) return false;
        seen.add(tag.id);
        return true;
    });
}
