"use client";

import { useEffect } from "react";
import type { ReactNode } from "react";
import { Clapperboard, Clipboard, Copy, Download, Expand, FileText, FlipHorizontal, FlipVertical, Focus, GalleryHorizontalEnd, Group, Image as ImageIcon, Images, Link2, LinkIcon, Music2, Play, Plus, Settings2, Trash2, Ungroup, Video } from "lucide-react";

import { canvasThemes } from "@/lib/canvas-theme";
import { useThemeStore } from "@/stores/use-theme-store";
import { CanvasNodeType, type CanvasNodeData, type ContextMenuState } from "../types";

type CreateType = CanvasNodeType.Image | CanvasNodeType.Text | CanvasNodeType.Config | CanvasNodeType.Video | CanvasNodeType.Audio | CanvasNodeType.Director;

export function CanvasNodeContextMenu({
    menu,
    canGroup = false,
    canConnectToConfig = false,
    canPaste = false,
    nodeTargets = [],
    menuNode = null,
    onClose,
    onCreateNode,
    onPaste,
    onDuplicate,
    onOpenDirector,
    onCopySelection,
    onGroup,
    onConnectToConfig,
    onConnectToExisting,
    onGenerate,
    onSaveAsset,
    onDownload,
    onImageFocus,
    onImageOutpaint,
    onImageStoryboard,
    onImagePanorama,
    onImageFlipHorizontal,
    onImageFlipVertical,
    onRunGroup,
    onUngroup,
    onDelete,
}: {
    menu: ContextMenuState;
    canGroup?: boolean;
    canConnectToConfig?: boolean;
    canPaste?: boolean;
    nodeTargets?: CanvasNodeData[];
    menuNode?: CanvasNodeData | null;
    onClose: () => void;
    onCreateNode: (type: CreateType) => void;
    onPaste: () => void;
    onDuplicate: () => void;
    onOpenDirector: () => void;
    onCopySelection: () => void;
    onGroup: () => void;
    onConnectToConfig: () => void;
    onConnectToExisting: (targetNodeId: string) => void;
    onGenerate: () => void;
    onSaveAsset: () => void;
    onDownload: () => void;
    onImageFocus?: () => void;
    onImageOutpaint?: () => void;
    onImageStoryboard?: () => void;
    onImagePanorama?: () => void;
    onImageFlipHorizontal?: () => void;
    onImageFlipVertical?: () => void;
    onRunGroup: () => void;
    onUngroup: () => void;
    onDelete: () => void;
}) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];
    const showCreate = menu.type === "canvas";
    const showNode = menu.type === "node";
    const showSelection = menu.type === "selection";
    const showGroup = menu.type === "group";
    const showConnection = menu.type === "connection";
    const showImageNode = showNode && menuNode?.type === CanvasNodeType.Image && Boolean(menuNode.metadata?.content);
    const showDirectorNode = showNode && menuNode?.type === CanvasNodeType.Director;

    useEffect(() => {
        const close = (event: PointerEvent) => {
            const target = event.target;
            if (target instanceof Element && target.closest("[data-canvas-context-menu],.ant-popover,.ant-modal,.ant-dropdown")) return;
            onClose();
        };
        window.addEventListener("pointerdown", close);
        return () => window.removeEventListener("pointerdown", close);
    }, [onClose]);

    return (
        <div
            data-canvas-context-menu
            className="fixed z-[80] max-h-[min(520px,calc(100dvh-32px))] min-w-56 overflow-y-auto rounded-xl border py-1 shadow-2xl"
            style={{ left: menu.x, top: menu.y, background: theme.toolbar.panel, borderColor: theme.toolbar.border, color: theme.node.text }}
            onPointerDown={(event) => event.stopPropagation()}
            onContextMenu={(event) => event.preventDefault()}
        >
            {showCreate ? (
                <>
                    <MenuLabel>新建节点</MenuLabel>
                    <MenuButton icon={<ImageIcon className="size-4" />} label="图片节点" onClick={() => onCreateNode(CanvasNodeType.Image)} />
                    <MenuButton icon={<FileText className="size-4" />} label="文本节点" onClick={() => onCreateNode(CanvasNodeType.Text)} />
                    <MenuButton icon={<Settings2 className="size-4" />} label="配置节点" onClick={() => onCreateNode(CanvasNodeType.Config)} />
                    <MenuButton icon={<Video className="size-4" />} label="视频节点" onClick={() => onCreateNode(CanvasNodeType.Video)} />
                    <MenuButton icon={<Music2 className="size-4" />} label="音频节点" onClick={() => onCreateNode(CanvasNodeType.Audio)} />
                    <MenuButton icon={<Clapperboard className="size-4" />} label="3D 导演台" onClick={() => onCreateNode(CanvasNodeType.Director)} />
                    <MenuDivider />
                    <MenuButton icon={<Clipboard className="size-4" />} label="粘贴" disabled={!canPaste} onClick={onPaste} />
                </>
            ) : null}

            {showNode ? (
                <>
                    <MenuButton icon={<Copy className="size-4" />} label="复制节点" onClick={onDuplicate} />
                    {showDirectorNode ? (
                        <MenuButton icon={<Clapperboard className="size-4" />} label="打开3D 导演台" onClick={onOpenDirector} />
                    ) : (
                        <>
                            <MenuButton icon={<Play className="size-4" />} label="生成" onClick={onGenerate} />
                            <MenuButton icon={<Download className="size-4" />} label="下载" onClick={onDownload} />
                            <MenuButton icon={<Plus className="size-4" />} label="保存素材" onClick={onSaveAsset} />
                        </>
                    )}
                    {showImageNode ? (
                        <>
                            <MenuDivider />
                            <MenuButton icon={<Focus className="size-4" />} label="聚焦提取" onClick={onImageFocus} />
                            <MenuButton icon={<Expand className="size-4" />} label="扩图" onClick={onImageOutpaint} />
                            <MenuButton icon={<GalleryHorizontalEnd className="size-4" />} label="故事板导出" onClick={onImageStoryboard} />
                            <MenuButton icon={<Images className="size-4" />} label="全景图" onClick={onImagePanorama} />
                            <MenuButton icon={<FlipHorizontal className="size-4" />} label="水平翻转" onClick={onImageFlipHorizontal} />
                            <MenuButton icon={<FlipVertical className="size-4" />} label="垂直翻转" onClick={onImageFlipVertical} />
                        </>
                    ) : null}
                    <MenuDivider />
                </>
            ) : null}

            {showSelection ? (
                <>
                    <MenuButton icon={<Copy className="size-4" />} label="复制选中节点" onClick={onCopySelection} />
                    <MenuButton icon={<Link2 className="size-4" />} label="连接到配置" disabled={!canConnectToConfig} onClick={onConnectToConfig} />
                    <TargetNodeList targets={nodeTargets} onConnect={onConnectToExisting} />
                    <MenuButton icon={<Group className="size-4" />} label="创建分组" disabled={!canGroup} onClick={onGroup} />
                    <MenuDivider />
                </>
            ) : null}

            {showGroup ? (
                <>
                    <MenuButton icon={<Play className="size-4" />} label="批量执行" onClick={onRunGroup} />
                    <MenuButton icon={<Ungroup className="size-4" />} label="解组" onClick={onUngroup} />
                    <MenuDivider />
                </>
            ) : null}

            {showConnection ? <MenuButton icon={<Trash2 className="size-4" />} label="删除连线" danger onClick={onDelete} /> : null}
            {!showConnection && !showCreate ? <MenuButton icon={<Trash2 className="size-4" />} label={showGroup ? "删除分组" : "删除"} danger onClick={onDelete} /> : null}
        </div>
    );
}

function TargetNodeList({ targets, onConnect }: { targets: CanvasNodeData[]; onConnect: (targetNodeId: string) => void }) {
    if (!targets.length) return <MenuButton icon={<LinkIcon className="size-4" />} label="连接到已有节点" disabled />;
    return (
        <div>
            <MenuLabel>连接到已有节点</MenuLabel>
            {targets.slice(0, 12).map((node) => (
                <MenuButton key={node.id} icon={<LinkIcon className="size-4" />} label={node.title || node.type} onClick={() => onConnect(node.id)} />
            ))}
        </div>
    );
}

function MenuLabel({ children }: { children: ReactNode }) {
    return <div className="px-3 pb-1 pt-2 text-[11px] font-semibold uppercase tracking-normal opacity-45">{children}</div>;
}

function MenuDivider() {
    return <div className="my-1 h-px bg-white/10" />;
}

function MenuButton({ icon, label, onClick, danger = false, disabled = false }: { icon: ReactNode; label: string; onClick?: () => void; danger?: boolean; disabled?: boolean }) {
    const theme = canvasThemes[useThemeStore((state) => state.theme)];

    return (
        <button
            type="button"
            disabled={disabled}
            className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs transition-colors hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-40"
            style={{ color: danger ? "#f87171" : theme.node.text }}
            onClick={onClick}
        >
            {icon}
            <span className="min-w-0 truncate">{label}</span>
        </button>
    );
}
