import { PROJECT_STORAGE_MODE } from "@/constant/env";
import { applyServerSyncMeta, createServerProject } from "@/services/api/project-canvas";
import type { WorkspaceScope } from "@/stores/use-workspace-scope-store";

import { useCanvasStore, type CanvasProject } from "../stores/use-canvas-store";

export type CreateCanvasProjectResult = {
    id: string;
    project: CanvasProject;
    syncError?: Error;
};

export function suggestedCanvasProjectTitle(scope: WorkspaceScope, projects = useCanvasStore.getState().projects) {
    const titles = new Set(projects.filter((project) => (project.scope || "personal") === scope).map((project) => project.title.trim()));
    let index = titles.size + 1;
    while (titles.has(`分镜画布 ${index}`)) index += 1;
    return `分镜画布 ${index}`;
}

export async function createCanvasProjectAndSync({ title, scope }: { title: string; scope: WorkspaceScope }): Promise<CreateCanvasProjectResult> {
    const store = useCanvasStore.getState();
    const normalizedTitle = title.trim() || suggestedCanvasProjectTitle(scope, store.projects);
    const id = store.createProject(normalizedTitle, scope);
    let project = useCanvasStore.getState().openProject(id);
    if (!project) throw new Error("本地画布创建失败");

    if (PROJECT_STORAGE_MODE !== "server") return { id, project };

    try {
        const serverProject = await createServerProject(project, scope);
        const syncedProject = applyServerSyncMeta(project, serverProject);
        useCanvasStore.getState().updateProjectSyncMeta(id, {
            serverProjectId: syncedProject.serverProjectId,
            workspaceId: syncedProject.workspaceId,
            snapshotVersion: syncedProject.snapshotVersion,
            lastSyncAt: syncedProject.lastSyncAt,
            syncStatus: syncedProject.syncStatus,
        });
        project = useCanvasStore.getState().openProject(id) || syncedProject;
        return { id, project };
    } catch (error) {
        const syncError = error instanceof Error ? error : new Error("服务端注册失败");
        useCanvasStore.getState().updateProjectSyncMeta(id, { syncStatus: "pending" });
        project = useCanvasStore.getState().openProject(id) || project;
        return { id, project, syncError };
    }
}
